(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-antiquities-2-e", [{"sp": "HDR", "t": "Ἰουδαϊκὴ Ἀρχαιολογία"}, {"sp": "HDR", "t": "Βιβλίον Εʹ", "st": "5"}, {"sp": "N", "t": "Μωυσέος δὲ τὸν προειρημένον τρόπον ἐξ ἀνθρώπων ἀπογεγονότος Ἰησοῦς ἁπάντων ἤδη τῶν ἐπ’ αὐτῷ νενομισμένων τέλος ἐχόντων καὶ τοῦ πένθους λελωφηκότος παρήγγειλεν ἐπὶ στρατείαν ἕτοιμον εἶναι τὸ πλῆθος, πέμπει τε κατασκόπους εἰς Ἱεριχοῦντα τήν τε δύναμιν αὐτῶν καὶ τίνα διάνοιαν ἔχουσιν αὐτοὶ γνωσομένους, αὐτὸς δὲ ἐξήταζε τὸν στρατὸν ὡς κατὰ καιρὸν διαβησόμενος τὸν Ἰόρδανον. ἀνακαλεσάμενος δὲ τοὺς τῆς Ῥουβηλίδος φυλῆς ἄρχοντας καὶ τοὺς τῆς Γάδιδος καὶ Μανασσήτιδος προεστῶτας, ἐξ ἡμισείας γὰρ καὶ τῇδε τῇ φυλῇ τὴν Ἀμορίαν κατοικεῖν ἐπετέτραπτο τῆς Χαναναίων γῆς ἕβδομον οὖσαν μέρος, ὑπεμίμνησκεν ἃ ὑπέσχοντο Μωυσεῖ, καὶ παρεκάλει χαριζομένους τῇ τε ἐκείνου προνοίᾳ μηδ’ ὅτε ἀπέθνησκε περὶ αὐτοὺς καμούσῃ τῷ τε κοινῇ συμφέροντι παρέχειν αὑτοὺς εἰς τὰ παραγγελλόμενα προθύμους. τῶν δ’ ἑπομένων ὁπλίταις πεντακισμυρίοις ἀπὸ τῆς Ἀβέλης ἐπὶ τὸν Ἰόρδανον ἐξῄει σταδίους ἑξήκοντα.", "st": "5.1.1"}, {"sp": "N", "t": "Καὶ στρατοπεδεύσαντος εὐθὺς οἱ κατάσκοποι παρῆσαν μηδὲν ἀγνοήσαντες τῶν παρὰ τοῖς Χαναναίοις· ἐλθόντες γὰρ τὸ πρῶτον ἅπασαν ἐπ’ ἀδείας αὐτῶν τὴν πόλιν κατενόησαν, τῶν τε τειχῶν ὅσα καρτερὰ καὶ ὅσα μὴ τοῦτον ἔχει τὸν τρόπον αὐτοῖς ἀσφαλῶς καὶ τῶν πυλίδων αἳ πρὸς εἴσοδον τῷ στρατοπέδῳ δι’ ἀσθένειαν συνέφερον. ἠμέλουν δὲ θεωμένων οἱ ἐντυγχάνοντες κατὰ ἱστορίαν ξένοις προσήκουσαν ἀκριβῶς ἕκαστα πολυπραγμονεῖν τῶν ἐν τῇ πόλει νομίζοντες, ἀλλ’ οὐχὶ διανοίᾳ πολεμίων. ὡς δὲ γενομένης ὀψίας ὑποχωροῦσιν εἴς τι καταγώγιον τοῦ τείχους πλησίον, εἰς ὃ καὶ προήχθησαν δειπνοποιησάμενοι καὶ περὶ ἀπαλλαγῆς αὐτοῖς τὸ λοιπὸν ἡ φροντὶς ἦν, μηνύονται τῷ βασιλεῖ περὶ δεῖπνον ὄντι κατασκεψόμενοί τινες τὴν πόλιν ἀπὸ τοῦ τῶν Ἑβραίων στρατοπέδου παρεῖναι καὶ ὄντες ἐν τῷ τῆς Ῥαάβης καταγωγίῳ μετὰ πολλῆς τῆς τοῦ λανθάνειν προνοίας ὑπάρχειν. ὁ δ’ εὐθὺς πέμψας πρὸς αὐτοὺς ἐκέλευσεν ἀγαγεῖν συλλαβόντας, ἵνα βασανίσας μάθῃ, τί καὶ βουλόμενοι παρεῖεν. ὡς δ’ ἔγνω τὴν ἔφοδον αὐτῶν ἡ Ῥαάβη, λίνου γὰρ ἀγκαλίδας ἐπὶ τοῦ τείχους ἔψυχε, τοὺς μὲν κατασκόπους εἰς ταύτας ἀποκρύπτει, τοῖς δὲ πεμφθεῖσιν ὑπὸ τοῦ βασιλέως ἔλεγεν, ὡς ξένοι τινὲς εἶεν ἀγνῶτες ὀλίγῳ πρότερον ἢ δῦναι τὸν ἥλιον παρ’ αὐτῇ δειπνήσαντες ἀπαλλαγεῖεν, οὓς εἰ φοβεροὶ τῇ πόλει δοκοῦσιν, ἢ κίνδυνον τῷ βασιλεῖ φέροντες ἧκον, ἀπόνως εἶναι λαβεῖν διωχθέντας. οἱ δὲ τῆς γυναικὸς οὕτως αὐτοὺς ὑπελθούσης οὐδένα ὑπονοήσαντες δόλον ἀπῆλθον οὐδ’ ἐρευνήσαντες τὸ καταγώγιον. ἐπεὶ δ’ ὁρμήσαντες καθ’ ἃς ἐνόμιζον αὐτοὺς μάλιστα τῶν ὁδῶν ἀπέρχεσθαι καὶ κατὰ τὰς εἰς τὸν ποταμὸν φερούσας οὐδενὶ γνωρίσματι περιετύγχανον, παύονται τοῦ πονεῖν. τοῦ δὲ θορύβου σταλέντος ἡ Ῥαάβη καταγαγοῦσα τοὺς ἄνδρας καὶ τὸν κίνδυνον εἰποῦσα, ὃν ὑπὲρ τῆς αὐτῶν ὑπέλθοι σωτηρίας, ἁλοῦσαν γὰρ ἀποκρύπτουσαν αὐτοὺς οὐκ ἂν διαφυγεῖν τὴν ἐκ τοῦ βασιλέως τιμωρίαν, ἀλλὰ πανοικὶ αὐτὴν ἀπολέσθαι κακῶς, παρακαλέσασα διὰ μνήμης ἔχειν, ὅταν ἐγκρατεῖς τῆς Χαναναίων γῆς καταστάντες ἀμοιβὴν ἐκτῖσαι δύνωνται τῆς ἄρτι σωτηρίας, χωρεῖν ἐκέλευεν ἐπὶ τὰ οἰκεῖα ὀμόσαντας ἦ μὴν σώσειν αὐτὴν καὶ τὰ αὐτῆς, ὅταν τὴν πόλιν ἑλόντες φθείρωσι πάντας τοὺς ἐν αὐτῇ κατὰ ψήφισμα τὸ παρ’ αὐτοῖς γενόμενον· ταῦτα γὰρ εἰδέναι σημείοις τοῖς ἐκ τοῦ θεοῦ διδαχθεῖσαν. οἱ δὲ καὶ τῶν παρόντων αὐτῇ χάριν ἔχειν ὡμολόγουν καὶ περὶ τῶν αὖθις ὤμνυον ἔργῳ τὴν ἀμοιβὴν ἀποδώσειν· ἡνίκα δ’ ἂν αἴσθηται μελλούσης ἁλίσκεσθαι τῆς πόλεως, συνεβούλευον κτῆσίν τε τὴν αὐτῆς καὶ τοὺς οἰκείους ἅπαντας εἰς τὸ καταγώγιον ἀποθεμένην ἐγκαθεῖρξαι πρὸ τῶν θυρῶν ἀνατείνασαν φοινικίδας, ὅπως εἰδὼς τὴν οἰκίαν ὁ στρατηγὸς φυλάττηται κακῶς ποιεῖν· μηνύσομεν γὰρ αὐτῷ, ἔφασαν, διὰ τὸ σὸν σώζεσθαι πρόθυμον. εἰ δέ τις ἐν τῇ μάχῃ πέσοι τῶν σῶν, σύ τε οὐκ ἂν ἡμῖν ἐπενέγκοις αἰτίαν καὶ τὸν θεὸν ὃν ὀμωμόκαμεν παραιτούμεθα μηδὲν ὡς ἐπὶ παραβαίνουσι τοὺς ὅρκους δυσχερᾶναι. καὶ οἱ μὲν ταῦτα συνθέμενοι ἐχώρουν διὰ τοῦ τείχους καθιμήσαντες ἑαυτούς, καὶ διασωθέντες πρὸς τοὺς οἰκείους ἐδήλωσαν ὅσα πράξαντες ἐπὶ τῆς πόλεως ἧκον· Ἰησοῦς δὲ τῷ ἀρχιερεῖ Ἐλεαζάρῳ καὶ τῇ γερουσίᾳ φράζει τὰ τοῖς σκοποῖς ὁμοθέντα πρὸς τὴν Ῥαάβην· οἱ δ’ ἐπεκύρουν τὸν ὅρκον.", "st": "5.1.2"}, {"sp": "N", "t": "Δεδιότος δὲ τοῦ στρατοῦ τὴν διάβασιν, μέγας γὰρ ἦν ὁ ποταμὸς τῷ ῥεύματι καὶ οὔτε γεφύραις πορευτός, οὐ γὰρ ἔζευκτο τὸ πρότερον, βουλομένους τε γεφυροῦν οὐχ ἕξειν σχολὴν παρὰ τῶν πολεμίων ὑπελάμβανον πορθμείων τε μὴ τυγχανόντων, διαβατὸν αὐτοῖς ὁ θεὸς ἐπαγγέλλεται ποιήσειν τὸν ποταμὸν μειώσας αὐτοῦ τὸ πλῆθος. καὶ δύο ἐπισχὼν ἡμέρας Ἰησοῦς διεβίβαζε τὸν στρατὸν καὶ τὴν πληθὺν ἅπασαν τοιούτῳ τρόπῳ· προῄεσαν μὲν οἱ ἱερεῖς τὴν κιβωτὸν ἔχοντες, ἔπειτα οἱ Λευῖται τήν τε σκηνὴν καὶ τὰ πρὸς ὑπηρεσίαν ταῖς θυσίαις σκεύη κομίζοντες, εἵποντο δὲ τοῖς Λευίταις κατὰ φυλὰς ὁ πᾶς ὅμιλος μέσους ἔχων παῖδας καὶ γυναῖκας, δεδιὼς περὶ αὐτῶν μὴ βιασθεῖεν ὑπὸ τοῦ ῥεύματος. ὡς δὲ τοῖς ἱερεῦσι πρώτοις ἐμβᾶσι πορευτὸς ἔδοξεν ὁ ποταμός, τοῦ μὲν βάθους ἐπεσχημένου, τοῦ δὲ κάχληκος τῷ μὴ πολὺν εἶναι μηδ’ ὀξὺν τὸν ῥοῦν ὥσθ’ ὑποφέρειν αὐτὸν τῇ βίᾳ ἀντ’ ἐδάφους κειμένου, πάντες ἤδη θαρσαλέως ἐπεραιοῦντο τὸν ποταμόν, οἷον αὐτὸν ὁ θεὸς προεῖπε ποιήσειν τοιοῦτον κατανοοῦντες. ἔστησαν δὲ ἐν μέσῳ οἱ ἱερεῖς ἕως οὗ διαβαίη τὸ πλῆθος καὶ τἀσφαλοῦς ἁψάμενον τύχοι. πάντων δὲ διαβάντων ἐξῄεσαν οἱ ἱερεῖς ἐλεύθερον ἀφέντες ἤδη τὸ ῥεῦμα χωρεῖν κατὰ τὴν συνήθειαν. καὶ ὁ μὲν ποταμὸς εὐθὺς ἐκβάντων αὐτὸν τῶν Ἑβραίων ηὔξετο καὶ τὸ ἴδιον ἀπελάμβανε μέγεθος.", "st": "5.1.3"}, {"sp": "N", "t": "Οἱ δὲ πεντήκοντα προελθόντες στάδια βάλλονται στρατόπεδον ἀπὸ δέκα σταδίων τῆς Ἱεριχοῦντος, Ἰησοῦς τε τόν τε βωμὸν ἐκ τῶν λίθων ὧν ἕκαστος ἀνείλετο τῶν φυλάρχων ἐκ τοῦ βυθοῦ τοῦ προφήτου κελεύσαντος ἱδρυσάμενος τεκμήριον γενησόμενον τῆς ἀνακοπῆς τοῦ ῥεύματος ἔθυεν ἐπ’ αὐτοῦ τῷ θεῷ, καὶ τὴν φάσκα ἑώρταζον ἐν ἐκείνῳ τῷ χωρίῳ, πάντων ὧν αὐτοῖς πρότερον συνέβαινε σπανίζειν τότε ῥᾳδίως εὐποροῦντες· τόν τε γὰρ σῖτον ἀκμάζοντα ἤδη τῶν Χαναναίων ἐθέριζον καὶ τὰ λοιπὰ λείαν ἦγον· τότε γὰρ αὐτοὺς καὶ ἡ τῆς μάννας ἐπελελοίπει τροφὴ χρησαμένους ἐπὶ ἔτη τεσσαράκοντα.", "st": "5.1.4"}, {"sp": "N", "t": "Ὡς δὲ ταῦτα ποιούντων τῶν Ἰσραηλιτῶν οὐκ ἐπεξῄεσαν οἱ Χαναναῖοι τειχήρεις δ’ ἡσύχαζον, πολιορκεῖν αὐτοὺς Ἰησοῦς ἔγνω. καὶ τῇ πρώτῃ τῆς ἑορτῆς ἡμέρᾳ τὴν κιβωτὸν οἱ ἱερεῖς φέροντες, περὶ δ’ αὐτὴν ἐν κύκλῳ μέρος τι τῶν ὁπλιτῶν φυλάττον ἦν, οἳ καὶ προῄεσαν ἑπτὰ κέρασιν αὐτῶν σαλπίζοντες παρεκάλουν τὸν στρατὸν εἰς ἀλκὴν, περιώδευόν τε τὸ τεῖχος ἑπομένης τῆς γερουσίας, καὶ σαλπισάντων μόνον τῶν ἱερέων, τούτου γὰρ οὐδὲν ἐποίησαν περισσότερον, ἀνέζευξαν εἰς τὸ στρατόπεδον. καὶ τοῦτο ἐπὶ ἡμέρας ἓξ ποιησάντων τῇ ἑβδόμῃ τὸ ὁπλιτικὸν Ἰησοῦς συναγαγὼν καὶ τὸν λαὸν ἅπαντα τὴν ἅλωσιν αὐτοῖς τῆς πόλεως εὐηγγελίζετο, ὡς κατ’ ἐκείνην τὴν ἡμέραν αὐτοῖς τοῦ θεοῦ ταύτην παρέξοντος αὐτομάτως καὶ δίχα [τοῦ] πόνου τοῦ σφετέρου τῶν τειχῶν κατενεχθησομένων. κτείνειν μέντοι πάνθ’ ὁντινοῦν εἰ λάβοιεν παρεκελεύετο καὶ μήτε κάμνοντας ἀποστῆναι τοῦ φόνου τῶν πολεμίων, μήτ’ ἐλέῳ παραχωρήσαντας μήτε περὶ ἁρπαγὴν γινομένους περιορᾶν φεύγοντας τοὺς ἐχθρούς· ἀλλὰ τὰ μὲν ζῷα πάντα διαφθείρειν μηδὲν αὐτοὺς εἰς ἰδίαν ὠφέλειαν λαμβάνοντας, ὅσος δ’ ἂν ἄργυρος ᾖ καὶ χρυσός, ταῦτα ἐκέλευσε συγκομίζοντας ἀπαρχὴν ἐξαίρετον τῶν κατωρθωμένων τῷ θεῷ τηρεῖν ἐκ τῆς πρῶτον ἁλισκομένης πόλεως εἰληφότας· σώζειν δὲ μόνην Ῥαάβην καὶ τὴν γενεὰν αὐτῆς διὰ τοὺς γενομένους πρὸς αὐτὴν τοῖς κατασκόποις ὅρκους.", "st": "5.1.5"}, {"sp": "N", "t": "Ταῦτ’ εἰπὼν καὶ διατάξας τὸν στρατὸν προσήγαγεν ἐπὶ τὴν πόλιν· περιῄεσαν δὲ πάλιν τὴν πόλιν ἡγουμένης τῆς κιβωτοῦ καὶ τῶν ἱερέων τοῖς κέρασιν ἐξοτρυνόντων τὴν δύναμιν πρὸς τὸ ἔργον. καὶ περιελθόντων ἑπτάκις καὶ πρὸς ὀλίγον ἠρεμησάντων κατέπεσε τὸ τεῖχος μήτε μηχανῆς μήτε ἄλλης βίας αὐτῷ προσενεχθείσης ὑπὸ τῶν Ἑβραίων.", "st": "5.1.6"}, {"sp": "N", "t": "Οἱ δ’ εἰσελθόντες εἰς Ἱεριχοῦντα πάντας ἔκτεινον, τῶν ἐν αὐτῇ πρὸς τὴν παράδοξον τοῦ τείχους ἀνατροπὴν καταπεπληγότων καὶ τοῦ φρονήματος αὐτοῖς πρὸς ἄμυναν ἀχρείου γεγονότος· ἀνῃροῦντο δ’ οὖν ἐν ταῖς ὁδοῖς ἀποσφαττόμενοι καὶ ἐν ταῖς οἰκίαις ἐπικαταλαμβανόμενοι. παρῃτεῖτο δ’ οὐδὲν αὐτούς, ἀλλὰ πάντες ἀπώλλυντο ἄχρι γυναικῶν καὶ παιδίων, καὶ νεκρῶν ἡ πόλις ἦν ἀνάπλεως καὶ διέφυγεν οὐδέν. τὴν δὲ πόλιν ἐνέπρησαν ἅπασαν καὶ τὴν χώραν. καὶ τὴν Ῥαάβην σὺν τοῖς οἰκείοις εἰς τὸ καταγώγιον συμφυγοῦσαν ἔσωσαν οἱ κατάσκοποι, καὶ πρὸς αὐτὸν Ἰησοῦς ἀχθείσῃ χάριν ἔχειν ὡμολόγει τῆς σωτηρίας τῶν κατασκόπων καὶ μὴν τῆς εὐεργεσίας ταύτης ἔλεγεν ἐν ταῖς ἀμοιβαῖς οὐχ ἥττονα φανήσεσθαι, δωρεῖται δ’ αὐτὴν εὐθὺς ἀγροῖς καὶ διὰ τιμῆς εἶχε τῆς πάσης.", "st": "5.1.7"}, {"sp": "N", "t": "Τῆς δὲ πόλεως εἰ καί τι παρέλθοι τὸ πῦρ κατέσκαπτε καὶ κατὰ τῶν οἰκησόντων, εἴ τις πορθηθεῖσαν ἀνεγείρειν ἐθελήσειεν, ἀρὰς ἔθετο, ὅπως θεμελίους μὲν τειχῶν βαλόμενος στερηθῇ τοῦ πρώτου παιδός, τελειώσας δὲ τὸν νεώτατον τῶν παίδων ἀποβάλῃ. τῆς δὲ ἀρᾶς τὸ θεῖον οὐκ ἠμέλησεν, ἀλλ’ ἐν τοῖς ὑστέροις ἀπαγγελοῦμεν τὸ περὶ αὐτὴν πάθος γενόμενον.", "st": "5.1.8"}, {"sp": "N", "t": "Ἄπειρον δέ τι πλῆθος ἐκ τῆς ἁλώσεως συναθροίζεται ἀργύρου τε καὶ χρυσοῦ καὶ προσέτι χαλκοῦ μηδενὸς παραβάντος τὰ δεδογμένα μηδ’ εἰς ἰδίαν ὠφέλειαν αὐτὰ διαρπασαμένων, ἀλλ’ ἀποσχομένων ὡς ἤδη τῷ θεῷ καθιερωμένων. καὶ ταῦτα μὲν Ἰησοῦς τοῖς ἱερεῦσιν εἰς τοὺς θησαυροὺς παραδίδωσι καταθέσθαι. καὶ Ἱεριχοῦς μὲν τοῦτον ἀπώλετο τὸν τρόπον.", "st": "5.1.9"}, {"sp": "N", "t": "Ἄχαρος δέ τις Ζεβεδαίου παῖς ὢν ἐκ τῆς Ἰούδα φυλῆς εὑρὼν χλαμύδα βασίλειον ἐκ χρυσοῦ μὲν πᾶσαν ὑφασμένην, μᾶζαν δὲ χρυσοῦ σταθμὸν ἕλκουσαν σίκλων διακοσίων καὶ δεινὸν ἡγησάμενος, εἰ ὃ κινδυνεύσας ηὕρατο κέρδος, τοῦτο τῆς ἰδίας χρείας ἀφελόμενος δοῦναι φέρων τῷ θεῷ καὶ μὴ δεομένῳ, ὄρυγμα βαθὺ ποιήσας ἐν τῇ αὐτοῦ σκηνῇ κατώρυξεν εἰς τοῦτο, λήσειν νομίζων ὡς τοὺς συστρατιώτας οὕτως καὶ τὸν θεόν.", "st": "5.1.10"}, {"sp": "N", "t": "Ἐκλήθη δὲ ὁ τόπος ἐν ᾧ στρατόπεδον ἐβάλετο Ἰησοῦς Γάλγαλα· σημαίνει δὲ τοῦτο ἐλευθέριον ὄνομα· διαβάντες γὰρ τὸν ποταμὸν ἐλευθέρους ἑαυτοὺς ἤδη ἀπό τε τῶν Αἰγυπτίων καὶ τῆς ἐν τῇ ἐρήμῳ ταλαιπωρίας ἐγίνωσκον.", "st": "5.1.11"}, {"sp": "N", "t": "Μετὰ δ’ ὀλίγας ἡμέρας τῆς Ἱεριχοῦντος συμφορᾶς πέμπει τρισχιλίους ὁπλίτας Ἰησοῦς εἰς Ναϊὰν πόλιν ὑπὲρ τῆς Ἱεριχοῦντος κειμένην αἱρήσοντας, οἳ συμβαλόντων αὐτοῖς τῶν Ναϊητῶν τραπέντες ἀποβάλλουσιν ἄνδρας ἓξ καὶ τριάκοντα. τοῦτ’ ἀγγελθὲν τοῖς Ἰσραηλίταις λύπην τε μεγάλην καὶ δεινὴν ἐποίησεν ἀθυμίαν οὐ κατὰ τὸ οἰκεῖον τῶν ἀπολωλότων, καίτοι γε πάντων ἀνδρῶν ἀγαθῶν καὶ σπουδῆς ἀξίων διεφθαρμένων, ἀλλὰ κατὰ ἀπόγνωσιν· πιστεύοντες γὰρ ἤδη τῆς γῆς ἐγκρατεῖς εἶναι καὶ σῶον ἕξειν ἐν ταῖς μάχαις τὸν στρατὸν οὕτως τοῦ θεοῦ προϋπεσχημένου, τεθαρρηκότας παραδόξως ἑώρων τοὺς πολεμίους· καὶ σάκκους ἐπενδύντες ταῖς στολαῖς δι’ ὅλης ἡμέρας ἐν δακρύοις ἦσαν καὶ πένθει τροφῆς οὐδεμίαν ἐπιζήτησιν ποιούμενοι, μειζόνως δὲ τὸ συμβεβηκὸς εἶχον ἀχθόμενοι.", "st": "5.1.12"}, {"sp": "N", "t": "Βλέπων δὲ οὕτως ὁ Ἰησοῦς τήν τε στρατιὰν καταπεπληγυῖαν καὶ περὶ τῶν ὅλων πονηρὰν ἤδη τὴν ἐλπίδα λαμβάνουσαν παρρησίαν λαμβάνει πρὸς τὸν θεόν· ἡμεῖς γὰρ εἶπεν οὐχ ὑπ’ αὐθαδείας προήχθημεν ὥστε ταύτην ὑπάγεσθαι τοῖς ὅπλοις τὴν γῆν, ἀλλὰ Μωυσέος τοῦ σοῦ δούλου πρὸς τοῦθ’ ἡμᾶς ἐξεγείραντος, ᾧ διὰ πολλῶν τεκμηρίων ἐπηγγέλλου κτήσασθαι παρέξειν ἡμῖν τήνδε τὴν γῆν καὶ τὸν στρατὸν ἡμῶν ἀεὶ τῶν πολεμίων ποιήσειν τοῖς ὅπλοις κρείττονα. τινὰ μὲν οὖν κατὰ τὰς ὑποσχέσεις ἡμῖν ἀπήντησε τὰς σάς, νῦν δὲ παρὰ δόξαν ἐπταικότες καὶ τῆς δυνάμεώς τινας ἀποβαλόντες ἐπὶ τούτοις ὡς οὐ βεβαίων τῶν παρὰ σοῦ καὶ ὧν προεῖπε Μωυσῆς ἀχθόμεθα καὶ χεῖρον ἡ τῶν μελλόντων ἐλπὶς ἡμᾶς ἀνιᾷ τῇ πρώτῃ πείρᾳ τοιαύτῃ συντυχόντας. ἀλλὰ σύ, δέσποτα, δύναμις γάρ σοι τούτων ἴασιν εὑρεῖν, τό τε παρὸν ἡμῶν λυπηρὸν νίκην παρασχόμενος καὶ τὸ περὶ τῶν αὖθις δύσελπι διακείμενον οὕτως τῆς διανοίας ἔξελε.", "st": "5.1.13"}, {"sp": "N", "t": "Ταῦτα μὲν Ἰησοῦς ἐπὶ στόμα πεσὼν ἠρώτα τὸν θεόν· χρηματίσαντος δὲ ἀνίστασθαι τοῦ θεοῦ καὶ καθαίρειν τὸν στρατὸν μιάσματος ἐν αὐτῷ γεγονότος κλοπῆς τε τῶν καθιερωμένων αὐτῷ χρημάτων τετολμημένης, διὰ γὰρ ταῦτα τὴν νῦν αὐτοῖς ἧτταν συμπεσεῖν, ἀναζητηθέντος δὲ τοῦ δράσαντος καὶ κολασθέντος νίκην αὐτοῖς ἀεὶ πορίζεσθαι τῶν πολεμίων, φράζει ταῦτα πρὸς τὸν λαὸν Ἰησοῦς, καὶ καλέσας Ἐλεάζαρον τὸν ἀρχιερέα καὶ τοὺς ἐν τέλει κατὰ φυλὴν ἐκλήρου. τούτου δὲ τὸ τετολμημένον ἐκ τῆς Ἰούδα φυλῆς δηλοῦντος κατὰ φατρίας πάλιν ταύτης προτίθησι τὸν κλῆρον. τὸ δ’ ἀληθὲς τοῦ κακουργήματος περὶ τὴν Ἀχάρου συγγένειαν ηὑρίσκετο. κατ’ ἄνδρα δὲ τῆς ἐξετάσεως γινομένης λαμβάνουσι τὸν Ἄχαρον· ὁ δ’ οὐκ ἔχων ἔξαρνος εἶναι τοῦ θεοῦ δεινῶς αὐτὸν ἐκπεριελθόντος ὡμολόγει τε τὴν κλοπὴν καὶ τὰ φώρια παρῆγεν εἰς μέσον. καὶ οὗτος μὲν εὐθὺς ἀναιρεθεὶς ἐν νυκτὶ ταφῆς ἀτίμου καὶ καταδίκῳ πρεπούσης τυγχάνει.", "st": "5.1.14"}, {"sp": "N", "t": "Ἰησοῦς δὲ ἁγνίσας τὸν στρατὸν ἐξῆγεν ἐπὶ τὴν Ναϊὰν αὐτὸς καὶ νυκτὸς τὰ περὶ τὴν πόλιν ἐνέδραις προλοχίσας ὑπὸ τὸν ὄρθρον συμβάλλει τοῖς πολεμίοις. τῶν δὲ μετὰ θράσους αὐτοῖς διὰ τὴν προτέραν νίκην ἐπιόντων ὑποχωρεῖν προσποιησάμενος ἕλκει τῷ τρόπῳ τούτῳ μακρὰν αὐτοὺς τῆς πόλεως διώκειν οἰομένους καὶ ὡς ἐπὶ νίκῃ καταφρονοῦντας. ἔπειτ’ ἀναστρέψας τὴν δύναμιν κατὰ πρόσωπον αὐτοῖς ποιεῖ, σημεῖά τε δοὺς ἃ πρὸς τοὺς ἐν ταῖς ἐνέδραις συνετέτακτο κἀκείνους ἐπὶ τὴν μάχην ἐξανίστησιν. οἱ δ’ εἰσεπήδων εἰς τὴν πόλιν τῶν ἔνδον περὶ τοῖς τείχεσιν ὄντων, ἐνίων δὲ καὶ πρὸς θέαν τῶν ἔξω τὴν γνώμην περισπωμένων. καὶ οἱ μὲν τὴν πόλιν ᾕρουν καὶ πάντας τοὺς ἐντυγχάνοντας ἔκτεινον, Ἰησοῦς δὲ τοὺς προσελθόντας εἰς χεῖρας βιασάμενος φυγεῖν τρέπεται, συνελαυνόμενοι δὲ ὡς εἰς ἀκέραιον τὴν πόλιν ἐπεὶ καὶ ταύτην ἐχομένην ἑώρων καὶ καταπιμπραμένην ὁμοῦ γυναιξὶ καὶ τέκνοις κατέλαβον, διὰ τῶν ἀγρῶν σκεδασθέντες καὶ ἀμύνειν αὐτοῖς ὑπὸ μονώσεως οὐ δυνάμενοι. τοιαύτης δὲ τῆς συμφορᾶς τοὺς Ναϊτιανοὺς καταλαβούσης, παίδων τε ὄχλος ἑάλω καὶ γυναικῶν καὶ θεραπείας καὶ τῆς ἄλλης ἀποσκευῆς ἄπειρόν τι πλῆθος, ἀγέλας τε βοσκημάτων ἔλαβον οἱ Ἑβραῖοι καὶ χρήματα πολλά, καὶ γὰρ πλούσιον ἦν τὸ χωρίον, καὶ ταῦτα πάντα τοῖς στρατιώταις Ἰησοῦς διένειμεν ἐν Γαλγάλοις γενόμενος.", "st": "5.1.15"}, {"sp": "N", "t": "Γεβεωνῖται δὲ κατοικοῦντες ἔγγιστα τοῖς Ἱεροσολύμοις τά τε τοῖς Ἱεριχουντίοις συμβεβηκότα πάθη καὶ τὰ τοῖς Ναϊτίνοις ὁρῶντες καὶ πρὸς σφᾶς μεταβήσεσθαι τὸ δεινὸν ὑπονοοῦντες, Ἰησοῦν μὲν παρακαλεῖν οὐ διέγνωσαν· οὐδὲ γὰρ τεύξεσθαί τινος τῶν μετρίων ὑπελάμβανον ἐπ’ ὀλέθρῳ τοῦ Χαναναίων ἔθνους παντὸς πολεμοῦντος αὐτούς· Κεφηρίτας δὲ καὶ Καριαθιαριμίτας γείτονας ὄντας αὐτοῖς ἐπὶ συμμαχίαν παρεκάλουν, οὐδ’ αὐτοὺς διαφεύξεσθαι τὸν κίνδυνον λέγοντες, εἰ φθάσαιεν αὐτοὶ ληφθέντες ὑπὸ τῶν Ἰσραηλιτῶν, συνασπίσαντας δὲ αὐτοῖς διέγνωσαν διαδρᾶναι τὴν δύναμιν αὐτῶν. προσδεξαμένων δὲ τοὺς λόγους αὐτῶν πέμπουσι πρέσβεις πρὸς Ἰησοῦν φιλίαν σπεισομένους οὓς μάλιστα τῶν πολιτῶν ἐδοκίμαζον ἱκανοὺς πρᾶξαι τὰ συμφέροντα τῷ πλήθει. οἱ δὲ ὁμολογεῖν αὑτοὺς Χαναναίους ἐπισφαλὲς ἡγούμενοι, διαφεύξεσθαι τὸν διὰ τοῦτο κίνδυνον ὑπολαμβάνοντες, εἰ λέγοιεν αὑτοὺς μὴ προσήκειν κατὰ μηδὲν Χαναναίοις ἀλλὰ πορρωτάτω τούτων κατοικεῖν, ἥκειν τε κατὰ πύστιν τῆς ἀρετῆς αὐτοῦ πολλὴν ἀνύσαντες ὁδὸν ἔφασκον καὶ τεκμήριον τοῦ λόγου τούτου τὸ σχῆμα ὑπεδείκνυον· τὰς γὰρ ἐσθῆτας καινὰς ὅτε ἐξῄεσαν οὔσας ὑπὸ τοῦ χρόνου τῆς ὁδοιπορίας αὐτοῖς τετρῖφθαι· τρυχίνας γὰρ εἰς τὸ ταῦτα πιστοῦσθαι πρὸς αὐτῶν ἐπίτηδες ἔλαβον. στάντες οὖν εἰς μέσους ἔλεγον, ὡς πεμφθεῖεν ὑπὸ τῶν Γεβεωνιτῶν καὶ τῶν περιοίκων πόλεων πλεῖστον ἀπεχουσῶν τῆσδε τῆς γῆς ποιησόμενοι πρὸς αὐτοὺς φιλίαν ἐφ’ αἷς πάτριον αὐτοῖς ἐστι συνθήκαις· μαθόντες γὰρ ἐκ θεοῦ χάριτος καὶ δωρεᾶς τὴν Χαναναίων αὐτοῖς γῆν κτήσασθαι δεδόσθαι τούτοις τ’ ἔλεγον ἥδεσθαι καὶ πολίτας ἀξιοῦν αὐτῶν γενέσθαι. καὶ οἱ μὲν ταῦτα λέγοντες καὶ ἐπιδεικνύντες τὰ τεκμήρια τῆς ὁδοιπορίας παρεκάλουν ἐπὶ συνθήκας καὶ φιλίαν τοὺς Ἑβραίους· Ἰησοῦς δὲ πιστεύσας οἷς ἔλεγον, ὡς οὐκ εἰσὶ τοῦ Χαναναίων ἔθνους, ποιεῖται πρὸς αὐτοὺς φιλίαν, καὶ Ἐλεάζαρος ὁ ἀρχιερεὺς μετὰ τῆς γερουσίας ὄμνυσιν ἕξειν τε φίλους καὶ συμμάχους καὶ μηδὲν μοχλεύσεσθαι κατ’ αὐτῶν ἄδικον τοῖς ὅρκοις ἐπισυναινέσαντος τοῦ πλήθους. καὶ οἱ μὲν ὧν ἤθελον τυχόντες ἐξ ἀπάτης ἀπῄεσαν πρὸς αὑτούς. Ἰησοῦς δὲ τῆς Χαναναίας στρατεύσας εἰς τὴν ὑπώρειον καὶ μαθὼν οὐ πόρρω τῶν Ἱεροσολύμων τοὺς Γεβεωνίτας κατῳκημένους καὶ τοῦ γένους ὄντας τῶν Χαναναίων, μεταπεμψάμενος αὐτῶν τοὺς ἐν τέλει τῆς ἀπάτης αὐτοῖς ἐνεκάλει. τῶν δ’ οὐκ ἄλλην ἀφορμὴν σωτηρίας ἔχειν ἢ ταύτην προφασιζομένων καὶ διὰ τοῦτ’ ἐπ’ αὐτὴν ἐξ ἀνάγκης καταφυγεῖν συγκαλεῖ τὸν ἀρχιερέα Ἐλεάζαρον καὶ τὴν γερουσίαν, καὶ δημοσίους αὐτοὺς δικαιούντων ποιεῖν ἐπὶ τῷ μὴ παραβῆναι τὸν ὅρκον ἀποδείκνυσιν εἶναι τοιούτους. καὶ οἱ μὲν τῆς καταλαβούσης αὐτοὺς συμφορᾶς τοιαύτην φυλακὴν καὶ ἀσφάλειαν εὕραντο.", "st": "5.1.16"}, {"sp": "N", "t": "Τοῦ δὲ τῶν Ἱεροσολυμιτῶν βασιλέως χαλεπῶς φέροντος ἐπὶ τῷ μετατάξασθαι πρὸς τὸν Ἰησοῦν τοὺς Γεβεωνίτας καὶ τοὺς τῶν πλησίον ἐθνῶν παρακαλέσαντος βασιλέας συνάρασθαι τῷ κατ’ αὐτῶν πολέμῳ, ὡς τούτους τε εἶδον παρόντας σὺν αὐτῷ, τέσσαρες δὲ ἦσαν, οἱ Γεβεωνῖται καὶ στρατοπεδευσαμένους ἐπί τινι πηγῇ τῆς πόλεως οὐκ ἄπωθεν παρασκευάζεσθαι πρὸς πολιορκίαν, ἐπεκαλοῦντο σύμμαχον Ἰησοῦν· ἐν τούτοις γὰρ ἦν αὐτοῖς τὰ πράγματα, ὡς ὑπὸ μὲν τούτων ἀπολεῖσθαι προσδοκᾶν, ὑπὸ δὲ τῶν ἐπ’ ὀλέθρῳ τοῦ Χαναναίων γένους στρατευσάντων σωθήσεσθαι διὰ τὴν γενομένην φιλίαν ὑπολαμβάνειν. καὶ Ἰησοῦς πανστρατιᾷ σπεύσας ἐπὶ τὴν βοήθειαν καὶ δι’ ἡμέρας καὶ νυκτὸς ἀνύσας ὄρθριος προσμίγνυσι τοῖς πολεμίοις καὶ τραπεῖσιν εἵπετο διώκων διὰ χωρίων ἐπικλινῶν, Βηθωρὰ καλεῖται. ἔνθα καὶ τὴν τοῦ θεοῦ συνεργίαν ἔμαθεν ἐπισημήναντος αὐτοῦ βρονταῖς τε καὶ κεραυνῶν ἀφέσει καὶ χαλάζης καταφορᾷ μείζονος τῆς συνήθους· ἔτι γε μὴν καὶ τὴν ἡμέραν αὐξηθῆναι πλέον, ὡς ἂν μὴ καταλαβοῦσα νὺξ ἐπίσχῃ τὸ τῶν Ἑβραίων πρόθυμον, συνέπεσεν, ὥστε καὶ λαμβάνει τοὺς βασιλέας Ἰησοῦς ἔν τινι κρυπτομένους σπηλαίῳ κατὰ Μακχίδα καὶ κολάζει πάντας. ὅτι δὲ τὸ μῆκος τῆς ἡμέρας ἐπέδωκε τότε καὶ τοῦ συνήθους ἐπλεόνασε, δηλοῦται διὰ τῶν ἀνακειμένων ἐν τῷ ἱερῷ γραμμάτων.", "st": "5.1.17"}, {"sp": "N", "t": "Κατεστραμμένων δ’ οὕτως τῶν περὶ τοὺς βασιλέας, οἳ τοὺς Γεβεωνίτας πολεμήσοντες ἐστράτευσαν, ἐπανῄει πάλιν τῆς Χαναναίας ἐπὶ τὴν ὀρεινὴν Ἰησοῦς καὶ πολὺν τῶν ἐν αὐτῇ φόνον ἐργασάμενος καὶ λείαν λαβὼν παρῆν εἰς τὸ ἐν Γαλγάλοις στρατόπεδον. τοῦ δὲ περὶ τῆς τῶν Ἑβραίων ἀρετῆς λόγου πολλοῦ φοιτῶντος εἰς τοὺς περιοίκους κατάπληξις εἶχε τοὺς ἀκούοντας τὸ τῶν ἀπολωλότων πλῆθος καὶ στρατεύουσιν ἐπ’ αὐτοὺς οἱ περὶ Λίβανον ὄρος βασιλεῖς ὄντες Χαναναῖοι καὶ οἱ ἐν τοῖς πεδίοις τῶν Χαναναίων Παλαιστίνους προσλαβόντες στρατοπεδεύουσι πρὸς Βηρώθῃ πόλει Γαλιλαίας τῆς ἄνω Κεδέσης οὐ πόρρω· Γαλιλαίων δ’ ἐστὶ καὶ τοῦτο τὸ χωρίον. τοῦ δὲ στρατοῦ παντὸς ὁπλιτῶν μὲν ἦσαν μυριάδες τριάκοντα μύριοι δ’ ἱππεῖς καὶ ἅρματα δισμύρια. καταπλήττει δὲ τὸ πλῆθος τῶν πολεμίων αὐτόν τε Ἰησοῦν καὶ τοὺς Ἰσραηλίτας καὶ πρὸς τὴν ἐλπίδα τοῦ κρείττονος εὐλαβεστέρως εἶχον δι’ ὑπερβολὴν τοῦ δέους. τοῦ θεοῦ δ’ ἐξονειδίσαντος αὐτοῖς τὸν φόβον καὶ τί πλέον τῆς παρ’ αὐτοῦ βοηθείας ποθοῦσιν, ὑποσχομένου τε νικήσειν τοὺς ἐχθροὺς καὶ κελεύσαντος τούς τε ἵππους ἀχρήστους ποιῆσαι καὶ τὰ ἅρματα πυρῶσαι, θαρσαλέος πρὸς τὰς ὑποσχέσεις τοῦ θεοῦ γενόμενος ἐξώρμησεν ἐπὶ τοὺς πολεμίους, καὶ διὰ πέμπτης ἡμέρας ἐπ’ αὐτοὺς ἐλθὼν συνάπτει καὶ καρτερὰ μάχη γίνεται καὶ φόνος κρείττων πίστεως παρὰ τοῖς ἀκροωμένοις. διώκων δ’ ἐπὶ πλεῖστον ἐξῆλθε καὶ πᾶν τὸ στράτευμα τῶν ἐχθρῶν πλὴν ὀλίγων διέφθειρε, καὶ οἱ βασιλεῖς πάντες ἔπεσον, ὥστε τῶν ἀνθρώπων ἐπιλελοιπότων πρὸς τὸ κτείνεσθαι τοὺς ἵππους Ἰησοῦς αὐτῶν ἀνῄρει καὶ τὰ ἅρματα ἐνεπίμπρα, τήν τε χώραν ἐπ’ ἀδείας διεπορεύετο μηδενὸς τολμῶντος εἰς μάχην ἐπεξελθεῖν, ἀλλὰ πολιορκίᾳ τὰς πόλεις αἱρῶν καὶ πᾶν ὅ τι λάβοι φονεύων.", "st": "5.1.18"}, {"sp": "N", "t": "Ἔτος δὲ πέμπτον ἤδη παρεληλύθει καὶ Χαναναίων οὐκέτ’ οὐδεὶς ὑπολέλειπτο πλὴν εἰ μή τινες ὀχυρότητι τειχῶν διέφυγον. Ἰησοῦς δ’ ἐκ τῶν Γαλγάλων ἀναστρατοπεδεύσας εἰς τὴν ὄρειον ἱστᾷ τὴν ἱερὰν σκηνὴν κατὰ Σιλοῦν πόλιν, ἐπιτήδειον γὰρ ἐδόκει τὸ χωρίον διὰ κάλλος, ἕως οἰκοδομεῖν ναὸν αὐτοῖς τὰ πράγματα παράσχοι. καὶ χωρήσας ἐντεῦθεν ἐπὶ Σικίμων σὺν ἅπαντι τῷ λαῷ βωμόν τε ἵστησιν ὅπου προεῖπε Μωυσῆς καὶ νείμας τὴν στρατιὰν ἐπὶ μὲν τῷ Γαριζεῖ ὄρει τὴν ἡμίσειαν ἵστησιν, ἐπὶ δὲ τῷ Ἡβήλῳ τὴν ἡμίσειαν ἐν ᾧ καὶ ὁ βωμός ἐστι καὶ τὸ Λευιτικὸν καὶ τοὺς ἱερέας. θύσαντες δὲ καὶ ἀρὰς ποιησάμενοι καὶ ταύτας ἐπὶ τῷ βωμῷ γεγραμμένας καταλιπόντες εἰς τὴν Σιλοῦν ἀνέζευξαν.", "st": "5.1.19"}, {"sp": "N", "t": "Ἰησοῦς δ’ ἤδη γηραιὸς ὢν καὶ τὰς τῶν Χαναναίων πόλεις ὁρῶν οὐκ εὐαλώτους ὑπό τε τῶν χωρίων ἐν οἷς ἦσαν ὀχυρότητος καὶ τῆς τῶν τειχῶν ἰσχύος, ἃ τῇ φυσικῇ τῶν πόλεων πλεονεξίᾳ προσεπιβαλλόμενοι προσεδόκων τοὺς πολεμίους ἀφέξεσθαι πολιορκίας δι’ ἀπόγνωσιν τοῦ λαβεῖν, καὶ γὰρ ἐπ’ ὀλέθρῳ τῷ ἑαυτῶν οἱ Χαναναῖοι μαθόντες τοὺς Ἰσραηλίτας ποιησαμένους τὴν ἔξοδον τὴν ἀπ’ Αἰγύπτου πρὸς τῷ τὰς πόλεις καρτερὰς ποιεῖν ἐκεῖνον ἅπαντ’ ἦσαν τὸν χρόνον, συναγαγὼν τὸν λαὸν εἰς τὴν Σιλοῦν ἐκκλησίαν παρήγγειλε. καὶ σπουδῇ συνδραμόντων τά τε ἤδη κατωρθωμένα καὶ τὰς γεγενημένας πράξεις, ὡς εἰσὶν ἄρισται καὶ τοῦ θείου τοῦ παρασχόντος αὐτὰς ἄξιαι καὶ τῆς ἀρετῆς τῶν νόμων οἷς κατακολουθοῦσιν ἔλεγε, βασιλεῖς τε τριάκοντα καὶ ἕνα τολμήσαντας αὐτοῖς εἰς χεῖρας ἐλθεῖν κεκρατῆσθαι δηλῶν καὶ στρατιὰν ὅση ποτὲ κατελπίσασα τῆς αὐτῶν δυνάμεως εἰς μάχην συνῆψεν ἅπασαν διαφθαρεῖσαν, ὡς μηδὲ γενεὰν αὐτοῖς ὑπολελεῖφθαι. τῶν δὲ πόλεων ἐπειδήπερ αἱ μὲν ἑαλώκεσαν, πρὸς ἃς δὲ δεῖ χρόνου καὶ μεγάλης πολιορκίας διὰ τὴν τῶν τειχῶν ὀχυρότητα καὶ τὴν ἐπὶ ταύτῃ τῶν οἰκητόρων πεποίθησιν, ἠξίου τοὺς ἐκ τῆς περαίας τοῦ Ἰορδάνου συνεξορμήσαντας αὐτοῖς καὶ τῶν κινδύνων συναραμένους ὄντας συγγενεῖς ἀπολύειν ἤδη πρὸς τὰ οἰκεῖα χάριν αὐτοῖς ὧν συνέκαμον ὁμολογοῦντας, ἕνα τε κατὰ φυλὴν ἀρετῇ προύχειν μαρτυρηθέντα πέμπειν, οἳ τὴν γῆν ἐκμετρησόμενοι πιστῶς καὶ μηδὲν κακουργήσοντες δηλώσουσιν ἡμῖν ἀδόλως αὐτῆς τὸ μέγεθος.", "st": "5.1.20"}, {"sp": "N", "t": "Καὶ Ἰησοῦς μὲν τούτους ποιησάμενος τοὺς λόγους συγκάταινον ἔσχε τὸ πλῆθος καὶ ἄνδρας τοὺς ἐκμετρησομένους τὴν χώραν αὐτῶν ἐξέπεμψε παραδοὺς αὐτοῖς τινας γεωμετρίας ἐπιστήμονας, οὓς τἀληθὲς οὐκ ἔμελλε λήσεσθαι διὰ τὴν τέχνην, ἐντολὰς δοὺς ἀποτιμήσασθαι τῆς τε εὐδαίμονος ἰδίᾳ τὸ μέτρον γῆς καὶ τῆς ἧσσον ἀγαθῆς. ἡ γὰρ φύσις τῆς Χαναναίων γῆς τοιαύτη τίς ἐστιν, ὡς ἴδοι τις ἂν πεδία μεγάλα καὶ καρποὺς φέρειν ἱκανώτατα καὶ συγκρινόμενα μὲν ἑτέρᾳ γῇ πανευδαίμονα νομισθησόμενα, τοῖς δ’ Ἱεριχουντίων χωρίοις παραβαλλόμενα καὶ τοῖς Ἱεροσολυμιτῶν τὸ μηδὲν ἀναφανησόμενα· καίτοι παντελῶς ὀλίγην αὐτῶν εἶναι τὴν γῆν συμβέβηκε ταύτης δὲ ὀρεινὴν τὴν πολλήν, ἀλλ’ ὑπερβολὴν εἰς καρπῶν ἐκτροφήν τε καὶ κάλλος οὐκ ἀπολέλοιπεν ἑτέρᾳ. καὶ διὰ τοῦτο τιμητοὺς μᾶλλον ἢ μετρητοὺς τοὺς κλήρους εἶναι δεῖν ὑπέλαβε πολλάκις ἑνὸς πλέθρου κἂν χιλίων ἀνταξίου γενομένου. οἱ δὲ ἄνδρες οἱ πεμφθέντες, δέκα δὲ ἦσαν, περιοδεύσαντες καὶ τιμησάμενοι τὴν γῆν ἐν ἑβδόμῳ μηνὶ παρῆσαν πρὸς αὐτὸν εἰς Σιλοῦντα πόλιν, ἔνθα τὴν σκηνὴν ἑστάκεσαν.", "st": "5.1.21"}, {"sp": "N", "t": "Καὶ Ἰησοῦς Ἐλεάζαρόν τε καὶ τὴν γερουσίαν σὺν τοῖς φυλάρχοις παραλαβὼν νέμει ταῖς ἐννέα φυλαῖς καὶ τῶν Μανασσητῶν τοῖς ἡμίσεσι, κατὰ μέγεθος ἑκάστης τῶν φυλῶν τὴν μέτρησιν ποιησάμενος. κληρώσαντος δὲ αὐτοῦ, ἡ μὲν Ἰούδα λαχοῦσα πᾶσαν αἱρεῖται τὴν καθύπερθεν Ἰδουμαίαν παρατείνουσαν μὲν ἄχρι τῶν Ἱεροσολύμων τὸ δ’ εὖρος ἕως τῆς Σοδομίτιδος λίμνης καθήκουσαν· ἐν δὲ τῷ κλήρῳ τούτῳ πόλεις ἦσαν Ἀσκάλων καὶ Γάζα. Σεμεωνὶς δέ, δευτέρα γὰρ ἦν, ἔλαχε τῆς Ἰδουμαίας τὴν Αἰγύπτῳ τε καὶ τῇ Ἀραβίᾳ πρόσορον οὖσαν. Βενιαμῖται δὲ τὴν ἀπὸ Ἰορδάνου ποταμοῦ ἔλαχον ἄχρι θαλάσσης μὲν τὸ μῆκος, τὸ δὲ πλάτος Ἱεροσολύμοις ὁριζομένην καὶ Βηθήλοις· στενώτατος δὲ ὁ κλῆρος οὗτος ἦν διὰ τὴν τῆς γῆς ἀρετήν· Ἱεριχοῦντα γὰρ καὶ τὴν Ἱεροσολυμιτῶν πόλιν ἔλαβον. ἡ δ’ Ἐφρὰν φυλὴ τὴν ἄχρι Γαζάρων ἀπὸ Ἰορδάνου ποταμοῦ μηκυνομένην ἔλαχεν, εὐρεῖαν δὲ ὅσον ἀπὸ Βεθήλων εἰς τὸ μέγα τελευτᾷ πεδίον, τῆς τε Μανασσήτιδος οἱ ἡμίσεις ἀπὸ μὲν Ἰορδάνου μέχρι Δώρων πόλεως, πλάτος δὲ ἐπὶ Βηθησάνων, ἣ νῦν Σκυθόπολις καλεῖται, καὶ μετὰ τούτους Ἰσαχαρὶς Κάρμηλόν τε τὸ ὄρος καὶ τὸν ποταμὸν τοῦ μήκους ποιησαμένη τέρμονα, τὸ δὲ Ἰταβύριον ὄρος τοῦ πλάτους. Ζαβουλωνῖται δὲ τὴν μέχρι Γενησαρίδος καθήκουσαν δὲ περὶ Κάρμηλον καὶ θάλασσαν ἔλαχον. τὴν δὲ ἀπὸ τοῦ Καρμήλου κοιλάδα προσαγορευομένην διὰ τὸ καὶ τοιαύτην εἶναι Ἀσηρῖται φέρονται πᾶσαν τὴν ἐπὶ Σιδῶνος τετραμμένην· Ἄρκη δὲ πόλις ὑπῆρχεν αὐτοῖς ἐν τῇ μερίδι ἡ καὶ Ἐκδείπους. τὰ δὲ πρὸς τὰς ἀνατολὰς τετραμμένα μέχρι Δαμασκοῦ πόλεως καὶ τῆς Γαλιλαίας τὰ καθύπερθεν Νεφθαλῖται παρέλαβον ἕως τοῦ Λιβάνου ὄρους καὶ τῶν τοῦ Ἰορδάνου πηγῶν, αἳ τὴν ὁρμὴν ἐκ τοῦ ὄρους ἔχουσιν, ἐκ τοῦ καθήκοντος τοῖς ὅροις κατὰ τὰ βόρεια πόλεως Ἄρκης παροικούσης. Δανῖται δὲ τῆς κοίλης ὅσα πρὸς δυόμενον τέτραπται τὸν ἥλιον λαγχάνουσιν Ἀζώτῳ καὶ Δώροις ὁριζόμενοι Ἰάμνειάν τε πᾶσαν καὶ Γίτταν ἀπ’ Ἀκκαρῶνος ἕως τοῦ ὄρους, ἐξ οὗ ἡ Ἰούδα ἦρκτο φυλή.", "st": "5.1.22"}, {"sp": "N", "t": "Καὶ ἓξ μὲν ἔθνη τῶν υἱέων τοῦ Χαναναίου φέροντα τὴν ἐπωνυμίαν διεῖλεν οὕτως Ἰησοῦς καὶ τὴν γῆν ταῖς ἐννέα καὶ τῇ ἡμισείᾳ φυλαῖς ἔδωκε νέμεσθαι· τὴν γὰρ Ἀμορρῖτιν καὶ αὐτὴν οὕτως ἀφ’ ἑνὸς τῶν Χαναναίου παίδων καλουμένην Μωυσῆς ἤδη προειληφὼς νενεμήκει ταῖς δυσὶ φυλαῖς καὶ τῷ ἡμίσει· τοῦτο δὲ καὶ πρότερον δεδηλώκαμεν. τὰ δὲ περὶ Σιδῶνα καὶ Ἀρουκαίους καὶ Ἀμαθαίους καὶ Ἀριδαίους ἀδιακόσμητα ἦν.", "st": "5.1.23"}, {"sp": "N", "t": "Ἰησοῦς δὲ τοῦ γήρως ἐμποδίζοντος ἤδη πράττειν ὅσα καὶ νοήσειε τῶν τε μετ’ αὐτὸν τὴν ἡγεμονίαν παραλαβόντων ἀμελῶς προστάντων τοῦ κοινῇ συμφέροντος, παρήγγειλέ τε φυλῇ ἑκάστῃ τοῦ γένους τῶν Χαναναίων μηδὲν ὑπολιπεῖν ἐν τῇ κατακεκληρωμένῃ γῇ· τὴν γὰρ ἀσφάλειαν αὐτοῖς καὶ τὴν φυλακὴν τῶν πατρίων ἐθῶν ἐν μόνῳ τούτῳ καὶ Μωυσῆν αὐτοῖς εἶναι προειπεῖν καὶ τοῦτ’ αὐτοὺς πεπεῖσθαι. καὶ τοῖς Λευίταις δὲ τὰς ὀκτὼ καὶ τριάκοντα πόλεις ἀποδιδόναι· προειλήφεισαν γὰρ ἤδη κατὰ τὴν Ἀμορραίαν τὰς δέκα. τούτων τρεῖς ἀπονέμει τοῖς φυγάσιν οἰκεῖν ἐν αὐταῖς, πολλὴ γὰρ ἦν πρόνοια τοῦ μηδὲν ὧν Μωυσῆς διέταξε παραλιπεῖν, τῆς μὲν οὖν Ἰούδα φυλῆς Ἰέβρωνα, Σίκιμα δὲ τῆς Ἐφραίμ, τῆς Νεφθαλίτιδος δὲ Κεδέσην· ἔστι τῆς καθύπερθεν Γαλιλαίας τοῦτο τὸ χωρίον. νέμει δὲ καὶ τῆς λείας ὅσα ἦν ἔτι λοιπά, πλείστη δ’ ἐγεγόνει, καὶ μεγάλους πλούτους περιεβέβληντο καὶ κοινῇ πάντες καὶ κατ’ ἰδίαν ἕκαστος χρυσοῦ τε καὶ ἀργύρου καὶ ἐσθήτων καὶ τῆς ἄλλης ἐπισκευῆς ἕνεκα, τετραπόδων τε πλήθους ὅσον οὐδὲ ἀριθμῷ μαθεῖν ἦν προσγενομένου.", "st": "5.1.24"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα συναγαγὼν εἰς ἐκκλησίαν τὸν στρατὸν τοῖς ὑπὲρ τὸν Ἰόρδανον κατὰ τὴν Ἀμορραίαν ἱδρυμένοις, συνεστράτευον δ’ αὐτοῖς πεντακισμύριοι ὁπλῖται, ἔλεξε τάδε· ἐπεὶ ὁ θεός, πατὴρ καὶ δεσπότης τοῦ Ἑβραίων γένους, γῆν τε κτήσασθαι ταύτην ἔδωκε καὶ κτηθεῖσαν εἰς ἅπαν ἡμετέραν φυλάξειν ὑπείσχηται, συνεργίας δὲ τῆς παρ’ ὑμῶν κατ’ ἐντολὴν τὴν ἐκείνου δεομένοις ἑαυτοὺς εἰς ἅπαν προθύμους ἐδώκατε, δίκαιον ὑμᾶς μηδενὸς ἔτι δυσκόλου περιμένοντος ἀναπαύσεως ἤδη τυχεῖν φειδοῖ τῆς προθυμίας ὑμῶν, ἵν’ εἰ καὶ πάλιν δεήσειεν ἡμῖν αὐτῆς ἄοκνον ἔχωμεν εἰς τὰ κατεπείξοντα καὶ μὴ τοῖς νῦν καμοῦσαν αὖθις βραδυτέραν. χάριν τε οὖν ὑμῖν ὧν συνήρασθε κινδύνων καὶ οὐχὶ νῦν μόνον ἀλλ’ ἀεὶ πάντως ἕξομεν, ὄντες ἀγαθοὶ μεμνῆσθαι τῶν φίλων καὶ παρὰ τῇ διανοίᾳ κρατεῖν ὅσα παρ’ αὐτῶν ἡμῖν ὑπῆρξεν, ὅτι τε τὴν ἀπόλαυσιν τῶν ὑπαρχόντων ὑμῖν ἀγαθῶν δι’ ἡμᾶς ἀνεβάλεσθε καὶ πονήσαντες εἰς ἃ νῦν εὐνοίᾳ θεοῦ κατέστημεν ἔπειθ’ οὕτως ἐκρίνατε αὐτῶν μεταλαμβάνειν. γέγονε δὲ πρὸς τοῖς ὑπάρχουσιν ἀγαθοῖς ἐκ τῶν σὺν ἡμῖν πόνων πλοῦτος ἄφθονος λείαν τε πολλὴν ἐπαξομένοις καὶ χρυσὸν καὶ ἄργυρον καὶ τὸ τούτων ἔτι πλεῖον, παρ’ ἡμῖν εὔνοια καὶ πρὸς ὅ τι βουληθείητε κατ’ ἀμοιβὴν πρόθυμον. οὔτε γὰρ ὧν Μωυσῆς προεῖπεν ἀπελείφθητε καταφρονήσαντες ἐξ ἀνθρώπων ἀπελθόντος οὔτ’ ἔστιν οὐδὲν ἐφ’ ᾧ μὴ χάριν ὑμῖν οἴδαμεν. χαίροντας οὖν ὑμᾶς ἐπὶ τὰς κληρουχίας ἀπολύομεν καὶ παρακαλοῦμεν μηδένα τῆς πρὸς ἡμᾶς συγγενείας ὅρον ὑπολαμβάνειν, μηδ’ ὅτι μεταξὺ ποταμὸς οὗτός ἐστιν ἑτέρους ἡμᾶς νομίσητε καὶ οὐχὶ Ἑβραίους. Ἁβράμου γὰρ ἅπαντές ἐσμεν οἵ τ’ ἐνθάδε κἀκεῖ κατοικοῦντες, θεός τε εἷς, ὃς τούς τε ἡμετέρους προγόνους καὶ τοὺς ὑμῶν αὐτῶν παρήγαγεν εἰς τὸν βίον· οὗ τῆς θρησκείας ἐπιμελεῖσθε καὶ πολιτείας, ἣν αὐτὸς διὰ Μωυσέος διέταξε, φυλακὴν ἔχετε τὴν πᾶσαν, ὡς ἐμμενόντων μὲν τούτοις καὶ τοῦ θεοῦ παρέξοντος εὔνουν εἶναι καὶ σύμμαχον ἑαυτόν, ἐκτραπέντων δὲ εἰς ἑτέρων ἐθνῶν μίμησιν ἀποστραφησομένου τὸ γένος ὑμῶν. ταῦτα εἰπὼν καὶ καθ’ ἕνα τοὺς ἐν τέλει καὶ κοινῇ τὸ πλῆθος αὐτῶν ἀσπασάμενος αὐτὸς μὲν ὑπέμεινε, προύπεμπε δ’ αὐτοὺς ὁ λαὸς οὐκ ἀδακρυτὶ καὶ μόλις ἀλλήλων ἀπελύθησαν.", "st": "5.1.25"}, {"sp": "N", "t": "Διαβᾶσα δὲ τὸν ποταμὸν ἥ τε Ῥουβηλὶς φυλὴ καὶ Γαδὶς καὶ ὅσοι τῶν Μανασσητῶν αὐτοῖς συνείποντο βωμὸν ὑπὲρ τῆς ὄχθης ἱδρύονται τοῦ Ἰορδάνου, μνημεῖον τοῖς ἔπειτα γενησόμενον [σύμβολον] τῆς πρὸς τοὺς πέραν κατῳκημένους οἰκειότητος. ἀκούσαντες δὲ οἱ πέραν βωμὸν ἱδρῦσθαι τοὺς ἀπολυθέντας οὐ μεθ’ ἧς ἐκεῖνοι γνώμης ἀνέστησαν αὐτόν, ἀλλ’ ἐπὶ νεωτερισμῷ καὶ ξενικῶν εἰσαγωγῇ θεῶν, οὐκ ἤθελον ἀπιστεῖν, ἀλλὰ περὶ θείαν θρησκείαν τὴν διαβολὴν πιθανὴν νομίζοντες ἐν ὅπλοις ἦσαν, ὡς ἐπ’ ἀμύνῃ τῶν τὸν βωμὸν ἱδρυσαμένων περαιωσόμενοι τὸν ποταμὸν καὶ κολάσοντες αὐτοὺς τῆς παρατροπῆς τῶν πατρίων ἐθῶν. οὐ γὰρ ἐδόκει τὴν συγγένειαν αὐτοὺς λογίζεσθαι καὶ τὸ ἀξίωμα τῶν τὴν αἰτίαν εἰληφότων, ἀλλὰ τὸ τοῦ θεοῦ βουλητὸν καὶ ᾧ τρόπῳ τιμώμενος χαίρει. καὶ οἱ μὲν ἐστράτευσαν ὑπ’ ὀργῆς, ἐπέσχε δ’ αὐτοὺς Ἰησοῦς καὶ ὁ ἀρχιερεὺς Ἐλεάζαρος καὶ ἡ γερουσία λόγοις συμβουλεύοντες ἀπόπειραν αὐτῶν τῆς γνώμης λαβεῖν πρῶτον, ἔπειτ’ ἂν κακοήθη μάθωσι τὴν διάνοιαν αὐτῶν τότε τοῖς. ὅπλοις χωρεῖν ἐπ’ αὐτούς. πέμπουσιν οὖν πρεσβευτὰς πρὸς αὐτοὺς Φινεέσην τὸν υἱὸν Ἐλεαζάρου καὶ δέκα σὺν αὐτῷ τῶν ἐν τιμῇ παρὰ τοῖς Ἑβραίοις μαθησομένους, τί καὶ φρονήσαντες τὸν βωμὸν ἐπὶ τῆς ὄχθης τοῦ ποταμοῦ διαβάντες ἔστησαν. ὡς δὲ περαιωσαμένων καὶ πρὸς αὐτοὺς ἀφικομένων ἐκκλησία συνελέγη, στὰς Φινεέσης μείζω μὲν αὐτοὺς ἁμαρτεῖν ἔλεγεν, ἢ ὥστε λόγοις ἐπιτιμηθέντας νενουθετῆσθαι πρὸς τὰ μέλλοντα πλὴν οὐ πρὸς τὸ μέγεθος τῆς παρανομίας ἀπιδόντας εὐθὺς ἐφ’ ὅπλα καὶ τὴν ἐκ χειρῶν τιμωρίαν ὁρμῆσαι, πρὸς δὲ τὸ συγγενὲς καὶ τὸ τάχα καὶ λόγοις ἂν σωφρονῆσαι σκοπήσαντας οὕτω ποιήσασθαι τὴν πρεσβείαν, ἵνα τὴν αἰτίαν μαθόντες ὑφ’ ἧς προήχθητε τὸν βωμὸν κατασκευάσαι μήτε προπετεῖς δοκῶμεν ὅπλοις μετιόντες ὑμᾶς κατὰ λογισμὸν ὅσιον ποιησαμένους τὸν βωμόν, κατι δικαίως ἀμυνώμεθα τῆς διαβολῆς ἐλεγχθείσης ἀληθοῦς. οὐ γὰρ ἠξιοῦμεν ὑμᾶς πείρᾳ τῆς τοῦ θεοῦ γνώμης ἐντὸς γεγενημένους καὶ νόμων ὧν αὐτὸς ἡμῖν δέδωκεν ἀκροατὰς ὑπάρχοντας, διαζευχθέντας ἡμῶν καὶ παρόντας εἰς τὸν ἴδιον κλῆρον, ὃν κατὰ χάριν τοῦ θεοῦ καὶ τῆς ἐκείνου περὶ ἡμᾶς προνοίας ἐλάχετε, λήθην λαβεῖν αὐτοῦ καὶ τὴν σκηνὴν καὶ τὴν κιβωτὸν καταλιπόντας καὶ βωμὸν ὃς ἡμῖν πάτριος ξενικοὺς θεοὺς ἐπιφέρειν τοῖς Χαναναίων κακοῖς προσκεχωρηκότας. ἀλλ’ οὐδὲν ἀδικεῖν δόξετε μετανοήσαντες καὶ μὴ περαιτέρω μανέντες νόμων δὲ πατρίων αἰδῶ καὶ μνήμην λαβόντες. ἂν δ’ ἐπιμένητε τοῖς ἡμαρτημένοις, οὐ περιστησόμεθα τὸν ὑπὲρ τῶν νόμων πόνον, ἀλλὰ περαιωσάμενοι τὸν Ἰόρδανον τούτοις βοηθήσομεν καὶ πρὸ αὐτῶν τῷ θεῷ, μηδὲν ὑμᾶς Χαναναίων διαφέρειν ὑπολαμβάνοντες ἀλλ’ ὁμοίως ἐκείνοις διαφθείροντες. μὴ γὰρ νομίσητε τῷ διαβεβηκέναι τὸν ποταμὸν καὶ τῆς τοῦ θεοῦ δυνάμεως ἔξω γεγονέναι πανταχοῦ δ’ ἐν τοῖς τούτου ἐστὲ καὶ ἀποδρᾶναι τὴν ἐξουσίαν αὐτοῦ καὶ τὴν ἀπὸ ταύτης δίκην ἀδύνατον. εἰ δ’ οἴεσθε τὴν ἐνθάδε παρουσίαν ὑμῖν ἐμπόδιον εἶναι τοῦ σωφρονεῖν, οὐδὲν κωλύει πάλιν τὴν γῆν ὑμᾶς ἀναδάσασθαι καὶ ταύτην ἀνεῖναι μηλόβοτον. ἀλλ’ εὖ ποιήσετε σωφρονήσαντες καὶ ἐπὶ νεαροῖς μετατιθέμενοι τοῖς ἁμαρτήμασι. καὶ παρακαλοῦμεν ὑμᾶς πρὸς παίδων καὶ γυναικῶν μὴ παρασχεῖν ἡμῖν ἀνάγκην ἀμύνασθαι. ὡς οὖν τῆς ὑμετέρας αὐτῶν σωτηρίας καὶ τῶν φιλτάτων ὑμῖν ἐν τῇδε τῇ ἐκκλησίᾳ κειμένης οὕτω βουλεύεσθε, λόγοις ἡττηθῆναι συμφέρειν ὑπολαμβάνοντες ἢ πεῖραν ἔργων καὶ πολέμου περιμένειν.", "st": "5.1.26"}, {"sp": "N", "t": "Τοσαῦτα τοῦ Φινεέσου διαλεχθέντος οἱ προεστῶτες τῆς ἐκκλησίας καὶ τὸ πλῆθος αὐτὸ πᾶν ἤρξαντο περὶ τῶν ἐγκεκλημένων αὐτοῖς ἀπολογεῖσθαι, καὶ μήτε συγγενείας τῆς πρὸς αὐτοὺς ἀποστήσεσθαι μήτε κατὰ νεωτερισμὸν ἀναστῆσαι τὸν βωμὸν λέγειν, ἀλλὰ θεόν τε ἕνα γινώσκειν τὸν Ἑβραίοις ἅπασι κοινὸν καὶ τὸν πρὸ τῆς σκηνῆς βωμὸν χάλκεον, ᾧ τὰς θυσίας ποιήσειν· τὸν μέντοι γε νῦν ἀνασταθέντα, δι’ ὃν καὶ ὕποπτοι γεγόνασιν, οὐ κατὰ θρησκείαν ἱδρῦσθαι, σύμβολον δὲ ὅπως εἴη καὶ τεκμήριον εἰς τὸν αἰῶνα τῆς πρὸς ὑμᾶς οἰκειότητος καὶ ἀνάγκη τοῦ σωφρονεῖν καὶ τοῖς πατρίοις ἐμμένειν, ἀλλ’ οὐχὶ παραβάσεως ἀρχήν, ὡς ὑπονοεῖτε. μάρτυς δ’ ἡμῖν τοῦ ἐπὶ τοιαύτῃ τὸν βωμὸν αἰτίᾳ κατασκευάσαι γένοιτο ὁ θεὸς ἀξιόχρεως, ὅθεν ἀμείνονα περὶ ἡμῶν ἔχοντες ὑπόληψιν μηδὲν καταγινώσκετε τούτων, ἐφ’ οἷς ἐξώλεις εἶναι δίκαιοι πάντες ὅσοι τοῦ Ἁβράμου γένους ὄντες νεωτέροις ἐπιχειροῦσιν ἔθεσι καὶ τοῦ συνήθους τρόπου παρηλλαγμένοις.", "st": "5.1.27"}, {"sp": "N", "t": "Ταῦτα εἰπόντας ἐπαινέσας ὁ Φινεέσης παρῆν πρὸς Ἰησοῦν καὶ τὰ παρ’ αὐτῶν ἀνήγγειλε τῷ λαῷ. ὁ δὲ χαίρων, ὅτι μηδεμία στρατολογεῖν αὐτοὺς ἀνάγκη μέλλει μηδ’ εἰς ὅπλα καὶ πόλεμον ἐξαγαγεῖν κατὰ ἀνδρῶν συγγενῶν, χαριστηρίους ὑπὲρ τούτων τῷ θεῷ θυσίας ἐπιτελεῖ. καὶ διαλύσας μετὰ ταῦτα τὸ πλῆθος εἰς τὰς ἰδίας κληρουχίας Ἰησοῦς αὐτὸς ἐν Σικίμοις διῆγεν. ἔτει δ’ ὕστερον εἰκοστῷ ὑπέργηρως ὢν μεταπεμψάμενος τοὺς ἐπ’ ἀξιώματος μάλιστα τῶν πόλεων καὶ τὰς ἀρχὰς καὶ τὴν γερουσίαν καὶ τοῦ πλήθους ὅσον ἦν ἐφικτὸν αὐτῷ συναγαγών, ἐπεὶ παρῆσαν, τάς τε εὐεργεσίας τοῦ θεοῦ ἁπάσας ἀνεμίμνησκεν αὐτούς, πολλαὶ δὲ ἦσαν τοῖς ἐκ ταπεινοῦ σχήματος εἰς τοῦτο δόξης καὶ περιουσίας προελθοῦσι, φυλάττειν τε τὴν τοῦ θεοῦ προαίρεσιν οὕτως ἔχουσαν πρὸς αὐτοὺς παρεκάλει καὶ τῇ εὐσεβείᾳ, ᾗ γε μόνῃ φίλον αὐτοῖς διαμένειν τὸ θεῖον· αὐτῷ γὰρ καλῶς ἔχειν ἀπιέναι μέλλοντι τοῦ ζῆν παραίνεσιν αὐτοῖς τοιαύτην καταλιπεῖν κἀκείνους ἠξίου διὰ μνήμης ποιήσασθαι τὴν παρακέλευσιν.", "st": "5.1.28"}, {"sp": "N", "t": "Καὶ ὁ μὲν τοσαῦτα πρὸς τοὺς παρόντας διαλεχθεὶς τελευτᾷ βιοὺς ἑκατὸν ἔτη καὶ δέκα, ὧν Μωυσεῖ μὲν ἐπὶ διδασκαλίᾳ τῶν χρησίμων συνδιέτριψεν τεσσαράκοντα, στρατηγὸς δὲ μετὰ τὴν ἐκείνου τελευτὴν γίνεται πέντε καὶ εἴκοσιν, ἀνὴρ [δὲ] μήτε συνέσεως ὢν ἐνδεὴς μήτε τοῦ τὰ νοηθέντα πρὸς τοὺς πολλοὺς σαφῶς ἐξενεγκεῖν ἄπειρος, ἀλλ’ ἐν ἀμφοτέροις ἄκρος πρός τε τὰ ἔργα καὶ τοὺς κινδύνους εὔψυχος καὶ μεγαλότολμος πρυτανεῦσαί τε τὰ κατὰ τὴν εἰρήνην δεξιώτατος καὶ πρὸς ἅπαντα καιρὸν τὴν ἀρετὴν ἡρμοσμένος. θάπτεται δὲ ἐν πόλει Θαμνᾶ τῆς Ἐφραίμου φυλῆς. θνήσκει δὲ ὑπ’ αὐτὸν τὸν καιρὸν καὶ Ἐλεάζαρος ὁ ἀρχιερεὺς Φινεέσῃ τῷ παιδὶ τὴν ἱερωσύνην καταλιπών, καὶ μνημεῖον αὐτῷ καὶ τάφος ἐν Γαβαθᾶ πόλει τυγχάνει.", "st": "5.1.29"}, {"sp": "N", "t": "Μετὰ δὲ τὴν τούτων τελευτὴν Φινεέσης προφητεύει κατὰ τὴν τοῦ θεοῦ βούλησιν ἐπ’ ἐξωλείᾳ τοῦ Χαναναίων γένους τῇ Ἰούδα φυλῇ παρασχεῖν τὴν ἡγεμονίαν· καὶ γὰρ τῷ λαῷ διὰ σπουδῆς ἦν μαθεῖν τί καὶ τῷ θεῷ δοκεῖ. καὶ προσλαβοῦσα τὴν Σεμεωνίδα, ἐφ’ ᾧτε ἐξαιρεθέντων τῶν ἐκείνης ὑποτελῶν καὶ τοὺς ἐν αὐτῇ τῇ κληρουχίᾳ τοῦτο ποιῶσιν", "st": "5.2.1"}, {"sp": "N", "t": "Χαναναῖοι δ’ ἀκμαζόντων αὐτοῖς κατ’ ἐκεῖνον τὸν καιρὸν τῶν πραγμάτων στρατῷ μεγάλῳ κατὰ Ζεβέκην αὐτοὺς ὑπέμενον τῷ βασιλεῖ τῶν Ζεβεκηνῶν Ἀδωνιζεβέκῳ τὴν ἡγεμονίαν ἐπιτρέψαντες· τὸ δὲ ὄνομα τοῦτο σημαίνει Ζεβεκηνῶν κύριος· ἀδωνὶ γὰρ τῇ Ἑβραίων διαλέκτῳ κύριος γίνεται· ἤλπιζόν τε κρατήσειν τῶν Ἰσραηλιτῶν διὰ τὸ τεθνάναι Ἰησοῦν. συμμίξαντες δὲ αὐτοῖς Ἰσραηλῖται ταῖς δυσὶ φυλαῖς αἷς προεῖπον ἐμαχέσαντο λαμπρῶς καὶ κτείνουσι μὲν αὐτῶν ὑπὲρ μυρίους, τρεψάμενοι δὲ τὸ λοιπὸν καὶ διώκοντες αἱροῦσι τὸν Ἀδωνιζέβεκον, ὃς ἀκρωτηριασθεὶς ὑπ’ αὐτῶν φησιν, ἀλλ’ οὐκ εἰς τὸ πᾶν ἄρα λήσεσθαι θεὸν ἔμελλον τάδε πεπονθώς, ἃ κατὰ δυοῖν καὶ ἑβδομήκοντα βασιλέων πρᾶξαι πρότερον οὐκ ἐνετράπην. καὶ ζῶντα μὲν κομίζουσιν ἕως Ἱεροσολύμων, τελευτήσαντα δὲ γῇ θάπτουσι. καὶ διεξῄεσαν αἱροῦντες τὰς πόλεις, πλείστας τε λαβόντες ἐπολιόρκουν Ἱεροσόλυμα· καὶ τὴν μὲν κάτω λαβόντες σὺν χρόνῳ πάντας ἔκτεινον τοὺς ἐνοικοῦντας, χαλεπὴ δ’ ἦν ἡ καθύπερθεν αὐτοῖς αἱρεθῆναι τειχῶν ὀχυρότητι καὶ φύσει τοῦ χωρίου.", "st": "5.2.2"}, {"sp": "N", "t": "Ὅθεν μετεστρατοπέδευσαν εἰς Νεβρῶνα καὶ ταύτην ἑλόντες κτείνουσι πάντας· ὑπελείπετο δὲ τῶν γιγάντων ἔτι γένος, οἳ διὰ σωμάτων μεγέθη καὶ μορφὰς οὐδὲν τοῖς ἄλλοις ἀνθρώποις παραπλησίας παράδοξον ἦσαν θέαμα καὶ δεινὸν ἄκουσμα. δείκνυται δὲ καὶ νῦν ἔτι τούτων ὀστᾶ μηδὲν τοῖς ὑπὸ πύστιν ἐρχομένοις ἐοικότα. καὶ τοῦτο μὲν τοῖς Λευίταις ἐξαίρετον γέρας ἔδοσαν μετὰ καὶ τῶν δισχιλίων πηχῶν, τὴν δὲ γῆν Χαλέβῳ δωρεὰν ἔδοσαν κατὰ Μωυσέος ἐντολάς· οὗτος δ’ ἦν τῶν κατασκόπων εἷς ὧν ἔπεμψε Μωυσῆς εἰς τὴν Χαναναίαν. διδόασι δὲ καὶ τοῖς Ἰέθρου τοῦ Μαδιανίτου ἀπογόνοις, Μωυσέος γὰρ ἦν γαμβρός, γῆν ἵνα νέμοιντο· τὴν γὰρ πατρίδα καταλιπόντες ἠκολούθησαν ἐκείνοις καὶ συνῆσαν αὐτοῖς ἐπὶ τῆς ἐρήμου.", "st": "5.2.3"}, {"sp": "N", "t": "Ἡ δὲ Ἰούδα φυλὴ καὶ Σεμεωνὶς τὰς μὲν κατὰ τὴν ὀρεινὴν τῆς Χαναναίας πόλεις εἷλον, τῶν δ’ ἐν τῷ πεδίῳ καὶ πρὸς θαλάσσῃ Ἀσκάλωνά τε καὶ Ἄζωτον. διαφεύγει δ’ αὐτοὺς Γάζα καὶ Ἀκκάρων· πεδίων γὰρ ὄντων καὶ πολλῆς ἁρμάτων εὐπορίας κακῶς ἐποίουν τοὺς ἐπελθόντας. καὶ αἵδε μὲν αἱ φυλαὶ μεγάλως ἐκ τοῦ πολεμεῖν εὐδαιμονήσασαι ἀνεχώρησαν εἰς τὰς ἑαυτῶν πόλεις καὶ κατατίθενται τὰ ὅπλα.", "st": "5.2.4"}, {"sp": "N", "t": "Βενιαμῖται δέ, τούτων γὰρ ἦν Ἱεροσόλυμα, τοῖς οἰκήτορσιν αὐτῶν συνεχώρησαν φόρους τελεῖν. καὶ οὕτως παυσάμενοι πάντες οἱ μὲν τοῦ κτείνειν οἱ δὲ κινδυνεύειν, ἐργάζεσθαι τὴν γῆν εὐσχόλουν. τὸ δ’ αὐτὸ καὶ αἱ λοιπαὶ φυλαὶ τὴν Βενιαμῖτιν μιμησάμεναι ἐποίουν καὶ τοῖς τελουμένοις ἀρκούμενοι φόροις ἐπέτρεπον τοῖς Χαναναίοις ἀπολέμοις εἶναι.", "st": "5.2.5"}, {"sp": "N", "t": "Ἡ δ’ Ἐφρὰν πολιορκοῦσα Βήθηλα τέλος οὐδὲν ἄξιον τοῦ χρόνου καὶ τῶν πόνων ηὕρισκε τῆς πολιορκίας, οἱ δὲ καίπερ ἀχθόμενοι τῇ καθέδρᾳ προσεκαρτέρουν. ἔπειτα συλλαβόντες τινὰ τῶν ἐν τῇ πόλει προελθόντα ἐπὶ κομιδῇ τῶν ἀναγκαίων τινὰς πίστεις ἔδοσαν αὐτῷ παραδιδόντι τὴν πόλιν σώσειν αὐτόν τε καὶ τοὺς συγγενεῖς αὐτοῦ. κἀκεῖνος ἐπὶ τούτοις ὤμνυε τὴν πόλιν αὐτοῖς ἐγχειριεῖν. καὶ ὁ μὲν οὕτως προδοὺς σώζεται μετὰ τῶν οἰκείων, οἱ δὲ ἀποκτείναντες ἅπαντας τοὺς ἐνοικοῦντας εἶχον τὴν πόλιν.", "st": "5.2.6"}, {"sp": "N", "t": "Καὶ μετὰ ταῦτα πρὸς μὲν τοὺς πολεμίους μαλακῶς εἶχον οἱ Ἰσραηλῖται, τῆς δὲ γῆς καὶ τῶν ταύτης ἔργων ἐπεμελοῦντο. τῶν δὲ κατὰ τὸν πλοῦτον αὐτοῖς ἐπιδιδόντων ὑπὸ τρυφῆς καὶ ἡδονῆς τοῦ κόσμου ὠλιγώρουν καὶ τῆς πολιτείας τῶν νόμων οὐκέτ’ ἦσαν ἀκριβεῖς ἀκροαταί. παροξυνθὲν δ’ ἐπὶ τούτοις τὸ θεῖον ἀναιρεῖ, πρῶτον μὲν ὡς φείσαιντο παρὰ τὴν αὐτοῦ γνώμην τῶν Χαναναίων, ἔπειθ’ ὡς ἐκεῖνοι χρήσοιντο πολλῇ κατ’ αὐτῶν ὠμότητι καιροῦ λαβόμενοι. οἱ δὲ καὶ πρὸς τὰ παρὰ τοῦ θεοῦ δυσθύμως εἶχον καὶ πρὸς τὸ πολεμεῖν ἀηδῶς πολλά τε παρὰ τῶν Χαναναίων λαβόντες καὶ πρὸς τοὺς πόνους ἤδη διὰ τὴν τρυφὴν ἐκλελυμένοι. καὶ συνέβαινεν ἤδη τὴν ἀριστοκρατίαν διεφθάρθαι, καὶ τὰς γερουσίας οὐκ ἀπεδείκνυσαν οὐδ’ ἀρχὴν ἄλλην οὐδεμίαν τῶν πρότερον νενομισμένων, ἦσαν δὲ ἐν τοῖς ἀγροῖς ἡδονῇ τοῦ κερδαίνειν προσδεδεμένοι. καὶ διὰ τὴν πολλὴν ἄδειαν στάσις αὐτοὺς πάλιν καταλαμβάνει δεινὴ καὶ προήχθησαν εἰς τὸ πολεμεῖν ἀλλήλοις ἐκ τοιαύτης αἰτίας.", "st": "5.2.7"}, {"sp": "N", "t": "Λευίτης ἀνὴρ τῶν δημοτικωτέρων τῆς Ἐφράνου κληρουχίας ὢν καὶ ἐν ἐκείνῃ κατοικῶν ἄγεται γύναιον ἀπὸ Βηθλέμων, τῆς δὲ Ἰούδα φυλῆς τοῦτ’ ἔστι τὸ χωρίον. ἐρῶν δὲ σφόδρα τῆς γυναικὸς καὶ τοῦ κάλλους αὐτῆς ἡττημένος ἠτύχει τῶν παρ’ ἐκείνης οὐχ ὁμοίων πειρώμενος. ἀλλοτρίως δ’ αὐτῆς ἐχούσης καὶ διὰ τοῦτο μᾶλλον ἐκκαιομένου τῷ πάθει μέμψεις συνεχεῖς αὐτοῖς ἐγίνοντο καὶ τέλος ἡ γυνὴ πρὸς αὐτὰς βαρυνομένη καταλιποῦσα τὸν ἄνδρα πρὸς τοὺς γονεῖς παραγίνεται μηνὶ τετάρτῳ. χαλεπῶς δὲ φέρων ὁ ἀνὴρ ἐπὶ τῷ ἔρωτι ἧκε πρὸς τοὺς πενθεροὺς καὶ διαλυσάμενος τὰς μέμψεις καταλλάττεται πρὸς αὐτήν. καὶ τέτταρας μὲν ἡμέρας προσαυτόθι διαιτᾶται φιλοφρονουμένων αὐτὸν τῶν γονέων, τῇ δὲ πέμπτῃ δόξαν ἀπιέναι πρὸς αὑτὸν περὶ δείλην ἔξεισι· βράδιον γὰρ ἀπέλυον οἱ γονεῖς τὴν θυγατέρα καὶ τῆς ἡμέρας τριβὴν ἐποιοῦντο. θεράπων δ’ αὐτοῖς εἷς εἵπετο καὶ ὄνος ἦν αὐτοῖς, ἐφ’ ἧς ὠχεῖτο τὸ γύναιον. γενομένων δ’ αὐτῶν κατὰ Ἱεροσόλυμα, σταδίους δ’ ἐληλύθεσαν ἤδη τριάκοντα, συνεβούλευεν ὁ θεράπων καταχθῆναί που, μὴ καί τι τῆς νυκτὸς αὐτοὺς ὁδεύοντας καταλάβῃ δύσκολον καὶ ταῦτα οὐδὲ πόρρω πολεμίων ὄντας, τοῦ καιροῦ πολλάκις ἐπισφαλῆ καὶ ὕποπτα ποιοῦντος καὶ τὰ φίλα. τῷ δ’ οὐκ ἤρεσεν ἡ γνώμη παρ’ ἀλλοφύλοις ἀνδράσι ξενοῦσθαι, Χαναναίων γὰρ ἦν ἡ πόλις, ἀλλὰ προελθόντας εἴκοσι στάδια εἰς οἰκείαν ἠξίου κατάγεσθαι πόλιν, καὶ κρατήσας τῇ γνώμῃ παρῆν εἰς Γαβὰν φυλῆς τῆς Βενιαμίτιδος ἤδη ὀψίας οὔσης. καὶ μηδενὸς ἐπὶ ξενίαν τῶν κατὰ τὴν ἀγορὰν αὐτὸν παρακαλοῦντος πρεσβύτης ἐξ ἀγροῦ κατιὼν τῆς μὲν Ἐφράμιος φυλῆς ὢν ἐν δὲ τῇ Γάβῃ διαιτώμενος συντυγχάνων αὐτῷ, τίς τε ὢν ἤρετο καὶ δι’ ἃς αἰτίας στελλόμενος σκότους ἤδη τὰ πρὸς τὸ δεῖπνον αὑτῷ λαμβάνοι. ὁ δὲ Λευίτης μὲν ἔφησεν εἶναι, γύναιον δὲ παρὰ τῶν γονέων ἄγων πρὸς αὐτὸν ἀπιέναι, τὴν δ’ οἴκησιν ἐδήλου τυγχάνειν ἐν τῇ Ἐφράμου κληρουχίᾳ. ὁ δὲ πρεσβύτης καὶ διὰ συγγένειαν καὶ διὰ τὸ τὴν αὐτὴν φυλὴν νέμειν καὶ διὰ τὴν συντυχίαν παρ’ αὐτὸν ξενισθησόμενον ἦγε. νεανίαι δέ τινες τῶν Γαβαηνῶν ἐπὶ τῆς ἀγορᾶς τὸ γύναιον θεασάμενοι καὶ τὴν εὐπρέπειαν θαυμάσαντες, ἐπεὶ παρὰ τῷ πρεσβύτῃ κατηγμένην ἔμαθον καταφρονήσαντες τῆς ἀσθενείας καὶ τῆς ὀλιγότητος ἧκον ἐπὶ τὰς θύρας. τοῦ δὲ πρεσβύτου παρακαλοῦντος ἀπαλλάττεσθαι καὶ μὴ προσφέρειν βίαν μηδὲ ὕβριν ἠξίουν αὐτὸν παρασχόντα τὴν ξένην πραγμάτων ἀπηλλάχθαι. συγγενῆ δὲ λέγοντος καὶ Λευῖτιν τοῦ πρεσβύτου καὶ δράσειν αὐτοὺς δεινὰ ὑφ’ ἡδονῆς εἰς τοὺς νόμους ἐξαμαρτάνοντας ὠλιγώρουν τοῦ δικαίου καὶ κατεγέλων, ἠπείλουν δὲ ἀποκτείνειν αὐτὸν ἐμποδίζοντα ταῖς ἐπιθυμίαις αὐτῶν. εἰς δ’ ἀνάγκην περιηγμένος καὶ μὴ βουλόμενος τοὺς ξένους περιιδεῖν ὑβρισθέντας τῆς ἑαυτοῦ θυγατρὸς αὐτοῖς παρεχώρει, πληρώσειν τε τὴν ἐπιθυμίαν αὐτοὺς λέγων νομιμώτερον δίχα τῆς εἰς τοὺς ξένους ὕβρεως αὐτός τε μηδὲν ἀδικήσειν οὓς ὑπεδέξατο τούτῳ τῷ τρόπῳ νομίζων. ὡς δ’ οὐδὲν τῆς σπουδῆς τῆς ἐπὶ τὴν ξένην ἐνεδίδοσαν, ἀλλὰ ἐνέκειντο ταύτην παραλαβεῖν ἀξιοῦντες, ὁ μὲν ἱκέτευε μηδὲν τολμᾶν παράνομον, οἱ δ’ ἁρπασάμενοι καὶ προσθέμενοι μᾶλλον τῷ βιαίῳ τῆς ἡδονῆς ἀπήγαγον πρὸς αὑτοὺς τὴν γυναῖκα καὶ δι’ ὅλης νυκτὸς ἐμπλησθέντες τῆς ὕβρεως ἀπέλυσαν περὶ ἀρχομένην ἡμέραν. ἡ δὲ τεταλαιπωρημένη τοῖς συμβεβηκόσι παρῆν ἐπὶ τὴν ξενίαν καὶ ὑπὸ λύπης ὧν ἐπεπόνθει καὶ τοῦ μὴ τολμᾶν ὑπ’ αἰσχύνης εἰς ὄψιν ἐλθεῖν τἀνδρί, τοῦτον γὰρ μάλιστα τοῖς γεγενημένοις ἔχειν ἀνιάτως ἐλογίζετο, καταπεσοῦσα τὴν ψυχὴν ἀφίησιν. ὁ δὲ ἀνὴρ αὐτῆς οἰόμενος ὕπνῳ βαθεῖ κατεισχῆσθαι τὴν γυναῖκα καὶ μηδὲν σκυθρωπὸν ὑφορώμενος ἀνεγείρειν ἐπειρᾶτο παραμυθήσασθαι διεγνωκώς, ὡς οὐκ ἐξ ἑκουσίου γνώμης αὑτὴν παράσχοι τοῖς καθυβρίσασιν, ἀλλ’ ἁρπασαμένων ἐπὶ τὴν ξενίαν ἐλθόντων αὐτῶν. ὡς δὲ τελευτήσασαν ἔμαθε, σωφρόνως πρὸς τὸ μέγεθος τῶν κακῶν ἐπιθέμενος τῷ κτήνει νεκρὰν τὴν γυναῖκα κομίζει πρὸς αὑτόν, καὶ διελὼν αὐτὴν κατὰ μέλος εἰς μέρη δώδεκα διέπεμψεν εἰς ἑκάστην φυλὴν ἐντειλάμενος τοῖς κομίζουσι λέγειν τοὺς αἰτίους τῆς τελευτῆς τῇ γυναικὶ καὶ τὴν παροινίαν τῆς φυλῆς.", "st": "5.2.8"}, {"sp": "N", "t": "Οἱ δ’ ὑπό τε τῆς ὄψεως καὶ τῆς ἀκοῆς τῶν βεβιασμένων κακῶς διατεθέντες πρότερον οὐδενὸς τοιούτου πεῖραν εἰληφότες, ὑπ’ ὀργῆς ἀκράτου καὶ δικαίας εἰς τὴν Σιλοῦν συλλεγέντες καὶ πρὸ τῆς σκηνῆς ἀθροισθέντες εἰς ὅπλα χωρεῖν εὐθὺς ὥρμηντο καὶ χρήσασθαι τοῖς Γαβαηνοῖς ὡς πολεμίοις. ἐπέσχε δ’ αὐτοὺς ἡ γερουσία πείσασα μὴ δεῖν ὀξέως οὕτως πρὸς τοὺς ὁμοφύλους ἐκφέρειν πόλεμον πρὶν ἢ λόγοις διαλεχθῆναι περὶ τῶν ἐγκλημάτων, τοῦ νόμου μηδ’ ἐπὶ τοὺς ἀλλοτρίους ἐφιέντος δίχα πρεσβείας καὶ τοιαύτης πρὸς τὸ μετανοῆσαι πείρας τοὺς δόξαντας ἀδικεῖν στρατιὰν ἀγαγεῖν· καλῶς οὖν ἔχει τῷ νόμῳ πειθομένους πρὸς τοὺς Γαβαηνοὺς ἐξαιτοῦντας τοὺς αἰτίους ἐκπέμψαι καὶ παρεχομένων μὲν ἀρκεῖσθαι τῇ τούτων κολάσει, καταφρονησάντων δὲ τότε τοῖς ὅπλοις αὐτοὺς ἀμύνασθαι. πέμπουσιν οὖν πρὸς τοὺς Γαβαηνοὺς κατηγοροῦντες τῶν νεανίσκων τὰ περὶ τὴν γυναῖκα καὶ πρὸς τιμωρίαν αἰτοῦντες τοὺς δράσαντας μὲν οὐ νόμιμα, γενομένους δὲ δικαίους ἀντ’ αὐτῶν ἐκείνων ἀποθανεῖν. οἱ δὲ Γαβαηνοὶ οὔτε τοὺς νεανίσκους ἐξέδοσαν καὶ δεινὸν ἀλλοτρίοις ὑπακούειν προστάγμασιν ἡγοῦντο πολέμου φόβῳ μηδενὸς ἀξιοῦντες εἶναι χείρους ἐν τοῖς ὅπλοις μήτε διὰ πλῆθος μήτε δι’ εὐψυχίαν. ἦσαν δὲ ἐν παρασκευῇ μεγάλῃ καὶ τῶν ἄλλων φυλετῶν, συναπενοήθησαν γὰρ αὐτοῖς ὡς ἀμυνούμενοι βιαζομένους.", "st": "5.2.9"}, {"sp": "N", "t": "Ὡς δὲ τοιαῦτα τοῖς Ἰσραηλίταις τὰ παρὰ τῶν Γαβαηνῶν ἀπηγγέλθη, ὅρκους ποιοῦνται μηδένα σφῶν ἀνδρὶ Βενιαμίτῃ δώσειν πρὸς γάμον θυγατέρα στρατεύσειν τε ἐπ’ αὐτούς, μᾶλλον αὐτοῖς δι’ ὀργῆς ὄντες ἢ τοῖς Χαναναίοις τοὺς προγόνους ἡμῶν παρειλήφαμεν γενομένους. παραχρῆμά τε ἐξῆγον ἐπ’ αὐτοὺς τὸ στρατόπεδον μυριάδας τεσσαράκοντα ὁπλιτῶν· καὶ Βενιαμιτῶν τὸ ὁπλιτικὸν ἦν ὑπὸ δισμυρίων καὶ πεντακισχιλίων καὶ ἑξακοσίων, ὧν ἦσαν εἰς πεντακοσίους ταῖς λαιαῖς τῶν χειρῶν σφενδονᾶν ἄριστοι, ὥστε καὶ μάχης πρὸς τῇ Γαβᾷ γενομένης τρέπουσι τοὺς Ἰσραηλίτας οἱ Βενιαμῖται ἄνδρες τε πίπτουσιν ἐξ αὐτῶν εἰς δισμυρίους καὶ δισχιλίους, ἐφθάρησαν δὲ ἴσως ἂν καὶ πλείονες, εἰ μὴ νὺξ αὐτοὺς ἐπέσχε καὶ διέλυσε μαχομένους. καὶ οἱ μὲν Βενιαμῖται χαίροντες ἀνεχώρουν εἰς τὴν πόλιν, οἱ δ’ Ἰσραηλῖται καταπεπληγότες ὑπὸ τῆς ἥττης εἰς τὸ στρατόπεδον. τῇ δ’ ἐπιούσῃ πάλιν συμβαλόντων οἱ Βενιαμῖται κρατοῦσι καὶ θνήσκουσι τῶν Ἰσραηλιτῶν ὀκτακισχίλιοι καὶ μύριοι, καὶ δείσαντες τὸν φόνον ἐξέλιπον τὸ στρατόπεδον. παραγενόμενοι δὲ εἰς Βέθηλα πόλιν ἔγγιστα κειμένην καὶ νηστεύσαντες κατὰ τὴν ὑστεραίαν τὸν θεὸν ἱκέτευον διὰ Φινεέσου τοῦ ἀρχιερέως παύσασθαι τῆς ὀργῆς τῆς πρὸς αὐτοὺς καὶ ταῖς δυσὶν αὐτῶν ἥτταις ἀρκεσθέντα δοῦναι νίκην καὶ κράτος κατὰ τῶν πολεμίων. ὁ δὲ θεὸς ἐπαγγέλλεται ταῦτα διὰ Φινεέσου προφητεύσαντος.", "st": "5.2.10"}, {"sp": "N", "t": "Ποιήσαντες οὖν τὴν στρατιὰν δύο μέρη τὴν μὲν ἡμίσειαν προλοχίζουσι νυκτὸς περὶ τὴν πόλιν, οἱ δ’ ἡμίσεις συνέβαλον τοῖς Βενιαμίταις ὑπεχώρουν τε ἐγκειμένων, καὶ ἐδίωκον οἱ Βενιαμῖται τῶν Ἑβραίων ὑποφευγόντων ἠρέμα καὶ ἐπὶ πολὺ θελόντων εἰς ἅπαν αὐτοὺς ἐξελθεῖν ἀναχωροῦσιν εἵποντο, ὡς καὶ τοὺς ἐν τῇ πόλει πρεσβύτας καὶ νέους ὑπολειφθέντας διεκδραμεῖν δι’ ἀσθένειαν αὐτοῖς πασσυδὶ βουλομένους χειρώσασθαι τοὺς πολεμίους. ὡς δὲ πολὺ τῆς πόλεως ἀπέσχον, ἐπαύσαντο μὲν φεύγοντες οἱ Ἑβραῖοι, ἐπιστραφέντες δ’ ἵστανται πρὸς μάχην καὶ τοῖς ἐν ταῖς ἐνέδραις οὖσι τὸ σημεῖον αἴρουσιν ὃ συνέκειτο. οἱ δ’ ἐξαναστάντες μετὰ βοῆς ἐπῄεσαν τοῖς πολεμίοις. οἱ δὲ ἅμα τε ἠπατημένους αὑτοὺς ᾔσθοντο καὶ ἐν ἀμηχανίᾳ συνεστήκεσαν, καὶ εἴς τι κοῖλον συνελαθέντας καὶ φαραγγῶδες χωρίον περιστάντες κατηκόντισαν, ὥστε πάντας διαφθαρῆναι πλὴν ἑξακοσίων. οὗτοι δὲ συστραφέντες καὶ πυκνώσαντες ἑαυτοὺς καὶ διὰ μέσων ὠσάμενοι τῶν πολεμίων ἔφυγον ἐπὶ τὰ πλησίον ὄρη, καὶ κατασχόντες ἱδρύθησαν. οἱ δ’ ἄλλοι πάντες περὶ δισμυρίους ὄντες καὶ πεντακισχιλίους ἀπέθανον. οἱ δ’ Ἰσραηλῖται τήν τε Γάβαν ἐμπιπρᾶσι καὶ τὰς γυναῖκας καὶ τῶν ἀρρένων τοὺς μὴ ἐν ἀκμῇ διεχρήσαντο, τάς τε ἄλλας τῶν Βενιαμιτῶν πόλεις ταὐτὰ δρῶσιν, οὕτως τε ἦσαν παρωξυμμένοι, ὡς καὶ Ἰάβησον τῆς Γαλαδίτιδος οὖσαν, ὅτι μὴ συμμαχήσειεν αὐτοῖς κατὰ τῶν Βενιαμιτῶν, πέμψαντες μυρίους καὶ δισχιλίους ἐκ τῶν τάξεων ἐκέλευσαν ἀνελεῖν. καὶ φονεύουσι τὸ μάχιμον τῆς πόλεως οἱ πεμφθέντες σὺν τέκνοις καὶ γυναιξὶ πλὴν τετρακοσίων παρθένων. ἐπὶ τοσοῦτον ὑπ’ ὀργῆς προήχθησαν τῷ κατὰ τὴν γυναῖκα πάθει προσλαβόντες καὶ τὸ κατὰ τὴν ἀναίρεσιν τῶν ὁπλιτῶν.", "st": "5.2.11"}, {"sp": "N", "t": "Μετάνοια δ’ αὐτοὺς λαμβάνει τῆς τῶν Βενιαμιτῶν συμφορᾶς καὶ νηστείαν ἐπ’ αὐτοῖς προέθεντο καίτοι δίκαια παθεῖν αὐτοὺς ἀξιοῦντες εἰς τοὺς νόμους ἐξαμαρτάνοντας, καὶ τοὺς διαφυγόντας αὐτῶν ἑξακοσίους διὰ πρεσβευτῶν ἐκάλουν· καθίδρυντο γὰρ ὑπὲρ πέτρας τινὸς Ῥοᾶς καλουμένης κατὰ τὴν ἔρημον. οἱ δὲ πρέσβεις ὡς οὐκ ἐκείνοις τῆς συμφορᾶς μόνοις γεγενημένης ἀλλὰ καὶ αὐτοῖς τῶν συγγενῶν ἀπολωλότων ὀδυρόμενοι πρᾴως ἔπειθον φέρειν καὶ συνελθεῖν εἰς ταὐτὸ καὶ μὴ παντελῆ τῆς Βενιαμίτιδος φυλῆς ὄλεθρον τό γε ἐπ’ αὐτοῖς καταψηφίσασθαι. συγχωροῦμεν δὲ ὑμῖν, ἔλεγον, τὴν ἁπάσης τῆς φυλῆς γῆν καὶ λείαν ὅσην ἂν ἄγειν δυνηθῆτε. οἱ δὲ τῶν καθ’ ἑαυτοὺς θεοῦ ψήφῳ γεγονότων καὶ κατ’ ἀδικίαν τὴν αὐτῶν γνωσιμαχήσαντες κατῄεσαν εἰς τὴν πάτριον φυλὴν πειθόμενοι τοῖς προκαλουμένοις. οἱ δ’ Ἰσραηλῖται γυναῖκας αὐτοῖς τὰς τετρακοσίας ἔδοσαν παρθένους τὰς Ἰαβίτιδας, περὶ δὲ τῶν διακοσίων ἐσκόπουν, ὅπως κἀκεῖνοι γυναικῶν εὐπορήσαντες παιδοποιῶνται. γεγενημένων δὲ αὐτοῖς ὅρκων ὥστε μηδενὶ Βενιαμίτῃ συνοικίσαι θυγατέρα πρὸ τοῦ πολέμου, οἱ μὲν ὀλιγωρεῖν συνεβούλευον τῶν ὀμωμοσμένων ὡς ὑπ’ ὀργῆς ὀμόσαντες οὐ γνώμῃ καὶ κρίσει, τῷ δὲ θεῷ μηδὲν ἐναντίον ποιήσειν εἰ φυλὴν ὅλην κινδυνεύουσαν ἀπολέσθαι σῶσαι δυνηθεῖεν, τάς τε ἐπιορκίας οὐχ ὅταν ὑπὸ ἀνάγκης γένωνται χαλεπὰς εἶναι καὶ ἐπισφαλεῖς, ἀλλ’ ὅταν ἐν κακουργίᾳ τολμηθῶσι. τῆς δὲ γερουσίας πρὸς τὸ τῆς ἐπιορκίας ὄνομα σχετλιασάσης ἔφη τις τούτοις τε γυναικῶν εὐπορίαν ἔχειν εἰπεῖν καὶ τήρησιν τῶν ὅρκων. ἐρομένων δὲ τὴν ἐπίνοιαν, ἡμῖν, εἶπεν, τρὶς τοῦ ἔτους εἰς Σιλὼ συνιοῦσιν ἕπονται κατὰ πανήγυριν αἱ γυναῖκες καὶ αἱ θυγατέρες. τούτων κατὰ ἁρπαγὴν ἐφείσθω γαμεῖν Βενιαμίτας ἃς ἂν δυνηθεῖεν ἡμῶν οὔτε προτρεπομένων οὔτε κωλυόντων. πρὸς δὲ τοὺς πατέρας αὐτῶν δυσχεραίνοντας καὶ τιμωρίαν λαμβάνειν ἀξιοῦντας φήσομεν αὐτοὺς αἰτίους φυλακῆς ἀμελήσαντας τῶν θυγατέρων, ὅτι δὲ δεῖ τῆς ὀργῆς ἐπὶ Βενιαμίτας ὑφεῖναι χρησαμένους αὐτῇ καὶ θᾶττον ἀμέτρως. καὶ οἱ μὲν τούτοις πεισθέντες ψηφίζονται τὸν διὰ τῆς ἁρπαγῆς γάμον τοῖς Βενιαμίταις. ἐνστάσης δὲ τῆς ἑορτῆς οἱ μὲν διακόσιοι κατὰ δύο καὶ τρεῖς πρὸ τῆς πόλεως ἐνήδρευον παρεσομένας τὰς παρθένους ἔν τε ἀμπελῶσι καὶ χωρίοις ἐν οἷς λήσειν ἔμελλον, αἱ δὲ μετὰ παιδιᾶς οὐδὲν ὑφορώμεναι τῶν μελλόντων ἀφυλάκτως ὥδευον· οἱ δὲ σκεδασθεισῶν εἴχοντο ἐξαναστάντες. καὶ οὗτοι μὲν οὕτως γαμήσαντες ἐπ’ ἔργα τῆς γῆς ἐχώρησαν καὶ πρόνοιαν ἐποιήσαντο πάλιν εἰς τὴν προτέραν εὐδαιμονίαν ἐπανελθεῖν. Βενιαμιτῶν μὲν οὖν ἡ φυλὴ κινδυνεύσασα τελέως ἐκφθαρῆναι τῷ προειρημένῳ τρόπῳ κατὰ τὴν Ἰσραηλιτῶν σοφίαν σώζεται ἤνθησέ τε παραχρῆμα καὶ ταχεῖαν εἴς τε πλῆθος καὶ τὰ ἄλλα πάντα ἐποιήσατο τὴν ἐπίδοσιν. οὗτος μὲν οὖν ὁ πόλεμος οὕτως παύεται.", "st": "5.2.12"}, {"sp": "N", "t": "Ὅμοια δὲ τούτοις παθεῖν καὶ τὴν Δάνην συνέβη φυλὴν ἐξ αἰτίας τοιαύτης εἰς τοῦτο προαχθεῖσαν. τῶν Ἰσραηλιτῶν ἐκλελοιπότων ἤδη τὴν ἐν τοῖς πολέμοις ἄσκησιν καὶ πρὸς τοῖς ἔργοις ὄντων τῆς γῆς Χαναναῖοι καταφρονήσαντες αὐτῶν συνεποιήσαντο δύναμιν, οὐδὲν μὲν αὐτοὶ πείσεσθαι προσδοκῶντες, ὡς δὲ βεβαίαν τὴν τοῦ ποιήσειν κακῶς τοὺς Ἑβραίους ἐλπίδα λαβόντες ἐπ’ ἀδείας τὸ λοιπὸν οἰκεῖν τὰς πόλεις ἠξίουν. ἅρματά τε οὖν παρεσκευάζοντο καὶ τὸ ὁπλιτικὸν συνεκρότουν αἵ τε πόλεις αὐτῶν συνεφρόνουν καὶ τῆς Ἰούδα φυλῆς τὴν Ἀσκάλωνα καὶ Ἀκαρῶνα παρεσπάσαντο ἄλλας τε πολλὰς τῶν ἐν τῷ πεδίῳ καὶ Δανίτας εἰς τὸ ὄρος ἠνάγκασαν συμφυγεῖν οὐδὲ ὀλίγον αὐτοῖς ἐπιβατὸν τοῦ πεδίου καταλιπόντες. οἱ δ’ οὔτε πολεμεῖν ὄντες ἱκανοὶ γῆν τε οὐκ ἔχοντες ἀρκοῦσαν πέμπουσιν ἐξ αὐτῶν πέντε ἄνδρας εἰς τὴν μεσόγειον κατοψομένους γῆν, εἰς ἣν μετοικήσαιντο. οἱ δ’ οὐ πόρρω τοῦ Λιβάνου ὄρους καὶ ἐλάσσονος Ἰορδάνου τῶν πηγῶν κατὰ τὸ μέγα πεδίον Σιδῶνος πόλεως ὁδὸν ἡμέρας μιᾶς προελθόντες καὶ κατασκεψάμενοι γῆν ἀγαθὴν καὶ πάμφορον σημαίνουσι τοῖς αὑτῶν· οἱ δ’ ὁρμηθέντες στρατῷ κτίζουσιν αὐτόθι πόλιν Δάνα ὁμώνυμον τῷ Ἰακώβου παιδὶ φυλῆς δ’ ἐπώνυμον τῆς αὐτῶν.", "st": "5.3.1"}, {"sp": "N", "t": "Τοῖς δ’ Ἰσραηλίταις προύβαινεν ὑπό τε ἀπειρίας τοῦ πονεῖν τὰ κακὰ καὶ ἀπὸ τῆς περὶ τὸ θεῖον ὀλιγωρίας· μετακινηθέντες γὰρ ἅπαξ τοῦ κόσμου τῆς πολιτείας ἐφέροντο πρὸς τὸ καθ’ ἡδονὴν καὶ βούλησιν ἰδίαν βιοῦν, ὡς καὶ τῶν ἐπιχωριαζόντων παρὰ τοῖς Χαναναίοις ἀναπίμπλασθαι κακῶν. ὀργίζεται τοίνυν αὐτοῖς ὁ θεὸς καὶ ἣν σὺν πόνοις μυρίοις εὐδαιμονίαν ἐκτήσαντο, ταύτην ἀπέβαλον διὰ τρυφήν. στρατεύσαντος γὰρ ἐπ’ αὐτοὺς Χουσαρσάθου τοῦ τῶν Ἀσσυρίων βασιλέως πολλούς τε τῶν παραταξαμένων ἀπώλεσαν καὶ πολιορκούμενοι κατὰ κράτος ᾑρέθησαν, εἰσὶ δ’ οἳ διὰ φόβον ἑκουσίως αὐτῷ προσεχώρησαν, φόρους τε τοῦ δυνατοῦ μείζονας ἐπιταγέντες ἐτέλουν καὶ ὕβρεις παντοίας ὑπέμενον ἕως ἐτῶν ὀκτώ, μεθ’ ἃ τῶν κακῶν οὕτως ἠλευθερώθησαν.", "st": "5.3.2"}, {"sp": "N", "t": "Τῆς Ἰούδα φυλῆς τις Κενίαζος ὄνομα δραστήριος ἀνὴρ καὶ τὸ φρόνημα γενναῖος, χρησθὲν αὐτῷ μὴ περιορᾶν ἐν τοιαύτῃ τοὺς Ἰσραηλίτας ἀνάγκῃ κειμένους ἀλλ’ εἰς ἐλευθερίαν αὐτοὺς ἐξαιρεῖσθαι τολμᾶν, παρακελευσάμενος συλλαμβάνεσθαι τῶν κινδύνων αὐτῷ τινάς, ὀλίγοι δ’ ἦσαν, οἷς αἰδὼς ἐπὶ τοῖς τότε παροῦσιν ἐτύγχανε καὶ προθυμία μεταβολῆς, πρῶτον μὲν τὴν παρ’ αὐτοῖς οὖσαν φρουρὰν τοῦ Χουσαρσάθου διαφθείρει, προσγενομένων δὲ πλειόνων τῶν συναγωνιζομένων ἐκ τοῦ μὴ διαμαρτεῖν περὶ τὰ πρῶτα τῆς ἐπιχειρήσεως, μάχην τοῖς Ἀσσυρίοις συνάπτουσι καὶ πρὸς τὸ παντελὲς αὐτοὺς ἀπωσάμενοι περαιοῦσθαι τὸν Εὐφράτην ἐβιάζοντο. Κενίαζος δὲ ὡς ἔργῳ πεῖραν αὐτοῦ δεδωκὼς τῆς ἀνδραγαθίας γέρας ὑπὲρ αὐτῆς λαμβάνει παρὰ τοῦ πλήθους ἀρχήν, ὥστε κρίνειν τὸν λαόν. καὶ ἄρξας ἐπ’ ἔτη τεσσαράκοντα καταστρέφει τὸν βίον.", "st": "5.3.3"}, {"sp": "N", "t": "Τελευτήσαντος δὲ τούτου πάλιν τὰ τῶν Ἰσραηλιτῶν ὑπὸ ἀναρχίας ἐνόσει πράγματα, καὶ τῷ μὴ διὰ τιμῆς ἄγειν τὸν θεὸν μηδὲ τοῖς νόμοις ὑπακούειν ἔτι μᾶλλον ἐκακοῦτο, ὡς καταφρονήσαντα αὐτῶν τῆς ἀκοσμίας τῆς κατὰ τὴν πολιτείαν Ἐγλῶνα τὸν Μωαβιτῶν βασιλέα πόλεμον πρὸς αὐτοὺς ἐξενεγκεῖν καὶ πολλαῖς μάχαις αὐτῶν κρατήσαντα καὶ τοὺς φρονήματι τῶν ἄλλων διαφέροντας ὑποτάξαντα πρὸς τὸ παντελὲς αὐτῶν τὴν δύναμιν ταπεινῶσαι καὶ φόρους αὐτοῖς ἐπιτάξαι τελεῖν. καθιδρύσας δ’ αὐτῷ ἐν Ἱεριχοῦντι βασίλειον ταύτην ἀποδείξας οὐδὲν τῆς εἰς τὸ πλῆθος κακώσεως παρέλιπεν εἴς τε πενίαν αὐτοὺς κατέστησεν ἐπὶ ὀκτωκαίδεκα ἔτη. λαβὼν δ’ οἶκτον ὁ θεὸς τῶν [Ἰσραηλιτῶν] ἐφ’ οἷς ἔπασχον καὶ ταῖς ἱκετείαις αὐτῶν ἐπικλασθεὶς ἀπήλλαξε τῆς ὑπὸ τοῖς Μωαβίταις ὕβρεως. ἠλευθερώθησαν δὲ τούτῳ τῷ τρόπῳ.", "st": "5.4.1"}, {"sp": "N", "t": "Τῆς Βενιαμίτιδος φυλῆς νεανίας Ἰούδης μὲν τοὔνομα Γήρα τε πατρὸς τολμῆσαί τε ἀνδρειότατος καὶ τῷ σώματι πρὸς τὰ ἔργα χρῆσθαι δυνατὸς τῶν χειρῶν τὴν ἀριστερὰν ἀμείνων κἀπ’ ἐκείνης τὴν ἅπασαν ἰσχὺν ἔχων κατῴκει μὲν ἐν Ἱεριχοῦντι καὶ αὐτός, συνήθης δὲ γίνεται τῷ Ἐγλῶνι δωρεαῖς αὐτὸν θεραπεύων καὶ ὑπερχόμενος, ὡς διὰ τοῦτο καὶ τοῖς περὶ τὸν βασιλέα προσφιλῆ τυγχάνειν αὐτόν. καί ποτε σὺν δυσὶν οἰκέταις δῶρα τῷ βασιλεῖ φέρων ξιφίδιον κρύφα τῷ δεξιῷ σκέλει περιδησάμενος εἰσῄει πρὸς αὐτόν. ὥρα δ’ ἦν θέρους καὶ τῆς ἡμέρας ἤδη μεσούσης ἀνεῖντο αἱ φυλακαὶ ὑπό τε τοῦ καύματος καὶ πρὸς ἄριστον τετραμμένων. δοὺς οὖν τὰ δῶρα τῷ Ἐγλῶνι ὁ νεανίσκος, διέτριβε δ’ ἔν τινι δωματίῳ δεξιῶς πρὸς θέρος ἔχοντι, πρὸς ὁμιλίαν ἐτράποντο. μόνοι δ’ ἦσαν τοῦ βασιλέως καὶ τοὺς ἐπεισιόντας τῶν θεραπόντων ἀπιέναι κελεύσαντος διὰ τὸ πρὸς Ἰούδην ὁμιλεῖν. καθῆστο δ’ ἐπὶ θρόνου καὶ δέος εἰσῄει τὸν Ἰούδην, μὴ διαμάρτῃ καὶ μὴ δῷ καιρίαν πληγήν. ἀνίστησιν οὖν αὐτὸν ὄναρ εἰπὼν ἔχειν ἐκ προστάγματος αὐτῷ δηλῶσαι τοῦ θεοῦ. καὶ ὁ μὲν πρὸς τὴν χαρὰν τὴν τοῦ ὀνείρατος ἀνεπήδησεν ἀπὸ τοῦ θρόνου, πλήξας δ’ αὐτὸν Ἰούδης εἰς τὴν καρδίαν καὶ τὸ ξιφίδιον ἐγκαταλιπὼν ἔξεισι προσκλίνας τὴν θύραν. οἵ τε θεράποντες ἠρέμουν εἰς ὕπνον τετράφθαι νομίζοντες τὸν βασιλέα.", "st": "5.4.2"}, {"sp": "N", "t": "Ὁ δ’ Ἰούδης τοῖς Ἱεριχουντίοις ἀποσημαίνων κρυπτῶς παρεκάλει τῆς ἐλευθερίας ἀντιλαμβάνεσθαι. οἱ δ’ ἀσμένως ἀκούσαντες αὐτοί τε εἰς τὰ ὅπλα ᾔεσαν καὶ διέπεμπον εἰς τὴν χώραν τοὺς ἀποσημαίνοντας κέρασιν οἰῶν· τούτοις γὰρ συγκαλεῖν τὸ πλῆθος πάτριον. οἱ δὲ περὶ τὸν Ἐγλῶνα πολὺν μὲν χρόνον ἠγνόουν τὸ συμβεβηκὸς αὐτῷ πάθος, ἐπεὶ δὲ πρὸς ἑσπέραν ἦν, δείσαντες μή τι νεώτερον εἴη περὶ αὐτὸν γεγονός, εἰσῆλθον εἰς τὸ δωμάτιον καὶ νεκρὸν εὑρόντες ἐν ἀμηχανίᾳ καθειστήκεσαν, καὶ πρὶν τὴν φρουρὰν συστραφῆναι τὸ τῶν Ἰσραηλιτῶν αὐτοῖς ἐπέρχεται πλῆθος. καὶ οἱ μὲν παραχρῆμα ἀναιροῦνται, οἱ δ’ εἰς φυγὴν τρέπονται ὡς ἐπὶ τὴν Μωαβῖτιν σωθησόμενοι, ἦσαν δὲ ὑπὲρ μυρίους. καὶ Ἰσραηλῖται προκατειληφότες τοῦ Ἰορδάνου τὴν διάβασιν διώκοντες ἔκτεινον καὶ κατὰ τὴν διάβασιν πολλοὺς αὐτῶν ἀναιροῦσι, διέφυγέ τε οὐδεὶς τὰς χεῖρας αὐτῶν. καὶ οἱ μὲν Ἑβραῖοι τούτῳ τῷ τρόπῳ τῆς ὑπὸ τοῖς Μωαβίταις δουλείας ἀπηλλάγησαν, Ἰούδης δ’ ἐκ τῆς αἰτίας ταύτης τιμηθεὶς τῇ τοῦ πλήθους παντὸς ἡγεμονίᾳ τελευτᾷ τὴν ἀρχὴν ἔτεσιν ὀγδοήκοντα κατασχών, ἀνὴρ καὶ δίχα τῆς προειρημένης πράξεως ἐπαίνου δίκαιος τυγχάνειν. καὶ μετὰ τοῦτον Σαάγαρος ὁ Ἀνάθου παῖς αἱρεθεὶς ἄρχειν ἐν τῷ πρώτῳ τῆς ἀρχῆς ἔτει κατέστρεψε τὸν βίον.", "st": "5.4.3"}, {"sp": "N", "t": "Ἰσραηλῖται δὲ πάλιν, οὐδὲν γὰρ ἐπὶ διδαχῇ τοῦ κρείττονος ἐλάμβανον τῶν πρότερον ἠτυχημένων ὑπό τε τοῦ μήτε σέβειν τὸν θεὸν μήθ’ ὑπακούειν τοῖς νόμοις, πρὶν ἢ καὶ τῆς ὑπὸ Μωαβίταις ἀναπνεῦσαι δουλείας πρὸς ὀλίγον Ἀβίτω τοῦ Χαναναίων βασιλέως δουλοῦνται. οὗτος γὰρ ἐξ Ἀσώρου πόλεως ὁρμώμενος, αὕτη δ’ ὑπέρκειται τῆς Σεμαχωνίτιδος λίμνης, στρατοῦ μὲν ὁπλιτῶν τριάκοντα ἔτρεφε μυριάδας μυρίους δὲ ἱππέας, τρισχιλίων δὲ ἁρμάτων ηὐπόρει. ταύτης οὖν στρατηγὸς τῆς δυνάμεως Σισάρης τιμῆς πρώτης παρὰ τῷ βασιλεῖ τυγχάνων συνελθόντας πρὸς αὐτὸν τοὺς Ἰσραηλίτας ἐκάκωσε δεινῶς, ὥστε αὐτοῖς ἐπιτάξαι τελεῖν φόρους.", "st": "5.5.1"}, {"sp": "N", "t": "Εἴκοσι μὲν οὖν ἔτη ταῦτα πάσχοντες ἤνυσαν μήτε αὐτοὶ φρονεῖν ὑπὸ τῆς δυστυχίας ὄντες ἀγαθοὶ καὶ τοῦ θεοῦ πλέον δαμάσαι ἔτι θέλοντος αὐτῶν τὴν ὕβριν διὰ τὴν περὶ αὐτὸν ἀγνωμοσύνην, ἵνα μεταθέμενοι τοῦ λοιποῦ σωφρονῶσιν διδαχθέντες τὰς συμφορὰς αὐτοῖς ἐκ τῆς περιφρονήσεως τῶν νόμων ὑπάρξαι, Δαβώραν [δέ] τινα προφῆτιν, μέλισσαν δὲ σημαίνει τοὔνομα κατὰ τὴν Ἑβραίων γλῶσσαν, ἱκέτευον δεηθῆναι τοῦ θεοῦ λαβεῖν οἶκτον αὐτῶν καὶ μὴ περιιδεῖν ἀπολλυμένους αὐτοὺς ὑπὸ Χαναναίων. ὁ δὲ θεὸς ἐπένευσε σωτηρίαν αὐτοῖς καὶ στρατηγὸν αἱρεῖται Βάρακον τῆς Νεφθαλίδος ὄντα φυλῆς· βάρακος δέ ἐστιν ἀστραπὴ κατὰ τὴν Ἑβραίων γλῶσσαν.", "st": "5.5.2"}, {"sp": "N", "t": "Μεταπεμψαμένη δ’ ἡ Δαβώρα τὸν Βάρακον ἐπιλέξαντα τῶν νέων μυρίους ἐκέλευε χωρεῖν ἐπὶ τοὺς πολεμίους· ἀποχρῆναι γὰρ τοσούτους τοῦ θεοῦ προειρηκότος καὶ νίκην ἀποσημήναντος. Βαράκου δὲ φαμένου οὐ στρατηγήσειν μὴ κἀκείνης αὐτῷ συστρατηγούσης ἀγανακτήσασα, σὺ μέν, εἶπε, γυναικὶ παραχωρεῖς ἀξίωμα ὃ σοὶ δέδωκεν ὁ θεός, ἐγὼ δὲ οὐ παραιτοῦμαι. καὶ συναριθμήσαντες μυρίους ἐστρατοπεδεύσαντο πρὸς Ἰταβυρίῳ ὄρει. ἀπήντα δ’ αὐτοῖς ὁ Σισάρης τοῦ βασιλέως κελεύσαντος καὶ στρατοπεδεύονται τῶν πολεμίων οὐκ ἄπωθεν. τοὺς δ’ Ἰσραηλίτας καὶ τὸν Βάρακον καταπλαγέντας τὸ πλῆθος τῶν πολεμίων καὶ ἀναχωρεῖν διεγνωκότας ἡ Δεβώρα κατεῖχε τὴν συμβολὴν ποιεῖσθαι κατ’ ἐκείνην κελεύουσα τὴν ἡμέραν· νικήσειν γὰρ αὐτοὺς καὶ συλλήψεσθαι τὸν θεόν.", "st": "5.5.3"}, {"sp": "N", "t": "Συνῄεσαν οὖν καὶ προσμιγέντων ὄμβρος ἐπιγίνεται μέγας καὶ ὕδωρ πολὺ καὶ χάλαζα, τόν τε ὑετὸν κατὰ πρόσωπον ἤλαυνε τῶν Χαναναίων ἄνεμος ταῖς ὄψεσιν αὐτῶν ἐπισκοτῶν, ὡς τὰς τοξείας ἀχρήστους αὐτοῖς εἶναι καὶ τὰς σφενδόνας· οἵ τε ὁπλῖται διὰ τὸ κρύος χρῆσθαι τοῖς ξίφεσιν οὐκ εἶχον. τοὺς δ’ Ἰσραηλίτας ἧττόν τε ἔβλαπτε κατόπιν γινόμενος ὁ χειμὼν καὶ πρὸς τὴν ἔννοιαν τῆς βοηθείας τοῦ θεοῦ θάρσος ἐλάμβανον, ὥστε εἰς μέσους ὠσάμενοι τοὺς πολεμίους πολλοὺς αὐτῶν ἀπέκτειναν. καὶ οἱ μὲν ὑπὸ τῶν Ἰσραηλιτῶν, οἱ δ’ ὑπὸ τῆς οἰκείας ἵππου ταραχθέντες ἔπεσον, ὡς ὑπὸ τῶν ἁρμάτων πολλοὺς αὐτῶν ἀποθανεῖν. Σισάρης δὲ καταπηδήσας τοῦ ἅρματος ὡς εἶδε τὴν τροπὴν γινομένην, φυγὼν ἀφικνεῖται παρά τινα τῶν Κενελίδων γυναῖκα Ἰάλην ὄνομα, ἣ κρύψαι τε ἀξιώσαντα δέχεται καὶ ποτὸν αἰτήσαντι δίδωσι γάλα διεφθορὸς ἤδη. ὁ δὲ πιὼν τοῦ μέτρου δαψιλέστερον εἰς ὕπνον τρέπεται. ἡ δὲ Ἰάλη κοιμωμένου σιδήρεον ἧλον ἐλάσασα σφύρῃ κατὰ τοῦ στόματος καὶ τοῦ χελυνίου διέπειρε τὸ ἔδαφος καὶ τοῖς περὶ τὸν Βάρακον μικρὸν ὕστερον ἐλθοῦσιν ἐπεδείκνυε τῇ γῇ προσηλωμένον. καὶ οὕτως μὲν ἡ νίκη αὕτη περιέστη κατὰ τὰ ὑπὸ Δαβώρας εἰρημένα εἰς γυναῖκα. Βάρακος δὲ στρατεύσας ἐπ’ Ἄσωρον Ἰοαβινόν τε ὑπαντιάσαντα κτείνει καὶ τοῦ στρατηγοῦ πεσόντος καθελὼν εἰς ἔδαφος τὴν πόλιν στρατηγεῖ τῶν Ἰσραηλιτῶν ἐπ’ ἔτη τεσσαράκοντα.", "st": "5.5.4"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Βαράκου καὶ Δαβώρας κατὰ τὸν αὐτὸν καιρὸν μετὰ ταῦτα Μαδιηνῖται παρακαλέσαντες Ἀμαληκίτας τε καὶ Ἄραβας στρατεύουσιν ἐπὶ τοὺς Ἰσραηλίτας καὶ μάχῃ τε νικῶσι τοὺς συμβαλόντας καὶ τὸν καρπὸν δῃώσαντες τὴν λείαν ἐπήγοντο. τοῦτο δὲ ποιούντων ἐπ’ ἔτη ἑπτὰ εἰς τὰ ὄρη τῶν Ἰσραηλιτῶν ἀνεστάλη τὸ πλῆθος καὶ τῶν πεδίων ἐξεχώρουν ὑπονόμους τε καὶ σπήλαια ποιησάμενοι πᾶν ὅ τι τοὺς πολεμίους διέφυγεν ἐν τούτοις εἶχον φυλάττοντες. οἱ γὰρ Μαδιηνῖται κατὰ ὥραν θέρους στρατεύοντες τὸν χειμῶνα γεωργεῖν τοῖς Ἰσραηλίταις ἐπέτρεπον, ὅπως ἔχωσι πεπονηκότων αὐτῶν εἰς ἃ βλάπτωσι. λιμὸς δ’ ἦν καὶ σπάνις τροφῆς καὶ τρέπονται πρὸς ἱκετείαν τοῦ θεοῦ σώζειν αὐτοὺς παρακαλοῦντες.", "st": "5.6.1"}, {"sp": "N", "t": "Καὶ Γεδεὼν ὁ Ἰάσου παῖς Μανασσίδος φυλῆς ἐν ὀλίγοις δράγματα σταχύων φερόμενος κρυπτῶς εἰς τὴν ληνὸν ἔκοπτε· τοὺς γὰρ πολεμίους ἐδεδίει φανερῶς τοῦτο ποιεῖν ἐπὶ τῆς ἅλωος. φαντάσματος δὲ αὐτῷ παραστάντος νεανίσκου μορφῇ καὶ φήσαντος εὐδαίμονα καὶ φίλον τῷ θεῷ, ὑποτυχών τοῦτο γοῦν, ἔφη, τεκμήριον τῆς εὐμενείας αὐτοῦ μέγιστον τῇ ληνῷ με νῦν ἀντὶ ἅλωος χρῆσθαι. θαρσεῖν δὲ παρακελευσαμένου καὶ πειρᾶσθαι τῆς ἐλευθερίας ἀνασώζειν ἀδυνάτως ἔχειν ἔλεγε· τήν τε γὰρ φυλὴν ἐξ ἧς ὑπῆρχε πλήθους ὑστερεῖν καὶ νέον αὐτὸν εἶναι καὶ τηλικούτων πραγμάτων ἀσθενέστερον. ὁ δὲ θεὸς αὐτὸς ἀναπληρώσειν τὸ λεῖπον ἐπηγγέλλετο καὶ νίκην παρέξειν Ἰσραηλίταις αὐτοῦ στρατηγοῦντος.", "st": "5.6.2"}, {"sp": "N", "t": "Τοῦτ’ οὖν διηγούμενος ὁ Γεδεὼν τισὶ τῶν νέων ἐπιστεύετο, καὶ παραχρῆμα πρὸς τοὺς ἀγῶνας ἕτοιμον ἦν τὸ στρατόπεδον μυρίων ἀνδρῶν. ἐπιστὰς δὲ κατὰ τοὺς ὕπνους ὁ θεὸς τῷ Γεδεῶνι τὴν ἀνθρωπίνην φύσιν αὐτῷ φίλαυτον οὖσαν ἐδήλου καὶ πρὸς τοὺς ἀρετῇ διαφέροντας ἀπεχθανομένην, ὅπως τε τὴν νίκην παρέντες τοῦ θεοῦ δοκεῖν νομίζουσιν ἰδίαν ὡς πολὺς στρατὸς ὄντες καὶ πρὸς τοὺς πολεμίους ἀξιόμαχος. ἵνα μάθωσιν οὖν βοηθείας τῆς αὐτοῦ τὸ ἔργον, συνεβούλευε περὶ μεσοῦσαν τὴν ἡμέραν ἐν ἀκμῇ τοῦ καύματος ὄντος ἄγειν τὴν στρατιὰν ἐπὶ τὸν ποταμὸν καὶ τοὺς μὲν κατακλιθέντας καὶ οὕτως πίνοντας εὐψύχους ὑπολαμβάνειν, ὅσοι δ’ ἂν ἐσπευσμένως καὶ μετὰ θορύβου πίνοντες τύχοιεν τούτους δειλοὺς νομίζειν καὶ καταπεπληγότας τοὺς πολεμίους. ποιήσαντος δὲ τοῦ Γεδεῶνος κατὰ τὰς ὑποθήκας τοῦ θεοῦ τριακόσιοι ἄνδρες εὑρέθησαν ταῖς χερσὶ μετὰ φόβου προσενεγκάμενοι τὸ ὕδωρ τεταραγμένως, ἔφησέ τε ὁ θεὸς τούτους ἐπαγόμενον ἐπιχειρεῖν τοῖς πολεμίοις. ἐστρατοπεδεύοντο δὲ ὑπὲρ τοῦ Ἰορδάνου μέλλοντες εἰς τὴν ἐπιοῦσαν περαιοῦσθαι.", "st": "5.6.3"}, {"sp": "N", "t": "Γεδεῶνος δ’ ἐν φόβῳ καθεστῶτος, καὶ γὰρ νυκτὸς ἐπιχειρεῖν αὐτῷ ὁ θεὸς προειρήκει, τοῦ δέους αὐτὸν ἀπαγαγεῖν βουλόμενος κελεύει προσλαβόντα ἕνα τῶν στρατιωτῶν πλησίον χωρεῖν ταῖς Μαδιηνιτῶν σκηναῖς· παρ’ αὐτῶν γὰρ ἐκείνων λήψεσθαι φρόνημα καὶ θάρσος. πεισθεὶς δὲ ᾔει Φρουρὰν τὸν ἑαυτοῦ θεράποντα παραλαβών, καὶ πλησιάσας σκηνῇ τινι καταλαμβάνει τοὺς ἐν αὐτῇ ἐγρηγορότας καὶ τὸν ἕτερον ὄναρ διηγούμενον τῷ συσκηνοῦντι, ὥστε ἀκούειν τὸν Γεδεῶνα. τὸ δὲ τοιοῦτον ἦν· μᾶζαν ἐδόκει κριθίνην ὑπ’ εὐτελείας ἀνθρώποις ἄβρωτον διὰ τοῦ στρατοπέδου κυλιομένην τὴν τοῦ βασιλέως σκηνὴν καταβαλεῖν καὶ τὰς τῶν στρατιωτῶν πάντων. ὁ δὲ σημαίνειν ὄλεθρον τοῦ στρατοῦ τὴν ὄψιν ἔκρινε λέγων, ὅθεν τοῦτ’ αὐτῷ συνιδεῖν ἐπῆλθε, πᾶν τὸ σπέρμα τὸ καλούμενον κρίθινον εὐτελέστατον ὁμολογεῖσθαι τυγχάνειν, τοῦ δ’ Ἀσιανοῦ παντὸς τὸ Ἰσραηλιτῶν ἔστιν ἰδεῖν ἀτιμότερον νῦν γεγενημένον ὅμοιον δὲ τῷ κατὰ κριθὴν γένει. καὶ τὸ παρὰ τοῖς Ἰσραηλίταις νῦν μεγαλοφρονοῦν τοῦτ’ ἂν εἴη Γεδεὼν καὶ τὸ σὺν αὐτῷ στρατιωτικόν. ἐπεὶ οὖν τὴν μᾶζαν φῂς ἰδεῖν τὰς σκηνὰς ἡμῶν ἀνατρέπουσαν, δέδια μὴ θεὸς Γεδεῶνι τὴν καθ’ ἡμῶν νίκην ἐπινένευκε.", "st": "5.6.4"}, {"sp": "N", "t": "Γεδεῶνα δ’ ἀκούσαντα τὸ ὄναρ ἐλπὶς ἀγαθὴ καὶ θάρσος ἔλαβε καὶ προσέταξεν ἐν τοῖς ὅπλοις εἶναι τοὺς οἰκείους διηγησάμενος αὐτοῖς καὶ τὴν τῶν πολεμίων ὄψιν, οἱ δ’ ἕτοιμοι πρὸς τὰ παραγγελλόμενα φρονηματισθέντες ὑπὸ τῶν δεδηλωμένων ἦσαν. καὶ κατὰ τετάρτην μάλιστα φυλακὴν προσῆγε τὴν ἑαυτοῦ στρατιὰν Γεδεὼν εἰς τρία μέρη διελὼν αὐτήν, ἑκατὸν δὲ ἦσαν ἐν ἑκάστῳ. ἐκόμιζον δὲ πάντες ἀμφορέας κενοὺς καὶ λαμπάδας ἡμμένας ἐν αὐταῖς, ὅπως μὴ κατάφωρος τοῖς πολεμίοις ἡ ἔφοδος αὐτῶν γένηται, καὶ ἐν τῇ δεξιᾷ κριοῦ κέρας· ἐχρῶντο δὲ τούτοις ἀντὶ σάλπιγγος. χωρίον δὲ πολὺ κατεῖχε τὸ τῶν πολεμίων στράτευμα, πλείστην γὰρ αὐτοῖς εἶναι συνέβαινε κάμηλον, καὶ κατὰ τὰ ἔθνη νεμηθέντες ὑφ’ ἑνὶ κύκλῳ πάντες ἦσαν. οἱ δ’ Ἑβραῖοι, προειρημένον αὐτοῖς ὁπόταν γένωνται πλησίον τῶν πολεμίων ἐκ συνθήματος σάλπιγξί τε ἠχήσαντας καὶ τοὺς ἀμφορέας κατεάξαντας ὁρμῆσαι μετὰ τῶν λαμπάδων ἀλαλάξαντας καὶ νικᾶν θεοῦ Γεδεῶνι βοηθήσοντος, τοῦτ’ ἐποίησαν. ταραχὴ δὲ λαμβάνει τοὺς ἀνθρώπους ἔτι [τε] ὑπνοῦντας καὶ δείματα· νὺξ γὰρ ἦν καὶ ὁ θεὸς τοῦτο ἤθελεν. ἐκτείνοντο δὲ ὀλίγοι μὲν ὑπὸ τῶν πολεμίων, οἱ δὲ πλείους ὑπὸ τῶν συμμάχων διὰ τὸ τῇ γλώσσῃ διαφωνεῖν. ἅπαξ δὲ καταστάντες εἰς ταραχὴν πᾶν τὸ προστυχὸν ἀνῄρουν νομίζοντες εἶναι πολέμιον, φόνος τε πολὺς ἦν. καὶ φήμῃ πρὸς τοὺς Ἰσραηλίτας τῆς Γεδεῶνος νίκης ἀφικομένης ἐν τοῖς ὅπλοις ἦσαν, καὶ διώξαντες λαμβάνουσι τοὺς πολεμίους ἐν κοίλῳ τινὶ χαράδραις περιειλημμένῳ οὐ δυναμέναις διαπερᾶναι χωρίῳ καὶ περιστάντες κτείνουσιν ἅπαντας καὶ δύο τῶν βασιλέων Ὤρηβόν τε καὶ Ζῆβον. οἱ δὲ λοιποὶ τῶν ἡγεμόνων τοὺς περιλειφθέντας τῶν στρατιωτῶν ἐνάγοντες, ἦσαν δὲ μύριοι καὶ ὀκτακισχίλιοι, στρατοπεδεύονται πολὺ τῶν Ἰσραηλιτῶν ἄπωθεν. Γεδεὼν δὲ οὐκ ἀπηγορεύκει πονῶν, ἀλλὰ διώξας μετὰ παντὸς τοῦ στρατοῦ καὶ συμβαλὼν ἅπαντας διέφθειρε τοὺς πολεμίους καὶ τοὺς λοιποὺς ἡγεμόνας Ζεβὴν καὶ Ζαρμούνην αἰχμαλώτους λαβὼν ἀνήγαγεν. ἀπέθανον δ’ ἐν αὐτῇ τῇ μάχῃ Μαδιηνιτῶν τε καὶ τῶν συστρατευσάντων αὐτοῖς Ἀράβων περὶ μυριάδας δώδεκα, λεία τε πολλὴ χρυσὸς καὶ ἄργυρος καὶ ὕφη καὶ κάμηλος καὶ ὑποζύγια λαμβάνεται τοῖς Ἑβραίοις. Γεδεὼν δὲ παραγενόμενος εἰς Ἐφρὰν τὴν ἑαυτοῦ πατρίδα κτείνει τοὺς τῶν Μαδιηνιτῶν βασιλέας.", "st": "5.6.5"}, {"sp": "N", "t": "Ἡ δ’ Ἐφράμιδος φυλὴ τῇ Γεδεῶνος εὐπραγίᾳ δυσχεραίνουσα στρατεύειν ἐπ’ αὐτὸν διεγνώκει, τὸ μὴ προαγγεῖλαι τὴν ἐπιχείρησιν αὐτοῖς τὴν κατὰ τῶν πολεμίων ἐγκαλοῦντες. Γεδεὼν δὲ μέτριος ὢν καὶ πᾶσαν ἀρετὴν ἄκρος οὐκ αὐτὸς ἔλεγεν αὐτοκράτορι χρησάμενος λογισμῷ τοῖς ἐχθροῖς ἐπιθέσθαι χωρὶς αὐτῶν, ἀλλὰ τοῦ θεοῦ κελεύσαντος· τὴν δὲ νίκην οὐχ ἧττον αὐτῶν ἔφασκεν ἰδίαν ἢ τῶν ἐστρατευκότων εἶναι. καὶ τούτοις παρηγορήσας αὐτῶν τὴν ὀργὴν τοῖς λόγοις μᾶλλον τοὺς Ἑβραίους ὠφέλησε τῆς ἐπὶ τῶν πολεμίων εὐπραξίας [φήσας αἰτίους]· ἐμφυλίου γὰρ αὐτοὺς στάσεως ἄρχειν μέλλοντας ἐρρύσατο. τῆς μέντοι ὕβρεως ταύτης ἡ φυλὴ δίκην ἐξέτισεν, ἣν δηλώσομεν κατὰ καιρὸν ἴδιον.", "st": "5.6.6"}, {"sp": "N", "t": "Γεδεὼν δὲ τὴν ἀρχὴν ἀποθέσθαι βουλόμενος βιασθεὶς ἔσχεν αὐτὴν ἐπ’ ἔτη τεσσαράκοντα βραβεύων αὐτοῖς τὰ δίκαια καὶ περὶ τῶν διαφορῶν ἐπ’ αὐτὸν βαδιζόντων κύρια πάντα ἦν τὰ ὑπ’ αὐτοῦ λεγόμενα. καὶ ὁ μὲν γηραιὸς τελευτήσας ἐν Ἐφρὰν τῇ πατρίδι θάπτεται.", "st": "5.6.7"}, {"sp": "N", "t": "Παῖδες δὲ ἦσαν αὐτῷ γνήσιοι μὲν ἑβδομήκοντα, πολλὰς γὰρ ἔγημε γυναῖκας, νόθος δ’ εἷς ἐκ παλλακῆς Δρούμας Ἀβιμέλεχος τοὔνομα, ὃς μετὰ τὴν τοῦ πατρὸς τελευτὴν ἀναχωρήσας εἰς Σίκιμα πρὸς τοὺς ἀπὸ μητρὸς συγγενεῖς, ἐντεῦθεν γὰρ ἦν, καὶ λαβὼν ἀργύριον παρ’ αὐτῶν, οἳ διὰ πλῆθος ἀδικημάτων ἦσαν ἐπίσημοι, ἀφικνεῖται σὺν αὐτοῖς εἰς τὸν πατρῷον οἶκον καὶ κτείνει πάντας τοὺς ἀδελφοὺς πλὴν Ἰωθάμου· σώζεται γὰρ οὗτος διαφυγεῖν εὐτυχήσας. Ἀβιμέλεχος δὲ εἰς τυραννίδα τὰ πράγματα μεθίστησι κύριον αὑτὸν ὅ τι βούλεται ποιεῖν ἀντὶ τῶν νομίμων ἀποδείξας καὶ δεινῶς πρὸς τοὺς τοῦ δικαίου προϊσταμένους ἐκπικραινόμενος.", "st": "5.7.1"}, {"sp": "N", "t": "Καί ποτε δημοτελοῦς Σικίμοις οὔσης ἑορτῆς καὶ τοῦ πλήθους παντὸς ἐκεῖ συνειλεγμένου ὁ ἀδελφὸς αὐτοῦ Ἰωθάμης, ὃν καὶ διαφυγεῖν ἔφαμεν, ἀνελθὼν ἐπὶ τὸ ὄρος τὸ Γαριζείν, ὑπέρκειται δὲ τῆς Σικιμίων πόλεως, ἐκβοήσας εἰς ἐπήκοον τοῦ πλήθους ἡσυχίαν αὐτῷ παρασχόντος ἠξίου μαθεῖν τὰ ὑπ’ αὐτοῦ λεγόμενα. γενομένης δὲ σιγῆς εἶπεν, ὡς τὰ δένδρα φωνὴν ἀνθρώπειον προϊέμενα συνόδου γενομένης αὐτῶν δεηθείη συκῆς ἄρχειν αὐτῶν. ἀρνησαμένης δ’ ἐκείνης διὰ τὸ τιμῆς τῆς ἐπὶ τοῖς καρποῖς οἰκείας οὔσης ἀπολαύειν οὐχ ὑπ’ ἄλλων ἔξωθεν προσγινομένης, τὰ δένδρα τῆς ἐπὶ τῷ ἄρχεσθαι φροντίδος οὐκ ἀπελείπετο, ἐδόκει δ’ αὐτοῖς ἀμπέλῳ τὴν τιμὴν παρασχεῖν. καὶ ἡ ἄμπελος χειροτονουμένη τοῖς τῆς συκῆς χρησαμένη λόγοις παρῃτεῖτο τὴν ἀρχήν. τὸ δ’ αὐτὸ καὶ τῶν ἐλαιῶν ποιησαμένων ῥάμνος, ἐδεήθη γὰρ αὐτῆς ὥστε παραλαβεῖν τὴν βασιλείαν τὰ δένδρα, πυρεῖα δὲ ἀγαθὴ παρασχεῖν τῶν ξύλων ἐστίν, ὑπισχνεῖται τὴν ἀρχὴν ἀναλήψεσθαι καὶ ἀόκνως ἔχειν. δεῖ μέντοι συνιζάνειν αὐτὰ ὑπὸ τὴν σκιάν, εἰ δ’ ὄλεθρον ἐπ’ αὐτῇ φρονοῖεν, ὑπὸ τοῦ ἐνόντος πυρὸς διαφθαρεῖεν. ταῦτα δ’ οὐ γέλωτος ἕνεκα, φησί, λέγω, ὅτι δὲ πολλῶν ἀγαθῶν ἐκ Γεδεῶνος πεπειραμένοι περιορῶσιν Ἀβιμέλεχον ἐπὶ τῶν ὅλων ὄντα πραγμάτων σὺν αὐτῷ τοὺς ἀδελφοὺς ἀποκτείναντες, ὃν πυρὸς οὐδὲν διοίσειν. καὶ ὁ μὲν ταῦτα εἰπὼν ὑπεχώρησε καὶ διῃτᾶτο λανθάνων ἐν τοῖς ὄρεσι δεδιὼς ἐπ’ ἔτη τρία τὸν Ἀβιμέλεχον.", "st": "5.7.2"}, {"sp": "N", "t": "Μετ’ οὐ πολὺ δὲ τῆς ἑορτῆς Σικιμῖται, μετενόησαν γὰρ ἐπὶ τοῖς Γεδεῶνος υἱοῖς πεφονευμένοις, ἐξελαύνουσι τὸν Ἀβιμέλεχον τῆς πόλεως καὶ τῆς φυλῆς· ὁ δὲ κακοῦν τὴν πόλιν ἐφρόντιζε. τῆς δ’ ὥρας τῆς τοῦ τρυγᾶν γενομένης ἐδεδίεσαν συλλέγειν τὸν καρπὸν προϊόντες μή τι δράσῃ κακὸν Ἀβιμέλεχος εἰς αὐτούς. ἐπιδημήσαντος δὲ πρὸς αὐτοὺς τῶν ἀρχόντων τινὸς Γυάλου σὺν ὁπλίταις καὶ συγγενέσι τοῖς αὐτοῦ φυλακὴν οἱ Σικιμῖται δέονται παρασχεῖν αὐτοῖς, ἕως ἂν τρυγήσωσι. προσδεξαμένου δ’ ἐκείνου τὴν ἀξίωσιν προῄεσαν καὶ Γυάλης σὺν αὐτοῖς τὸ οἰκεῖον ἄγων ὁπλιτικόν. ὅ τε οὖν καρπὸς μετὰ ἀσφαλείας συνάγεται καὶ δειπνοῦντες κατὰ συμμορίαν φανερῶς ἀπετόλμων ἤδη βλασφημεῖν τὸν Ἀβιμέλεχον, οἵ τε ἄρχοντες ἐνέδραις καταλαμβανόμενοι τὰ περὶ τὴν πόλιν πολλοὺς τῶν Ἀβιμελέχου συλλαμβάνοντες ἀνῄρουν.", "st": "5.7.3"}, {"sp": "N", "t": "Ζάβουλος δέ τις τῶν Σικιμιτῶν ἄρχων ξένος ὢν Ἀβιμελέχου ὅσα παροξύνειεν Γυάλης τὸν δῆμον πέμπων ἀγγέλους ἐμήνυεν αὐτῷ καὶ παρῄνει λοχᾶν πρὸ τῆς πόλεως· πείσειν γὰρ Γυάλην ἐξελθεῖν ἐπ’ αὐτόν, καὶ τὸ λοιπὸν ἐπ’ ἐκείνῳ τυγχάνειν ὥστε ἀμύνασθαι· γενομένου γὰρ τούτου διαλλαγὰς αὐτῷ μνηστεύσεσθαι πρὸς τὸν δῆμον. ὅ τε οὖν Ἀβιμέλεχος ἐκάθισεν ἐνεδρεύων καὶ ὁ Γυάλης ἀφυλακτοτέρως διέτριβεν ἐπὶ τοῦ προαστείου καὶ Ζάβουλος σὺν αὐτῷ. ἰδὼν δὲ ὁπλίτας ἐπιφερομένους Γυάλης πρὸς Ζάβουλον ἔλεγεν ἄνδρας αὐτοῖς ἐπιέναι καθωπλισμένους. τοῦ δὲ σκιὰς εἶναι φαμένου τῶν πετρῶν, πλησίον ἤδη γινομένων τὸ ἀκριβὲς κατανοῶν οὐ σκιὰς ἔλεγε ταῦτ’ εἶναι, λόχον δ’ ἀνδρῶν. καὶ Ζάβουλος, οὐ σὺ μέντοι, φησίν, Ἀβιμελέχῳ κακίαν ἐπεκάλεις; τί οὖν οὐκ ἐπιδεικνύεις τὸ τῆς ἀρετῆς μέγεθος εἰς μάχην αὐτῷ συμβαλών; Γυάλης δὲ θορυβούμενος συνάπτει τοῖς Ἀβιμελέχου καὶ πίπτουσι μέν τινες τῶν σὺν αὐτῷ, φεύγει δ’ αὐτὸς εἰς τὴν πόλιν τοὺς ἄλλους ἀγόμενος. καὶ Ζάβουλος πολιτεύεται Γυάλην ἐκβληθῆναι τῆς πόλεως κατηγορήσας, ὡς μαλακῶς πρὸς τοὺς Ἀβιμελέχου στρατιώτας ἀγωνίσαιτο. Ἀβιμέλεχος δὲ πυθόμενος ἐξελευσομένους αὖθις κατὰ τρύγητον τοὺς Σικιμίους ἐνέδραις προλοχίζεται τὰ περὶ τὴν πόλιν, καὶ προελθόντων ἡ μὲν τρίτη μοῖρα τῆς στρατιᾶς καταλαμβάνει τὰς πύλας ἀφαιρησομένη τὴν εἴσοδον τοὺς πολίτας, οἱ δ’ ἄλλοι σκιδναμένους μεταθέουσι, πανταχοῦ τε φόνος ἦν. καὶ κατασκάψας εἰς ἔδαφος τὴν πόλιν, οὐ γὰρ ἀντέσχε πρὸς τὴν πολιορκίαν, ἅλας κατὰ τῶν ἐρειπίων σπείρας προῆγε. καὶ Σικιμῖται πάντες οὕτως ἀπώλοντο· ὅσοι δὲ κατὰ τὴν χώραν σκεδασθέντες διέφυγον τὸν κίνδυνον, οὗτοι πέτραν ὀχυρὰν εὑρόντες ἐπ’ αὐτῆς ἱδρύονται τειχίσαι τε ταύτην παρεσκευάζοντο. ἔφθη τε τὴν διάνοιαν αὐτῶν Ἀβιμέλεχος μαθὼν ἐλθεῖν ἐπ’ αὐτοὺς μετὰ τῆς δυνάμεως καὶ φακέλλους ὕλης ξηρᾶς περιβαλὼν τῷ χωρίῳ δι’ αὐτοῦ φέρων ταῦτα ποιεῖν τὴν στρατιὰν παρεκελεύσατο. καὶ ταχέως περιληφθείσης ἐν κύκλῳ τῆς πέτρας τοῖς ξύλοις πῦρ ἐμβάλλουσιν ὅσα τε μᾶλλον ἐξάπτειν φύσιν ἔχει καὶ μεγίστην αἴρουσι φλόγα. καὶ διαφεύγει μὲν ἀπὸ τῆς πέτρας οὐθείς, ἀλλ’ ἅμα γυναιξὶ καὶ τέκνοις ἀπώλοντο, ἄνδρες μὲν περὶ πεντακοσίους καὶ χιλίους, τὸ δὲ ἄλλο πλῆθος ἱκανόν. καὶ Σικιμίταις μὲν τοιαύτη συμφορὰ συνέπεσε μείζων καὶ τῆς ἐπ’ αὐτῇ λύπης γενομένη πλὴν ὅτι κατὰ δίκην ἐπ’ ἀνδρὸς εὐεργέτου συνθεῖσι κακὸν τηλικοῦτον.", "st": "5.7.4"}, {"sp": "N", "t": "Ἀβιμέλεχος δὲ τοῖς Σικιμιτῶν κακοῖς καταπλήξας τοὺς Ἰσραηλίτας μειζόνων ἐφιέμενος δῆλος ἦν καὶ μηδαμοῦ περιγράψων τὴν βίαν, εἰ μὴ πάντας ἀπολέσειεν. ἤλαυνεν οὖν ἐπὶ Θήβας καὶ τὴν μὲν πόλιν ἐξ ἐπιδρομῆς αἱρεῖ, πύργου δ’ ὄντος ἐν αὐτῇ μεγάλου, εἰς ὃν πᾶν τὸ πλῆθος συνέφυγε, πολιορκεῖν τοῦτον παρεσκευάζετο. καὶ αὐτὸν πλησίον ὁρμῶντα τῶν πυλῶν γυνὴ θραύσματι μύλης βαλοῦσα κατὰ τῆς κεφαλῆς τυγχάνει, πεσὼν δὲ Ἀβιμέλεχος τὸν ὑπασπιστὴν παρεκάλει κτείνειν αὐτόν, μὴ τῆς γυναικὸς ὁ θάνατος αὐτοῦ δόξειεν ἔργον. καὶ ὁ μὲν τὸ προσταχθὲν ἐποίει. ὁ δὲ τοιαύτην ὑπὲρ τῆς εἰς τοὺς ἀδελφοὺς παρανομίας ποινὴν ἐξέτισε καὶ τῶν εἰς Σικιμίους αὐτῷ τετολμημένων· τούτοις δὲ κατὰ τὴν Ἰωθάμου μαντείαν ἡ συμφορὰ συνέπεσε. τὸ μέντοι σὺν Ἀβιμελέχῳ στράτευμα πεσόντος αὐτοῦ σκεδασθὲν ἀνεχώρησεν ἐπὶ τὰ οἰκεῖα.", "st": "5.7.5"}, {"sp": "N", "t": "Τῶν δὲ Ἰσραηλιτῶν τὴν ἡγεμονίαν Ἰάρης ὁ Γαλαδηνὸς ἐκ τῆς Μανασσίτιδος φυλῆς παραλαμβάνει ἀνὴρ τά τε ἄλλα εὐδαίμων καὶ παῖδας ἀγαθοὺς πεποιημένος τριάκοντα μὲν τὸν ἀριθμὸν ἱππεύειν δὲ ἀρίστους καὶ τῶν κατὰ τὴν Γαλαδηνὴν πόλεων ἀρχὰς ἐγκεχειρισμένους. οὗτος δύο καὶ εἴκοσι ἔτη τὴν ἀρχὴν κατασχὼν τελευτᾷ γηραιὸς καὶ ταφῆς ἐν Καμμὼν πόλει τῆς Γαλαδηνῆς ἀξιοῦται.", "st": "5.7.6"}, {"sp": "N", "t": "Πάντα δὲ τὰ τῶν Ἑβραίων εἰς ἀκοσμίαν καὶ ὕβριν τοῦ θεοῦ καὶ τῶν νόμων ὑπεφέρετο, καὶ καταφρονήσαντες αὐτῶν Ἀμμανῖται καὶ Παλαιστῖνοι στρατῷ μεγάλῳ διήρπαζον τὴν χώραν καὶ τὴν Περαίαν ἅπασαν κατασχόντες καὶ ἐπὶ τὴν τῶν λοιπῶν ἤδη κτῆσιν διαβαίνειν ἐτόλμων. Ἑβραῖοι δὲ σωφρονισθέντες ὑπὸ τῶν κακῶν εἰς ἱκετείαν ἐτράποντο τοῦ θεοῦ καὶ θυσίας ἐπέφερον παρακαλοῦντες αὐτὸν μετριάσαντα καὶ πρὸς τὴν δέησιν αὐτῶν ὑπαχθέντα παύσασθαι τῆς ὀργῆς· ὁ δὲ θεὸς μεταβαλόμενος εἰς τὸ ἡμερώτερον ἔμελλεν αὐτοῖς βοηθεῖν.", "st": "5.7.7"}, {"sp": "N", "t": "Ἀμμανιτῶν δ’ ἐστρατευκότων ἐπὶ τὴν Γαλαδηνὴν ὑπήντων οἱ ἐπιχώριοι πρὸς τὸ ὄρος δεόμενοι τοῦ στρατηγήσοντος. ἦν δέ τις Ἰαφθᾶς ἀνὴρ διὰ τὴν πατρῴαν ἀρετὴν δυνατὸς καὶ δι’ οἰκείαν αὐτοῦ στρατιὰν ἣν ἔτρεφεν αὐτὸς μισθοφόρων. πρὸς τοῦτον οὖν πέμψαντες ἠξίουν αὐτὸν συμμαχεῖν ἐπαγγελλόμενοι παρασχεῖν εἰς ἅπαντ’ αὐτῷ τὸν χρόνον τὴν ἰδίαν ἡγεμονίαν. ὁ δ’ οὐ προσίεται τὴν παράκλησιν αὐτῶν ἐγκαλῶν, ὅτι μὴ βοηθήσειαν αὐτῷ ὑπὸ τῶν ἀδελφῶν ἀδικουμένῳ περιφανῶς· οὐ γὰρ ὄντα ὁμομήτριον αὐτοῖς ἀλλὰ ξένον περὶ τὴν μητέρα δι’ ἐρωτικὴν ἐπιθυμίαν ἐπαχθεῖσαν αὐτοῖς ὑπὸ τοῦ πατρὸς ἐξέβαλον καταφρονήσαντες τῆς αὐτοῦ ἀσθενείας. καὶ ὁ μὲν διέτριβεν ἐν τῇ Γαλαδίτιδι καλουμένῃ χώρᾳ πάντας τοὺς ὁποθενοῦν παραγινομένους πρὸς αὐτὸν ἐπὶ μισθῷ δεχόμενος. ἐκλιπαρησάντων δ’ αὐτῶν καὶ ὀμοσάντων εἰς ἀεὶ παρέξειν αὐτῷ τὴν ἡγεμονίαν ἐστράτευε.", "st": "5.7.8"}, {"sp": "N", "t": "Καὶ ποιησάμενος ὀξεῖαν τὴν τῶν πραγμάτων ἐπιμέλειαν ἐν πόλει Μασφαθῇ καθίσας τὸν στρατὸν πρεσβείαν πέμπει παρὰ τὸν Ἀμμανίτην αἰτιώμενος τῆς ἁλώσεως. ὁ δὲ ἀντιπέμψας ᾐτιᾶτο τῶν Ἰσραηλιτῶν τὴν ἔξοδον τὴν ἀπ’ Αἰγύπτου καὶ τῆς Ἀμορραίας αὐτοὺς ἠξίου παραχωρεῖν ὡς πατρῴας οὔσης ἀρχῆθεν. ἀποκρινάμενος δὲ ὁ Ἰαφθᾶς, ὡς οὔτε τῆς Ἀμορραίας τοῖς προγόνοις αὐτῶν εὐλόγως ἐγκαλοῦσι χάριν τε μᾶλλον τῆς Ἀμμανίτιδος αὐτοῖς ἔχειν ὀφείλουσι παρεθείσης, δυνατὸν γὰρ Μωυσεῖ καὶ ταύτην λαβεῖν παραχωρεῖν τε ἰδίας εἰπὼν γῆς, ἣν θεοῦ κατακτησαμένου μετὰ τριακόσια ἔτη νέμονται, μάχεσθαι πρὸς αὐτοὺς ἔφησεν.", "st": "5.7.9"}, {"sp": "N", "t": "Καὶ τοὺς μὲν πρέσβεις ταῦτ’ εἰπὼν ἀπέλυσεν· αὐτὸς δ’ εὐξάμενος νίκην καὶ θυσιάσειν ὑποσχόμενος, ἂν σῶος εἰς τὰ οἰκεῖα ὑποστρέψῃ, καὶ πᾶν ὅ τι καὶ πρῶτον αὐτῷ συντύχοι ἱερουργήσειν, συμβαλών τε νικᾷ παρὰ πολὺ καὶ φονεύων ἐδίωκε μέχρι πόλεως Μανιάθης, καὶ διαβὰς εἰς τὴν Ἀμμανῖτιν πόλεις τε ἠφάνισε πολλὰς καὶ λείαν ἤλασε καὶ τοὺς οἰκείους δουλείας ἀπήλλαξεν ἐν ἔτεσιν ὀκτωκαίδεκα ταύτην ὑπομείναντας. ἀναστρέφων δὲ συμφορᾷ περιπίπτει κατ’ οὐδὲν ὁμοίᾳ τοῖς κατωρθωμένοις αὐτῷ· ὑπήντησε γὰρ ἡ θυγάτηρ αὐτῷ, μονογενὴς δ’ ἦν, ἔτι παρθένος. ὁ δὲ ἀνοιμώξας ἐπὶ τῷ μεγέθει τοῦ πάθους κατεμέμφετο τῆς περὶ τὴν ὑπάντησιν σπουδῆς τὴν θυγατέρα· καθιερῶσαι γὰρ αὐτὴν τῷ θεῷ. τῇ δὲ τὸ συμβησόμενον οὐκ ἀηδῶς προσέπεσεν ἐπὶ νίκῃ τοῦ πατρὸς καὶ ἐλευθερίᾳ τῶν πολιτῶν τεθνηξομένῃ, παρεκάλεσε δὲ δύο μῆνας αὐτῇ παρασχόντα πρὸς τὸ μετὰ τῶν πολιτῶν ἀποθρηνῆσαι τὴν νεότητα τότε ποιεῖν τὰ κατὰ τὴν εὐχήν. συγχωρήσας δὲ τὰ κατὰ τὸν προειρημένον χρόνον μετὰ τοῦτον διελθόντα θύσας τὴν παῖδα ὡλοκαύτωσεν οὔτε νόμιμον οὔτε θεῷ κεχαρισμένην θυσίαν ἐπιτελῶν, μὴ διαβασανίσας τῷ λογισμῷ τὸ γενησόμενον οἷόν τε πραχθὲν δόξει τοῖς ἀκούσασι.", "st": "5.7.10"}, {"sp": "N", "t": "Τῆς δ’ Ἐφράνου φυλῆς ἐπ’ αὐτὸν στρατευσάσης, ὅτι μὴ κοινώσαιτο τὴν ἐπ’ Ἀμμανίτας ἔλασιν αὐτοῖς, ἀλλὰ μόνος καὶ τὴν λείαν ἔχοι καὶ τὴν ἐπὶ τοῖς πεπραγμένοις δόξαν, πρῶτον μὲν ἔλεγεν, ὡς οὔτε λάθοιεν αὐτοὺς οἱ συγγενεῖς πολεμούμενοι καλούμενοί τε πρὸς συμμαχίαν οὐ παρεγένοντο δέον καὶ πρὸ δεήσεως ἐγνωκότας ἐπειχθῆναι, ἔπειθ’ ὡς ἄδικα πράττειν ἐπιχειροῦσι τοῖς πολεμίοις οὐ τολμήσαντες εἰς χεῖρας ἐλθεῖν, ἐπὶ δὲ τοὺς συγγενεῖς ὡρμηκότες· ἠπείλει τε σὺν τῷ θεῷ λήψεσθαι δίκην παρ’ αὐτῶν, ἂν μὴ σωφρονῶσιν. ὡς δ’ οὐκ ἔπειθεν, ἀλλὰ συνέβαλεν αὐτοῖς ἐλθοῦσι μετὰ στρατιᾶς, ἣ μετάπεμπτος ἐκ τῆς Γαλαδηνῆς ἐληλύθει, φόνον τε πολὺν αὐτῶν εἰργάσατο καὶ διώκων τραπέντας προλαβὼν μέρει τινὶ προαπεσταλμένῳ τοῦ Ἰορδάνου τὰς διαβάσεις κτείνει περὶ δισχιλίους καὶ τετρακισμυρίους γεγονότας.", "st": "5.7.11"}, {"sp": "N", "t": "Αὐτὸς δὲ ἄρξας ἓξ ἔτη τελευτᾷ καὶ θάπτεται ἐν τῇ αὐτοῦ πατρίδι Σεβέῃ· τῆς Γαλαδηνῆς δ’ ἐστὶν αὕτη.", "st": "5.7.12"}, {"sp": "N", "t": "Τελευτήσαντος δὲ Ἰαφθᾶ τὴν ἀρχὴν Ἀψάνης παραλαμβάνει φυλῆς ὢν Ἰουδαϊκῆς Βηθλέμων δὲ πόλεως. τούτῳ δὲ παῖδες ἦσαν ἑξήκοντα, τριάκοντα μὲν ἄρρενες αἱ λοιπαὶ δὲ θυγατέρες, οὓς καὶ πάντας ζῶντας κατέλιπε τὰς μὲν ἀνδράσιν ἐκδοὺς τοῖς δὲ γυναῖκας ἠγμένος. πράξας δ’ οὐδὲν ἐν τῷ ἑπταετεῖ γενομένῳ χρόνῳ λόγου καὶ μνήμης ἄξιον γηραιὸς ὢν ἀπέθανε καὶ ταφῆς ἐν τῇ πατρίδι τυγχάνει.", "st": "5.7.13"}, {"sp": "N", "t": "Ἀψανοῦς δ’ οὕτως ἀποθανόντος οὐδ’ ὁ μετ’ αὐτὸν παραλαβὼν τὴν ἡγεμονίαν Ἤλων ἐπ’ ἔτη δέκα κατασχὼν αὐτὴν φυλῆς ὢν τῆς Ζαβούλης ἔπραξέ τι σπουδῆς ἄξιον.", "st": "5.7.14"}, {"sp": "N", "t": "Ἀβδὼν δὲ Ἤλωνος παῖς φυλῆς μὲν τῆς Ἐφραμίτιδος πόλεως δὲ τῆς Φαραθωνιτῶν γεγονώς, αὐτοκράτωρ ἡγεμὼν ἀποδειχθεὶς μετ’ Ἤλωνα μόνης ἂν τῆς εὐπαιδίας μνημονευθείη, [μηδὲν ἔργον] διὰ τὴν εἰρήνην καὶ τὴν ἄδειαν τῶν πραγμάτων λαμπρὸν μηδ’ αὐτὸς εἰργασμένος. υἱοὶ δὲ ἦσαν αὐτῷ τεσσαράκοντα καὶ τούτων τὴν γενεὰν καταλιπόντες τριάκοντα, ἤλαυνέ τε σὺν αὐτοῖς οὖσιν ἑβδομήκοντα πᾶσιν ἱππάζειν ἀρίστοις γεγενημένοις, καὶ πάντας ὑπὲρ γῆς ἀπολιπὼν θνήσκει γηραιὸς καὶ ταφῆς ἐν Φαραθῷ λαμπρᾶς τυγχάνει.", "st": "5.7.15"}, {"sp": "N", "t": "Μετὰ δὲ τοῦτον Παλαιστῖνοι τελευτήσαντα κρατοῦσι τῶν Ἰσραηλιτῶν καὶ φόρους παρ’ αὐτῶν ἐλάμβανον ἐπ’ ἔτη τεσσαράκοντα. ταύτης δ’ ἐλευθεροῦνται τῆς ἀνάγκης τούτῳ τῷ τρόπῳ·", "st": "5.8.1"}, {"sp": "N", "t": "Μανώχης τις Δανιτῶν ἐν ὀλίγοις ἄριστος καὶ τῆς πατρίδος ὁμολογούμενος πρῶτος εἶχε γύναιον ἐπ’ εὐμορφίᾳ περίβλεπτον καὶ τῶν κατ’ αὐτὸ διαφέρον. παίδων δ’ οὐ γινομένων αὐτῷ δυσφορῶν ἐπὶ τῇ ἀπαιδίᾳ θεὸν ἱκέτευεν ἐπὶ τὸ προάστειον συνεχῶς φοιτῶν μετὰ τῆς γυναικὸς δοῦναι διαδοχὴν αὐτοῖς γνησίαν· μέγα δέ ἐστι τοῦτο πεδίον. ἦν δὲ καὶ μανιώδης ὑπ’ ἔρωτος ἐπὶ τῇ γυναικὶ καὶ διὰ τοῦτο ζηλότυπος ἀκρατῶς. μονωθείσῃ δὲ τῇ γυναικὶ φάντασμα ἐπιφαίνεται τοῦ θεοῦ νεανίᾳ καλῷ παραπλήσιον μεγάλῳ καὶ εὐαγγελιζόμενον αὐτῇ παιδὸς γονὴν κατὰ θεοῦ πρόνοιαν καλοῦ τε καὶ ῥώμην ἐπιφανοῦς, ὑφ’ ᾧ πονήσειν Παλαιστίνους ἀνδρουμένῳ. παρῄνει τε τὰς κόμας αὐτῷ μὴ ἀποκείρειν· ἔσται δ’ αὐτῷ πρὸς ἄλλο μὲν ποτὸν ἀποστροφὴ τοῦ θεοῦ τοῦτο προστάσσοντος, πρὸς ὕδωρ δὲ μόνον οἰκειότης. καὶ ὁ μὲν ταῦτ’ εἰπὼν ᾤχετο κατὰ βούλησιν ἐλθὼν τοῦ θεοῦ.", "st": "5.8.2"}, {"sp": "N", "t": "Ἡ δὲ τἀνδρὶ παραγενομένῳ τὰ παρὰ τοῦ ἀγγέλου ἐκδιηγήσατο ἐκθαυμάζουσα τοῦ νεανίσκου τὸ κάλλος καὶ τὸ μέγεθος, ὡς ἐκεῖνον ἐκ τῶν ἐπαίνων εἰς ἔκπληξιν κατὰ ζηλοτυπίαν περιστῆναι καὶ ὑπόνοιαν τὴν ἐκ τοιούτου πάθους κινουμένην. ἡ δὲ βουλομένη τὴν ἄλογον τἀνδρὸς λύπην σταλῆναι τὸν θεὸν ἱκέτευε πάλιν πέμψαι τὸν ἄγγελον, ὡς ἂν καὶ τῷ ἀνδρὶ αὐτῆς ὁραθείη. καὶ παραγίνεται πάλιν κατὰ χάριν τοῦ θεοῦ ὁ ἄγγελος ὄντων ἐν τῷ προαστείῳ καὶ τῇ γυναικὶ φαίνεται τοῦ ἀνδρὸς μεμονωμένῃ. ἡ δ’ ἐπιμεῖναι δεηθεῖσα ὡς ἂν ἀγάγοι τὸν ἄνδρα συγχωρήσαντος μέτεισι τὸν Μάνωχον. ὁ δὲ θεασάμενος οὐδ’ οὕτως ἐπαύετο τῆς ὑπονοίας ἠξίωσέ τι καὶ αὐτῷ δηλοῦν ὅσα καὶ τῇ γυναικὶ μηνύσειεν. ἀρκέσειν δὲ φράσαντος ταύτην μόνην εἰδέναι, τίς εἴη λέγειν ἐκέλευεν, ἵνα τοῦ παιδὸς γενομένου χάριν αὐτῷ καὶ δωρεὰν παράσχωσι. τοῦ δὲ μηδέ τινων αὐτῷ δεῖσθαι φήσαντος, οὐδὲ γὰρ κατὰ χρείαν ταῦτα εὐαγγελίσασθαι περὶ τῆς τοῦ παιδὸς γονῆς, τοῦ δὲ μεῖναι παρακαλοῦντος καὶ ξενίων μετασχεῖν οὐκ ἐπένευσε, πεισθεὶς δ’ ὅμως λιπαροῦντος ἐπιμεῖναι ὡς ἂν ξένιον αὐτῷ τι κομίσῃ, καὶ θύσαντος ἔριφον τοῦ Μανώχου καὶ τοῦτον ὀπτᾶν τῇ γυναικὶ κελεύσαντος, ἐπεὶ πάντ’ ἦν εὐτρεπῆ, προσέταξεν ἐπὶ τῆς πέτρας ἀποθέσθαι τούς τε ἄρτους καὶ τὰ κρέα χωρὶς τῶν ἀγγείων. καὶ ποιησάντων ἅπτεται τῇ ῥάβδῳ ᾗ εἶχε τῶν κρεῶν, τὰ δὲ λάμψαντος πυρὸς ἅμα τοῖς ἄρτοις ἐκαίετο καὶ ὁ ἄγγελος διὰ τοῦ καπνοῦ ὥσπερ ὀχήματος ἀνιὼν εἰς οὐρανὸν αὐτοῖς φανερὸς ἦν. Μανώχην δὲ φοβούμενον, μή τι σφαλερὸν αὐτοῖς ἐκ τῆς ὄψεως τοῦ θεοῦ γένοιτο, θαρσεῖν ἡ γυνὴ παρεκελεύετο· ἐπὶ γὰρ συμφέροντι τῷ αὐτῶν τὸν θεὸν αὐτοῖς ὁραθῆναι.", "st": "5.8.3"}, {"sp": "N", "t": "Καὶ κύει τε ἐκείνη καὶ φυλακὴν εἶχε τῶν ἐντολῶν, καὶ γενόμενον τὸ παιδίον Σαμψῶνα καλοῦσιν, ἰσχυρὸν δ’ ἀποσημαίνει τὸ ὄνομα. ηὔξετο δ’ ὁ παῖς ῥᾳδίως καὶ δῆλος ἦν προφητεύσων ὑπὸ τῆς περὶ τὴν δίαιταν σωφροσύνης καὶ τῆς τῶν τριχῶν ἀνέσεως.", "st": "5.8.4"}, {"sp": "N", "t": "Ἀφικόμενος δὲ μετὰ τῶν γονέων εἰς Θάμνα πόλιν τῶν Παλαιστίνων πανηγύρεως ἀγομένης ἐρᾷ παρθένου τῶν ἐπιχωρίων παρακαλεῖ τε τοὺς γονεῖς ἄγεσθαι πρὸς γάμον αὐτῷ τὴν κόρην. τῶν δὲ ἀρνουμένων διὰ τὸ μὴ ὁμόφυλον εἶναι, τοῦ θεοῦ κατὰ τὸ Ἑβραίων σύμφορον ἐπινοοῦντος τὸν γάμον ἐκνικᾷ μνηστεύσασθαι τὴν παρθένον. συνεχῶς δ’ ἀπερχόμενος πρὸς τοὺς γονεῖς αὐτῆς συντυγχάνει λέοντι καὶ γυμνὸς ὢν ἐκδεξάμενος αὐτὸν ἄγχει ταῖς χερσὶ καὶ εἰς τὸ χωρίον τὸ ὑλῶδες ἐνδοτέρω τῆς ὁδοῦ ῥίπτει τὸ θηρίον.", "st": "5.8.5"}, {"sp": "N", "t": "Πάλιν τε ἀπιὼν πρὸς τὴν κόρην ἐπιτυγχάνει σμήνει μελιττῶν ἐν τῷ στήθει τοῦ λέοντος ἐκείνου νενοσσευκότων, καὶ ἀνελόμενος τρία μέλιτος κηρία σὺν τοῖς λοιποῖς δώροις οἷς ἐκόμιζε δίδωσι τῇ παιδί. τῶν δὲ Θαμνιτῶν παρὰ τὴν εὐωχίαν τὴν τῶν γάμων, εἱστία γὰρ αὐτοὺς ἅπαντας, διὰ δέος τῆς ἰσχύος τοῦ νεανίσκου τριάκοντα δόντων αὐτῷ τοὺς ἀκμαιοτάτους λόγῳ μὲν ἑταίρους ἐσομένους ἔργῳ δὲ φύλακας, μή τι παρακινεῖν ἐθελήσειεν, τοῦ πότου προβάντος καὶ παιδιᾶς οὔσης, οἷα φιλεῖ παρὰ τοὺς τοιούτους καιρούς, ὁ Σαμψὼν εἶπεν, ἀλλὰ προβάλλοντος ἐμοῦ λόγον εἰ λύσετε τοῦτον ἐφ’ ἡμέρας ἑπτὰ ποιούμενοι τὴν ζήτησιν, ὀθόνας τε καὶ στολὰς γέρας τῆς συνέσεως κατ’ ἄνδρα ἕκαστον φέρεσθε παρ’ ἐμοῦ. φιλοτιμουμένων δὲ ὁμοῦ τε συνετοὺς δόξαι καὶ κέρδος εὕρασθαι καὶ λέγειν ἀξιούντων φησίν, ὅτι τὸ πάμβορον γεγεννήκοι βορὰν ἡδεῖαν ἐξ αὐτοῦ καὶ πάνυ ἀηδοῦς ὄντος. τῶν δ’ ἐπὶ τρεῖς ἡμέρας οὐ δυναμένων ἐξευρεῖν τὸ νοούμενον παρακαλούντων δὲ τὴν κόρην μαθοῦσαν παρὰ τοῦ ἀνδρὸς αὐτοῖς μηνῦσαι, καὶ γὰρ ἠπείλουν ἐμπρήσειν αὐτὴν τοῦτο μὴ παρασχοῦσαν, ὁ Σαμψὼν δεομένης τῆς κόρης εἰπεῖν αὐτῇ τὸ μὲν πρῶτον ἀντέχειν ἐπειρᾶτο, ἐγκειμένης δ’ αὐτῆς καὶ εἰς δάκρυα προπιπτούσης καὶ τεκμήριον τιθεμένης τῆς πρὸς αὐτὴν δυσνοίας τὸ μὴ λέγειν αὐτῇ, μηνύει τὰ περὶ τὴν ἀναίρεσιν αὐτῇ τοῦ λέοντος καὶ ὡς τὰ τρία βαστάσας ἐξ αὐτοῦ κηρία μέλιτος γεγονότα κομίσειεν αὐτῇ. καὶ ὁ μὲν οὐδὲν ὑφορώμενος δολερὸν σημαίνει τὸ πᾶν, ἡ δ’ ἐκφέρει τὸν λόγον τοῖς δεηθεῖσι. κατὰ οὖν τὴν ἑβδόμην ἡμέραν, καθ’ ἣν ἔδει τὸν προβληθέντα λόγον αὐτῷ διασαφεῖν, πρὶν ἢ δῦναι τὸν ἥλιον συνελθόντες φασίν, οὔτε λέοντος ἀηδέστερόν τι τοῖς ἐντυγχάνουσιν οὔτε ἥδιον μέλιτος χρωμένοις. καὶ ὁ Σαμψὼν εἶπεν οὐδὲ γυναικὸς εἶναί τι δολερώτερον, ἥτις ὑμῖν ἐκφέρει τὸν ἡμέτερον λόγον. κἀκείνοις μὲν δίδωσιν ἃ ὑπέσχετο λείαν ποιησάμενος Ἀσκαλωνιτῶν τοὺς κατὰ τὴν ὁδὸν αὐτῷ συντυχόντας, Παλαιστῖνοι δ’ εἰσὶ καὶ οὗτοι, τὸν δὲ γάμον ἐκεῖνον παραιτεῖται καὶ ἡ παῖς ἐκφαυλίσασα τῆς ὀργῆς αὐτὸν συνῆν αὐτοῦ φίλῳ νυμφοστόλῳ γεγονότι.", "st": "5.8.6"}, {"sp": "N", "t": "Πρὸς δὲ τὴν ὕβριν ταύτην Σαμψὼν παροξυνθεὶς ἅπαντας ἔγνω σὺν αὐτῇ Παλαιστίνους μετέρχεσθαι. θέρους δ’ ὄντος καὶ πρὸς ἄμητον ἤδη τῶν καρπῶν ἀκμαζόντων συλλαβὼν τριακοσίας ἀλώπεκας καὶ τῶν οὐρῶν ἐξάψας λαμπάδας ἡμμένας ἀφίησιν εἰς τὰς ἀρούρας τῶν Παλαιστίνων. καὶ φθείρεται μὲν οὕτως αὐτοῖς ὁ καρπός, Παλαιστῖνοι δὲ γνόντες Σαμψῶνος εἶναι τὸ ἔργον καὶ τὴν αἰτίαν δι’ ἣν ἔπραξε, πέμψαντες τοὺς ἄρχοντας εἰς Θαμνὰ τὴν γενομένην αὐτοῦ γυναῖκα καὶ τοὺς συγγενεῖς ζῶντας κατέπρησαν ὡς αἰτίους τῶν κακῶν γεγονότας.", "st": "5.8.7"}, {"sp": "N", "t": "Σαμψὼν δὲ πολλοὺς ἐν τῷ πεδίῳ τῶν Παλαιστίνων ἀποκτείνας Αἰτὰν κατῴκει, πέτρα δ’ ἐστὶν ὀχυρὰ τῆς Ἰούδα φυλῆς. Παλαιστῖνοι δ’ ἐστράτευον ἐπὶ τὴν φυλήν. τῶν δ’ οὐ δικαίως λεγόντων τιμωρίαν αὐτοὺς εἰσπράττεσθαι περὶ τῶν Σαμψῶνος ἁμαρτημάτων φόρους αὐτοὺς τελοῦντας, εἰ βούλονται μὴ ἔχειν αἰτίαν ἔφασαν αὐτοῖς ὑποχείριον Σαμψῶνα δοῦναι. οἱ δὲ ἀνεπίκλητοι βουλόμενοι τυγχάνειν παρῆσαν ἐπὶ τὴν πέτραν τρισχίλιοι ὁπλῖται καὶ καταμεμψάμενοι τῶν εἰς Παλαιστίνους αὐτῷ τετολμημένων ἄνδρας ἅπαντι τῷ γένει τῶν Ἑβραίων συμφορὰν ἐπενεγκεῖν δυναμένους, ἥκειν τε λέγοντες ὅπως αὐτὸν λαβόντες ὑποχείριον δῶσιν αὐτοῖς ἠξίουν ἑκοντὶ τοῦθ’ ὑπομένειν. ὁ δὲ λαβὼν ὅρκους παρ’ αὐτῶν μηδὲν τούτων ποιήσειν περισσότερον ἀλλὰ τοῖς ἐχθροῖς ἐγχειριεῖν μόνον, καταβὰς ἐκ τῆς πέτρας αὑτὸν ἐν τῇ τῶν φυλετῶν τίθησιν ἐξουσίᾳ, κἀκεῖνοι δήσαντες αὐτὸν δυσὶ καλωδίοις ἦγον παραδοῦναι τοῖς Παλαιστίνοις. καὶ γενομένων κατὰ χωρίον, ὃ Σιαγὼν καλεῖται νῦν διὰ τὴν Σαμψῶνος ἀνδραγαθίαν ἐπ’ αὐτῷ γενομένην, πάλαι δ’ ἦν ἀνώνυμον, οὐκ ἄπωθεν ἐστρατοπεδευκότων τῶν Παλαιστίνων, ἀλλ’ ὑπαντώντων μετὰ χαρᾶς καὶ βοῆς ὡς ἐπὶ κατωρθωμένοις οἷς ἐβούλοντο, διαρρήξας τὰ δεσμὰ Σαμψὼν ἁρπασάμενος ὄνου σιαγόνα παρὰ ποσὶν οὖσαν εἰς τοὺς πολεμίους ὤσατο καὶ παίων αὐτοὺς τῇ σιαγόνι κτείνει εἰς χιλίους, τοὺς δὲ ἄλλους τρέπεται ταραχθέντας.", "st": "5.8.8"}, {"sp": "N", "t": "Σαμψὼν δὲ μεῖζον ἢ χρὴ ἐπὶ τούτῳ φρονῶν οὐ κατὰ θεοῦ συνεργίαν ἔλεγε τοῦτο συμβῆναι, τὴν δ’ ἰδίαν ἀρετὴν ἐπέγραψε τῷ γεγονότι, τῶν πολεμίων τοὺς μὲν πεσεῖν τοὺς δ’ εἰς φυγὴν τραπῆναι διὰ τοῦ παρ’ αὐτοῦ δέους αὐχῶν. δίψους δ’ αὐτὸν ἰσχυροῦ κατασχόντος κατανοῶν ὡς οὐδέν ἐστιν ἀνθρώπειος ἀρετὴ τῷ θεῷ πάντα προσεμαρτύρει καὶ καθικέτευε μηδὲν τῶν εἰρημένων πρὸς ὀργὴν λαβόντα τοῖς πολεμίοις αὐτὸν ἐγχειρίσαι, παρασχεῖν δὲ βοήθειαν πρὸς τὸ δεινὸν καὶ ῥύσασθαι τοῦ κακοῦ. καὶ πρὸς τὰς ἱκετείας ἐπικλασθεὶς ὁ θεὸς πηγὴν κατά τινος πέτρας ἀνίησιν ἡδεῖαν καὶ πολλήν, ὅθεν καὶ Σαμψὼν ἐκάλει τὸ χωρίον Σιαγόνα καὶ μέχρι τοῦ δεῦρο τοῦτο λέγεται.", "st": "5.8.9"}, {"sp": "N", "t": "Μετὰ δὲ ταύτην τὴν μάχην Σαμψὼν καταφρονῶν τῶν Παλαιστίνων εἰς Γάζαν ἀφικνεῖται καὶ ἔν τινι τῶν καταγωγίων διέτριβε. μαθόντες δὲ τῶν Γαζαίων οἱ ἄρχοντες τὴν αὐτόθι παρουσίαν αὐτοῦ τὰ πρὸ τῶν πυλῶν ἐνέδραις καταλαμβάνουσιν, ὅπως ἐξιὼν μὴ λάθῃ. Σαμψὼν δέ, οὐ γὰρ λανθάνουσιν αὐτὸν ταῦτα μηχανησάμενοι, περὶ μεσοῦσαν ἤδη τὴν νύκτα ἀναστὰς ἐνράσσει ταῖς πύλαις, αὐταῖς τε φλιαῖς καὶ μοχλοῖς ὅση τε ἄλλη περὶ αὐταῖς ἦν ξύλωσις ἀράμενος κατωμαδὸν εἰς τὸ ὑπὲρ Ἑβρῶνος ὄρος φέρων κατατίθησιν.", "st": "5.8.10"}, {"sp": "N", "t": "Παρέβαινε δ’ ἤδη τὰ πάτρια καὶ τὴν οἰκείαν δίαιταν παρεχάρασσεν ξενικῶν μιμήσει ἐθισμῶν καὶ τοῦτ’ αὐτῷ ἀρχὴ κακοῦ γίνεται· γυναικὸς γὰρ ἑταιριζομένης παρὰ τοῖς Παλαιστίνοις ἐρασθεὶς Δαλάλης τοὔνομα συνῆν αὐτῇ. καὶ τῶν Παλαιστίνων οἱ τοῦ κοινοῦ προεστῶτες ἐλθόντες πρὸς αὐτὴν πείθουσιν ἐπαγγελίαις μαθεῖν παρὰ τοῦ Σαμψῶνος τὴν αἰτίαν τῆς ἰσχύος, ὑφ’ ἧς ἄληπτός ἐστι τοῖς ἐχθροῖς. ἡ δὲ παρὰ πότον καὶ τοιαύτην συνουσίαν θαυμάζουσα τὰς πράξεις αὐτοῦ ἐτεχνίτευε μαθεῖν, τίνι τρόπῳ τοσοῦτον προύχει κατ’ ἀρετήν. ὁ δὲ Σαμψών, ἔτι γὰρ φρονεῖν ἰσχυρὸς ἦν, ἀντηπάτα τὴν Δαλάλην φάμενος, εἰ κλήμασιν ἑπτὰ δεθείη ἀμπέλου ἔτι καὶ περιειλεῖσθαι δυναμένοις, ἀσθενέστερος ἂν πάντων ἔσοιτο. ἡ δὲ τότε μὲν ἡσύχασεν, ἀποσημήνασα δὲ τοῖς ἄρχουσι τῶν Παλαιστίνων ἐνίδρυσε τῶν στρατιωτῶν ἔνδον τινὰς καὶ μεθύοντα κατέδει τοῖς κλήμασι κατὰ τὸ ἰσχυρότατον, ἔπειτ’ ἀνεγείρασα ἐδήλου παρεῖναί τινας ἐπ’ αὐτόν. ὁ δὲ ῥήξας τὰ κλήματα βοηθεῖν ὡς ἐπερχομένων αὐτῷ τινων ἐπειρᾶτο. καὶ ἡ γυνὴ συνεχῶς ὁμιλοῦντος αὐτῇ τοῦ Σαμψῶνος δεινῶς ἔχειν ἔλεγεν, εἰ κατ’ ἀπιστίαν εὐνοίας τῆς πρὸς αὐτὸν μὴ λέγει ταῦθ’ ἅπερ δεῖται, ὡς οὐ σιγησομένης ὅσα μὴ γινώσκεσθαι συμφέρειν οἶδεν αὐτῷ. τοῦ δὲ πάλιν ἀπατῶντος αὐτὴν καὶ φήσαντος ἑπτὰ κάλοις δεθέντα τὴν ἰσχὺν ἀπολέσειν, ἐπεὶ καὶ τοῦτο ποιήσασα οὐδὲν ἤνυσεν, τρίτον συνυφῆναι τὰς κόμας αὐτοῦ ἐμήνυσεν. ὡς δ’ οὐδὲ τούτου γενομένου ἀληθὲς ηὑρίσκετο, δεομένης τελευταῖον ὁ Σαμψών, ἔδει γὰρ αὐτὸν συμφορᾷ περιπεσεῖν, χαρίζεσθαι βουλόμενος τῇ Δαλάλῃ, ἐμοῦ, φησίν, ὁ θεὸς κήδεται καὶ κατὰ τὴν ἐκείνου πρόνοιαν γεννηθεὶς κόμην ταύτην τρέφω παρεγγυήσαντος μὴ ἀποκείρειν τοῦ θεοῦ· τὴν γὰρ ἰσχὺν εἶναί μοι κατὰ τὴν ταύτης αὔξησιν καὶ παραμονήν. ταῦτα μαθοῦσα καὶ στερήσασα τῆς κόμης αὐτὸν παραδιδοῖ τοῖς πολεμίοις οὐκέτ’ ὄντα ἰσχυρὸν ἀμύνασθαι τὴν ἔφοδον αὐτῶν. οἱ δ’ ἐκκόψαντες αὐτοῦ τοὺς ὀφθαλμοὺς δεδεμένον ἄγειν παρέδοσαν.", "st": "5.8.11"}, {"sp": "N", "t": "Προϊόντος δὲ τοῦ χρόνου ηὔξετο ἡ κόμη τῷ Σαμψῶνι, καὶ ἑορτῆς οὔσης τοῖς Παλαιστίνοις δημοτελοῦς καὶ τῶν ἀρχόντων καὶ γνωριμωτάτων ἐν ταὐτῷ εὐωχουμένων, οἶκος δ’ ἦν δύο κιόνων στεγόντων αὐτοῦ τὸν ὄροφον, ἄγεται μεταπεμψαμένων ὁ Σαμψὼν εἰς τὸ συμπόσιον, ὅπως ἐνυβρίσωσιν αὐτῷ παρὰ τὸν πότον. ὁ δὲ δεινότερον τῶν κακῶν ὑπολαμβάνων τὸ μὴ δύνασθαι ὑβριζόμενος ἀμύνασθαι, τὸν χειραγωγοῦντα παῖδα πείθει, προσαναπαύσασθαι χρῄζειν εἰπὼν ὑπὸ κόπου, τοῖς κίοσιν αὐτὸν ἐγγὺς ἀγαγεῖν. ὡς δὲ ἧκεν, ἐνσεισθεὶς αὐτοῖς ἐπικαταβάλλει τὸν οἶκον ἀνατραπέντων τῶν κιόνων τρισχιλίοις ἀνδράσιν, οἳ πάντες ἀπέθανον, ἐν αὐτοῖς δὲ καὶ Σαμψών. καὶ τὸν μὲν τοιοῦτον κατέσχε τέλος ἄρξαντα τῶν Ἰσραηλιτῶν εἴκοσιν ἔτη. θαυμάζειν δὲ ἄξιον τῆς ἀρετῆς καὶ τῆς ἰσχύος καὶ τοῦ περὶ τὴν τελευτὴν μεγαλόφρονος τὸν ἄνδρα καὶ τῆς ὀργῆς τῆς μέχρι τοῦ τελευτᾶν πρὸς τοὺς πολεμίους. καὶ τὸ μὲν ὑπὸ γυναικὸς ἁλῶναι δεῖ τῇ φύσει τῶν ἀνθρώπων προσάπτειν ἥττονι ἁμαρτημάτων οὔσῃ, μαρτυρεῖν δὲ ἐκείνῳ τὴν εἰς τὰ ἄλλα πάντα τῆς ἀρετῆς περιουσίαν. οἱ δὲ συγγενεῖς ἀράμενοι τὸ σῶμα αὐτοῦ θάπτουσιν ἐν Σαρασᾶ τῇ πατρίδι μετὰ τῶν συγγενῶν.", "st": "5.8.12"}, {"sp": "N", "t": "Μετὰ δὲ τὴν Σαμψῶνος τελευτὴν προέστη τῶν Ἰσραηλιτῶν Ἠλὶς ὁ ἀρχιερεύς. ἐπὶ τούτου λιμῷ τῆς χώρας κακοπαθούσης αὐτῶν Ἀβιμέλεχος ἐκ Βηθλέμων, ἔστι δὲ ἡ πόλις αὕτη τῆς Ἰούδα φυλῆς, ἀντέχειν τῷ δεινῷ μὴ δυνάμενος τήν τε γυναῖκα Νααμεὶν καὶ τοὺς παῖδας τοὺς ἐξ αὐτῆς αὐτῷ γεγενημένους Χελλιῶνα καὶ Μαλαῶνα ἐπαγόμενος εἰς τὴν Μωαβῖτιν μετοικίζεται. καὶ προχωρούντων αὐτῷ κατὰ νοῦν τῶν πραγμάτων ἄγεται τοῖς υἱοῖς γυναῖκας Μωαβίτιδας Χελλιῶνι μὲν Ὀρφᾶν Ῥούθην δὲ Μαλαῶνι. διελθόντων δὲ δέκα ἐτῶν ὅ τε Ἀβιμέλεχος καὶ μετ’ αὐτὸν οἱ παῖδες δι’ ὀλίγου τελευτῶσι, καὶ ἡ Ναάμις πικρῶς ἐπὶ τοῖς συμβεβηκόσι φέρουσα καὶ τὴν ὑπ’ ὄψιν τῶν φιλτάτων ἐρημίαν οὐχ ὑπομένουσα, δι’ ἣν καὶ τῆς πατρίδος ἐξεληλύθει, πάλιν εἰς αὐτὴν ἀπηλλάττετο· καὶ γὰρ ἤδη καλῶς τὰ κατ’ αὐτὴν ἐπυνθάνετο χωρεῖν. οὐκ ἐκαρτέρουν δὲ διαζευγνύμεναι αὐτῆς αἱ νύμφαι, οὐδὲ παραιτουμένη βουλομένας συνεξορμᾶν πείθειν ἐδύνατο, ἀλλ’ ἐγκειμένων εὐξαμένη γάμον εὐτυχέστερον αὐταῖς οὗ διημαρτήκεσαν παισὶ τοῖς αὐτῆς γαμηθεῖσαι καὶ τῶν ἄλλων ἀγαθῶν κτῆσιν, ὅτε τὰ πρὸς αὐτὴν οὕτως ἐστί, μένειν αὐτόθι παρεκάλει καὶ μὴ συμμεταλαμβάνειν αὐτῇ βούλεσθαι πραγμάτων ἀδήλων τὴν πάτριον γῆν καταλιπούσας. ἡ μὲν οὖν Ὀρφᾶ μένει, τὴν δὲ Ῥούθην μὴ πεισθεῖσαν ἀπήγαγε κοινωνὸν παντὸς τοῦ προστυχόντος γενησομένην.", "st": "5.9.1"}, {"sp": "N", "t": "Ἐλθοῦσαν δὲ Ῥούθην μετὰ τῆς πενθερᾶς εἰς τὴν Βηθλεέμων Βοώζης Ἀβιμελέχου συγγενὴς ὢν δέχεται ξενίᾳ. καὶ ἡ Ναάμις, προσαγορευόντων αὐτὴν ὀνομαστί, δικαιότερον εἶπε Μαρὰν καλεῖτέ με· σημαίνει δὲ καθ’ Ἑβραίων γλῶτταν ναάμις μὲν εὐτυχίαν, μαρὰ δὲ ὀδύνην. ἀμήτου δὲ γενομένου ἐξῄει καλαμησομένη κατὰ συγχώρησιν τῆς πενθερᾶς ἡ Ῥούθη, ὅπως τροφῆς εὐποροῖεν, καὶ εἰς τὸ Βοώζου τυχαίως ἀφικνεῖται χωρίον. παραγενόμενος δὲ Βόαζος μετ’ ὀλίγον καὶ θεασάμενος τὴν κόρην ἀνέκρινε τὸν ἀγροκόμον περὶ τῆς παιδός. ὁ δὲ μικρὸν ἔμπροσθεν παρ’ αὐτῆς ἅπαντα προπεπυσμένος ἐδήλου τῷ δεσπότῃ. ὁ δὲ τῆς περὶ τὴν πενθερὰν εὐνοίας ἅμα καὶ μνήμης τοῦ παιδὸς αὐτῆς ᾧ συνῴκησεν ἀσπασάμενος καὶ εὐξάμενος αὐτῇ πεῖραν ἀγαθῶν καλαμᾶσθαι μὲν αὐτὴν οὐκ ἠξίωσεν, θερίζειν δὲ πᾶν ὅ τι καὶ δύναιτο καὶ λαμβάνειν ἐπιτρέπει προστάξας τῷ ἀγροκόμῳ μηδὲν αὐτὴν διακωλύειν λαμβάνειν, ἄριστόν τε παρέχειν αὐτῇ καὶ ποτόν, ὁπότε σιτίζοι τοὺς θερίζοντας. Ῥούθη δὲ ἄλφιτα λαβοῦσα παρ’ αὐτοῦ ἐφύλαξε τῇ ἑκυρᾷ καὶ παρῆν ὀψὲ κομίζουσα μετὰ τῶν σταχύων· ἐτετηρήκει δ’ αὐτῇ καὶ ἡ Ναάμις ἀπομοίρας βρωμάτων τινῶν, οἷς αὐτὴν ἐπολυώρουν οἱ γειτονεύοντες· διηγεῖται δὲ αὐτῇ καὶ τὰ παρὰ τοῦ Βοάζου πρὸς αὐτὴν εἰρημένα. δηλωσάσης δ’ ἐκείνης ὡς συγγενής ἐστι καὶ τάχα ἂν δι’ εὐσέβειαν προνοήσειεν αὐτῶν, ἐξῄει πάλιν ταῖς ἐχομέναις ἡμέραις ἐπὶ καλάμης συλλογὴν σὺν ταῖς Βοάζου θεραπαινίσιν.", "st": "5.9.2"}, {"sp": "N", "t": "Ἐλθών τε μετ’ οὐ πολλὰς ἡμέρας καὶ Βόαζος ἤδη τῆς κριθῆς λελικμημένης ἐπὶ τῆς ἅλωος ἐκάθευδε. τοῦτο πυθομένη ἡ Ναάμις τεχνᾶται παρακατακλῖναι τὴν Ῥούθην αὐτῷ· καὶ γὰρ ἔσεσθαι χρηστὸν αὐταῖς ὁμιλήσαντα τῇ παιδί· καὶ πέμπει τὴν κόρην ὑπνωσομένην αὐτοῦ παρὰ τοῖς ποσίν. ἡ δέ, πρὸς οὐδὲν γὰρ ἀντιλέγειν τῶν ὑπὸ τῆς ἑκυρᾶς κελευομένων ὅσιον ἡγεῖτο, παραγίνεται καὶ παραυτίκα μὲν λανθάνει τὸν Βόαζον βαθέως καθυπνωκότα, περιεγερθεὶς δὲ περὶ μέσην νύκτα καὶ αἰσθόμενος τῆς ἀνθρώπου παρακατακειμένης ἀνέκρινε τίς εἴη. τῆς δ’ εἰπούσης τοὔνομα καὶ φαμένης ὡς αὐτῆς δεσπότην συγχωρεῖν, τότε μὲν ἡσυχίαν ἄγει, ὄρθριος δὲ πρὶν ἢ τοὺς οἰκέτας ἄρξασθαι κινεῖσθαι πρὸς τὸ ἔργον περιεγείρας αὐτὴν κελεύει τῶν κριθῶν λαβοῦσαν ὅ τι καὶ δύναιτο πορεύεσθαι πρὸς τὴν ἑκυρὰν πρὶν ὀφθῆναί τισιν αὐτόθι κεκοιμημένην, φυλάττεσθαι σῶφρον τὴν ἐπὶ τοιούτοις διαβολὴν καὶ μάλιστ’ ἐπὶ μὴ γεγονόσι. περὶ μέντοι τοῦ παντὸς οὕτω, φησίν, ἔσται, [ἐρωτᾶν] τὸν ἔγγιστά μου τῷ γένει τυγχάνοντα, εἰ σοῦ χρεία γαμετῆς ἐστιν αὐτῷ, καὶ λέγοντι μὲν ἀκολουθήσεις ἐκείνῳ, παραιτουμένου δὲ νόμῳ σε συνοικήσουσαν ἄξομαι.", "st": "5.9.3"}, {"sp": "N", "t": "Ταῦτα τῇ ἑκυρᾷ δηλωσάσης εὐθυμία κατεῖχεν αὐτὰς ἐν ἐλπίδι τοῦ πρόνοιαν ἕξειν αὐτῶν Βόαζον γενομένας. κἀκεῖνος ἤδη μεσούσης τῆς ἡμέρας κατελθὼν εἰς τὴν πόλιν τήν τε γερουσίαν συνῆγε καὶ μεταπεμψάμενος Ῥούθην ἐκάλει καὶ τὸν συγγενῆ, καὶ παραγενομένου φησίν· Ἀβιμελέχου καὶ τῶν υἱῶν αὐτοῦ κλήρων κρατεῖς; ὁμολογήσαντος δὲ συγχωρούντων τῶν νόμων κατὰ ἀγχιστείαν, οὐκοῦν, φησὶν ὁ Βόαζος, οὐκ ἐξ ἡμισείας δεῖ μεμνῆσθαι τῶν νόμων. ἀλλὰ πάντα ποιεῖν κατ’ αὐτούς. Μαάλου γὰρ δεῦρ’ ἥκει γύναιον, ὅπερ εἰ θέλεις τῶν ἀγρῶν κρατεῖν γαμεῖν σε δεῖ κατὰ τοὺς νόμους. ὁ δὲ Βοάζῳ καὶ τοῦ κλήρου καὶ τῆς γυναικὸς παρεχώρει συγγενεῖ μὲν ὄντι καὶ αὐτῷ τῶν τετελευτηκότων, εἶναι δὲ καὶ γυναῖκα λέγων αὐτῷ καὶ παῖδας ἤδη. μαρτυράμενος οὖν ὁ Βόαζος τὴν γερουσίαν ἐκέλευε τῇ γυναικὶ ὑπολῦσαι αὐτὸν προσελθοῦσαν κατὰ τὸν νόμον καὶ πτύειν εἰς τὸ πρόσωπον. γενομένου δὲ τούτου Βόαζος γαμεῖ τὴν Ῥούθην καὶ γίνεται παιδίον αὐτοῖς μετ’ ἐνιαυτὸν ἄρρεν. τοῦτο ἡ Ναάμις τιτθευομένη κατὰ συμβουλίαν τῶν γυναικῶν Ὠβήδην ἐκάλεσεν ἐπὶ γηροκομίᾳ τῇ αὐτῆς τραφησόμενον· ὠβήδης γὰρ κατὰ διάλεκτον τὴν Ἑβραίων ἀποσημαίνει δουλεύων. Ὠβήδου δὲ γίνεται παῖς Ἰεσσαῖος, τούτου Δαβίδης ὁ βασιλεύσας καὶ παισὶ τοῖς αὐτοῦ καταλιπὼν τὴν ἡγεμονίαν ἐπὶ μίαν καὶ εἴκοσι γενεὰς ἀνδρῶν. τὰ μὲν οὖν κατὰ Ῥούθην ἀναγκαίως διηγησάμην ἐπιδεῖξαι βουλόμενος τὴν τοῦ θεοῦ δύναμιν, ὅτι τούτῳ παράγειν ἐφικτόν ἐστιν εἰς ἀξίωμα λαμπρὸν καὶ τοὺς ἐπιτυχόντας, εἰς οἷον ἀνήγαγε καὶ Δαβίδην ἐκ τοιούτων γενόμενον.", "st": "5.9.4"}, {"sp": "N", "t": "Ἑβραῖοι δὲ τῶν πραγμάτων αὐτοῖς ὑπενεχθέντων πάλιν πόλεμον ἐκφέρουσι Παλαιστίνοις διὰ τοιαύτην αἰτίαν· Ἠλὶ τῷ ἀρχιερεῖ δύο παῖδες ἦσαν Ὁφνίης τε καὶ Φινεέσης. οὗτοι καὶ πρὸς ἀνθρώπους ὑβρισταὶ γενόμενοι καὶ πρὸς τὸ θεῖον ἀσεβεῖς οὐδενὸς ἀπείχοντο παρανομήματος, καὶ τὰ μὲν ἐφέροντο τῶν γερῶν κατὰ τιμήν, ἃ δ’ ἐλάμβανον αὐτοῖς ἁρπαγῆς τρόπῳ, γυναῖκάς τε τὰς ἐπὶ θρησκείᾳ παραγινομένας ὕβριζον φθοραῖς ταῖς μὲν βίαν προσφέροντες τὰς δὲ δώροις ὑπαγόμενοι· τυραννίδος δ’ οὐθὲν ἀπέλειπεν ὁ βίος αὐτῶν. ὅ τε οὖν πατὴρ αὐτὸς ἐπὶ τούτοις χαλεπῶς εἶχεν ὅσον οὐδέπω προσδοκῶν ἥξειν ἐκ θεοῦ τιμωρίαν αὐτοῖς ἐπὶ τοῖς πραττομένοις, τό τε πλῆθος ἐδυσφόρει, κἀπειδὴ φράζει τὴν ἐσομένην συμφορὰν ὁ θεὸς τοῖς παισὶν αὐτοῦ τῷ τε Ἠλὶ καὶ Σαμουήλῳ τῷ προφήτῃ παιδὶ τότε ὄντι, τότε φανερὸν ἐπὶ τοῖς υἱοῖς πένθος ἦγε.", "st": "5.10.1"}, {"sp": "N", "t": "Βούλομαι δὲ τὰ περὶ τοῦ προφήτου πρότερον διεξελθὼν ἔπειθ’ οὕτως τὰ περὶ τοὺς Ἠλὶ παῖδας εἰπεῖν καὶ τὴν δυστυχίαν τὴν τῷ παντὶ λαῷ Ἑβραίων γενομένην. Ἀλκάνης Λευίτης ἀνὴρ τῶν ἐν μέσῳ πολιτῶν τῆς Ἐφράμου κληρουχίας Ῥαμαθὰν πόλιν κατοικῶν ἐγάμει δύο γυναῖκας Ἄνναν τε καὶ Φενάνναν. ἐκ δὴ ταύτης καὶ παῖδες αὐτῷ γίνονται, τὴν δ’ ἑτέραν ἄτεκνον οὖσαν ἀγαπῶν διετέλει. ἀφικομένου δὲ μετὰ τῶν γυναικῶν τοῦ Ἀλκάνου εἰς Σιλὼ πόλιν θῦσαι, ἐνταῦθα γὰρ ἡ σκηνὴ τοῦ θεοῦ ἐπεπήγει καθὼς προειρήκαμεν, καὶ πάλιν κατὰ τὴν εὐωχίαν νέμοντος μοίρας κρεῶν ταῖς τε γυναιξὶ καὶ τοῖς τέκνοις, ἡ Ἄννα θεασαμένη τοὺς τῆς ἑτέρας παῖδας τῇ μητρὶ περικαθημένους, εἰς δάκρυά τε προύπεσε καὶ τῆς ἀπαιδίας αὑτὴν ὠλοφύρετο καὶ τῆς μονώσεως. καὶ τῆς τἀνδρὸς παραμυθίας τῇ λύπῃ κρατήσασα εἰς τὴν σκηνὴν ᾤχετο τὸν θεὸν ἱκετεύουσα δοῦναι γονὴν αὐτῇ καὶ ποιῆσαι μητέρα, ἐπαγγελλομένη τὸ πρῶτον αὐτῇ γενησόμενον καθιερώσειν ἐπὶ διακονίᾳ τοῦ θεοῦ δίαιταν οὐχ ὁμοίαν τοῖς ἰδιώταις ποιησόμενον. διατριβούσης δ’ ἐπὶ ταῖς εὐχαῖς πολὺν χρόνον Ἠλὶς ὁ ἀρχιερεύς, ἐκαθέζετο γὰρ πρὸ τῆς σκηνῆς, ὡς παροινοῦσαν ἐκέλευεν ἀπιέναι. τῆς δὲ πιεῖν ὕδωρ φαμένης, λυπουμένης δ’ ἐπὶ παίδων ἀπορίᾳ τὸν θεὸν ἱκετεύειν, θαρσεῖν παρεκελεύετο παρέξειν αὐτῇ παῖδας τὸν θεὸν καταγγέλλων.", "st": "5.10.2"}, {"sp": "N", "t": "Παραγενομένη δ’ εὔελπις πρὸς τὸν ἄνδρα τροφὴν χαίρουσα προσηνέγκατο, καὶ ἀναστρεψάντων εἰς τὴν πατρίδα κύειν ἤρξατο καὶ γίνεται παιδίον αὐτοῖς, ὃν Σαμουῆλον προσαγορεύουσι· θεαίτητον ἄν τις εἴποι. παρῆσαν οὖν ὑπὲρ τῆς τοῦ παιδὸς θύσοντες γενέσεως δεκάτας τ’ ἔφερον. ἀναμνησθεῖσα δ’ ἡ γυνὴ τῆς εὐχῆς τῆς ἐπὶ τῷ παιδὶ γεγενημένης παρεδίδου τῷ Ἠλὶ ἀνατιθεῖσα τῷ θεῷ προφήτην γενησόμενον· κόμη τε οὖν αὐτῷ ἀνεῖτο καὶ ποτὸν ἦν ὕδωρ. καὶ Σαμουῆλος μὲν ἐν τῷ ἱερῷ διῆγε τρεφόμενος, Ἀλκάνῃ δ’ ἐκ τῆς Ἄννας υἱεῖς τε γίνονται καὶ τρεῖς θυγατέρες.", "st": "5.10.3"}, {"sp": "N", "t": "Σαμουῆλος δὲ πεπληρωκὼς ἔτος ἤδη δωδέκατον προεφήτευε. καί ποτε κοιμώμενον ὀνομαστὶ ἐκάλεσεν ὁ θεός· ὁ δὲ νομίσας ὑπὸ τοῦ ἀρχιερέως πεφωνῆσθαι παραγίνεται πρὸς αὐτόν. οὐ φαμένου δὲ καλέσαι τοῦ ἀρχιερέως ὁ θεὸς εἰς τρὶς τοῦτο ποιεῖ. καὶ Ἠλὶς διαυγασθείς φησι πρὸς αὐτόν, ἀλλ’ ἐγὼ [μὲν], Σαμουῆλε, σιγὴν ὡς καὶ τὸ πρὶν ἦγον, θεὸς δ’ ἐστὶν ὁ καλῶν, σήμαινέ τε πρὸς αὐτόν, ὅτι παρατυγχάνω. καὶ τοῦ θεοῦ φθεγξαμένου πάλιν ἀκούσας ἠξίου λαλεῖν ἐπὶ τοῖς χρωμένοις· οὐ γὰρ ὑστερήσειν αὐτὸν ἐφ’ οἷς ἂν θελήσῃ διακονίας. καὶ ὁ θεός ἐπεί, φησί, παρατυγχάνεις, μάνθανε συμφορὰν Ἰσραηλίταις ἐσομένην λόγου μείζονα καὶ πίστεως τοῖς παρατυγχάνουσι, καὶ τοὺς Ἠλὶ δὲ παῖδας ἡμέρᾳ μιᾷ τεθνηξομένους καὶ τὴν ἱερωσύνην μετελευσομένην εἰς τὴν Ἐλεαζάρου οἰκίαν· Ἠλὶς γὰρ τῆς ἐμῆς θεραπείας μᾶλλον τοὺς υἱοὺς καὶ παρὰ τὸ συμφέρον αὐτοῖς ἠγάπησε. ταῦτα βιασάμενος ὅρκοις εἰπεῖν αὐτῷ τὸν προφήτην Ἠλίς, οὐ γὰρ ἐβούλετο λυπεῖν αὐτὸν λέγων, ἔτι μᾶλλον βεβαιοτέραν εἶχε τὴν προσδοκίαν τῆς τῶν τέκνων ἀπωλείας. Σαμουήλου δὲ ηὔξετο ἐπὶ πλέον ἡ δόξα πάντων ὧν προεφήτευσεν ἀληθινῶν βλεπομένων.", "st": "5.10.4"}, {"sp": "N", "t": "Κατὰ τοῦτον δὴ τὸν καιρὸν καὶ Παλαιστῖνοι στρατεύσαντες ἐπὶ τοὺς Ἰσραηλίτας στρατοπεδεύονται κατὰ πόλιν Ἀμφεκᾶν, δεξαμένων δ’ ἐξ ὀλίγου τῶν Ἰσραηλιτῶν συνῄεσαν εἰς τὴν ἐχομένην καὶ νικῶσιν οἱ Παλαιστῖνοι καὶ κτείνουσι μὲν τῶν Ἑβραίων εἰς τετρακισχιλίους, τὸ δὲ λοιπὸν πλῆθος συνδιώκουσιν εἰς τὸ στρατόπεδον.", "st": "5.11.1"}, {"sp": "N", "t": "Δείσαντες δὲ περὶ τῶν ὅλων Ἑβραῖοι πέμπουσιν ὡς τὴν γερουσίαν καὶ τὸν ἀρχιερέα τὴν κιβωτὸν τοῦ θεοῦ κελεύοντες κομίζειν, ἵνα παρούσης αὐτῆς παρατασσόμενοι κρατῶσι τῶν πολεμίων ἀγνοοῦντες, ὅτι μείζων ἐστὶν ὁ καταψηφισάμενος αὐτῶν τὴν συμφορὰν τῆς κιβωτοῦ, δι’ ὃν καὶ ταύτην συνέβαινεν εἶναι. παρῆν τε οὖν ἡ κιβωτὸς καὶ οἱ τοῦ ἀρχιερέως υἱεῖς τοῦ πατρὸς αὐτοῖς ἐπιστείλαντος, εἰ ληφθείσης τῆς κιβωτοῦ ζῆν ἐθέλουσιν, εἰς ὄψιν αὐτῷ μὴ παραγίνεσθαι. Φινεέσης δὲ ἤδη καὶ ἱερᾶτο τοῦ πατρὸς αὐτῷ παρακεχωρηκότος διὰ τὸ γῆρας. θάρσος οὖν ἐπιγίνεται πολὺ τοῖς Ἑβραίοις ὡς διὰ τὴν ἄφιξιν τῆς κιβωτοῦ περιεσομένοις τῶν πολεμίων, κατεπλήττοντο δὲ οἱ πολέμιοι δεδιότες τὴν παρουσίαν τῆς κιβωτοῦ τοῖς Ἰσραηλίταις. ταῖς μέντοι γε ἑκατέρων προσδοκίαις οὐχ ὅμοιον ἀπήντησε τὸ ἔργον, ἀλλὰ συμβολῆς γενομένης ἣν μὲν ἤλπιζον νίκην Ἑβραῖοι τῶν Παλαιστίνων αὕτη γίνεται, ἣν δ’ ἐφοβοῦντο ἧτταν οὗτοι ταύτην Ἑβραῖοι παθόντες ἔγνωσαν αὐτοὺς μάτην ἐπὶ τῇ κιβωτῷ τεθαρσηκότας· ἐτράπησάν τε γὰρ εὐθὺς εἰς χεῖρας ἐλθόντες τῶν πολεμίων καὶ ἀπέβαλον εἰς τρισμυρίους, ἐν οἷς ἔπεσον καὶ οἱ τοῦ ἀρχιερέως υἱεῖς, ἥ τε κιβωτὸς ἤγετο πρὸς τῶν πολεμίων.", "st": "5.11.2"}, {"sp": "N", "t": "Ἀπαγγελθείσης δὲ τῆς ἥττης εἰς τὴν Σιλὼ καὶ τῆς αἰχμαλωσίας τῆς κιβωτοῦ, Βενιαμίτης γάρ τις αὐτοῖς ἄγγελος ἀφικνεῖται νεανίας παρατετευχὼς τῷ γεγονότι, πένθους ἀνεπλήσθη πᾶσα ἡ πόλις. καὶ Ἠλὶς ὁ ἀρχιερεύς, ἐκαθέζετο γὰρ καθ’ ἑτέρας τῶν πυλῶν ἐφ’ ὑψηλοῦ θρόνου, ἀκούσας οἰμωγῆς καὶ νομίσας νεώτερόν τι πεπρᾶχθαι περὶ τοὺς οἰκείους καὶ μεταπεμψάμενος τὸν νεανίαν, ὡς ἔγνω τὰ κατὰ τὴν μάχην, ῥᾴων ἦν ἐπὶ τὸ τοῖς παισὶ τοῖς αὐτοῦ συνενηνεγμένοις περὶ τὸ στρατόπεδον ὡς ἂν προεγνωκὼς παρὰ τοῦ θεοῦ τὸ συμβησόμενον καὶ προαπηγγελκώς· συνέχει γὰρ ἀκριβῶς τὰ κατὰ προσδοκίαν συντυχόντα τῶν δεινῶν. ὡς δὲ καὶ τὴν κιβωτὸν ἤκουσεν ᾐχμαλωτίσθαι πρὸς τῶν πολεμίων, ὑπὸ τοῦ παρ’ ἐλπίδας αὐτῷ τοῦτο προσπεσεῖν περιαλγήσας ἀποκυλισθεὶς ἀπὸ τοῦ θρόνου τελευτᾷ, ὀκτὼ καὶ ἐνενήκοντα βιώσας ἔτη τὰ πάντα καὶ τούτων τεσσαράκοντα κατασχὼν τὴν ἀρχήν.", "st": "5.11.3"}, {"sp": "N", "t": "Θνήσκει δὲ κατ’ ἐκείνην τὴν ἡμέραν καὶ ἡ Φινεέσου τοῦ παιδὸς γυνὴ μὴ καρτερήσασα ζῆν ἐπὶ τῇ τἀνδρὸς δυστυχίᾳ. κυούσῃ μὲν αὐτῇ προσηγγέλη τὸ περὶ τὸν ἄνδρα πάθος, τίκτει δ’ ἑπταμηνιαῖον παῖδα, ὃν καὶ ζήσαντα Ἰαχώβην προσηγόρευσαν, σημαίνει δὲ ἀδοξίαν τὸ ὄνομα, διὰ τὴν προσπεσοῦσαν δύσκλειαν τότε τῷ στρατῷ.", "st": "5.11.4"}, {"sp": "N", "t": "Ἦρξε δὲ πρῶτος Ἠλὶς Ἰθαμάρου τῆς ἑτέρου τῶν Ἀαρῶνος υἱῶν οἰκίας· ἡ γὰρ Ἐλεαζάρου οἰκία τὸ πρῶτον ἱερᾶτο παῖς παρὰ πατρὸς ἐπιδεχόμενοι τὴν τιμήν, ἐκεῖνός τε Φινεέσῃ τῷ παιδὶ αὐτοῦ παραδίδωσι, μεθ’ ὃν Ἀβιεζέρης υἱὸς ὢν αὐτοῦ τὴν τιμὴν παραλαβὼν παιδὶ αὐτοῦ Βόκκι τοὔνομα αὐτὴν κατέλιπε, παρ’ οὗ διεδέξατο Ὄζις υἱὸς ὤν, μεθ’ ὃν Ἠλὶς ἔσχε τὴν ἱερωσύνην, περὶ οὗ νῦν ὁ λόγος, καὶ τὸ γένος τὸ ἀπ’ ἐκείνου μέχρι τῶν κατὰ τὴν τοῦ Σολομῶνος βασιλείαν καιρῶν. τότε δὲ οἱ Ἐλεαζάρου πάλιν αὐτὴν ἀπέλαβον.", "st": "5.11.5"}, {"sp": "HDR", "t": "Βιβλίον Ϛʹ", "st": "6"}, {"sp": "N", "t": "Λαβόντες δ’ οἱ Παλαιστῖνοι τὴν τῶν πολεμίων κιβωτὸν αἰχμάλωτον, ὡς προειρήκαμεν μικρὸν ἔμπροσθεν, εἰς Ἄζωτον ἐκόμισαν πόλιν καὶ παρὰ τὸν αὐτῶν θεὸν ὥσπερ τι λάφυρον, Δαγὼν δ’ οὗτος ἐκαλεῖτο, τιθέασι. τῇ δ’ ἐπιούσῃ πάντες ὑπὸ τὴν τῆς ἡμέρας ἀρχὴν εἰσιόντες εἰς τὸν ναὸν προσκυνῆσαι τὸν θεὸν ἐπιτυγχάνουσιν αὐτῷ τοῦτο ποιοῦντι τὴν κιβωτὸν· ἔκειτο γὰρ ἐπ’ αὐτῆς ἀποπεπτωκὼς τῆς βάσεως, ἐφ’ ἧς ἑστὼς διετέλει· καὶ βαστάσαντες πάλιν ἐφιστᾶσιν αὐτὸν ἐπὶ ταύτης δυσφορήσαντες ἐπὶ τῷ γεγενημένῳ. πολλάκις δὲ φοιτῶντες παρὰ τὸν Δαγὼν καὶ καταλαμβάνοντες ὁμοίως ἐπὶ τοῦ προσκυνοῦντος τὴν κιβωτὸν σχήματος κείμενον ἐν ἀπορίᾳ δεινῇ καὶ συγχύσει καθίσταντο. καὶ τελευταῖον ἀπέσκηψεν εἰς τὴν τῶν Ἀζωτίων πόλιν καὶ τὴν χώραν αὐτῶν φθορὰν τὸ θεῖον καὶ νόσον· ἀπέθνησκον γὰρ ὑπὸ δυσεντερίας, πάθους χαλεποῦ καὶ τὴν ἀναίρεσιν ὀξυτάτην ἐπιφέροντος πρὶν ἢ τὴν ψυχὴν αὐτοῖς εὐθανάτως ἀπολυθῆναι τοῦ σώματος, τὰ ἐντὸς ἀναφέροντες [ἐξεμοῦντες] διαβεβρωμένα καὶ παντοίως ὑπὸ τῆς νόσου διεφθαρμένα· τὰ δ’ ἐπὶ τῆς χώρας μυῶν πλῆθος ἀνελθὸν ἐπὶ τῆς γῆς κατέβλαψε μήτε φυτῶν μήτε καρπῶν ἀποσχόμενον. ἐν δὴ τούτοις ὄντες τοῖς κακοῖς οἱ Ἀζώτιοι καὶ πρὸς τὰς συμφορὰς ἀντέχειν οὐ δυνάμενοι συνῆκαν ἐκ τῆς κιβωτοῦ ταύτας αὐτοῖς ἀνασχεῖν, καὶ τὴν νίκην καὶ τὴν ταύτης αἰχμαλωσίαν οὐκ ἐπ’ ἀγαθῷ γεγενημένην. πέμπουσιν οὖν πρὸς τοὺς Ἀσκαλωνίτας ἀξιοῦντες τὴν κιβωτὸν αὐτοὺς παρὰ σφᾶς δέχεσθαι. τοῖς δὲ οὐκ ἀηδὴς ἡ τῶν Ἀζωτίων δέησις προσέπεσεν, ἀλλ’ ἐπινεύουσι μὲν αὐτοῖς τὴν χάριν, λαβόντες δὲ τὴν κιβωτὸν ἐν τοῖς ὁμοίοις δεινοῖς κατέστησαν· συνεξεκόμισε γὰρ αὑτῇ τὰ τῶν Ἀζωτίων ἡ κιβωτὸς πάθη πρὸς τοὺς ἀπ’ ἐκείνων αὐτὴν δεχομένους· καὶ πρὸς ἄλλους παρ’ αὑτῶν ἀποπέμπουσιν Ἀσκαλωνῖται. μένει δ’ οὐδὲ παρ’ ἐκείνοις· ὑπὸ γὰρ τῶν αὐτῶν παθῶν ἐλαυνόμενοι πρὸς τὰς ἐχομένας ἀπολύουσι πόλεις. καὶ τοῦτον ἐκπεριέρχεται τὸν τρόπον τὰς πέντε τῶν Παλαιστίνων πόλεις ἡ κιβωτὸς ὥσπερ δασμὸν ἀπαιτοῦσα παρ’ ἑκάστης τοῦ πρὸς αὐτὰς ἐλθεῖν ἃ δι’ αὐτὴν ἔπασχον.", "st": "6.1.1"}, {"sp": "N", "t": "Ἀπειρηκότες δὲ τοῖς κακοῖς οἱ πεπειραμένοι καὶ τοῖς ἀκούουσιν αὐτὰ διδασκαλία γινόμενοι τοῦ μὴ προσδέξασθαι τὴν κιβωτόν ποτε πρὸς αὑτοὺς ἐπὶ τοιούτῳ μισθῷ καὶ τέλει, τὸ λοιπὸν ἐζήτουν μηχανὴν καὶ πόρον ἀπαλλαγῆς αὐτῆς. καὶ συνελθόντες οἱ ἐκ τῶν [πέντε] πόλεων ἄρχοντες, Γίττης καὶ Ἀκάρων καὶ Ἀσκάλωνος ἔτι δὲ Γάζης καὶ Ἀζώτου, ἐσκόπουν τί δεῖ ποιεῖν. καὶ τὸ μὲν πρῶτον ἐδόκει τὴν κιβωτὸν ἀποπέμπειν τοῖς οἰκείοις, ὡς ὑπερεκδικοῦντος αὐτὴν τοῦ θεοῦ καὶ συνεπιδημησάντων αὐτῇ τῶν δεινῶν διὰ τοῦτο καὶ συνεισβαλόντων μετ’ ἐκείνης εἰς τὰς πόλεις αὐτῶν· ἦσαν δὲ οἱ λέγοντες τοῦτο μὲν μὴ ποιεῖν μηδ’ ἐξαπατᾶσθαι τὴν αἰτίαν τῶν κακῶν εἰς ἐκείνην ἀναφέροντας· οὐ γὰρ ταύτην εἶναι τὴν δύναμιν αὐτῇ καὶ τὴν ἰσχύν· οὐ γὰρ ἄν ποτ’ αὐτῆς κηδομένου τοῦ θεοῦ ὑποχείριον ἀνθρώποις γενέσθαι. ἡσυχάζειν δὲ καὶ πρᾴως ἔχειν ἐπὶ τοῖς συμβεβηκόσι παρῄνουν αἰτίαν τούτων οὐκ ἄλλην ἢ μόνην λογιζομένους τὴν φύσιν, ἣ καὶ σώμασι καὶ γῇ καὶ φυτοῖς καὶ πᾶσι τοῖς ἐξ αὐτῆς συνεστῶσι κατὰ χρόνων περιόδους τίκτει τοιαύτας μεταβολάς. νικᾷ δὲ τὰς προειρημένας γνώμας ἀνδρῶν ἔν τε τοῖς ἐπάνω χρόνοις συνέσει καὶ φρονήσει διαφέρειν πεπιστευμένων συμβουλία καὶ τότε μάλιστα δοξάντων· ἁρμοζόντως λέγειν τοῖς παροῦσιν, οἳ μήτ’ ἀποπέμπειν ἔφασαν τὴν κιβωτὸν μήτε κατασχεῖν, ἀλλὰ πέντε μὲν ἀνδριάντας ὑπὲρ ἑκάστης πόλεως χρυσοῦς ἀναθεῖναι τῷ θεῷ χαριστήριον, ὅτι προενόησεν αὐτῶν τῆς σωτηρίας καὶ κατέσχεν ἐν τῷ βίῳ διωκομένους ἐξ αὐτοῦ παθήμασιν, οἷς οὐκέτι ἦν ἀντιβλέψαι, τοσούτους δὲ τὸν ἀριθμὸν μύας χρυσοῦς τοῖς κατανεμηθεῖσιν αὐτῶν καὶ διαφθείρασι τὴν χώραν ἐμφερεῖς· ἔπειτα βαλόντας εἰς γλωσσόκομον αὐτοὺς καὶ θέντας ἐπὶ τὴν κιβωτὸν ἅμαξαν αὐτῇ καινὴν κατασκευάσαι, καὶ βόας ὑποζεύξαντας ἀρτιτόκους τὰς μὲν πόρτις ἐγκλεῖσαι καὶ κατασχεῖν, μὴ ταῖς μητράσιν ἐμποδὼν ἑπόμεναι γένωνται, πόθῳ δ’ αὐτῶν ὀξυτέραν ποιῶνται τὴν πορείαν· ἐκείνας δ’ ἐξελάσαντας τὴν κιβωτὸν φερούσας ἐπὶ τριόδου καταλιπεῖν αὐταῖς ἐπιτρέψαντας ἣν βούλονται τῶν ὁδῶν ἀπελθεῖν· κἂν μὲν τὴν Ἑβραίων ἀπίωσι καὶ τὴν τούτων χώραν ἀναβαίνωσιν, ὑπολαμβάνειν τὴν κιβωτὸν αἰτίαν τῶν κακῶν, ἂν δὲ ἄλλην τράπωνται, μεταδιώξωμεν αὐτὴν, ἔφασαν, μαθόντες ὅτι μηδεμίαν ἰσχὺν τοιαύτην ἔχει.", "st": "6.1.2"}, {"sp": "N", "t": "Ἔκριναν δ’ αὐτὰ καλῶς εἰρῆσθαι καὶ τοῖς ἔργοις εὐθὺς τὴν γνώμην ἐκύρωσαν. καὶ ποιήσαντες μὲν τὰ προειρημένα προάγουσιν [τὴν ἅμαξαν] ἐπὶ τὴν τρίοδον καὶ καταλιπόντες ἀνεχώρησαν, τῶν δὲ βοῶν τὴν ὀρθὴν ὁδὸν ὥσπερ ἡγουμένου τινὸς αὐταῖς ἀπιουσῶν ἠκολούθουν οἱ τῶν Παλαιστίνων ἄρχοντες, ποῦ ποτε στήσονται καὶ πρὸς τίνας ἥξουσι βουλόμενοι μαθεῖν. κώμη δέ τίς ἐστι τῆς Ἰούδα φυλῆς Βήθης ὄνομα· εἰς ταύτην ἀφικνοῦνται αἱ βόες, καὶ πεδίου μεγάλου καὶ καλοῦ τὴν πορείαν αὐτῶν ἐκδεξαμένου παύονται προσωτέρω χωρεῖν στήσασαι τὴν ἅμαξαν αὐτόθι. θέα δὲ ἦν τοῖς ἐν τῇ κώμῃ καὶ περιχαρεῖς ἐγένοντο· θέρους γὰρ ὥρᾳ πάντες ἐπὶ τὴν συγκομιδὴν τῶν καρπῶν ἐν ταῖς ἀρούραις ὑπάρχοντες ὡς εἶδον τὴν κιβωτὸν ὑφ’ ἡδονῆς ἁρπαγέντες καὶ τὸ ἔργον ἐκ τῶν χειρῶν ἀφέντες ἔδραμον εὐθὺς ἐπὶ τὴν ἅμαξαν. καὶ καθελόντες τὴν κιβωτὸν καὶ τὸ ἄγγος, ὃ τοὺς ἀνδριάντας εἶχε καὶ τοὺς μύας, τιθέασιν ἐπί τινος πέτρας, ἥτις ἦν ἐν τῷ πεδίῳ, καὶ θύσαντες λαμπρῶς τῷ θεῷ καὶ κατευωχηθέντες τήν τε ἅμαξαν καὶ τοὺς βόας ὡλοκαύτωσαν. καὶ ταῦτ’ ἰδόντες οἱ τῶν Παλαιστίνων ἄρχοντες ἀνέστρεψαν ὀπίσω.", "st": "6.1.3"}, {"sp": "N", "t": "Ὀργὴ δὲ καὶ χόλος τοῦ θεοῦ μέτεισιν ἑβδομήκοντα τῶν ἐκ τῆς Βήθης κώμης, οὓς οὐκ ὄντας ἀξίους ἅψασθαι τῆς κιβωτοῦ, ἱερεῖς γὰρ οὐκ ἦσαν, καὶ προσελθόντας αὐτῇ βαλὼν ἀπέκτεινεν. ἔκλαυσαν δὲ ταῦτα παθόντας αὐτοὺς οἱ κωμῆται, καὶ πένθος ἐπ’ αὐτοῖς ἤγειραν οἷον εἰκὸς ἐπὶ θεοπέμπτῳ κακῷ καὶ τὸν ἴδιον ἕκαστος ἀπεθρήνει· τοῦ τε μένειν τὴν κιβωτὸν παρ’ αὐτοῖς ἀναξίους ἀποφαίνοντες αὑτοὺς καὶ πρὸς τὸ κοινὸν τῶν Ἑβραίων πέμψαντες ἐδήλουν ἀποδεδόσθαι τὴν κιβωτὸν ὑπὸ τῶν Παλαιστίνων. κἀκεῖνοι γνόντες τοῦτο ἀποκομίζουσιν αὐτὴν εἰς Καριαθιαρεὶμ γείτονα πόλιν τῆς Βήθης κώμης. ἔνθα τινὸς Λευΐτου τὸ γένος Ἀμιναδάβου δόξαν ἔχοντος ἐπὶ δικαιοσύνῃ καὶ θρησκείᾳ καταβιοῦντος εἰς οἰκίαν τὴν κιβωτὸν ἤγαγον, ὥσπερ εἰς πρέποντα τῷ θεῷ τόπον ἐν ᾧ κατῴκει δίκαιος ἄνθρωπος. ἐθεράπευον δὲ τὴν κιβωτὸν οἱ τούτου παῖδες καὶ τῆς ἐπιμελείας ταύτης ἕως ἐτῶν εἴκοσι προέστησαν· τοσαῦτα γὰρ ἔμεινεν ἐν τῇ Καριαθιαρεὶμ ποιήσασα παρὰ τοῖς Παλαιστίνοις μῆνας τέσσαρας.", "st": "6.1.4"}, {"sp": "N", "t": "Τοῦ δὲ λαοῦ παντὸς ἐκείνῳ τῷ χρόνῳ, καθ’ ὃν εἶχεν ἡ τῶν Καριαθιαρειμιτῶν πόλις τὴν κιβωτὸν, ἐπ’ εὐχὰς καὶ θυσίας τραπέντος τοῦ θεοῦ καὶ πολλὴν ἐμφανίζοντος τὴν περὶ αὐτὸν θρησκείαν καὶ φιλοτιμίαν, ὁ προφήτης Σαμουῆλος ἰδὼν αὐτῶν τὴν προθυμίαν, ὡς εὔκαιρον πρὸς οὕτως ἔχοντας εἰπεῖν περὶ ἐλευθερίας καὶ τῶν ἀγαθῶν τῶν ἐν αὐτῇ, χρῆται λόγοις οἷς ᾤετο μάλιστα τὴν διάνοιαν αὐτῶν προσάξεσθαι καὶ πείσειν· ἄνδρες, γὰρ εἶπεν, οἷς ἔτι νῦν βαρεῖς μὲν πολέμιοι Παλαιστῖνοι, θεὸς δ’ εὐμενὴς ἄρχεται γίνεσθαι καὶ φίλος, οὐκ ἐπιθυμεῖν ἐλευθερίας δεῖ μόνον, ἀλλὰ καὶ ποιεῖν δι’ ὧν ἂν ἔλθοι πρὸς ὑμᾶς, οὐδὲ βούλεσθαι μὲν ἀπηλλάχθαι δεσποτῶν ἐπιμένειν δὲ πράττοντας ἐξ ὧν οὗτοι διαμενοῦσιν· ἀλλὰ γίνεσθε δίκαιοι, καὶ τὴν πονηρίαν ἐκβαλόντες τῶν ψυχῶν καὶ θεραπεύσαντες αὐτὴν ὅλαις ταῖς διανοίαις προστρέπεσθε τὸ θεῖον καὶ τιμῶντες διατελεῖτε· ταῦτα γὰρ ὑμῖν ποιοῦσιν ἥξει τὰ ἀγαθά, δουλείας ἀπαλλαγὴ καὶ νίκη πολεμίων, ἃ λαβεῖν οὔθ’ ὅπλοις οὔτε σωμάτων ἀλκαῖς οὔτε πλήθει συμμάχων δυνατόν ἐστιν· οὐ γὰρ τούτοις ὁ θεὸς ὑπισχνεῖται παρέξειν αὐτά, τῷ δ’ ἀγαθοὺς εἶναι καὶ δικαίους· ἐγγυητὴς δὲ αὐτοῦ τῶν ὑποσχέσεων ἐγὼ γίνομαι. ταῦτ’ εἰπόντος ἐπευφήμησε τὸ πλῆθος ἡσθὲν τῇ παραινέσει καὶ κατένευσεν αὑτὸ παρέξειν κεχαρισμένον τῷ θεῷ. συνάγει δ’ αὐτοὺς ὁ Σαμουῆλος εἴς τινα πόλιν λεγομένην Μασφάτην· κατοπτευόμενον τοῦτο σημαίνει κατὰ τὴν τῶν Ἑβραίων γλῶτταν· ἐντεῦθεν ὑδρευσάμενοί τε σπένδουσι τῷ θεῷ καὶ διανηστεύσαντες ὅλην τὴν ἡμέραν ἐπ’ εὐχὰς τρέπονται.", "st": "6.2.1"}, {"sp": "N", "t": "Οὐ λανθάνουσι δὲ τοὺς Παλαιστίνους ἐκεῖ συναχθέντες, ἀλλὰ μαθόντες οὗτοι τὴν ἄθροισιν αὐτῶν μεγάλῃ στρατιᾷ καὶ δυνάμει κατ’ ἐλπίδα τοῦ μὴ προσδοκῶσι μηδὲ παρεσκευασμένοις ἐπιπεσεῖσθαι τοῖς Ἑβραίοις ἐπέρχονται. καταπλήττει δ’ αὐτοὺς τοῦτο καὶ εἰς ταραχὴν ἄγει καὶ δέος, καὶ δραμόντες πρὸς Σαμουῆλον, ἀναπεπτωκέναι τὰς ψυχὰς αὐτῶν ὑπὸ φόβου καὶ τῆς προτέρας ἥττης ἔφασκον καὶ διὰ τοῦτ’ ἠρεμεῖν, ἵνα μὴ κινήσωμεν τὴν τῶν πολεμίων δύναμιν, σοῦ δ’ ἀναγαγόντος ἡμᾶς ἐπ’ εὐχὰς καὶ θυσίας καὶ ὅρκους γυμνοῖς καὶ ἀνόπλοις ἐπεστράτευσαν οἱ πολέμιοι· ἐλπὶς οὖν ἡμῖν οὐκ ἄλλη σωτηρίας, ἢ μόνη ἡ παρὰ σοῦ καὶ τοῦ θεοῦ ἱκετευθέντος ὑπὸ σοῦ παρασχεῖν ἡμῖν διαφυγεῖν Παλαιστίνους. ὁ δὲ θαρρεῖν τε προτρέπεται καὶ βοηθήσειν αὐτοῖς τὸν θεὸν ἐπαγγέλλεται καὶ λαβὼν ἄρνα γαλαθηνόν, ὑπὲρ τῶν ὄχλων θύει καὶ παρακαλεῖ τὸν θεὸν ὑπερσχεῖν αὐτῶν τὴν δεξιὰν ἐν τῇ πρὸς Παλαιστίνους μάχῃ καὶ μὴ περιϊδεῖν αὐτοὺς δεύτερον δυστυχήσαντας. ἐπήκοος δὲ γίνεται τῶν εὐχῶν ὁ θεὸς, καὶ προσδεξάμενος εὐμενεῖ καὶ συμμάχῳ τῇ διανοίᾳ τὴν θυσίαν ἐπινεύει νίκην αὐτοῖς καὶ κράτος. ἔτι δ’ ἐπὶ τοῦ βωμοῦ τὴν θυσίαν ἔχοντος τοῦ θεοῦ καὶ μήπω πᾶσαν διὰ τῆς ἱερᾶς φλογὸς ἀπειληφότος προῆλθεν ἐκ τοῦ στρατοπέδου ἡ τῶν πολεμίων δύναμις καὶ παρατάσσεται εἰς μάχην, ἐπ’ ἐλπίδι μὲν νίκης, ὡς ἀπειλημμένων ἐν ἀπορίᾳ τῶν Ἰουδαίων μήτε ὅπλα ἐχόντων μήτε ὡς ἐπὶ μάχῃ ἐκεῖσε ἀπηντηκότων, περιπίπτουσι δὲ οἷς οὐδ’ εἰ προύλεγέ τις ῥᾳδίως ἐπείσθησαν. πρῶτον μὲν γὰρ αὐτοὺς ὁ θεὸς κλονεῖ σεισμῷ καὶ τὴν γῆν αὐτοῖς ὑπότρομον καὶ σφαλερὰν κινήσας τίθησιν, ὡς σαλευομένης τε τὰς βάσεις ὑποφέρεσθαι καὶ διϊσταμένης εἰς ἔνια τῶν χασμάτων καταφέρεσθαι, ἔπειτα βρονταῖς καταψοφήσας καὶ διαπύροις ἀστραπαῖς ὡς καταφλέξων αὐτῶν τὰς ὄψεις περιλάμψας καὶ τῶν χειρῶν ἐκκροτήσας τὰ ὅπλα, γυμνοὺς εἰς φυγὴν ἀπέστρεψεν. ἐπεξέρχεται δὲ Σαμουῆλος μετὰ τῆς πληθύος καὶ πολλοὺς κατασφάξας κατακολουθεῖ μέχρι Κορραίων τόπου τινὸς οὕτω λεγομένου, καὶ καταπήξας ἐκεῖ λίθον ὥσπερ ὅρον τῆς νίκης καὶ τῆς φυγῆς τῶν πολεμίων, ἰσχυρὸν αὐτὸν προσαγορεύει σύμβολον τῆς παρὰ τοῦ θεοῦ γενομένης αὐτοῖς κατὰ τῶν ἐχθρῶν ἰσχύος.", "st": "6.2.2"}, {"sp": "N", "t": "Οἱ δὲ μετ’ ἐκείνην τὴν πληγὴν οὐκέτ’ ἐστράτευσαν ἐπὶ τοὺς Ἰσραηλίτας, ἀλλ’ ὑπὸ δέους καὶ μνήμης τῶν συμβεβηκότων ἡσύχαζον· ὃ δ’ ἦν πάλαι θάρσος τοῖς Παλαιστίνοις ἐπὶ τοὺς Ἑβραίους, τοῦτ’ ἐκείνων μετὰ τὴν νίκην ἐγένετο. καὶ Σαμουῆλος στρατεύσας ἐπ’ αὐτοὺς ἀναιρεῖ πολλοὺς καὶ τὰ φρονήματ’ αὐτῶν εἰς τὸ παντελὲς ταπεινοῖ καὶ τὴν χώραν ἀφαιρεῖται, ἣν τῶν Ἰουδαίων ἀπετέμοντο πρότερον κρατήσαντες τῇ μάχῃ· αὕτη δ’ ἦν μέχρι πόλεως Ἀκάρων ἀπὸ τῶν τῆς Γίττης ὅρων ἐκτεταμένη. ἦν δὲ κατ’ ἐκεῖνον τὸν καιρὸν φίλια τοῖς Ἰσραηλίταις τὰ ὑπολειπόμενα τῶν Χαναναίων.", "st": "6.2.3"}, {"sp": "N", "t": "Ὁ δὲ προφήτης Σαμουῆλος διακοσμήσας τὸν λαὸν καὶ πόλιν αὐτοῖς ἀποδοὺς εἰς ταύτην ἐκέλευσε συνερχομένοις περὶ τῶν πρὸς ἀλλήλους κρίνεσθαι διαφορῶν, αὐτὸς δὲ δι’ ἔτους ἐπερχόμενος τὰς πόλεις ἐδίκαζεν αὐτοῖς καὶ πολλὴν ἐβράβευεν εὐνομίαν ἐπὶ χρόνον πολύν.", "st": "6.3.1"}, {"sp": "N", "t": "ἔπειθ’ ὑπὸ γήρως βαρυνόμενος καὶ τὰ συνήθη πράττειν ἐμποδιζόμενος τοῖς υἱοῖς τὴν ἀρχὴν καὶ τὴν προστασίαν τοῦ ἔθνους παραδίδωσιν, ὧν ὁ μὲν πρεσβύτερος Ἰοῦλος προσηγορεύετο, τῷ δὲ νεωτέρῳ Ἐβίᾳ ὄνομα ἦν. προσέταξε δὲ τὸν μὲν ἐν Βεθήλῳ πόλει καθεζόμενον κρίνειν, τὸν δ’ ἕτερον ἐν Βερσουβεὶ μερίσας τὸν ὑπακουσόμενον ἑκατέρῳ λαόν. ἐγένοντο δὲ σαφὲς οὗτοι παράδειγμα καὶ τεκμήριον τοῦ μὴ τὸν τρόπον ὁμοίους τοῖς φύσασι γίνεσθαί τινας, ἀλλὰ τάχα μὲν χρηστοὺς καὶ μετρίους ἐκ πονηρῶν, τότε μέν γε φαύλους ἐξ ἀγαθῶν παρέσχον αὑτοὺς γενομένους· τῶν γὰρ τοῦ πατρὸς ἐπιτηδευμάτων ἐκτραπόμενοι καὶ τὴν ἐναντίαν ὁδὸν ἀπελθόντες δώρων καὶ λημμάτων αἰσχρῶν καθυφίεντο τὸ δίκαιον, καὶ τὰς κρίσεις οὐ πρὸς τὴν ἀλήθειαν, ἀλλὰ πρὸς τὸ κέρδος ποιούμενοι καὶ πρὸς τρυφὴν καὶ πρὸς διαίτας πολυτελεῖς ἀπονενευκότες πρῶτον μὲν ὑπεναντία ταῦτα ἔπρασσον τῷ θεῷ, δεύτερον δὲ τῷ προφήτῃ πατρὶ δ’ ἑαυτῶν, ὃς πολλὴν καὶ τοῦ τὸ πλῆθος εἶναι δίκαιον σπουδὴν εἰσεφέρετο καὶ πρόνοιαν.", "st": "6.3.2"}, {"sp": "N", "t": "Ὁ δὲ λαὸς ἐξυβριζόντων [εἰς] τὴν προτέραν κατάστασιν καὶ πολιτείαν τῶν τοῦ προφήτου παίδων χαλεπῶς τε τοῖς πραττομένοις ἔφερε καὶ πρὸς αὐτὸν συντρέχουσι, διέτριβε δ’ ἐν Ἀρμαθᾶ πόλει, καὶ τάς τε τῶν υἱῶν παρανομίας ἔλεγον καὶ ὅτι γηραιὸς ὢν αὐτὸς ἤδη καὶ παρειμένος ὑπὸ τοῦ χρόνου τῶν πραγμάτων οὐκέτι τὸν αὐτὸν προεστάναι δύναται τρόπον· ἐδέοντό τε καὶ ἱκέτευον ἀποδεῖξαί τινα αὐτῶν βασιλέα, ὃς ἄρξει τοῦ ἔθνους καὶ τιμωρήσεται Παλαιστίνους ὀφείλοντας ἔτ’ αὐτοῖς δίκας τῶν προτέρων ἀδικημάτων. ἐλύπησαν δὲ σφόδρα τὸν Σαμουῆλον οἱ λόγοι διὰ τὴν σύμφυτον δικαιοσύνην καὶ τὸ πρὸς τοὺς βασιλέας μῖσος· ἥττητο γὰρ δεινῶς τῆς ἀριστοκρατίας ὡς θείας καὶ μακαρίους ποιούσης τοὺς χρωμένους αὐτῆς τῇ πολιτείᾳ. ὑπὸ δὲ φροντίδος καὶ βασάνου τῆς ἐπὶ τοῖς εἰρημένοις οὔτε τροφῆς ἐμνημόνευσεν οὔτε ὕπνου, δι’ ὅλης δὲ τῆς νυκτὸς στρέφων τὰς περὶ τῶν πραγμάτων ἐννοίας διεκαρτέρει.", "st": "6.3.3"}, {"sp": "N", "t": "Ἔχοντι δὲ οὕτως ἐμφανίζεται τὸ θεῖον καὶ παραμυθεῖται μὴ δυσφορεῖν ἐφ’ οἷς ἠξίωσε τὸ πλῆθος, ὡς οὐκ ἐκεῖνον ὑπερηφανήσοντας ἀλλ’ ἑαυτὸν, εἰ μὴ βασιλεύσει μόνος· ταῦτα δὲ ἀφ’ ἧς ἡμέρας ἐξήγαγεν αὐτοὺς ἀπ’ Αἰγύπτου μηχανᾶσθαι τὰ ἔργα· λήψεσθαι μέντοι γε οὐκ εἰς μακρὰν μετάνοιαν αὐτοὺς ἐπίπονον, ὑφ’ ἧς οὐδὲν μὲν ἀγένητον ἔσται τῶν ἐσομένων, ἐλεγχθήσονται δὲ καταφρονήσαντες καὶ βουλὰς οὐκ εὐχαρίστους πρὸς ἐμὲ καὶ τὴν σὴν προφητείαν λαβόντες. κελεύω δή σε χειροτονεῖν αὐτοῖς ὃν ἂν ἐγὼ προείπω βασιλέα προδηλώσαντα ποταπῶν τε πειραθήσονται βασιλευόμενοι κακῶν καὶ διαμαρτυράμενον ἐφ’ οἵαν σπεύδουσι μεταβολήν.", "st": "6.3.4"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας Σαμουῆλος ἅμα ἕῳ συγκαλέσας τοὺς Ἰουδαίους ἀποδείξειν αὐτοῖς βασιλέα ὡμολόγησεν, ἔφη δὲ δεῖν πρῶτον μὲν αὐτοῖς ἐκδιηγήσασθαι τὰ παρὰ τῶν βασιλέων ἐσόμενα καὶ ὅσοις συνενεχθήσονται κακοῖς· γινώσκετε γὰρ ὅτι πρῶτον μὲν ὑμῶν ἀποσπάσουσι τὰ τέκνα καὶ τὰ μὲν αὐτῶν ἁρματηλάτας εἶναι κελεύσουσι, τοὺς δ’ ἱππεῖς καὶ σωματοφύλακας, δρομεῖς δὲ ἄλλους καὶ χιλιάρχους καὶ ἑκατοντάρχους, ποιήσουσι δὲ καὶ τεχνίτας ὁπλοποιοὺς καὶ ἁρματοποιοὺς καὶ ὀργάνων τέκτονας γεωργούς τε καὶ τῶν ἰδίων ἀγρῶν ἐπιμελητὰς καὶ σκαπανεῖς ἀμπέλων, καὶ οὐδέν ἐστιν ὃ μὴ κελευόμενοι ποιήσουσιν ἀνδραπόδων ἀργυρωνήτων τρόπον· καὶ τὰς θυγατέρας δ’ ὑμῶν μυρεψοὺς ἀποφανοῦσι καὶ ὀψοποιοὺς καὶ σιτοποιούς, καὶ πᾶν ἔργον ὃ θεραπαινίδες ἐξ ἀνάγκης πληγὰς φοβούμεναι καὶ βασάνους ὑπηρετήσουσι. κτῆσιν δὲ τὴν ὑμετέραν ἀφαιρήσονται καὶ ταύτην εὐνούχοις καὶ σωματοφύλαξι δωρήσονται καὶ βοσκημάτων ἀγέλας τοῖς αὑτῶν προσνεμοῦσι. συνελόντι δ’ εἰπεῖν, δουλεύσετε μετὰ πάντων τῶν ὑμετέρων τῷ βασιλεῖ σὺν τοῖς αὑτῶν οἰκέταις· ὃς γενόμενος μνήμην ὑμῖν τῶνδε τῶν λόγων γεννήσει καὶ τῷ πάσχειν αὐτὰ μεταγινώσκοντας ἱκετεῦσαι τὸν θεὸν ἐλεῆσαί τε ὑμᾶς καὶ δωρήσασθαι ταχεῖαν ἀπαλλαγὴν τῶν βασιλέων· ὁ δ’ οὐ προσδέξεται τὰς δεήσεις, ἀλλὰ παραπέμψας ἐάσει δίκην ὑποσχεῖν ὑμᾶς τῆς αὑτῶν κακοβουλίας.", "st": "6.3.5"}, {"sp": "N", "t": "Ἦν δ’ ἄρα καὶ πρὸς τὰς προρρήσεις τῶν συμβησομένων ἀνόητον τὸ πλῆθος καὶ δύσκολον ἐξελεῖν τῆς διανοίας κρίσιν ἤδη παρὰ τῷ λογισμῷ καθιδρυμένην· οὐδὲ γὰρ ἐπεστράφησαν οὐδ’ ἐμέλησεν αὐτοῖς τῶν Σαμουήλου λόγων, ἀλλ’ ἐνέκειντο λιπαρῶς καὶ χειροτονεῖν ἠξίουν ἤδη τὸν βασιλέα καὶ μὴ φροντίζειν τῶν ἐσομένων· ἐπὶ γὰρ τιμωρίᾳ τῶν ἐχθρῶν ἀνάγκη τὸν πολεμήσοντα σὺν αὑτοῖς ἔχειν, καὶ οὐδὲν ἄτοπον εἶναι τῶν πλησιοχώρων βασιλευομένων τὴν αὐτὴν ἔχειν αὐτοὺς πολιτείαν. ὁρῶν δ’ αὐτοὺς μηδ’ ὑπὸ τῶν προειρημένων ἀπεστραμμένους ὁ Σαμουῆλος, ἀλλ’ ἐπιμένοντας νῦν μὲν, εἶπεν, ἄπιτε πρὸς αὑτοὺς ἕκαστος, μεταπέμψομαι δὲ ὑμᾶς εἰς δέον, ὅταν μάθω παρὰ τοῦ θεοῦ τίνα δίδωσιν ὑμῖν βασιλέα.", "st": "6.3.6"}, {"sp": "N", "t": "Ἦν δέ τις ἐκ τῆς Βενιαμίτιδος φυλῆς ἀνὴρ εὖ γεγονὼς καὶ ἀγαθὸς τὸ ἦθος, Κεὶς ὄνομα· τούτῳ παῖς ὑπῆρχεν, ἦν δὲ νεανίας τὴν μορφὴν ἄριστος καὶ τὸ σῶμα μέγας τό τε φρόνημα καὶ τὴν διάνοιαν ἀμείνων τῶν βλεπομένων· Σαοῦλον αὐτὸν ἐκάλουν. οὗτος ὁ Κείς, ὄνων αὐτῷ ἐκ τῆς νομῆς καλῶν ἀποπλανηθεισῶν, ἥδετο γὰρ αὐταῖς ὡς οὐκ ἄλλῳ τινὶ τῶν κτημάτων, τὸν υἱὸν μεθ’ ἑνὸς θεράποντος ἐπὶ ζήτησιν τῶν κτηνῶν ἐξέπεμψεν· ὁ δ’ ἐπεὶ τὴν πάτριον περιῆλθε φυλὴν εἰς τὰς ἄλλας ἀφίκετο, οὐδ’ ἐν ταύταις δ’ ἐπιτυχὼν ἀπιέναι διεγνώκει, μὴ ποιήσῃ περὶ αὑτοῦ τῷ πατρὶ λοιπὸν φροντίδα. τοῦ δ’ ἑπομένου θεράποντος ὡς ἐγένοντο κατὰ τὴν Ἁραμαθὰ πόλιν εἶναι προφήτην ἐν αὐτῇ φήσαντος ἀληθῆ καὶ πρὸς αὐτὸν βαδίζειν συμβουλεύσαντος, γνώσεσθαι γὰρ παρ’ αὐτοῦ τὸ περὶ τῶν ὄνων τέλος, οὐθὲν ἔχειν πορευθέντας εἶπεν ἀντὶ τῆς προφητείας ὃ παράσχωσιν αὐτῷ· κεκενῶσθαι γὰρ ἤδη τῶν ἐφοδίων. τοῦ δ’ οἰκέτου τέταρτον αὐτῷ παρεῖναι σίκλου φήσαντος καὶ τοῦτο δώσειν, ὑπὸ γὰρ ἀγνοίας τοῦ μὴ λαμβάνειν τὸν προφήτην μισθὸν ἐπλανῶντο, παραγίνονται καὶ πρὸς ταῖς πύλαις παρατυγχάνοντες παρθένοις ἐφ’ ὕδωρ βαδιζούσαις ἐρωτῶσιν αὐτὰς τοῦ προφήτου τὴν οἰκίαν. αἱ δὲ σημαίνουσι καὶ σπεύδειν παρεκελεύσαντο πρὶν αὐτὸν εἰς τὸ δεῖπνον κατακλιθῆναι· πολλοὺς γὰρ ἑστιᾶν καὶ προκατακλίνεσθαι τῶν κεκλημένων. ὁ δὲ Σαμουῆλος διὰ τοῦτο πολλοὺς ἐπὶ τὴν ἑστίαν τότε συνήγαγε· δεομένῳ γὰρ κατὰ πᾶσαν ἡμέραν αὐτῷ τοῦ θεοῦ προειπεῖν τίνα ποιήσει βασιλέα τῇ παρελθούσῃ τοῦτον μηνύσαντος, πέμψειν γὰρ αὐτός τινα νεανίσκον ἐκ τῆς Βενιαμίτιδος φυλῆς κατὰ τήνδε τὴν ὥραν, αὐτὸς [μὲν] ἐπὶ τοῦ δώματος καθεζόμενος ἐξεδέχετο τὸν καιρὸν γενέσθαι, πληρωθέντος δ’ αὐτοῦ καταβὰς ἐπὶ τὸ δεῖπνον ἐπορεύετο. συναντᾷ δὲ τῷ Σαούλῳ καὶ ὁ θεὸς αὐτῷ σημαίνει τοῦτον εἶναι τὸν ἄρξειν μέλλοντα. Σαοῦλος δὲ πρόσεισι τῷ Σαμουήλῳ καὶ προσαγορεύσας ἐδεῖτο μηνύειν τὴν οἰκίαν τοῦ προφήτου· ξένος γὰρ ὢν ἀγνοεῖν ἔφασκε. τοῦ δὲ Σαμουήλου αὐτὸν εἶναι φράσαντος καὶ ἄγοντος ἐπὶ τὸ δεῖπνον, ὡς τῶν ὄνων ἐφ’ ὧν τὴν ζήτησιν ἐκπεμφθείη σεσωσμένων τά τε πάντα ἀγαθὰ ἔχειν αὐτῷ κεκυρωμένα, προστυχών ἀλλ’ ἥττων, εἶπεν, ἐγὼ, δέσποτα, ταύτης τῆς ἐλπίδος καὶ φυλῆς μικροτέρας ἢ βασιλέας ποιεῖν καὶ πατριᾶς ταπεινοτέρας τῶν ἄλλων πατριῶν. σὺ δὲ παίζεις καὶ γέλωτά με τίθεσαι περὶ μειζόνων ἢ κατὰ τὴν ἐμὴν χώραν διαλεγόμενος. ὁ δὲ προφήτης ἀγαγὼν αὐτὸν ἐπὶ τὴν ἑστίαν κατακλίνει καὶ τὸν ἀκόλουθον ἐπάνω τῶν κεκλημένων· οὗτοι δ’ ἦσαν ἑβδομήκοντα τὸν ἀριθμόν· προστάσσει δὲ τοῖς διακόνοις παραθεῖναι τῷ Σαούλῳ μερίδα βασιλικήν. ἐπεὶ δὲ κοίτης ὥρα προσῆγεν οἱ μὲν ἀναστάντες ἀπελύοντο πρὸς αὑτοὺς ἕκαστοι, ὁ δὲ Σαοῦλος παρὰ τῷ προφήτῃ σὺν τῷ θεράποντι κατεκοιμήθη.", "st": "6.4.1"}, {"sp": "N", "t": "Ἅμα δὲ ἡμέρᾳ Σαμουῆλος ἀναστήσας αὐτὸν ἐκ τῆς κοίτης προύπεμπε καὶ γενόμενος ἔξω τῆς πόλεως ἐκέλευσε τὸν μὲν θεράποντα ποιῆσαι προελθεῖν, ὑπολείπεσθαι δὲ αὐτὸν· ἔχειν γὰρ αὐτῷ τι φράσαι [μηδενὸς ἄλλου παρόντος]. καὶ ὁ μὲν Σαοῦλος ἀποπέμπεται τὸν ἀκόλουθον, λαβὼν δ’ ὁ προφήτης τὸ ἅγιον ἔλαιον καταχεῖ τῆς τοῦ νεανίσκου κεφαλῆς καὶ κατασπασάμενος ἴσθι, φησὶ, βασιλεὺς ὑπὸ τοῦ θεοῦ κεχειροτονημένος ἐπί τε Παλαιστίνους καὶ τὴν ὑπὲρ Ἑβραίων ἄμυναν. τούτων δὲ ἔσται σοι σημεῖον ὅ σε βούλομαι προγινώσκειν· ὅταν ἀπέλθῃς ἐντεῦθεν καταλήψῃ τρεῖς ἀνθρώπους ἐν τῇ ὁδῷ προσκυνῆσαι τῷ θεῷ πορευομένους εἰς Βέθηλα, ὧν τὸν μὲν πρῶτον τρεῖς ἄρτους ὄψει κομίζοντα, τὸν δὲ δεύτερον ἔριφον, ὁ τρίτος δὲ ἀσκὸν οἴνου φέρων ἀκολουθήσει. ἀσπάσονται δέ σε οὗτοι καὶ φιλοφρονήσονται καὶ δώσουσί σοι ἄρτους δύο, σὺ δὲ λήψῃ. κἀκεῖθεν ἥξεις εἰς τὸ Ῥαχήλας καλούμενον μνημεῖον, ὅπου συμβαλεῖς τῷ σεσῶσθαί σου τὰς ὄνους εὐαγγελιουμένῳ· ἔπειτ’ ἐκεῖθεν ἐλθὼν εἰς Γεβαθὰ προφήταις ἐκκλησιάζουσιν ἐπιτεύξῃ καὶ γενόμενος ἔνθεος προφητεύσεις σὺν αὐτοῖς, ὡς πάνθ’ ὅντιν’ ὁρῶντα ἐκπλήττεσθαί τε καὶ θαυμάζειν λέγοντα πόθεν εἰς τοῦτο εὐδαιμονίας ὁ Κεισαίου παῖς παρῆλθεν; ὅταν δέ σοι ταῦτα γένηται τὰ σημεῖα, τὸν θεὸν ἴσθι μετὰ σοῦ τυγχάνοντα, ἄσπασαί τε τὸν πατέρα σου καὶ τοὺς συγγενεῖς. ἥξεις δὲ μετάπεμπτος εἰς Γάλγαλα ὑπ’ ἐμοῦ, ἵνα χαριστήρια τούτων θύσωμεν τῷ θεῷ. φράσας ταῦτα καὶ προειπὼν ἀποπέμπει τὸν νεανίσκον· τῷ Σαούλῳ δὲ πάντα κατὰ τὴν Σαμουήλου προφητείαν ἀπήντησεν.", "st": "6.4.2"}, {"sp": "N", "t": "Ὡς δὲ ἦλθεν εἰς τὴν οἰκίαν τοῦ συγγενοῦς αὐτοῦ Ἀβηνάρου, καὶ γὰρ ἐκεῖνον τῶν ἄλλων οἰκείων μᾶλλον ἔστεργεν, ἀνερωτῶντος περὶ τῆς ἀποδημίας καὶ τῶν κατ’ αὐτὸν γεγονότων τῶν μὲν ἄλλων οὐδὲν ἀπεκρύψατο οὐδ’ ὡς ἀφίκοιτο παρὰ Σαμουῆλον τὸν προφήτην οὐδ’ ὡς ἐκεῖνος αὐτῷ σεσῶσθαι τὰς ὄνους ἔφρασε, περὶ δὲ τῆς βασιλείας καὶ τῶν κατ’ αὐτὴν, ἃ φθόνον ἀκουόμενα καὶ ἀπιστίαν ἔχειν ᾤετο, σιωπᾷ πρὸς αὐτὸν καὶ οὐδὲ πρὸς εὔνουν σφόδρα δοκοῦντα εἶναι καὶ περισσότερον τῶν ἀφ’ αἵματος ὑπ’ αὐτοῦ στεργόμενον ἀσφαλὲς ἢ σῶφρον ἔδοξε μηνύειν λογισάμενος οἶμαι τὴν ἀνθρωπίνην φύσιν οἵα ταῖς ἀληθείαις ἐστίν, ὅτι βεβαίως οὐδεὶς οὔτε φίλων οὔτε συγγενῶν οὐδ’ ἄχρι τῶν παρὰ τοῦ θεοῦ λαμπρῶν ἀποσώζει τὴν διάθεσιν, ἀλλὰ πρὸς τὰς ὑπεροχὰς κακοήθεις τυγχάνουσιν ἤδη καὶ βάσκανοι.", "st": "6.4.3"}, {"sp": "N", "t": "Σαμουῆλος δὲ καλεῖ τὸν λαὸν εἰς Μασφὰ πόλιν καὶ πρὸς αὐτὸν διατίθεται λόγους, οὓς κατ’ ἐντολὴν φράζειν ἔλεγε τοῦ θεοῦ, ὅτι τὴν ἐλευθερίαν αὐτοῖς ἐκείνου παρασχόντος καὶ τοὺς πολεμίους δουλώσαντος ἀμνημονήσειαν τῶν εὐεργεσιῶν, καὶ τὸν μὲν θεὸν ἀποχειροτονοῦσι τῆς βασιλείας οὐκ εἰδότες ὡς συμφορώτατον ὑπὸ τοῦ πάντων ἀρίστου προστατεῖσθαι, θεὸς δὲ πάντων ἄριστος, αἱροῦνται δ’ ἔχειν ἄνθρωπον βασιλέα, ὃς ὡς κτήματι τοῖς ὑποτεταγμένοις κατὰ βούλησιν καὶ ἐπιθυμίαν καὶ τῶν ἄλλων παθῶν ὁρμὴν χρήσεται τῆς ἐξουσίας ἀφειδῶς ἐμφορούμενος, ἀλλ’ οὐχ ὡς ἴδιον ἔργον καὶ κατασκεύασμα τὸ τῶν ἀνθρώπων γένος οὕτως διατηρῆσαι σπουδάσει, ὁ θεὸς δὲ κατὰ ταύτην τὴν αἰτίαν κήδοιτο. ἀλλ’ ἐπεὶ δέδοκται ταῦτα ὑμῖν καὶ κεκράτηκεν ἡ πρὸς τὸν θεὸν ὕβρις, τάχθητε πάντες κατὰ φυλάς τε καὶ σκῆπτρα καὶ κλήρους βάλετε.", "st": "6.4.4"}, {"sp": "N", "t": "Ποιησάντων δὲ τοῦτο τῶν Ἑβραίων ὁ τῆς Βενιαμίτιδος κλῆρος ἐξέπεσε, ταύτης δὲ κληρωθείσης ἔλαχεν ἡ Ματρὶς καλουμένη πατριὰ, ἧς κατ’ ἄνδρα κληρωθείσης λαγχάνει ὁ Κεισαίου βασιλεύειν παῖς Σαοῦλος. γνοὺς δὲ τοῦθ’ ὁ νεανίσκος φθάσας ἐκποδὼν αὑτὸν ἐποίει μὴ βουλόμενος οἶμαι δοκεῖν τὴν ἀρχὴν ἑκὼν λαμβάνειν, ἀλλὰ τοσαύτην ἐνεδείξατο ἐγκράτειαν καὶ σωφροσύνην, ὥστε τῶν πλείστων οὐδ’ ἐπὶ μικραῖς εὐπραγίαις τὴν χαρὰν κατασχεῖν δυναμένων, ἀλλ’ εἰς τὸ πᾶσι γενέσθαι φανεροὺς προπιπτόντων, ὁ δ’ οὐ μόνον οὐδὲν ἐνέφηνε τοιοῦτον ἐπὶ βασιλείᾳ καὶ τῷ τοσούτων καὶ τηλικούτων ἐθνῶν ἀποδεδεῖχθαι δεσπότης, ἀλλὰ καὶ τῆς ὄψεως αὑτὸν τῆς τῶν βασιλευθησομένων ἐξέκλεψεν καὶ ζητεῖν αὐτὸν καὶ περὶ τοῦτο πονεῖν παρεσκεύασεν. ὧν ἀμηχανούντων καὶ φροντιζόντων, ὅτι καὶ γένοιτο ἀφανὴς ὁ Σαοῦλος, ὁ προφήτης ἱκέτευε τὸν θεὸν δεῖξαι ποῦ ποτ’ εἴη καὶ παρασχεῖν εἰς ἐμφανὲς τὸν νεανίσκον. μαθὼν δὲ παρὰ τοῦ θεοῦ τὸν τόπον ἔνθα κρύπτεται ὁ Σαοῦλος πέμπει τοὺς ἄξοντας αὐτὸν καὶ παραγενόμενον ἵστησι μέσον τοῦ πλήθους. ἐξεῖχε δὲ ἁπάντων, καὶ τὸ ὕψος ἦν βασιλικώτατος.", "st": "6.4.5"}, {"sp": "N", "t": "Λέγει δὲ ὁ προφήτης· τοῦτον ὑμῖν ὁ θεὸς ἔδωκε βασιλέα· ὁρᾶτε δὲ ὡς καὶ κρείττων ἐστὶ πάντων καὶ τῆς ἀρχῆς ἄξιος. ὡς δ’ ἐπευφήμησε τῷ βασιλεῖ σωτηρίαν ὁ λαὸς, τὰ μέλλοντα συμβήσεσθαι καταγράψας αὐτοῖς ὁ προφήτης ἀνέγνω τοῦ βασιλέως ἀκροωμένου καὶ τὸ βιβλίον τίθησιν ἐν τῇ τοῦ θεοῦ σκηνῇ ταῖς μετέπειτα γενεαῖς μαρτύριον ὧν προείρηκε. ταῦτ’ ἐπιτελέσας ὁ Σαμουῆλος ἀπολύει τὴν πληθύν. καὶ αὐτὸς δὲ εἰς Ἀρμαθὰ παραγίνεται πόλιν, πατρὶς γὰρ ἦν αὐτῷ, Σαούλῳ δὲ ἀπερχομένῳ εἰς Γαβαθὴν, ἐξ ἧς ὑπῆρχε, συνήρχοντο πολλοὶ μὲν ἀγαθοὶ τὴν προσήκουσαν βασιλεῖ τιμὴν νέμοντες, πονηροὶ δὲ πλείους, οἳ καταφρονοῦντες αὐτοῦ καὶ τοὺς πολλοὺς ἐχλεύαζον καὶ οὔτε δῶρα προσέφερον οὔτ’ ἐν σπουδῇ καὶ λόγῳ τὸ ἀρέσκεσθαι τὸν Σαοῦλον ἐτίθεντο.", "st": "6.4.6"}, {"sp": "N", "t": "Μηνὶ δ’ ὕστερον ἄρχει τῆς παρὰ πάντων αὐτῷ τιμῆς ὁ πρὸς Ναάσην πόλεμος τὸν τῶν Ἀμμανιτῶν βασιλέα· οὗτος γὰρ πολλὰ κακὰ τοὺς πέραν τοῦ Ἰορδάνου ποταμοῦ κατῳκημένους τῶν Ἰουδαίων διατίθησι μετὰ πολλοῦ καὶ μαχίμου στρατεύματος διαβὰς ἐπ’ αὐτούς· καὶ τὰς πόλεις αὐτῶν εἰς δουλείαν ὑπάγεται ἰσχύι μὲν καὶ βίᾳ πρὸς τὸ παρὸν αὐτοὺς χειρωσάμενος, σοφίᾳ δὲ καὶ ἐπινοίᾳ πρὸς τὸ μηδ’ αὖθις ἀποστάντας δυνηθῆναι τὴν ὑπ’ αὐτῷ δουλείαν διαφυγεῖν ἀσθενεῖς ποιῶν· τῶν γὰρ ἢ κατὰ πίστιν ὡς αὐτὸν ἀφικνουμένων ἢ λαμβανομένων πολέμου νόμῳ τοὺς δεξιοὺς ὀφθαλμοὺς ἐξέκοπτεν. ἐποίει δὲ τοῦθ’, ὅπως τῆς ἀριστερᾶς αὐτοῖς ὄψεως ὑπὸ τῶν θυρεῶν καλυπτομένης ἄχρηστοι παντελῶς εἶεν. καὶ ὁ μὲν τῶν Ἀμμανιτῶν βασιλεὺς ταῦτ’ ἐργασάμενος τοὺς πέραν τοῦ Ἰορδάνου ἐπὶ τοὺς Γαλαδηνοὺς λεγομένους ἐπεστράτευσε καὶ στρατοπεδευσάμενος πρὸς τῇ μητροπόλει τῶν πολεμίων, Ἰαβὶς δ’ ἐστὶν αὕτη, πέμπει πρὸς αὐτοὺς πρέσβεις κελεύων ἤδη παραδοῦναι σφᾶς αὐτοὺς ἐπὶ τῷ τοὺς δεξιοὺς αὐτῶν ὀφθαλμοὺς ἐξορύξαι, ἢ πολιορκήσειν ἠπείλει καὶ τὰς πόλεις αὐτῶν ἀναστήσειν· τὴν δ’ αἵρεσιν ἐπ’ αὐτοῖς εἶναι, πότερόν ποτε βραχύ τι τοῦ σώματος ἀποτεμεῖν θέλουσιν ἢ παντάπασιν ἀπολωλέναι. οἱ δὲ Γαλαδηνοὶ καταπλαγέντες πρὸς οὐδέτερον μὲν ἐτόλμησαν οὐδὲν εἰπεῖν οὔτ’ εἰ παραδιδόασιν αὑτοὺς οὔτ’ εἰ πολεμοῦσιν, ἀνοχὴν δ’ ἡμερῶν ἑπτὰ λαβεῖν ἠξίωσαν, ἵνα πρεσβευσάμενοι πρὸς τοὺς ὁμοφύλους παρακαλέσωσι συμμαχεῖν αὐτοῖς καὶ εἰ μὲν ἔλθοι βοήθεια πολεμῶσιν, εἰ δ’ ἄπορα εἴη τὰ παρ’ ἐκείνων παραδώσειν αὑτοὺς ἔφασκον ἐπὶ τῷ παθεῖν ὅτι ἂν αὐτῷ δοκῇ.", "st": "6.5.1"}, {"sp": "N", "t": "Ὁ δὲ Ναάσης καταφρονήσας τοῦ τῶν Γαλαδηνῶν πλήθους καὶ τῆς ἀποκρίσεως αὐτῶν δίδωσί τε αὐτοῖς τὴν ἀνοχὴν καὶ πέμπειν πρὸς οὓς ἂν θέλωσι συμμάχους ἐπιτρέπει. πέμπουσιν οὖν εὐθὺς κατὰ πόλιν τοῖς Ἰσραηλίταις οἳ ἤγγελλον τὰ παρὰ τοῦ Ναάσου καὶ τὴν ἀμηχανίαν ἐν ᾗ καθειστήκεσαν. οἱ δ’ εἰς δάκρυα καὶ λύπην ὑπὸ τῆς ἀκοῆς τῶν περὶ τοὺς Ἰαβισηνοὺς προήχθησαν καὶ πέρα τούτων οὐδὲν αὐτοῖς ἄλλο πράττειν συνεχώρει τὸ δέος· γενομένων δὲ τῶν ἀγγέλων καὶ ἐν τῇ Σαούλου τοῦ βασιλέως πόλει καὶ τοὺς κινδύνους ἐν οἷς εἶναι συνέβαινε τοὺς Ἰαβισηνοὺς φρασάντων, ὁ μὲν λαὸς ταὐτὰ τοῖς πρώτοις ἔπασχεν· ὠδύρετο γὰρ τὴν συμφορὰν τὴν τῶν συγγενῶν· ὁ δὲ Σαοῦλος ἀπὸ τῶν περὶ τὴν γεωργίαν παραγενόμενος ἔργων εἰς τὴν πόλιν ἐπιτυγχάνει κλαίουσι τοῖς αὑτοῦ πολίταις, καὶ πυθόμενος τὴν αἰτίαν τῆς συγχύσεως καὶ κατηφείας αὐτῶν μανθάνει τὰ παρὰ τῶν ἀγγέλων. καὶ ἔνθεος γενόμενος ἀποπέμπει μὲν τοὺς Ἰαβισηνοὺς ὑποσχόμενος αὐτοῖς ἥξειν βοηθὸς τῇ τρίτῃ τῶν ἡμερῶν καὶ πρὶν ἥλιον ἀνασχεῖν κρατήσειν τῶν πολεμίων, ἵνα καὶ νενικηκότας ἤδη καὶ τῶν φόβων ἀπηλλαγμένους ὁ ἥλιος ἐπιτείλας ἴδῃ· ὑπομεῖναι δ’ ἐκέλευσέ τινας αὐτῶν ἡγησομένους τῆς ὁδοῦ.", "st": "6.5.2"}, {"sp": "N", "t": "Βουλόμενος δὲ φόβῳ ζημίας τὸν λαὸν ἐπὶ τὸν πρὸς Ἀμμανίτας ἐπιστρέψαι πόλεμον καὶ συνελθεῖν αὐτοὺς ὀξύτερον, ὑποτεμὼν τῶν αὐτοῦ βοῶν τὰ νεῦρα ταὐτὰ διαθήσειν ἠπείλησε τοὺς ἁπάντων, εἰ μὴ πρὸς τὸν Ἰόρδανον ὡπλισμένοι κατὰ τὴν ἐπιοῦσαν ἀπαντήσουσιν ἡμέραν καὶ ἀκολουθήσουσιν αὐτῷ καὶ Σαμουήλῳ τῷ προφήτῃ, ὅπου ποτ’ ἂν αὐτοὺς ἀγάγωσι. τῶν δὲ δι’ εὐλάβειαν τῆς κατεπηγγελμένης ζημίας εἰς τὸν ὡρισμένον καιρὸν συνελθόντων ἐξαριθμεῖται ἐν Βαλᾶ τῇ πόλει τὸ πλῆθος· εὑρίσκει δὲ τὸν ἀριθμὸν χωρὶς τῆς Ἰούδα φυλῆς εἰς ἑβδομήκοντα μυριάδας συνειλεγμένους, τῆς δὲ φυλῆς ἐκείνης ἦσαν μυριάδες ἑπτά. διαβὰς δὲ τὸν Ἰόρδανον καὶ σχοίνων δέκα δι’ ὅλης τῆς νυκτὸς ἀνύσας ὁδὸν φθάνει μὲν ἥλιον ἀνίσχοντα, τριχῇ δὲ τὸ στράτευμα διελὼν ἐπιπίπτει πανταχόθεν αἰφνιδίως οὐ προσδοκῶσι τοῖς ἐχθροῖς, καὶ συμβαλὼν εἰς μάχην ἄλλους τε πολλοὺς ἀποκτείνει τῶν Ἀμμανιτῶν καὶ Ναάσην τὸν βασιλέα. τοῦτο λαμπρὸν ἐπράχθη τῷ Σαούλῳ τὸ ἔργον καὶ πρὸς πάντας αὐτὸν διήγγειλε τοὺς Ἑβραίους ἐπαινούμενον καὶ θαυμαστῆς ἀπολαύοντα δόξης ἐπ’ ἀνδρείᾳ· καὶ γὰρ εἴ τινες ἦσαν οἳ πρότερον αὐτοῦ κατεφρόνουν, τότε μετέστησαν ἐπὶ τὸ τιμᾶν καὶ πάντων ἄριστον νομίζειν· οὐ γὰρ ἤρκεσεν αὐτῷ τοὺς Ἰαβισηνοὺς σεσωκέναι μόνον, ἀλλὰ καὶ τῇ τῶν Ἀμμανιτῶν ἐπιστρατεύσας χώρᾳ πᾶσαν αὐτὴν καταστρέφεται καὶ πολλὴν λαβὼν λείαν λαμπρὸς εἰς τὴν οἰκείαν ὑπέστρεψεν. ὁ δὲ λαὸς ὑφ’ ἡδονῆς τῶν Σαούλῳ κατωρθωμένων ἔχαιρε μὲν ὅτι τοιοῦτον ἐχειροτόνησε βασιλέα, πρὸς δὲ τοὺς οὐδὲν ὄφελος αὐτὸν ἔσεσθαι τοῖς πράγμασι λέγοντας ἐβόων· ποῦ νῦν εἰσὶν οὗτοι καὶ δότωσαν δίκην καὶ πάνθ’ ὅσα φιλεῖ λέγειν ὄχλος ἐπ’ εὐπραγίαις ἠρμένος πρὸς τοὺς ἐξευτελίζοντας ἔναγχος τοὺς τούτων αἰτίους. Σαοῦλος δὲ τούτων μὲν ἠσπάζετο τὴν εὔνοιαν καὶ τὴν περὶ αὐτὸν προθυμίαν, ὤμοσε δὲ μήτινα περιόψεσθαι τῶν ὁμοφύλων ἀναιρούμενον ἐπ’ ἐκείνης τῆς ἡμέρας· ἄτοπον γὰρ εἶναι τὴν ὑπὸ τοῦ θεοῦ δεδομένην νίκην αἵματι φῦραι καὶ φόνῳ τῶν πρὸς ἀλλήλους συγγενῶν ἑορτάζειν.", "st": "6.5.3"}, {"sp": "N", "t": "Σαμουήλου δὲ φήσαντος καὶ δευτέρᾳ δεῖν χειροτονίᾳ Σαούλῳ τὴν βασιλείαν ἐπικυρῶσαι συνίασι πάντες εἰς Γάλγαλα πόλιν· ἐκεῖ γὰρ αὐτοὺς ἐκέλευσεν ἐλθεῖν. καὶ πάλιν ὁρῶντος τοῦ πλήθους ὁ προφήτης χρίει τὸν Σαοῦλον τῷ ἁγίῳ ἐλαίῳ καὶ δεύτερον ἀναγορεύει βασιλέα. καὶ οὕτως ἡ τῶν Ἑβραίων πολιτεία εἰς βασιλείαν μετέπεσεν. ἐπὶ γὰρ Μωυσέος καὶ τοῦ μαθητοῦ αὐτοῦ [Ἰησοῦ], ὃς ἦν στρατηγὸς, ἀριστοκρατούμενοι διετέλουν· μετὰ δὲ τὴν ἐκείνου τελευτὴν ἔτεσι τοῖς πᾶσι δέκα καὶ πρὸς τούτοις ὀκτὼ τὸ πλῆθος αὐτῶν ἀναρχία κατέσχε. μετὰ ταῦτα δ’ εἰς τὴν προτέραν ἐπανῆλθον πολιτείαν τῷ κατὰ πόλεμον ἀρίστῳ δόξαντι γεγενῆσθαι καὶ κατ’ ἀνδρείαν περὶ τῶν ὅλων δικάζειν ἐπιτρέποντες· καὶ διὰ τοῦτο τὸν χρόνον τοῦτον τῆς πολιτείας κριτῶν ἐκάλεσαν.", "st": "6.5.4"}, {"sp": "N", "t": "Ἐκκλησίαν δὲ Σαμουῆλος ποιήσας ὁ προφήτης τῶν Ἑβραίων ἐπόμνυμαι, φησίν, ὑμῖν τὸν μέγιστον θεὸν, ὃς τοὺς ἀδελφοὺς ἐκείνους, λέγω δὴ Μωυσῆν καὶ Ἀαρῶνα, παρήγαγεν εἰς τὸν βίον καὶ τοὺς πατέρας ἡμῶν ἐξήρπασεν Αἰγυπτίων καὶ τῆς ὑπ’ αὐτοῖς δουλείας, μηδὲν μήτ’ αἰδοῖ χαρισαμένους μήτε ὑποστειλαμένους φόβῳ μήτε ἄλλῳ τινὶ πάθει παραχωρήσαντας εἰπεῖν, εἴ τι μοι πέπρακται σκαιὸν καὶ ἄδικον ἢ κέρδους ἕνεκα ἢ πλεονεξίας ἢ χάριτος τῆς πρὸς ἄλλους· ἐλέγξαι δὲ εἰ καὶ τῶν τοιούτων τι προσηκάμην [μόσχον ἢ πρόβατον], ἃ πρὸς τροφὴν ἀνεμέσητον δοκεῖ λαμβάνειν, ἢ εἴ τινος ὑποζύγιον εἰς ἐμὴν ἀποσπάσας χρείαν ἐλύπησα, τούτων ἕν τι κατειπεῖν παρόντος ὑμῶν τοῦ βασιλέως. οἱ δὲ ἀνέκραγον τούτων οὐδὲν ὑπ’ αὐτοῦ γεγονέναι, προστῆναι δὲ ὁσίως αὐτὸν καὶ δικαίως τοῦ ἔθνους.", "st": "6.5.5"}, {"sp": "N", "t": "Σαμουῆλος δὲ ταύτης ἐξ ἁπάντων τῆς μαρτυρίας αὐτῷ γενομένης ἐπεὶ δεδώκατέ μοι, φησί, τὸ μηδὲν ἄτοπον ἔθ’ ὑμᾶς περὶ ἐμοῦ δύνασθαι λέγειν, φέρε νῦν μετὰ παρρησίας ἀκούσατέ μου λέγοντος, ὅτι μεγάλα ἠσεβήσατε εἰς τὸν θεὸν αἰτησάμενοι βασιλέα. διαμνημονεύειν δὲ ὑμᾶς προσῆκεν, ὅτι σὺν ἑβδομήκοντα μόνοις ἐκ τοῦ γένους ἡμῶν ὁ πάππος Ἰάκωβος διὰ λιμὸν εἰς Αἴγυπτον ἦλθε, κἀκεῖ πολλῶν μυριάδων ἐπιτεκνωθεισῶν, ἃς εἰς δουλείας καὶ χαλεπὰς ὕβρεις ἤγαγον οἱ Αἰγύπτιοι, ὁ θεὸς εὐξαμένων τῶν πατέρων χωρὶς βασιλέως παρέσχεν αὐτοῖς ῥύσασθαι τῆς ἀνάγκης τὸ πλῆθος Μωυσῆν αὐτοῖς καὶ Ἀαρῶνα πέμψας ἀδελφοὺς, οἳ ἤγαγον ὑμᾶς εἰς τήνδε τὴν γῆν, ἣν νῦν ἔχετε. καὶ τούτων ἀπολαύσαντες ἐκ τοῦ θεοῦ προδεδώκατε τὴν θρησκείαν καὶ τὴν εὐσέβειαν. οὐ μὴν ἀλλὰ καὶ τοῖς πολεμίοις ὑποχειρίους γενομένους ἠλευθέρωσε πρῶτον μὲν Ἀσσυρίων καὶ τῆς ἐκείνων ἰσχύος ὑπερτέρους ἀπεργασάμενος, ἔπειτα Ἀμμανιτῶν κρατῆσαι παρασχὼν καὶ Μωαβιτῶν καὶ τελευταίων Παλαιστίνων. καὶ ταῦτ’ οὐ βασιλέως ἡγουμένου διεπράξασθε, ἀλλ’ Ἰφθάε καὶ Γεδεῶνος στρατηγούντων. τίς οὖν ἔσχεν ὑμᾶς ἄνοια φυγεῖν μὲν τὸν θεὸν, ὑπὸ βασιλέα δὲ εἶναι θέλειν; ἀλλ’ ἐγὼ μὲν ἀπέδειξα τοῦτον ὃν αὐτὸς ἐπελέξατο, ἵνα μέντοι γε φανερὸν ποιήσω τὸν θεὸν ὀργιζόμενον καὶ δυσχεραίνοντα τῇ τῆς βασιλείας ὑμῶν αἱρέσει, δηλῶσαι τοῦθ’ ὑμῖν [τὸν θεὸν] παρασκευάσω διὰ σημείων ἐναργῶς· ὃ γὰρ οὐδέπω πρότερον εἶδεν ὑμῶν οὐδεὶς ἐνταῦθα γεγενημένον, θέρους ἀκμῇ χειμῶνα, αἰτησάμενος τὸν θεὸν παρέξω τοῦτο νῦν ὑμῖν ἐπιγνῶναι. καὶ ταῦτα εἰπόντος πρὸς τὸ πλῆθος τοῦ Σαμουήλου βρονταῖς σημαίνει τὸ θεῖον καὶ ἀστραπαῖς καὶ χαλάζης καταφορᾷ τὴν τοῦ προφήτου περὶ πάντων ἀλήθειαν, ὡς τεθαμβηκότας αὐτοὺς καὶ περιδεεῖς γινομένους ἁμαρτεῖν τε ὁμολογεῖν καὶ κατ’ ἄγνοιαν εἰς τοῦτο προπεσεῖν, καὶ ἱκετεύειν τὸν προφήτην ὡς πατέρα χρηστὸν καὶ ἐπιεικῆ τὸν θεὸν αὐτοῖς εὐμενῆ καταστῆσαι καὶ ταύτην ἀφεῖναι τὴν ἁμαρτίαν, ἣν πρὸς οἷς ἐξύβρισαν ἄλλοις καὶ παρηνόμησαν προσεξειργάσαντο. ὁ δὲ ὑπισχνεῖται καὶ παρακαλέσειν τὸν θεὸν συγγνῶναι περὶ τούτων αὐτοῖς καὶ πείσειν, συνεβούλευε μέντοι δικαίους εἶναι καὶ ἀγαθοὺς καὶ μνημονεύειν ἀεὶ τῶν διὰ τὴν παράβασιν τῆς ἀρετῆς αὐτοῖς κακῶν συμπεσόντων καὶ τῶν σημείων τοῦ θεοῦ καὶ τῆς Μωυσέος νομοθεσίας, εἰ σωτηρίας αὐτοῖς καὶ τῆς μετὰ τοῦ βασιλέως εὐδαιμονίας ἐστὶν ἐπιθυμία. εἰ δὲ τούτων ἀμελήσουσιν, ἔλεγεν ἥξειν αὐτοῖς τε καὶ τῷ βασιλεῖ μεγάλην ἐκ θεοῦ πληγήν. καὶ Σαμουῆλος μὲν ταῦτα τοῖς Ἑβραίοις προφητεύσας ἀπέλυσεν αὐτοὺς ἐπὶ τὰ οἰκεῖα βεβαιώσας ἐκ δευτέρου τῷ Σαούλῳ τὴν βασιλείαν.", "st": "6.5.6"}, {"sp": "N", "t": "Οὗτος δ’ ἐπιλέξας ἐκ τοῦ πλήθους ὡς τρισχιλίους τοὺς μὲν δισχιλίους ὥστε σωματοφυλακεῖν αὐτὸν λαβὼν αὐτὸς διέτριβεν ἐν πόλει Βεθήβῳ, Ἰωνάθῃ δὲ τῷ παιδὶ τοὺς λοιποὺς δοὺς ὥστε σωματοφυλακεῖν αὐτὸν εἰς Γεβὰλ ἔπεμψεν. ὁ δ’ ἐκπολιορκεῖ τι φρούριον τῶν Παλαιστίνων οὐ πόρρω Γεβάλων. οἱ γὰρ Παλαιστῖνοι καταστρεφόμενοι τοὺς Ἰουδαίους τά τε ὅπλα αὐτοὺς ἀφῃροῦντο καὶ τοὺς ὀχυρωτάτους τῆς χώρας τόπους φρουραῖς κατελαμβάνοντο καὶ σιδηροφορεῖν χρῆσθαί τε καθάπαξ ἀπηγόρευον σιδήρῳ, καὶ διὰ ταύτην τὴν πρόρρησιν οἱ γεωργοὶ, εἴποτε δεήσει’ αὐτοὺς ἐπισκευάσαι τι τῶν ἐργαλείων, ἢ ὕνιν ἢ δίκελλαν ἢ ἄλλο τι τῶν εἰς γεωργίαν χρησίμων, φοιτῶντες εἰς τοὺς Παλαιστίνους ταῦτα ἔπραττον. ὡς δὲ ἠκούσθη τοῖς Παλαιστίνοις ἡ τῆς φρουρᾶς ἀναίρεσις ἀγανακτήσαντες καὶ δεινὴν ὕβριν τὴν καταφρόνησιν ἡγησάμενοι στρατεύουσιν ἐπὶ τοὺς Ἰουδαίους πεζῶν μὲν τριάκοντα μυριάσιν ἅρμασι δὲ τρισμυρίοις, ἵππον δὲ ἑξακισχιλίαν ἐπήγοντο· καὶ στρατοπεδευσαμένων πρὸς πόλει Μαχμὰ τοῦτο Σαοῦλος ὁ τῶν Ἰουδαίων βασιλεὺς μαθὼν εἰς Γάλγαλα καταβαίνει πόλιν καὶ διὰ πάσης κηρύσσει τῆς χώρας ἐπ’ ἐλευθερίᾳ καλῶν τὸν λαὸν ἐπὶ τὸν πόλεμον τὸν πρὸς Παλαιστίνους, τὴν δύναμιν ἐκφαυλίζων αὐτῶν καὶ διασύρων ὡς οὐκ ἀξιόλογον οὐδ’ ὥστε φοβεῖσθαι διακινδυνεύειν πρὸς αὐτούς. κατανοήσαντες δὲ τὸ πλῆθος τῶν Παλαιστίνων οἱ τοῦ Σαούλου κατεπλάγησαν, καὶ οἱ μὲν εἰς τὰ σπήλαια καὶ τοὺς ὑπονόμους ἔκρυψαν αὑτοὺς, οἱ πλείους δὲ εἰς τὴν πέραν τοῦ Ἰορδάνου γῆν ἔφυγον· αὕτη δ’ ἦν Γάδου καὶ Ῥουβήλου.", "st": "6.6.1"}, {"sp": "N", "t": "Πέμψας δὲ Σαοῦλος πρὸς τὸν προφήτην ἐκάλει πρὸς αὑτὸν συνδιασκεψόμενον περὶ τοῦ πολέμου καὶ τῶν πραγμάτων. ὁ δὲ περιμένειν αὐτὸν ἐκέλευσεν αὐτόθι καὶ παρασκευάζειν θύματα· μετὰ γὰρ ἡμέρας ἑπτὰ πρὸς αὐτὸν ἥξειν, ὅπως θύσωσι τῇ ἑβδόμῃ τῶν ἡμερῶν, ἔπειθ’ οὕτως συμβάλωσι τοῖς πολεμίοις. καὶ περιμένει μὲν ὡς ὁ προφήτης ἐπέστειλεν, οὐκέτι μέντοι γε διατηρεῖ τὴν ἐντολήν, ἀλλ’ ὡς ἑώρα βραδύνοντα μὲν τὸν προφήτην, αὑτὸν δὲ ὑπὸ τῶν στρατιωτῶν καταλειπόμενον, λαβὼν τὰ θύματα τὴν θυσίαν ἐπετέλει· ἐπεὶ δὲ τὸν Σαμουῆλον ἤκουσε προσιόντα ὑπαντησόμενος ἐξῆλθεν. ὁ δ’ οὐκ ὀρθῶς αὐτὸν ἔφη πεποιηκέναι παρακούσαντα ὧν ἐπέστειλεν αὐτὸς καὶ φθάσαντα τὴν παρουσίαν, ἣν κατὰ βούλησιν γινομένην τοῦ θείου πρὸς τὰς εὐχὰς καὶ τὰς θυσίας τὰς ὑπὲρ τοῦ πλήθους προλάβοι κακῶς ἱερουργήσας καὶ προπετὴς γενόμενος. ἀπολογουμένου δὲ τοῦ Σαούλου καὶ περιμεῖναι μὲν τὰς ἡμέρας ἃς ὥρισε λέγοντος, ὑπὸ δὲ ἀνάγκης καὶ ἀναχωρήσεως μὲν τῶν αὑτοῦ στρατιωτῶν διὰ φόβον, στρατοπεδείας δὲ τῶν ἐχθρῶν ἐν Μαχμᾶ καὶ ἀκοῆς τῆς ἐπ’ αὐτὸν εἰς Γάλγαλα καταβάσεως ἐπειχθῆναι πρὸς τὴν θυσίαν. ὑπολαβὼν δὲ ὁ Σαμουῆλος ἀλλὰ σύγε, φησίν, εἰ δίκαιος ἦσθα καὶ μὴ παρήκουσας ἐμοῦ μηδ’ ὧν ὑπέθετό μοι περὶ τῶν παρόντων ὁ θεὸς ὠλιγώρησας ταχύτερος ἢ συνέφερε τοῖς πράγμασι γεγονὼς, σοί τ’ αὐτῷ πλεῖστον ἂν βασιλεῦσαι χρόνον ἐξεγένετο καὶ τοῖς σοῖς ἐγγόνοις. καὶ Σαμουῆλος μὲν ἀχθόμενος ἐπὶ τοῖς γεγενημένοις ἀνεχώρησε παρ’ αὑτὸν, Σαοῦλος δὲ εἰς Γαβαὼν πόλιν ἔχων ἑξακοσίους μεθ’ ἑαυτοῦ μόνον ἧκε σὺν Ἰωνάθῃ τῷ παιδί. τούτων δὲ οἱ πλείους οὐκ εἶχον ὅπλα τῆς χώρας σπανιζούσης σιδήρου καὶ τῶν ὅπλα χαλκεύειν δυναμένων· οὐ γὰρ εἴων οἱ Παλαιστῖνοι ταῦτα εἶναι, καθὼς μικρὸν ἔμπροσθεν δεδηλώκαμεν. διελόντες δ’ εἰς τρία μέρη τὴν στρατιὰν οἱ Παλαιστῖνοι καὶ κατὰ τοσαύτας ὁδοὺς ἐπερχόμενοι τὴν τῶν Ἑβραίων χώραν ἐπόρθουν, βλεπόντων τε Σαούλου τοῦ βασιλέως αὐτῶν καὶ τοῦ παιδὸς Ἰωνάθου ἀμῦναί τε τῇ γῇ, μεθ’ ἑξακοσίων γὰρ μόνων ἦσαν, οὐ δυναμένων. καθεζόμενοι δ’ αὐτός τε καὶ ὁ παῖς αὐτοῦ καὶ ὁ ἀρχιερεὺς Ἐχίας ἀπόγονος ὢν Ἠλὶ τοῦ ἀρχιερέως ἐπὶ βουνοῦ ὑψηλοῦ καὶ τὴν γῆν λεηλατουμένην ὁρῶντες ἐν ἀγωνίᾳ δεινῇ καθεστήκεσαν. συντίθεται δὲ ὁ Σαούλου παῖς τῷ ὁπλοφόρῳ, κρύφα πορευθέντες αὐτοὶ εἰς τὴν τῶν πολεμίων παρεμβολὴν ἐκδραμεῖν καὶ ταραχὴν ἐμποιῆσαι καὶ θόρυβον [αὐτοῖς]. τοῦ δὲ ὁπλοφόρου προθύμως ἕπεσθαι φήσαντος ὅποι ποτ’ ἂν ἡγῆται, κἂν ἀποθανεῖν δέῃ, προσλαβὼν τὴν τοῦ νεανίσκου συνεργίαν καὶ καταβὰς ἀπὸ τοῦ βουνοῦ πρὸς τοὺς πολεμίους ἐπορεύετο. ἦν δὲ τὸ τῶν πολεμίων στρατόπεδον ἐπὶ κρημνοῦ, τρισὶν ἄκραις εἰς λεπτὸν ἀπηκονημέναις μῆκος πέτρας ἐν κύκλῳ περιστεφανούσης ὥσπερ προβόλοις τὰς ἐπιχειρήσεις ἀπομαχόμενον. ἔνθεν συνέβαινεν ἠμελῆσθαι τὰς φυλακὰς τοῦ στρατοπέδου διὰ τὸ φύσει περιεῖναι τῷ χωρίῳ τὴν ἀσφάλειαν καὶ παντὶ νομίζειν ἀμήχανον εἶναι κατ’ ἐκείνας οὐκ ἀναβῆναι μόνον ἀλλὰ καὶ προσελθεῖν. ὡς οὖν ἧκον εἰς τὴν παρεμβολὴν ὁ Ἰωνάθης παρεθάρσυνε τὸν ὁπλοφόρον καὶ προσβάλωμεν τοῖς πολεμίοις, ἔλεγε, κἂν μὲν ἀναβῆναι κελεύσωσι πρὸς αὑτοὺς ἡμᾶς ἰδόντες σημεῖον τοῦτο νίκης ὑπολάμβανε, ἐὰν δὲ φθέγξωνται μηδὲν ὡς οὐ καλοῦντες ἡμᾶς ὑποστρέψωμεν. προσιόντων δὲ αὐτῶν τῷ στρατοπέδῳ τῶν πολεμίων ὑποφαινούσης ἤδη τῆς ἡμέρας ἰδόντες οἱ Παλαιστῖνοι πρὸς ἀλλήλους ἔλεγον ἐκ τῶν ὑπονόμων καὶ σπηλαίων προϊέναι τοὺς Ἑβραίους, καὶ πρὸς Ἰωνάθην καὶ τὸν ὁπλοφόρον αὐτοῦ δεῦτε, ἔφασαν, ἀνέλθετε πρὸς ἡμᾶς, ἵνα ὑμᾶς τιμωρησώμεθα τῶν τετολμημένων ἀξίως. ἀσπασάμενος δὲ τὴν φωνὴν ὁ τοῦ Σαούλου παῖς ὡς νίκην αὐτῷ σημαίνουσαν παραυτίκα μὲν ἀνεχώρησαν ἐξ οὗπερ ὤφθησαν τόπου τοῖς πολεμίοις, παραμειψάμενοι δὲ τοῦτον ἐπὶ τὴν πέτραν ἧκον ἔρημον οὖσαν τῶν φυλαττόντων διὰ τὴν ὀχυρότητα. κἀκεῖθεν ἀνερπύσαντες μετὰ πολλῆς ταλαιπωρίας ἐβιάσαντο τὴν τοῦ χωρίου φύσιν ἀνελθεῖν ἐπὶ τοὺς πολεμίους, ἐπιπεσόντες δ’ αὐτοῖς κοιμωμένοις ἀποκτείνουσι μὲν ὡς εἴκοσι, ταραχῆς δὲ καὶ ἐκπλήξεως αὐτοὺς ἐγέμισαν, ὡς τινὰς μὲν φυγεῖν τὰς πανοπλίας ἀπορρίψαντας, οἱ δὲ πολλοὶ μὴ γνωρίζοντες ἑαυτοὺς διὰ τὸ ἐκ πολλῶν ἐθνῶν εἶναι πολεμίους ὑπονοοῦντες ἀλλήλους, καὶ γὰρ εἴκαζον ἀναβῆναι πρὸς αὐτοὺς τῶν Ἑβραίων οὐ δύο μόνους, εἰς μάχην ἐτράποντο. καὶ οἱ μὲν αὐτῶν ἀπέθνησκον κτεινόμενοι, τινὲς δὲ φεύγοντες κατὰ τῶν πετρῶν ὠθούμενοι κατεκρημνίζοντο.", "st": "6.6.2"}, {"sp": "N", "t": "Τῶν δὲ τοῦ Σαούλου κατασκόπων τεταράχθαι τὸ στρατόπεδον τῶν Παλαιστίνων φρασάντων τῷ βασιλεῖ Σαοῦλος ἠρώτα, μή τις εἴη τῶν αὑτοῦ κεχωρισμένος. ἀκούσας δὲ τὸν υἱὸν καὶ σὺν αὐτῷ τὸν ὁπλοφόρον ἀπεῖναι κελεύει τὸν ἀρχιερέα λαβόντα τὴν ἀρχιερατικὴν στολὴν προφητεύειν αὐτῷ περὶ τῶν μελλόντων. τοῦ δὲ νίκην ἔσεσθαι καὶ κράτος κατὰ τῶν πολεμίων φράσαντος ἐπεξέρχεται τοῖς Παλαιστίνοις καὶ τεταραγμένοις προσβάλλει καὶ φονεύουσιν ἀλλήλους. προσρέουσι δὲ αὐτῷ καὶ οἱ πρότερον εἴς τε τοὺς ὑπονόμους καὶ εἰς τὰ σπήλαια συμφυγόντες ἀκούσαντες ὅτι νικᾷ Σαοῦλος· γενομένων δὲ ὡς μυρίων ἤδη τῶν Ἑβραίων διώκει τοὺς πολεμίους κατὰ πᾶσαν ἐσκορπισμένους τὴν χώραν. εἴτε δὲ ὑπὸ τῆς ἐπὶ τῇ νίκῃ χαρᾶς οὕτω παραλόγως γενομένῃ, συμβαίνει γὰρ μὴ κρατεῖν τοῦ λογισμοῦ τοὺς οὕτως εὐτυχήσαντας, εἴθ’ ὑπὸ ἀγνοίας εἰς δεινὸν προπίπτει καὶ πολλὴν ἔχον κατάμεμψιν ἔργον· βουλόμενος γὰρ αὑτῷ τε τιμωρῆσαι καὶ δίκην ἀπολαβεῖν παρὰ τῶν Παλαιστίνων ἐπαρᾶται τοῖς Ἑβραίοις, ἵν’ εἴ τις ἀποσχόμενος τοῦ φονεύειν τοὺς ἐχθροὺς φάγοι καὶ μὴ μέχρι νὺξ ἐπελθοῦσα τῆς ἀναιρέσεως καὶ τῆς διώξεως αὐτοὺς παύσει τῶν πολεμίων, οὗτος ἐπάρατος ᾖ. τοῦ δὲ Σαούλου τοῦτο φήσαντος, ἐπεὶ κατά τινα δρυμὸν ἐγένοντο βαθὺν καὶ μελισσῶν γέμοντα τῆς Ἐφράμου κληρουχίας, ὁ τοῦ Σαούλου παῖς οὐκ ἐπακηκοὼς τῆς τοῦ πατρὸς ἀρᾶς οὐδὲ τῆς ἐπ’ αὐτῇ τοῦ πλήθους ὁμολογίας ἀποθλίψας τι κηρίον τοῦ μέλιτος ἤσθιε. μεταξὺ δὲ γνοὺς, ὅτι μετὰ δεινῆς ἀρᾶς ὁ πατὴρ ἀπεῖπε μὴ γεύσασθαί τινα πρὸ ἡλίου δυσμῶν, ἐσθίων μὲν ἐπαύσατο, ἔφη δὲ οὐκ ὀρθῶς κωλῦσαι τὸν πατέρα· μετὰ μείζονος γὰρ ἰσχύος ἂν καὶ προθυμίας διώκοντας, εἰ τροφῆς μετελάμβανον, πολλῷ πλείονας τῶν ἐχθρῶν καὶ λαβεῖν καὶ φονεῦσαι.", "st": "6.6.3"}, {"sp": "N", "t": "Πολλὰς γοῦν κατακόψαντες μυριάδας τῶν Παλαιστίνων δείλης ὀψίας ἐπὶ διαρπαγὴν τοῦ στρατοπέδου τῶν Παλαιστίνων τρέπονται, καὶ λείαν πολλὴν καὶ βοσκήματα λαβόντες κατασφάζουσι καὶ ταῦτ’ ἔναιμα κατήσθιον. ἀπαγγέλλεται δὲ τῷ βασιλεῖ ὑπὸ τῶν γραμματέων, ὅτι τὸ πλῆθος εἰς τὸν θεὸν ἐξαμαρτάνει θῦσαν καὶ πρὶν ἢ τὸ αἷμα καλῶς ἀποπλῦναι καὶ τὰς σάρκας ποιῆσαι καθαρὰς ἐσθίον. καὶ Σαοῦλος κελεύει κυλισθῆναι λίθον μέγαν εἰς μέσον καὶ κηρύσσει θύειν ἐπ’ αὐτοῦ τὸν ὄχλον τὰ ἱερεῖα καὶ τὰ κρέα μὴ σὺν τῷ αἵματι δαίνυσθαι· τοῦτο γὰρ οὐκ εἶναι τῷ θεῷ κεχαρισμένον. τοῦτο δὲ πάντων κατὰ τὴν πρόσταξιν τοῦ βασιλέως ποιησάντων ἵστησιν ἐκεῖ βωμὸν ὁ Σαοῦλος καὶ ὡλοκαύτωσεν ἐπ’ αὐτοῦ ἐκεῖ τῷ θεῷ. τοῦτον πρῶτον βωμὸν κατεσκεύασεν.", "st": "6.6.4"}, {"sp": "N", "t": "Ἄγειν δ’ εὐθὺς τὴν στρατιὰν ἐπὶ τὴν παρεμβολὴν τῶν πολεμίων ἐπὶ τὴν διαρπαγὴν τῶν ἐν αὐτῇ βουλόμενος πρὶν ἡμέρας καὶ τῶν στρατιωτῶν οὐκ ὀκνούντων ἕπεσθαι, πολλὴν δ’ εἰς ἃ προστάττει προθυμίαν ἐνδεικνυμένων, καλέσας ὁ βασιλεὺς Ἀχίτωβον τὸν ἀρχιερέα κελεύει αὐτὸν γνῶναι, εἰ δίδωσιν αὐτοῖς ὁ θεὸς καὶ συγχωρεῖ βαδίσασιν ἐπὶ τὸ στρατόπεδον τῶν ἐχθρῶν διαφθεῖραι τοὺς ἐν αὐτῷ τυγχάνοντας. εἰπόντος δὲ τοῦ ἱερέως μὴ ἀποκρίνεσθαι τὸν θεόν ἀλλ’ οὐ δίχα αἰτίας, εἶπεν ὁ Σαοῦλος, πυνθανομένοις ἡμῖν φωνὴν οὐ δίδωσιν ὁ θεὸς, ὃς πρότερον αὐτὸς προεμήνυσε πάντα καὶ μηδ’ ἐπερωτῶσιν ἔφθασε λέγων, ἀλλ’ ἔστι τι λανθάνον ἐξ ἡμῶν ἁμάρτημα πρὸς αὐτὸν αἴτιον τῆς σιωπῆς. καὶ ὄμνυμί γε τοῦτον αὐτὸν, ἦ μὴν κἂν ὁ παῖς ὁ ἐμὸς Ἰωνάθης ᾖ τὸ ἁμάρτημα τοῦτο ἐργασάμενος ἀποκτείνειν αὐτὸν καὶ τὸν θεὸν οὕτως ἱλάσασθαι, ὡς ἂν εἰ καὶ παρ’ ἀλλοτρίου καὶ μηδὲν ἐμοὶ προσήκοντος τὴν ὑπὲρ αὐτοῦ δίκην ἀπελάμβανον. τοῦ δὲ πλήθους τοῦτο ποιεῖν ἐπιβοήσαντος παραχρῆμα πάντας ἵστησιν εἰς ἕνα τόπον, ἵσταται δὲ καὶ αὐτὸς σὺν τῷ παιδὶ κατ’ ἄλλο μέρος καὶ κλήρῳ τὸν ἡμαρτηκότα μαθεῖν ἐπεζήτει· καὶ λαγχάνει δοκεῖν οὗτος εἶναι Ἰωνάθης. ἐπερωτώμενος δὲ ὑπὸ τοῦ πατρὸς τί πεπλημμέληκε καὶ τί παρὰ τὸν βίον οὐκ ὀρθῶς οὐδὲ ὁσίως αὑτῷ διαπραξαμένῳ συνέγνωκε πάτερ, εἶπεν, ἄλλο μὲν οὐδὲν, ὅτι δὲ χθὲς ἀγνοῶν τὴν ἀρὰν αὐτοῦ καὶ τὸν ὅρκον μεταξὺ διώκων τοὺς πολεμίους ἐγεύσατο κηρίων. Σαοῦλος δ’ ἀποκτείνειν αὐτὸν ὄμνυσι καὶ τῆς γενέσεως καὶ τῆς φύσεως τῶν φίλτρων ἐτίμησε τὸν ὅρκον. ὁ δ’ οὐ καταπλήττεται τὴν ἀπειλὴν τοῦ θανάτου, παραστησάμενος δ’ εὐγενῶς καὶ μεγαλοφρόνως οὐδ’ ἐγώ σε, φησίν, ἱκετεύσω φείσασθαί μου, πάτερ, ἥδιστος δέ μοι ὁ θάνατος ὑπέρ τε τῆς σῆς εὐσεβείας γινόμενος καὶ ἐπὶ νίκῃ λαμπρᾷ· μέγιστον γὰρ παραμύθιον τὸ καταλιπεῖν Ἑβραίους Παλαιστίνων κεκρατηκότας. ἐπὶ τούτοις ὁ λαὸς πᾶς ἤλγησε καὶ συνέπαθεν ὤμοσέ τε μὴ περιόψεσθαι τὸν αἴτιον τῆς νίκης Ἰωνάθην ἀποθανόντα. καὶ τὸν μὲν οὕτως ἐξαρπάζουσι τῆς τοῦ πατρὸς ἀρᾶς, αὐτοὶ δὲ εὐχὰς ὑπὲρ τοῦ νεανίσκου ποιοῦνται τῷ θεῷ ὥστε αὐτὸν ἀπολῦσαι τοῦ ἁμαρτήματος.", "st": "6.6.5"}, {"sp": "N", "t": "Καὶ ὁ Σαοῦλος εἰς τὴν ἑαυτοῦ πόλιν ὑπέστρεψε διαφθείρας ὡσεὶ μυριάδας ἓξ τῶν πολεμίων. βασιλεύει δὲ εὐτυχῶς, καὶ τὰ πλησιόχωρα τῶν ἐθνῶν πολεμήσας χειροῦται τό τε Ἀμμανιτῶν καὶ Μωαβιτῶν Παλαιστίνους Ἰδουμαίους [Ἀμαληκίτας τε] καὶ τὸν βασιλέα τῆς Σωβᾶς. ἦσαν δὲ παῖδες αὐτῷ τρεῖς μὲν ἄρσενες Ἰωνάθης καὶ Ἰησοῦς καὶ Μέλχισος, θυγατέρες δὲ Μερόβη καὶ Μιχαάλ. στρατηγὸν δὲ εἶχε τὸν τοῦ θείου παῖδα Ἀβήναρον· Νῆρος δ’ ἐκεῖνος ἐκαλεῖτο, Νῆρος δὲ καὶ Κεὶς ὁ Σαούλου πατὴρ ἀδελφοὶ ἦσαν, υἱοὶ δ’ Ἀβελίου. ἦν δὲ καὶ πλῆθος ἁρμάτων Σαούλῳ καὶ ἱππέων, οἷς δὲ πολεμήσειε νικήσας ἀπηλλάσσετο, καὶ τοὺς Ἑβραίους εἰς εὐπραγίας καὶ μέγεθος εὐδαιμονίας προηγάγετο καὶ τῶν ἄλλων ἀπέδειξεν ἐθνῶν δυνατωτέρους, καὶ τῶν νέων τοὺς δὴ καὶ μεγέθει καὶ κάλλει διαφέροντας φύλακας τοῦ σώματος ἐποιεῖτο.", "st": "6.6.6"}, {"sp": "N", "t": "Σαμουῆλος δὲ παραγενόμενος πρὸς τὸν Σαοῦλον πεμφθῆναι πρὸς αὐτὸν ἔφασκεν ὑπὸ τοῦ θεοῦ, ὅπως αὐτὸν ὑπομνήσῃ, ὅτι βασιλέα προκρίνας αὐτὸν ἁπάντων ὁ θεὸς ἀπέδειξε, καὶ διὰ τοῦτο πείθεσθαι καὶ κατήκοον αὐτῷ γενέσθαι ὡς αὐτοῦ μὲν ἔχοντος τὴν τῶν ἐθνῶν ἡγεμονίαν, τοῦ δὲ θεοῦ καὶ τὴν κατ’ ἐκείνου καὶ τῶν ὅλων πραγμάτων. λέγειν τοίνυν ἔφασκε τὸν θεὸν· ἐπεὶ πολλὰ κακὰ τοὺς Ἑβραίους Ἀμαληκῖται διέθηκαν κατὰ τὴν ἔρημον, ὅτε ἐξελθόντες ἀπ’ Αἰγύπτου εἰς τὴν νῦν ὑπάρχουσαν αὐτοῖς ἐστέλλοντο χώραν, κελεύω πολέμῳ τιμωρησάμενον τοὺς Ἀμαληκίτας καὶ κρατήσαντα μηδέν’ αὐτῶν ὑπολιπεῖν, ἀλλὰ πάσης διεξελθεῖν ἡλικίας ἀρξαμένους ἀπὸ γυναικῶν κτείνειν καὶ νηπίων καὶ τοιαύτην ὑπὲρ ὧν τοὺς προγόνους ὑμῶν εἰργάσαντο τιμωρίαν ἀπολαβεῖν, φείσασθαι δὲ μήτε ὑποζυγίων μήτε τῶν ἄλλων βοσκημάτων εἰς ὠφέλειαν καὶ κτῆσιν ἰδίαν, ἅπαντα δ’ ἀναθεῖναι τῷ θεῷ καὶ τὸ Ἀμαλήκου ὄνομα ταῖς Μωυσέος κατακολουθήσαντ’ ἐντολαῖς ἐξαλεῖψαι.", "st": "6.7.1"}, {"sp": "N", "t": "Ὁμολογεῖ δὲ ποιήσειν Σαοῦλος τὰ προστασσόμενα, τὴν δὲ πειθαρχίαν τὴν πρὸς τὸν θεὸν οὐκ ἐν τῷ ποιήσασθαι τὴν πρὸς τοὺς Ἀμαληκίτας στρατείαν λογιζόμενος εἶναι μόνον, ἀλλὰ καὶ τὴν ἑτοιμότητα καὶ τὸ τάχος ἀναβολῆς οὐ προσούσης ἔτι μᾶλλον ἐμφανίζει, ἀθροίζει τε πᾶσαν τὴν δύναμιν καὶ ταύτην ἐξαριθμήσας ἐν Γαλγάλοις εὑρίσκει τῶν Ἰσραηλιτῶν ἔξω τῆς Ἰούδα φυλῆς περὶ τεσσαράκοντα μυριάδας· ἥδε γὰρ ἡ φυλὴ καθ’ αὑτήν ἐστι στρατιῶται τρισμύριοι. Σαοῦλος δ’ ἐμβαλὼν εἰς τὴν τῶν Ἀμαληκιτῶν χώραν ἐνέδρας πολλὰς καὶ λόχους περὶ τὸν χειμάρρουν τίθησιν, ὡς μὴ μόνον ἐκ τοῦ φανεροῦ μαχομένους αὐτοὺς κακῶς ποιεῖν, ἀλλὰ καὶ μὴ προσδοκῶσι κατὰ τὰς ὁδοὺς ἐπιπίπτειν καὶ κυκλουμένους ἀναιρεῖν· καὶ δὴ συμβαλὼν αὐτοῖς εἰς μάχην τρέπεται τοὺς πολεμίους καὶ διαφθείρει πάντας φεύγουσιν ἐπακολουθῶν. ὡς δ’ ἐκεῖνο τὸ ἔργον αὐτῷ κατὰ τὴν τοῦ θεοῦ προφητείαν ἐχώρησε, ταῖς πόλεσι τῶν Ἀμαληκιτῶν προσέβαλε καὶ τὰς μὲν μηχανήμασι, τὰς δὲ ὀρύγμασιν ὑπονόμοις καὶ τείχεσιν ἔξωθεν ἀντῳκοδομημένοις, τὰς δὲ λιμῷ καὶ δίψει, τὰς δὲ ἄλλοις τρόποις ἐκπολιορκήσας καὶ λαβὼν κατὰ κράτος ἐπὶ σφαγὴν γυναικῶν καὶ νηπίων ἐχώρησεν, οὐδὲν ὠμὸν οὐδ’ ἀνθρωπίνης σκληρότερον διαπράσσεσθαι φύσεως ἡγούμενος, πρῶτον μὲν πολεμίους ταῦτα δρῶν, ἔπειτα προστάγματι θεοῦ, ᾧ τὸ μὴ πείθεσθαι κίνδυνον ἔφερε. λαμβάνει δὲ καὶ τὸν βασιλέα τῶν ἐχθρῶν Ἄγαγον αἰχμάλωτον, οὗ θαυμάσας τὸ κάλλος καὶ τὸ μέγεθος τοῦ σώματος σωτηρίας ἄξιον ἔκρινεν οὐκέτι τοῦτο ποιῶν κατὰ βούλησιν τοῦ θεοῦ, πάθει δὲ νικώμενος ἰδίῳ καὶ χαριζόμενος ἀκαίρως περὶ ὧν οὐκ εἶχεν ἀκίνδυνον ἐξουσίαν οἴκτῳ. ὁ μὲν γὰρ θεὸς οὕτως ἐμίσησε τὸ τῶν Ἀμαληκιτῶν ἔθνος, ὡς μηδὲ νηπίων φείσασθαι κελεῦσαι πρὸς ἃ μᾶλλον ἔλεος γίνεσθαι πέφυκε, Σαοῦλος δὲ αὐτῶν τὸν βασιλέα καὶ τὸν ἡγεμόνα τῶν εἰς Ἑβραίους κακῶν ἔσωσε τῆς μνήμης ὧν ἐπέστειλεν ὁ θεὸς τὸ τοῦ πολεμίου κάλλος ἐπίπροσθεν ποιησάμενος. συνεξήμαρτε δ’ αὐτῷ καὶ τὸ πλῆθος· καὶ γὰρ ἐκεῖνοι τῶν ὑποζυγίων καὶ τῶν βοσκημάτων ἐφείσαντο καὶ διήρπασαν μὴ τηρεῖν αὐτὰ τοῦ θεοῦ κελεύσαντος τά τε ἄλλα χρήματα καὶ τὸν πλοῦτον ἐξεφόρησαν, εἰ δέ τι μὴ σπουδῆς ἦν ἄξιον ὥστε κεκτῆσθαι διέφθειραν.", "st": "6.7.2"}, {"sp": "N", "t": "Νικήσας δὲ Σαοῦλος ἅπαντας τοὺς ἀπὸ Πηλουσίου τῆς Αἰγύπτου καθήκοντας ἕως τῆς Ἐρυθρᾶς θαλάσσης διέφθειρε πολεμίους παραλιπὼν τὸ τῶν Σικιμιτῶν ἔθνος· οὗτοι γὰρ ἐν τῇ Μαδιηνῇ χώρᾳ μέσοι κατῴκηνται. πρὸ δὲ τῆς μάχης πέμψας παρήγγειλεν αὐτοῖς ἀναχωρεῖν, μὴ τοῖς Ἀμαληκίταις κοινωνήσωσι συμφορᾶς· συγγενεῖς γὰρ αὐτοὺς ὄντας Ῥαγουήλου τοῦ Μωυσέος πενθεροῦ σώζειν αἰτίαν ἔχειν.", "st": "6.7.3"}, {"sp": "N", "t": "Καὶ Σαοῦλος μὲν ὡς μηδενὸς παρακούσας ὧν ὁ προφήτης ἐπέστειλε μέλλοντι τὸν πρὸς Ἀμαληκίτας ἐκφέρειν πόλεμον, ἀλλ’ ὡς ἐπὶ πᾶσιν ἐκείνοις ἀκριβῶς πεφυλαγμένοις νενικηκὼς τοὺς πολεμίους οἴκαδε πρὸς αὑτὸν ὑπέστρεψε χαίρων ἐπὶ τοῖς κατωρθωμένοις. ὁ δὲ θεὸς ἄχθεται τῇ τε τοῦ βασιλέως τῶν Ἀμαληκιτῶν σωτηρίᾳ καὶ τῇ τῶν βοσκημάτων διαρπαγῇ τοῦ πλήθους, ὅτι μὴ συγχωρήσαντος αὐτοῦ ταῦτ’ ἐπράχθη· δεινὸν γὰρ ἡγεῖτο νικᾶν μὲν καὶ περιγίνεσθαι τῶν ἐχθρῶν ἐκείνου τὴν ἰσχὺν διδόντος αὐτοῖς, καταφρονεῖσθαι δὲ καὶ παρακούεσθαι μηδὲ ὡς ἄνθρωπον βασιλέα. μετανοεῖν οὖν ἔλεγε πρὸς τὸν προφήτην Σαμουῆλον ἐπὶ τῷ χειροτονῆσαι βασιλέα τὸν Σαοῦλον μηδὲν ὧν αὐτὸς κελεύει πράττοντα, τῇ δ’ οἰκείᾳ βουλήσει χρώμενον. σφόδρα ταῦτ’ ἀκούσας ὁ Σαμουῆλος συνεχύθη καὶ δι’ ὅλης τῆς νυκτὸς παρακαλεῖν ἤρξατο τὸν θεὸν καταλλάττεσθαι τῷ Σαούλῳ καὶ μὴ χαλεπαίνειν. ὁ δὲ τὴν συγγνώμην οὐκ ἐπένευσεν εἰς τὸν Σαοῦλον αἰτουμένῳ τῷ προφήτῃ λογισάμενος οὐκ εἶναι δίκαιον ἁμαρτήματα χαρίζεσθαι παραιτήσει· οὐ γὰρ ἐξ ἄλλου τινὸς φύεσθαι μᾶλλον ἢ τοῦ μαλακίζεσθαι τοὺς ἀδικουμένους· θηρωμένους γὰρ δόξαν ἐπιεικείας καὶ χρηστότητος λανθάνειν αὐτοὺς ταῦτα γεννῶντας. ὡς οὖν ἀπεῖπεν ὁ θεὸς τῇ τοῦ προφήτου δεήσει καὶ δῆλος ἦν μεταμελόμενος, ἅμ’ ἡμέρᾳ Σαμουῆλος εἰς Γάλγαλα παραγίνεται πρὸς Σαοῦλον· θεασάμενος δ’ αὐτὸν ὁ βασιλεὺς προστρέχει καὶ κατασπασάμενος τῷ θεῷ, φησίν, εὐχαριστῶ δόντι μοι τὴν νίκην, ἅπαντα μέντοι γε τὰ κελευσθέντα ὑπ’ αὐτοῦ πέπρακται. Σαμουῆλος δὲ πρὸς τοῦθ’ ὑπολαβὼν πόθεν οὖν ἀκούω θρεμμάτων, εἶπε, καὶ ὑποζυγίων βοῆς ἐν τῷ στρατοπέδῳ; ὁ δὲ τὸν λαὸν ταῦτ’ εἰς θυσίας ἀπεκρίνατο τετηρηκέναι· τὸ μέντοι γε τῶν Ἀμαληκιτῶν γένος πᾶν ἐξηφανίσθαι κατὰ τὴν ἐντολὴν καὶ περιλείπεσθαι ἄλλον μηδένα, πρὸς δ’ αὐτὸν ἀγαγεῖν μόνον τηρήσαντα αὐτῶν τὸν βασιλέα, περὶ οὗ τί δεῖ ποιεῖν βουλεύσεσθαι πρὸς ἀλλήλους ἔφασκεν. ὁ δὲ προφήτης οὐχὶ θυσίαις ἔλεγεν ἥδεσθαι τὸ θεῖον, ἀλλὰ τοῖς ἀγαθοῖς καὶ δικαίοις. οὗτοι δέ εἰσιν οἱ τῇ βουλήσει καὶ ταῖς ἐντολαῖς αὐτοῦ κατακολουθοῦντες καὶ μηδὲν ἄλλο πραχθήσεσθαι καλῶς ὑφ’ ἑαυτῶν νομίζοντες ἢ ὅτι ἂν ποιήσωσι τοῦ θεοῦ κεκελευκότος· καταφρονεῖσθαι γὰρ οὐχ ὅταν αὐτῷ μὴ θύῃ τις, ἀλλ’ ὅταν ἀπειθεῖν δοκῇ. παρὰ δὲ τῶν οὐχ ὑποτασσομένων οὐδ’ ἀληθῆ καὶ μόνην τῷ θεῷ κεχαρισμένην θρησκευόντων θρησκείαν, οὔτ’ ἂν πολλὰ καὶ πιμελῆ καταθύσωσιν ἱερεῖα, οὔτ’ ἂν κόσμον ἀναθημάτων ἐξ ἀργύρου καὶ χρυσοῦ πεποιημένων προσφέρωσι, δέχεται ταῦτ’ εὐμενῶς, ἀλλ’ ἀποστρέφεται καὶ δείγματα τῆς πονηρίας οὐκ εὐσέβειαν ἡγεῖται. τοῖς δ’ ἓν καὶ μόνον τοῦθ’ ὅτι περ ἂν φθέγξηται καὶ κελεύσῃ ὁ θεὸς διὰ μνήμης ἔχουσι καὶ τεθνάναι μᾶλλον ἢ παραβῆναί τι τούτων αἱρουμένοις ἐπιτέρπεται, καὶ οὔτε θυσίαν ἐπιζητεῖ παρ’ αὐτῶν καὶ παρὰ θυόντων δὲ, κἂν ᾖ λιτά, τῆς πενίας ἥδιον τὴν τιμὴν ἢ παρὰ τῶν πλουσιωτάτων δεξιοῦται. σὺ τοίνυν ἴσθι σαυτὸν δι’ ὀργῆς ὄντα τῷ θεῷ· κατεφρόνησας γὰρ καὶ κατημέλησας ὧν ἐπέστειλε. πῶς οὖν οἴει τὴν θυσίαν ἂν αὐτὸν προσβλέπειν ἐξ ὧν κατέκρινεν ἀπολέσθαι γινομένην; πλὴν εἰ μὴ νομίζεις ὅμοιον ὄλεθρον τὸ θύεσθαι ταῦτα τῷ θεῷ. προσδόκα τοίνυν τὴν βασιλείαν ἀφαιρεθησόμενος καὶ τὴν ἐξουσίαν, ἀφ’ ἧς ὁρμώμενος τοῦ παρασχόντος σοι θεοῦ ταύτην ἠμέλησας. Σαοῦλος δὲ ἀδικεῖν ὡμολόγει καὶ τὴν ἁμαρτίαν οὐκ ἠρνεῖτο· παραβῆναι γὰρ τὰς ἐντολὰς τοῦ προφήτου· κατὰ μέντοι γε δέος καὶ τὸν ἀπὸ τῶν στρατιωτῶν φόβον μὴ κωλῦσαι διαρπάζοντας αὐτοὺς τὴν λείαν μηδ’ ἐπισχεῖν. ἀλλὰ συγγίνωσκε καὶ πρᾷος ἴσθι· φυλάξεσθαι γὰρ εἰς τοὐπιὸν ἁμαρτεῖν, παρεκάλει δὲ τὸν προφήτην ὑποστρέψαντα θυσίας χαριστηρίους ἐπιτελέσαι τῷ θεῷ· ὁ δὲ, οὐ γὰρ ἑώρα τὸν θεὸν διαλλαττόμενον, ἀπῄει πρὸς ἑαυτόν.", "st": "6.7.4"}, {"sp": "N", "t": "Σαοῦλος δὲ κατασχεῖν βουλόμενος τὸν Σαμουῆλον ἐλλαμβάνεται τῆς διπλοΐδος καὶ βιαίας τῆς ὁλκῆς διὰ τὸ μεθ’ ὁρμῆς ἀπιέναι τὸν Σαμουῆλον γενομένης διασχίζει τὸ ἱμάτιον. τοῦ δὲ προφήτου τὴν βασιλείαν οὕτως [αὐτοῦ] διασχισθῆναι φήσαντος καὶ λήψεσθαι ταύτην ἀγαθὸν καὶ δίκαιον, ἐμμένειν γὰρ τὸν θεὸν τοῖς περὶ αὐτοῦ κεκριμένοις ὡς τοῦ μεταβάλλεσθαι καὶ στρέφειν τὴν γνώμην ἀνθρωπίνου πάθους ὄντος οὐχὶ θείας ἰσχύος, ὁ Σαοῦλος ἀσεβῆσαι μὲν ἔλεγεν, ἀγένητα δὲ ποιῆσαι τὰ πεπραγμένα μὴ δύνασθαι· τιμῆσαί γε μὴν αὐτὸν παρεκάλει τοῦ πλήθους ὁρῶντος σὺν αὐτῷ παραγενόμενον τὸν θεὸν προσκυνῆσαι. δίδωσι δὲ τοῦτο Σαμουῆλος αὐτῷ καὶ συνελθὼν προσκυνεῖ τῷ θεῷ. ἄγεται δὲ καὶ ὁ τῶν Ἀμαληκιτῶν βασιλεὺς Ἄγαγος πρὸς αὐτόν· καὶ πυνθανομένου, πῶς εἴη πικρὸς ὁ θάνατος, εἶπεν ὡς σὺ πολλὰς μητέρας Ἑβραίων ἐπὶ τέκνοις ὀδύρεσθαι καὶ πένθος ἄγειν ἐποίησας, οὕτως ὀδυνήσεις ἐπὶ σαυτῷ διαφθαρέντι τὴν μητέρα. καὶ κελεύει παραχρῆμα αὐτὸν ἐν Γαλγάλοις ἀποθανεῖν. καὶ αὐτὸς δὲ εἰς Ἅρμαθον πόλιν ἀπαλλάσσεται.", "st": "6.7.5"}, {"sp": "N", "t": "Σαοῦλος δὲ ὁ βασιλεὺς αἰσθόμενος ὧν πειραθείη κακῶν ἐχθρὸν αὑτῷ τὸν θεὸν κατασκευάσας, εἰς τὸ βασίλειον ἀναβαίνει Γαβᾶ, σημαίνει βουνὸν ἑρμηνευόμενον τὸ ὄνομα, καὶ μετ’ ἐκείνην οὐκέτι τὴν ἡμέραν εἰς ὄψιν ἔρχεται τῷ προφήτῃ. Σαμουήλῳ δὲ λυπουμένῳ περὶ αὐτοῦ παύσασθαι μὲν τῆς φροντίδος ἐκέλευσεν ὁ θεός, λαβόντι δὲ τὸ ἅγιον ἔλαιον εἰς Βηθλέμην ἀπελθεῖν πόλιν πρὸς Ἰεσσαῖον παῖδα Ὠβήδου καὶ χρῖσαι τῶν υἱῶν αὐτοῦ ὃν ἂν αὐτὸς ἐπιδείξῃ βασιλέα γενησόμενον. ὁ δὲ εὐλαβεῖσθαι φήσας, μὴ τοῦτο μαθὼν Σαοῦλος ἀνέλῃ λοχήσας αὐτὸν ἢ καὶ φανερῶς, ὑποθεμένου τοῦ θεοῦ καὶ δόντος ἀσφαλείας ὁδὸν ἧκεν εἰς τὴν προειρημένην πόλιν. καὶ πάντες αὐτὸν ἠσπάζοντό τε καὶ τὴν αἰτίαν τῆς ἀφίξεως ἀνηρώτων, ἔλεγε δὲ ἥκειν ἵνα θύσῃ τῷ θεῷ. ποιήσας οὖν τὴν θυσίαν καλεῖ τὸν Ἰεσσαῖον μετὰ τῶν τέκνων ἐπὶ τὰ ἱερὰ καὶ θεασάμενος αὐτοῦ τὸν πρεσβύτατον υἱὸν εὐμεγέθη καὶ καλὸν εἴκασεν ἐκ τῆς εὐμορφίας τοῦτον εἶναι τὸν μέλλοντα βασιλεύειν. διαμαρτάνει δὲ τῆς τοῦ θεοῦ προνοίας· ἐπερωτήσαντι γὰρ αὐτὸν, εἰ χρίσει τῷ ἐλαίῳ τὸν νεανίσκον, ὃν αὐτός τε θαυμάζει καὶ τῆς βασιλείας ἄξιον ἔκρινεν, οὐ τὰ αὐτὰ βλέπειν ἀνθρώπους εἶπε καὶ θεόν· ἀλλὰ σὺ μὲν εἰς τὸ κάλλος ἀπιδὼν τοῦ νεανίσκου καὶ δὴ τοῦτον ἡγῇ ἄξιον τοῦ βασιλεύειν εἶναι, ἐγὼ δ’ οὐ σωμάτων εὐμορφίας ἔπαθλον ποιοῦμαι τὴν βασιλείαν ἀλλὰ ψυχῶν ἀρετῆς καὶ ζητῶ ὅστις ταύτης ἐστὶ τελέως εὐπρεπὴς, εὐσεβείᾳ καὶ δικαιοσύνῃ καὶ ἀνδρείᾳ καὶ πειθοῖ ἐξ ὧν τὸ τῆς ψυχῆς συνίσταται κάλλος κατακεκοσμημένος. ταῦτα φράσαντος τοῦ θεοῦ πάντας ἐκέλευσεν αὐτῷ τὸν Ἰεσσαῖον τοὺς υἱοὺς ἐπιδεῖξαι Σαμουῆλος· ὁ δὲ πέντε ἄλλους ἐποίησεν ἐλθεῖν, ὧν ὁ μὲν πρεσβύτερος Ταλίαβος, ὁ δεύτερος Ἀμινάδαβος, Σάμαλος ὁ τρίτος, ὁ τέταρτος Ναθαναῆλος, καὶ Ῥάηλος ὁ πέμπτος ἐκαλεῖτο, ὁ δὲ ἕκτος Ἄσαμος. ἰδὼν δὲ καὶ τούτους ὁ προφήτης μηδὲν χείρους τοῦ πρεσβυτέρου ταῖς μορφαῖς ἐπηρώτησε τὸν θεὸν, τίνα τούτων αἱρεῖται βασιλέα. εἰπόντος δ’ οὐδένα πυνθάνεται τοῦ Ἰεσσαίου, μὴ πρὸς τούτοις αὐτῷ καὶ ἄλλοι παῖδές εἰσι. φήσαντος δὲ εἶναι Δαβίδην τοὔνομα, ποιμαίνειν δὲ καὶ τῆς τῶν βοσκημάτων φυλακῆς ἐπιμελεῖσθαι κελεύει καλεῖν αὐτὸν ἐν τάχει· κατακλιθῆναι γὰρ εἰς εὐωχίαν οὐκ εἶναι δυνατὸν αὐτοῖς ἐκείνου μὴ παρόντος. ὡς δ’ ἧκεν ὁ Δαβίδης μεταπεμφθεὶς ὑπὸ τοῦ πατρὸς, παῖς ξανθὸς μὲν τὴν χρόαν γοργὸς δὲ τὰς ὄψεις καὶ καλὸς ἄλλως οὗτός ἐστιν, εἰπὼν ἡσυχῇ πρὸς αὑτὸν Σαμουῆλος, ὁ βασιλεύειν ἀρέσας τῷ θεῷ κατακλίνεται μὲν αὐτός, κατακλίνει δ’ ὑφ’ αὑτὸν τὸν νεανίσκον καὶ τὸν Ἰεσσαῖον μετὰ καὶ τῶν παίδων. ἔπειτα λαβὼν ὁρῶντος τοῦ Δαβίδου τὸ ἔλαιον ἀλείφει τ’ αὐτὸν καὶ πρὸς τὸ οὖς ἠρέμα λαλεῖ καὶ σημαίνει τοῦθ’, ὅτι βασιλεύειν αὐτὸν ὁ θεὸς ᾕρηται, παρῄνει δ’ εἶναι δίκαιον καὶ κατήκοον αὐτοῦ τῶν προσταγμάτων· οὕτως γὰρ αὐτῷ παραμενεῖν τὴν βασιλείαν εἰς πολὺν χρόνον καὶ τὸν οἶκον λαμπρὸν καὶ περιβόητον γενήσεσθαι, καταστρέψεσθαι δὲ καὶ Παλαιστίνους, καὶ οἷς ἂν ἔθνεσι πολεμῇ νικῶντα καὶ περιόντα τῇ μάχῃ κλέος ἀοίδιμον ζῶντά τε ἕξειν καὶ τοῖς μετ’ αὐτὸν ἀπολείψειν.", "st": "6.8.1"}, {"sp": "N", "t": "Καὶ Σαμουῆλος μὲν ἀπαλλάσσεται ταῦτα παραινέσας, πρὸς δὲ τὸν Δαβίδην μεταβαίνει τὸ θεῖον καταλιπὸν Σαοῦλον. καὶ ὁ μὲν προφητεύειν ἤρξατο τοῦ θείου πνεύματος εἰς αὐτὸν μετοικισαμένου, τὸν Σαοῦλον δὲ περιήρχετο πάθη τινὰ καὶ δαιμόνια πνιγμοὺς αὐτῷ καὶ στραγγάλας ἐπιφέροντα, ὡς τοὺς ἰατροὺς ἄλλην μὲν αὐτῷ θεραπείαν μὴ ἐπινοεῖν, εἰ δέ τίς ἐστιν ἐξᾴδειν δυνάμενος καὶ ψάλλειν ἐπὶ κινύρᾳ τοῦτον ἐκέλευσαν ζητήσαντας, ὁπόταν αὐτῷ προσίῃ τὰ δαιμόνια καὶ ταράττῃ, ποιεῖν ὑπὲρ κεφαλῆς στάντα ψάλλειν τε καὶ τοὺς ὕμνους ἐπιλέγειν. ὁ δὲ οὐκ ἠμέλησεν, ἀλλὰ ζητεῖσθαι προσέταξε τοιοῦτον ἄνθρωπον· φήσαντος δέ τινος αὐτῷ τῶν παρόντων ἐν Βηθλεέμῃ πόλει τεθεᾶσθαι Ἰεσσαίου μὲν υἱὸν, ἔτι [δὲ] παῖδα τὴν ἡλικίαν, εὐπρεπῆ δὲ καὶ καλὸν τά τε ἄλλα σπουδῆς ἄξιον καὶ δὴ καὶ ψάλλειν εἰδότα καὶ ᾄδειν ὕμνους καὶ πολεμιστὴν ἄκρον, πέμψας πρὸς τὸν Ἰεσσαῖον ἐκέλευσεν ἀποστέλλειν αὐτῷ τὸν Δαβίδην τῶν ποιμνίων ἀποσπάσαντα· βούλεσθαι γὰρ αὐτὸν ἰδεῖν περὶ τῆς εὐμορφίας καὶ τῆς ἀνδρείας ἀκούσας τοῦ νεανίσκου. ὁ δὲ Ἰεσσαῖος πέμπει τὸν υἱὸν καὶ ξένια δοὺς κομίσαι τῷ Σαούλῳ. ἐλθόντι δὲ ἥσθη καὶ ποιήσας ὁπλοφόρον διὰ πάσης ἦγε τιμῆς· ἐξῄδετο γὰρ ὑπ’ αὐτοῦ καὶ πρὸς τὴν ἀπὸ τῶν δαιμονίων ταραχήν, ὁπότε αὐτῷ ταῦτα προσέλθοι, μόνος ἰατρὸς ἦν λέγων τε τοὺς ὕμνους καὶ ψάλλων ἐν τῇ κινύρᾳ καὶ ποιῶν ἑαυτοῦ γίνεσθαι τὸν Σαοῦλον. πέμπει τοίνυν πρὸς τὸν πατέρα τοῦ παιδὸς Ἰεσσαῖον ἐᾶσαι παρ’ αὐτῷ τὸν Δαβίδην κελεύων· ἥδεσθαι γὰρ αὐτῷ βλεπομένῳ καὶ παρόντι· τὸν δ’ οὐκ ἀντειπεῖν τῷ Σαούλῳ, συγχωρῆσαι δὲ κατέχειν.", "st": "6.8.2"}, {"sp": "N", "t": "Χρόνοις δ’ ὕστερον οὐ πολλοῖς οἱ Παλαιστῖνοι πάλιν συνελθόντες καὶ δύναμιν ἀθροίσαντες μεγάλην ἐπίασι τοῖς Ἰσραηλίταις καὶ μεταξὺ Σωκοῦς καὶ Ἀζηκοῦς καταλαμβανόμενοι στρατοπεδεύονται. ἀντεπεξάγει δ’ αὐτοῖς τὴν στρατιὰν καὶ Σαοῦλος καὶ ἐπί τινος ὄρους στρατοπεδευσάμενος ἀναγκάζει τοὺς Παλαιστίνους τὸ μὲν πρῶτον στρατόπεδον καταλιπεῖν, ὁμοίως δ’ ἐπί τινος ὄρους ἀντικρὺ τοῦ καταληφθέντος ὑπὸ τοῦ Σαούλου στρατοπεδεύσασθαι. διίστη δ’ ἀπ’ ἀλλήλων τὰ στρατόπεδα μέσος αὐλὼν τῶν ὀρῶν ἐφ’ ὧν ἦν. καταβὰς οὖν τις τῶν ἐκ τοῦ Παλαιστίνων στρατοπέδου Γολιάθης ὄνομα· πόλεως δὲ Γίττης ἀνὴρ παμμεγεθέστατος· ἦν γὰρ πηχῶν τεσσάρων καὶ σπιθαμῆς ὅπλα τῇ φύσει τοῦ σώματος ἀναλογοῦντα περικείμενος· θώρακα μὲν γὰρ ἐνεδέδυτο σταθμὸν ἄγοντα πέντε χιλιάδας σίκλων, κόρυθα δὲ καὶ κνημῖδας χαλκέας ὁποίας εἰκὸς ἦν ἀνδρὸς οὕτω παραδόξου τὸ μέγεθος σκεπάσαι μέρη, δόρυ δὲ ἦν οὐ κοῦφον βάσταγμα δεξιᾶς, ἀλλ’ ἐπὶ τῶν ὤμων αὐτὸ αἴρων ἔφερεν, εἶχε δὲ καὶ λόγχην ἑξακοσίων σίκλων, εἵποντο δὲ πολλοὶ βαστάζοντες τὰ ὅπλα· στὰς τοίνυν ὁ Γολίαθος οὗτος μεταξὺ τῶν παρατάξεων βοήν τε ἀφίησι μεγάλην καὶ πρὸς τὸν Σαοῦλον καὶ τοὺς Ἑβραίους λέγει· μάχης μὲν ὑμᾶς καὶ κινδύνων ἀπαλλάττω· τίς γὰρ ἀνάγκη τὴν στρατιὰν ἡμῶν συμπεσοῦσαν κακοπαθεῖν; δότε δ’ ὅστις ἐμοὶ μαχεῖται τῶν ὑμετέρων, καὶ βραβευθήσεται τὰ τοῦ πολέμου ἑνὶ τῷ νενικηκότι· δουλεύσουσι γὰρ ἐκεῖνοι τοῖς ἑτέροις, ὧν ἂν ὁ νικήσας γένηται· πολὺ δὲ κρεῖττον εἶναι καὶ σωφρονέστατον ἑνὸς κινδύνῳ λαβεῖν ὃ βούλεσθε ἢ τῷ ἁπάντων. ταῦτ’ εἰπὼν ἀνεχώρησεν εἰς τὸ τῶν οἰκείων στρατόπεδον. τῇ δ’ ἐχομένῃ πάλιν ἐλθὼν τοὺς αὐτοὺς ἐποιήσατο λόγους, καὶ μέχρι τεσσαράκοντα ἡμερῶν οὐ διέλειπε προκαλούμενος ἐπὶ τοῖς προειρημένοις τοὺς πολεμίους, ὡς καταπλαγῆναι αὐτόν τε τὸν Σαοῦλον καὶ τὴν στρατιάν. καὶ παρετάσσοντο μὲν ὡς εἰς μάχην, οὐκ ἤρχοντο δὲ εἰς χεῖρας.", "st": "6.9.1"}, {"sp": "N", "t": "Τοῦ δὲ πολέμου συνεστηκότος τοῖς Ἑβραίοις καὶ τοῖς Παλαιστίνοις Σαοῦλος ἀπέλυσε τὸν Δαβίδην πρὸς τὸν πατέρα Ἰεσσαῖον ἀρκούμενος αὐτοῦ τοῖς τρισὶν υἱοῖς, οὓς ἐπὶ συμμαχίαν καὶ τοὺς κινδύνους ἔπεμψεν. ὁ δὲ τὸ μὲν πρῶτον ἐπὶ τὰ ποίμνια πάλιν καὶ τὰς νομὰς τῶν βοσκημάτων παραγίνεται, μετ’ οὐ πολὺ δὲ ἔρχεται εἰς τὸ στρατόπεδον τῶν Ἑβραίων πεμφθεὶς ὑπὸ τοῦ πατρὸς κομίσαι τε τοῖς ἀδελφοῖς ἐφόδια καὶ γνῶναι τί πράττουσι. τοῦ δὲ Γολιάθου πάλιν ἐλθόντος καὶ προκαλουμένου καὶ ὀνειδίζοντος, ὅτι μηδείς ἐστιν ἀνδρεῖος ἐν αὐτοῖς, ὃς εἰς μάχην αὐτῷ τολμᾷ καταβῆναι, μεταξὺ τοῖς ἀδελφοῖς ὁμιλῶν Δαβίδης περὶ ὧν ἐπέστειλεν ὁ πατὴρ ἀκούσας βλασφημοῦντος τὴν στρατιὰν καὶ κακίζοντος τοῦ Παλαιστίνου ἠγανάκτησε καὶ πρὸς τοὺς ἀδελφοὺς αὐτοῦ εἶπεν ἑτοίμως ἔχειν μονομαχῆσαι τῷ πολεμίῳ. πρὸς τοῦθ’ ὁ πρεσβύτατος τῶν ἀδελφῶν Ἰάναβος ἐπέπληξεν αὐτῷ τολμηρότερον παρ’ ἡλικίαν καὶ ἀμαθῆ τοῦ προσήκοντος εἰπών, ἐκέλευσέ τε πρὸς τὰ ποίμνια καὶ τὸν πατέρα βαδίζειν. καταιδεσθεὶς δὲ τὸν ἀδελφὸν ὑπεχώρησε καὶ πρός τινας τῶν στρατιωτῶν ἀπελάλησεν, ὅτι θέλοι μάχεσθαι τῷ προκαλουμένῳ. δηλωσάντων δ’ εὐθὺς τῷ Σαούλῳ τὴν τοῦ νεανίσκου προαίρεσιν μεταπέμπεται αὐτὸν ὁ βασιλεύς, καὶ πυθομένου τί βούλεται λέγειν μὴ ταπεινὸν ἔστω τὸ φρόνημα μηδ’ εὐλαβὲς, ὦ βασιλεῦ· καθαιρήσω γὰρ ἐγὼ τὴν ἀλαζονείαν τοῦ πολεμίου χωρήσας αὐτῷ διὰ μάχης καὶ τὸν ὑψηλὸν καὶ μέγαν ὑπ’ ἐμαυτῷ βαλών. γένοιτο μὲν ἂν αὐτὸς οὕτως καταγέλαστος, ἔνδοξον δὲ τὸ σὸν στράτευμα, εἰ μηδ’ ὑπ’ ἀνδρὸς πολεμεῖν ἤδη δυναμένου καὶ πιστευομένου παράταξιν καὶ μάχας, ἀλλ’ ὑπὸ παιδὸς ἔτι δοκοῦντος καὶ ταύτην ἔχοντος τὴν ἡλικίαν ἀποθάνοι.", "st": "6.9.2"}, {"sp": "N", "t": "Τοῦ δὲ Σαούλου τὸ μὲν τολμηρὸν αὐτοῦ καὶ τὴν εὐψυχίαν θαυμάζοντος, οὐ θαρροῦντος δὲ ἐπ’ αὐτῷ διὰ τὴν ἡλικίαν, ἀλλ’ ἀσθενέστερον εἶναι διὰ ταύτην πρὸς εἰδότα πολεμεῖν μάχεσθαι λέγοντος, ταῦτ’, εἶπε Δαβίδης, ἐπαγγέλλομαι τῷ θεῷ θαρρῶν ὄντι μετ’ ἐμοῦ· πεπείραμαι γὰρ αὐτοῦ τῆς βοηθείας. λέοντα γὰρ ἐπελθόντα μού ποτε τοῖς ποιμνίοις καὶ ἁρπάσαντα ἄρνα διώξας καταλαμβάνω καὶ τὸν μὲν ἄρνα τοῦ στόματος ἐξαρπάζω τοῦ θηρὸς, αὐτὸν δ’ ὁρμήσαντα ἐπ’ ἐμὲ τῆς οὐρᾶς βαστάσας καὶ προσρήξας τῇ γῇ διαφθείρω. ταὐτὸ δὲ καὶ ἄρκον ἀμυνόμενος διατίθεμαι. νομιζέσθω δὴ καὶ ὁ πολέμιος ἐκείνων εἶναι τῶν θηρίων ὀνειδίζων ἐκ πολλοῦ τὴν στρατιὰν καὶ βλασφημῶν ἡμῶν τὸν θεὸν, ὃς αὐτὸν ὑποχείριον ἐμοὶ θήσει.", "st": "6.9.3"}, {"sp": "N", "t": "Τῇ προθυμίᾳ τοιγαροῦν καὶ τῇ τόλμῃ τοῦ παιδὸς ὅμοιον γενέσθαι τέλος παρὰ τοῦ θεοῦ Σαοῦλος εὐξάμενος ἄπιθι, φησί πρὸς τὴν μάχην. καὶ περιθεὶς αὐτῷ τὸν αὑτοῦ θώρακα καὶ περιζώσας τὸ ξίφος καὶ περικεφαλαίαν ἁρμόσας ἐξέπεμψεν. ὁ δὲ Δαβίδης βαρυνόμενος ὑπὸ τῶν ὅπλων, οὐκ ἐγεγύμναστο γὰρ οὐδ’ ἐμεμαθήκει φέρειν ὅπλα, ταῦτα μέν, εἶπεν, ὦ βασιλεῦ, σὸς ἔστω κόσμος τοῦ βαστάζειν δυναμένου, συγχώρησον δὲ ὡς δούλῳ σου καὶ ὡς ἐγὼ βούλομαι μαχεσθῆναι. τίθησιν οὖν τὰ ὅπλα καὶ τὴν βακτηρίαν ἀράμενος καὶ πέντε λίθους ἐκ τοῦ χειμάρρου βαλὼν εἰς τὴν πήραν τὴν ποιμενικὴν καὶ σφενδόνην ἐν τῇ δεξιᾷ χειρὶ φέρων ἐπὶ τὸν Γολίαθον ἐπορεύετο. καταφρονεῖ δὲ οὕτως ἰδὼν αὐτὸν ὁ πολέμιος ἐρχόμενον καὶ προσέσκωψεν, ὡς οὐχ οἷα πρὸς ἄνθρωπον ὅπλα νενόμισται ταῦτ’ ἔχων μέλλοι μάχεσθαι, οἷς δὲ κύνας ἀπελαύνομεν καὶ φυλασσόμεθα. μὴ αὐτὸν ἀντὶ ἀνθρώπου κύνα εἶναι δοκεῖ; ὁ δ’ οὐχὶ τοιοῦτον ἀλλὰ καὶ χείρω κυνὸς αὐτὸν νομίζειν ἀπεκρίνατο. κινεῖ δὲ πρὸς ὀργὴν τὸν Γολίαθον, καὶ ἀρὰς αὐτῷ τίθεται ἐκ τῆς προσηγορίας τοῦ θεοῦ καὶ δώσειν ἠπείλησε τὰς σάρκας αὐτοῦ τοῖς ἐπιγείοις καὶ τοῖς μεταρσίοις διασπάσασθαι· ἀμείβεται δ’ αὐτὸν ὁ Δαβίδης· σὺ μὲν ἐπέρχῃ μοι ἐν ῥομφαίᾳ καὶ δόρατι καὶ θώρακι, ἐγὼ δὲ χωρῶν ἐπὶ σὲ τὸν θεὸν ὥπλισμαι, ὃς σέ τε καὶ πᾶσαν ὑμῶν στρατιὰν χερσὶ ταῖς ἡμετέραις διολέσει. καρατομήσω μὲν γάρ σε σήμερον καὶ τὸ ἄλλο σῶμα τοῖς ὁμοφύλοις κυσὶ παραβαλῶ, μαθήσονται δὲ πάντες, ὅτι προέστηκεν Ἑβραίων τὸ θεῖον καὶ ὅπλα ἡμῖν καὶ ἰσχὺς τοῦτ’ ἔστι κηδόμενον, ἡ δ’ ἄλλη παρασκευὴ καὶ δύναμις ἀνωφελὴς θεοῦ μὴ παρόντος. ὁ δὲ Παλαιστῖνος ὑπὸ βάρους τῶν ὅπλων εἰς ὠκύτητα καὶ δρόμον ἐμποδιζόμενος βάδην ἐπὶ τὸν Δαβίδην παραγίνεται καταφρονῶν καὶ πεποιθὼς γυμνὸν ὁμοῦ καὶ παῖδα ἔτι τὴν ἡλικίαν ἀπόνως ἀναιρήσειν.", "st": "6.9.4"}, {"sp": "N", "t": "Ἀπαντᾷ δὲ ὁ νεανίσκος μετὰ συμμάχου μὴ βλεπομένου τῷ πολεμίῳ· θεὸς δ’ ἦν οὗτος. καὶ ἀνελόμενος ἐκ τῆς πήρας ὧν εἰς αὐτὴν κατέθηκεν ἐκ τοῦ χειμάρρου λίθων ἕνα καὶ ἁρμόσας τῇ σφενδόνῃ βάλλει ἐπὶ τὸν Γολίαθον εἰς τὸ μέτωπον· καὶ διῆλθεν ἕως τοῦ ἐγκεφάλου τὸ βληθέν, ὡς εὐθὺς καρωθέντα πεσεῖν τὸν Γολίαθον ἐπὶ τὴν ὄψιν. δραμὼν δ’ ἐφίσταται τῷ πολεμίῳ κειμένῳ καὶ τῇ ῥομφαίᾳ τῇ ἐκείνου μάχαιραν οὐκ ἔχων αὐτὸς ἀποτέμνει τὴν κεφαλὴν αὐτοῦ. πεσὼν δ’ ὁ Γολίαθος ἧττα καὶ φυγὴ γίνεται Παλαιστίνοις· τὸν γὰρ δοκιμώτατον ἰδόντες ἐρριμμένον καὶ περὶ τῶν ὅλων δείσαντες οὐκέτι μένειν διέγνωσαν, ἀλλ’ αἰσχρᾷ καὶ ἀκόσμῳ φυγῇ παραδόντες ἑαυτοὺς ἐξαρπάζειν τῶν κινδύνων ἐπειρῶντο. Σαοῦλος δὲ καὶ πᾶς ὁ τῶν Ἑβραίων στρατὸς ἀλαλάξαντες ἐκπηδῶσιν εἰς αὐτοὺς καὶ πολλοὺς ἀποσφάττοντες διώκουσιν ἄχρι τῶν Γίττης ὁρίων καὶ τῶν πυλῶν τῶν Ἀσκάλωνος. καὶ θνήσκουσι μὲν τῶν Παλαιστίνων εἰς τρισμυρίους, δὶς δὲ τοσοῦτοι τραυματίαι γίνονται. Σαοῦλος δὲ ὑποστρέψας εἰς τὸ στρατόπεδον αὐτῶν διαρπάζει τὸ χαράκωμα καὶ ἐνέπρησε· τὴν κεφαλὴν δὲ Γολιάθου Δαβίδης εἰς τὴν ἰδίαν σκηνὴν ἐκόμισε καὶ τὴν ῥομφαίαν ἀνέθηκε τῷ θεῷ.", "st": "6.9.5"}, {"sp": "N", "t": "Φθόνον δὲ καὶ μῖσος τοῦ Σαούλου πρὸς αὐτὸν αἱ γυναῖκες ἐρεθίζουσιν· ὑπαντῶσαι γὰρ τῇ στρατιᾷ νικηφόρῳ μετὰ κυμβάλων καὶ τυμπάνων καὶ παντοίας χαρᾶς ᾖδον αἱ μὲν γυναῖκες, [ὡς] πολλὰς Σαοῦλος ἀπώλεσε Παλαιστίνων χιλιάδας, αἱ παρθένοι δὲ, ὡς μυριάδας Δαυίδης ἀφανίσειε. τούτων δὲ ἀκούων ὁ βασιλεύς, ὡς τὸ μὲν ἔλαττον τῆς μαρτυρίας αὐτὸς λάβοι, τὸ δὲ τῶν μυριάδων πλῆθος ἀνατεθείη τῷ νεανίσκῳ, καὶ λογισάμενος μηδὲν οὕτω μετὰ λαμπρὰν εὐφημίαν ἢ τὴν βασιλείαν ὑστερεῖν αὐτῷ φοβεῖσθαι καὶ ὑποπτεύειν ἤρξατο τὸν Δαυίδην. καὶ τῆς μὲν πρώτης τάξεως, ἐπεὶ τῷ δέει πλησίον αὐτοῦ καὶ λίαν ἐγγὺς ἐδόκει, ἐποίησε γὰρ αὐτὸν ὁπλοφόρον, μεταστήσας ἀποδείκνυσι χιλίαρχον δοὺς αὐτῷ χώραν ἀμείνονα μὲν ἀσφαλεστέραν δὲ ὡς ἐνόμιζεν αὑτῷ· ἐβούλετο γὰρ εἰς τοὺς πολεμίους αὐτὸν ἐκπέμπειν καὶ τὰς μάχας ὡς ἐν τοῖς κινδύνοις τεθνηξόμενον.", "st": "6.10.1"}, {"sp": "N", "t": "Δαυίδης δὲ πανταχοῦ τὸν θεὸν ἐπαγόμενος ὅποι ποτ’ ἀφίκοιτο κατώρθου καὶ διευπραγῶν ἐδείκνυτο, ὡς δι’ ὑπερβολὴν τῆς ἀνδρείας τόν τε λαὸν αὐτοῦ καὶ τὴν Σαούλου θυγατέρα παρθένον ἔτι οὖσαν λαβεῖν ἔρωτα καὶ τοῦ πάθους ὑπερκρατοῦντος γενέσθαι φανερὰν καὶ διαβληθῆναι πρὸς τὸν πατέρα. ὁ δ’ ὡς ἀφορμῇ χρησάμενος τῆς ἐπὶ Δαυίδην ἐπιβουλῆς ἡδέως ἤκουσε καὶ δώσειν προθύμως αὐτῷ τὴν παρθένον πρὸς τοὺς τὸν ἔρωτα μηνύσαντας αὐτῆς ἔφη γενησόμενον ἀπωλείας καὶ κινδύνων αἴτιον αὐτῷ ληψομένῳ· κατεγγυῶ γὰρ, εἶπεν, αὐτῷ τὸν τῆς θυγατρός μου γάμον, ἂν ἑξακοσίας μοι κομίσῃ κεφαλὰς τῶν πολεμίων. ὁ δὲ καὶ γέρως οὕτω λαμπροῦ προτεθέντος καὶ βουλόμενος ἐπ’ ἔργῳ παραβόλῳ καὶ ἀπίστῳ λαβεῖν κλέος ὁρμήσει μὲν ἐπὶ τὴν πρᾶξιν, διαφθαρήσεται δὲ ὑπὸ τῶν Παλαιστίνων καὶ χωρήσει μοι τὰ κατ’ αὐτὸν εὐπρεπῶς· ἀπαλλαγήσομαι γὰρ αὐτοῦ δι’ ἄλλων αὐτὸν ἀλλ’ οὐχὶ δι’ ἐμαυτοῦ κτείνας. διάπειραν δὴ τῆς τοῦ Δαυίδου διανοίας κελεύει τοὺς οἰκέτας λαμβάνειν, πῶς ἔχει πρὸς τὸ γῆμαι τὴν κόρην. οἱ δ’ ἤρξαντο διαλέγεσθαι πρὸς αὐτόν, ὅτι στέργει μὲν αὐτὸν ὁ βασιλεὺς Σαοῦλος καὶ ὁ λαὸς ἅπας, βούλεται δ’ αὐτῷ κηδεῦσαι τὴν θυγατέρα. ὁ δὲ μικρὸν ἄρ’ ὑμῖν, εἶπε, δοκεῖ γαμβρὸν γενέσθαι βασιλέως· ἐμοὶ δ’ οὐχὶ τοιοῦτον φαίνεται καὶ μάλιστα ὄντι ταπεινῷ καὶ δόξης καὶ τιμῆς ἀμοίρῳ. Σαοῦλος δὲ ἀγγειλάντων αὐτῷ τῶν οἰκετῶν τὰς τοῦ Δαυίδου ἀποκρίσεις οὐ χρημάτων, ἔφη, δεῖσθαί με φράζετε αὐτῷ οὐδὲ ἔδνων, ἀπεμπολᾶν γὰρ ἔστιν οὕτως τὴν θυγατέρα μᾶλλον ἢ συνοικίζειν, γαμβροῦ δὲ ἀνδρείαν ἔχοντος καὶ τὴν ἄλλην ἀρετὴν ἅπασαν, ἣν ὁρᾶν ὑπάρχουσαν αὐτῷ. βούλεσθαι δή με παρ’ αὐτοῦ λαβεῖν ἀντὶ τοῦ γάμου τῆς θυγατρὸς οὐ χρυσὸν οὐδ’ ἄργυρον οὐδ’ ὅπως ταῦτα ἐκ τῶν τοῦ πατρὸς οἰκιῶν κομίσῃ, Παλαιστίνων δὲ τιμωρίαν καὶ κεφαλὰς αὐτῶν ἑξακοσίας. αὐτῷ τε γὰρ ἐμοὶ τούτων οὐδὲν ἂν οὔτε ποθεινότερον οὔτε λαμπρότερον οὔτε προτιμότερον δῶρον γένοιτο, τῇ τε παιδί μου πολὺ τῶν νενομισμένων ἔδνων ζηλωτότερον τὸ συνοικεῖν ἀνδρὶ τοιούτῳ καὶ μαρτυρουμένῳ τὴν τῶν πολεμίων ἧτταν.", "st": "6.10.2"}, {"sp": "N", "t": "Κομισθέντων δὲ τούτων πρὸς τὸν Δαυίδην τῶν λόγων ἡσθεὶς τὸν Σαοῦλον ἐσπουδακέναι νομίζων αὐτοῦ περὶ τὴν συγγένειαν, οὐδὲ βουλεύσασθαι περιμείνας οὐδ’ εἰ δυνατὸν ἢ δύσκολόν ἐστι τὸ προκείμενον ἔργον τῷ λογισμῷ περινοήσας ὥρμησεν εὐθὺς μετὰ τῆς ἑταιρίας ἐπὶ τοὺς πολεμίους καὶ τὴν ὑπὲρ τοῦ γάμου κατηγγελμένην πρᾶξιν καί, θεὸς γὰρ ἦν ὁ πάντα ποιῶν εὐμαρῆ καὶ δυνατὰ τῷ Δαυΐδῃ, κτείνας πολλοὺς καὶ κεφαλὰς ἑξακοσίων ἀποτεμὼν ἧκε πρὸς τὸν βασιλέα διὰ τῆς τούτων ἐπιδείξεως τὸν ἀντὶ τούτων γάμον ἀπαιτῶν. Σαοῦλος δὲ οὐκ ἔχων ἀναφυγεῖν ἐκ τῶν ὑπεσχημένων, αἰσχρὸν γὰρ ὑπελάμβανεν ἢ ψεύσασθαι δοκεῖν ἢ δι’ ἐπιβουλὴν ἵν’ ὡς ἀδυνάτοις ἐπιχειρῶν ὁ Δαυίδης ἀποθάνῃ τὸν γάμον ἐπηγγέλθαι, δίδωσιν αὐτῷ τὴν θυγατέρα Μελχὰν ὀνόματι.", "st": "6.10.3"}, {"sp": "N", "t": "Ἔμελλε δὲ οὐκ ἐπὶ πολὺ τοῖς γεγενημένοις ἐμμένειν Σαοῦλος ἄρα· ὁρῶν γὰρ τὸν Δαυίδην παρὰ τῷ θεῷ καὶ παρὰ τοῖς ὄχλοις εὐδοκιμοῦντα κατέδεισε, καὶ τὸν φόβον οὐκ ἔχων ἀποκρύψασθαι περὶ μεγάλων ὄντα βασιλείας τε καὶ ζωῆς, ὧν καὶ θατέρου στερηθῆναι συμφορὰ δεινή, κτείνειν τὸν Δαυίδην διεγνώκει καὶ προστάσσει τὴν ἀναίρεσιν αὐτοῦ Ἰωνάθῃ τῷ παιδὶ καὶ τοῖς πιστοτάτοις τῶν οἰκετῶν. ὁ δὲ τὸν πατέρα τῆς ἐπὶ τῷ Δαυίδῃ μεταβολῆς θαυμάσας οὐκ ἐπὶ μετρίοις ἀπὸ τῆς πολλῆς εὐνοίας ἀλλ’ ἐπὶ θανάτῳ γενομένης, καὶ τὸν νεανίσκον ἀγαπῶν καὶ τὴν ἀρετὴν αὐτοῦ καταιδούμενος λέγει πρὸς αὐτὸν τὸ τοῦ πατρὸς ἀπόρρητον καὶ τὴν προαίρεσιν. συμβουλεύει μέντοι φυλάσσεσθαι γενόμενον ἐκποδὼν τὴν ἐπιοῦσαν ἡμέραν· αὐτὸς γὰρ ἀσπάσεσθαι τὸν πατέρα καὶ καιροῦ παραφανέντος αὐτῷ διαλεχθήσεσθαι περὶ αὐτοῦ καὶ τὴν αἰτίαν μαθήσεσθαι καὶ ταύτην ἐκφαυλίσειν, ὡς οὐ δεῖν ἐπ’ αὐτῇ κτείνειν τοσαῦτα μὲν ἀγαθὰ τὸ πλῆθος ἐργασάμενον εὐεργέτην δ’ αὐτοῦ γεγενημένον, δι’ ἃ καὶ συγγνώμην ἂν ἐπὶ τοῖς μεγίστοις ἁμαρτήμασιν εἰκότως εὕρατο. δηλώσω δέ σοι τὴν τοῦ πατρὸς γνώμην. Δαυίδης δὲ πεισθεὶς συμβουλίᾳ χρηστῇ ὑπεξίσταται τῆς τοῦ βασιλέως ὄψεως.", "st": "6.11.1"}, {"sp": "N", "t": "Τῇ δ’ ἐπιούσῃ πρὸς τὸν Σαοῦλον Ἰωνάθης ἐλθὼν ὡς ἱλαρόν τε καὶ χαίροντα κατέλαβεν ἤρξατο λόγους αὐτῷ περὶ τοῦ Δαυίδου προσφέρειν· τί καταγνοὺς αὐτοῦ μικρὸν ἢ μεῖζον ἀδίκημα, πάτερ, προσέταξας ἀνελεῖν ἄνδρα μέγα μὲν αὐτῷ πρὸς σωτηρίαν ὄφελος γεγενημένον, μεῖζον δὲ πρὸς τὴν Παλαιστίνων τιμωρίαν, ὕβρεως δὲ καὶ χλεύης ἀπαλλάξαντα τὸν Ἑβραίων λαὸν ἣν ἐπὶ τεσσαράκοντα ἡμέρας ὑπέμεινε μόνος τολμῶν ὑποστῆναι τὴν τοῦ πολεμίου πρόκλησιν, καὶ μετὰ ταῦτα κομίσαντα μὲν ὅσας ἐπετάχθη κεφαλὰς τῶν ἐχθρῶν, λαβόντα δ’ ἐπὶ τούτῳ γέρας τὴν ἐμὴν ἀδελφὴν πρὸς γάμον, ὡς ἂν ἀλγεινὸς αὐτοῦ γένοιθ’ ἡμῖν ὁ θάνατος οὐ διὰ τὴν ἀρετὴν μόνον, ἀλλὰ καὶ διὰ τὴν συγγένειαν· συναδικεῖται γὰρ αὐτοῦ τῷ θανάτῳ καὶ ἡ σὴ θυγάτηρ χηρείαν πρὶν ἢ τῆς συμβιώσεως εἰς ὄνησιν ἐλθεῖν μέλλουσα πειράζειν. ταῦτα λογισάμενος μεταβαλοῦ πρὸς τὸ ἡμερώτερον καὶ μηδὲν ποιήσῃς κακὸν ἄνδρα πρῶτον μὲν εὐεργεσίαν εὐεργετήσαντα μεγάλην τὴν σὴν σωτηρίαν, ὅτε σοι τοῦ πονηροῦ πνεύματος καὶ τῶν δαιμονίων ἐγκαθεζομένων τὰ μὲν ἐξέβαλεν, εἰρήνην δὲ ἀπ’ αὐτῶν τῇ ψυχῇ σου παρέσχεν, δεύτερον δὲ τὴν ἀπὸ τῶν πολεμίων ἐκδικίαν· αἰσχρὸν γὰρ τούτων ἐπιλελῆσθαι. τούτοις παρηγορεῖται τοῖς λόγοις Σαοῦλος καὶ μηδὲν ἀδικήσειν τὸν Δαυίδην ὄμνυσι τῷ παιδί· κρείττων γὰρ ὀργῆς καὶ φόβου δίκαιος λόγος. Ἰωνάθης δὲ μεταπεμψάμενος τὸν Δαυίδην σημαίνει τε αὐτῷ χρηστὰ καὶ σωτήρια τὰ παρὰ τοῦ πατρὸς ἄγει τε πρὸς αὐτόν, καὶ παρέμεινε τῷ βασιλεῖ Δαυίδης ὥσπερ ἔμπροσθεν.", "st": "6.11.2"}, {"sp": "N", "t": "Κατὰ δὲ τοῦτον τὸν καιρὸν τῶν Παλαιστίνων στρατευσαμένων πάλιν ἐπὶ τοὺς Ἑβραίους πέμπει μετὰ στρατιᾶς τὸν Δαυίδην πολεμήσοντα τοῖς Παλαιστίνοις, καὶ συμβαλὼν πολλοὺς αὐτῶν ἀπέκτεινε καὶ νικήσας ἐπάνεισι πρὸς τὸν βασιλέα. προσδέχεται δ’ αὐτὸν ὁ Σαοῦλος οὐχ ὡς ἤλπισεν ἀπὸ τοῦ κατορθώματος, ἀλλ’ ὑπὸ τῆς εὐπραγίας αὐτοῦ λυπηθεὶς ὡς ἐπισφαλέστερος αὐτὸς ἐκ τῶν ἐκείνου πράξεων γενόμενος. ἐπεὶ δὲ πάλιν αὐτὸν προσελθὸν τὸ δαιμόνιον ἐθορύβει πνεῦμα καὶ συνετάραττε, καλέσας εἰς τὸ δωμάτιον ἐν ᾧ κατέκειτο κατέχων τὸ δόρυ προσέταξε τῷ ψαλμῷ καὶ τοῖς ὕμνοις ἐξᾴδειν αὐτόν. ἐκείνου δὲ τὰ κελευσθέντα ποιοῦντος διατεινάμενος ἀκοντίζει τὸ δόρυ· καὶ τὸ μὲν προϊδόμενος ὁ Δαυίδης ἐξέκλινε, φεύγει δὲ εἰς τὸν οἶκον τὸν αὑτοῦ καὶ δι’ ὅλης ἔμεινεν ἡμέρας αὐτόθι.", "st": "6.11.3"}, {"sp": "N", "t": "Νυκτὸς δὲ πέμψας ὁ βασιλεὺς ἐκέλευσεν αὐτὸν ἄχρι τῆς ἕω φυλάττεσθαι μὴ καὶ λάθῃ παντελῶς ἀφανὴς γενόμενος, ἵνα παραγενόμενος εἰς τὸ δικαστήριον καὶ κρίσει παραδοὺς ἀποκτείνῃ. Μελχὰ δὲ ἡ γυνὴ Δαυίδου θυγάτηρ δὲ τοῦ βασιλέως τὴν τοῦ πατρὸς μαθοῦσα διάνοιαν τῷ ἀνδρὶ παρίσταται δειλὰς ἔχουσα τὰς περὶ αὐτοῦ ἐλπίδας καὶ περὶ τῆς ἰδίας ψυχῆς ἀγωνιῶσα· οὐδὲ γὰρ αὑτὴν ζῆν ὑπομενεῖν ἐκείνου στερηθεῖσαν. καί μή σε, φησίν, ὁ ἥλιος ἐνταυθοῖ καταλάβῃ· οὐ γὰρ ἔτ’ ὄψεταί σε. φεῦγε δ’ ἕως τοῦτό σοι δύναται παρασχεῖν ἡ παροῦσα νύξ· καὶ ποιήσει δέ σοι ταύτην ὁ θεὸς μακροτέραν· ἴσθι γὰρ σαυτὸν ἂν εὑρεθῇς ὑπὸ τοῦ πατρὸς ἀπολούμενον. καὶ καθιμήσασα διὰ θυρίδος αὐτὸν ἐξέσωσεν· ἔπειτα σκευάσασα τὴν κλίνην ὡς ἐπὶ νοσοῦντι καὶ ὑποθεῖσα τοῖς ἐπιβολαίοις ἧπαρ αἰγός, ἅμ’ ἡμέρᾳ τοῦ πατρὸς ὡς αὐτὴν πέμψαντος ἐπὶ τὸν Δαυίδην ὠχλῆσθαι διὰ τῆς νυκτὸς εἶπε τοῖς παροῦσιν ἐπιδείξασα τὴν κλίνην κατακεκαλυμμένην καὶ τῷ πηδήματι τοῦ ἥπατος σαλεύοντι τὴν ἐπιβολὴν πιστωσαμένη τὸ κατακείμενον τὸν Δαυίδην ἀσθμαίνειν. ἀπαγγειλάντων δὲ τῶν πεμφθέντων, ὅτι γένοιτο διὰ τῆς νυκτὸς ἀσθενέστερος, ἐκέλευσεν οὕτως ἔχοντα κομισθῆναι· βούλεσθαι γὰρ αὐτὸν ἀνελεῖν. ἐλθόντες δὲ καὶ ἀνακαλύψαντες τὴν κλίνην καὶ τὸ σόφισμα τῆς γυναικὸς εὑρόντες ἀπήγγειλαν τῷ βασιλεῖ. μεμφομένου δὲ τοῦ πατρὸς αὐτήν, ὅτι σώσειε μὲν τὸν ἐχθρὸν αὐτοῦ κατασοφίσαιτο δ’ αὐτόν, ἀπολογίαν σκήπτεται πιθανήν· ἀπειλήσαντα γὰρ αὐτὴν ἀποκτείνειν ἔφησε τυχεῖν ἐκ τοῦ δέους τῆς πρὸς τὸ σωθῆναι συνεργίας· ὑπὲρ ἧς συγγνῶναι καλῶς ἔχειν αὐτῇ κατ’ ἀνάγκην ἀλλὰ μὴ κατὰ προαίρεσιν γενομένης· οὐ γὰρ οὕτως, ἔλεγεν, οἶμαι τὸν ἐχθρὸν ἐζήτεις ἀποθανεῖν, ὡς ἐμὲ σώζεσθαι. καὶ συγγινώσκει δὲ τῇ κόρῃ Σαοῦλος. ὁ δὲ Δαυίδης ἐκφυγὼν τὸν κίνδυνον ἧκε πρὸς τὸν προφήτην Σαμουῆλον εἰς Ἀραμαθὰ καὶ τὴν ἐπιβουλὴν αὐτῷ τὴν τοῦ βασιλέως ἐδήλωσε καὶ ὡς παρὰ μικρὸν ὑπ’ αὐτοῦ τῷ δόρατι βληθεὶς ἀποθάνοι, μήτ’ ἐν τοῖς πρὸς αὐτὸν κακὸς γενόμενος μήτ’ ἐν τοῖς πρὸς τοὺς πολεμίους ἀγῶσιν ἄνανδρος, ἀλλ’ ἐν ἅπασι μετὰ [τοῦ] θυμοῦ καὶ ἐπιτυχής. τοῦτο δ’ ἦν αἴτιον Σαούλῳ τῆς πρὸς Δαυίδην ἀπεχθείας.", "st": "6.11.4"}, {"sp": "N", "t": "Μαθὼν δ’ ὁ προφήτης τὴν τοῦ βασιλέως ἀδικίαν καταλείπει μὲν τὴν πόλιν Ἀραμαθάν, ἀγαγὼν δὲ τὸν Δαυίδην ἐπί τινα τόπον Γαλβουὰθ ὄνομα ἐκεῖ διέτριβε σὺν αὐτῷ. ὡς δ’ ἀπηγγέλη τῷ Σαούλῳ παρὰ τῷ προφήτῃ τυγχάνων ὁ Δαυίδης πέμψας ὁπλίτας πρὸς αὑτὸν ἄγειν προσέταξε συλλαμβάνοντας. οἱ δ’ ἐλθόντες πρὸς τὸν Σαμουῆλον καὶ καταλαβόντες προφητῶν ἐκκλησίαν τοῦ θείου μεταλαμβάνουσι πνεύματος καὶ προφητεύειν ἤρξαντο· Σαοῦλος δ’ ἀκούσας ἄλλους ἔπεμψεν ἐπὶ τὸν Δαυίδην· κἀκείνων ταὐτὸ τοῖς πρώτοις παθόντων πάλιν ἀπέστειλεν ἑτέρους· προφητευόντων δὲ καὶ τῶν τρίτων τελευταῖον ὀργισθεὶς αὐτὸς ἐξώρμησεν. ἐπεὶ δ’ ἐγγὺς ἦν ἤδη, Σαμουῆλος πρὶν ἰδεῖν αὐτὸν προφητεύειν ἐποίησεν. ἐλθὼν δὲ πρὸς αὐτὸν Σαοῦλος ὑπὸ τοῦ πολλοῦ πνεύματος ἐλαυνόμενος ἔκφρων γίνεται καὶ τὴν ἐσθῆτα περιδύσας ἑαυτὸν καταπεσὼν ἔκειτο δι’ ὅλης ἡμέρας τε καὶ νυκτὸς Σαμουήλου τε καὶ Δαυίδου βλεπόντων.", "st": "6.11.5"}, {"sp": "N", "t": "Ἰωνάθης δὲ ὁ Σαούλου παῖς ἀφικομένου πρὸς αὐτὸν ἐκεῖθεν Δαυίδου καὶ περὶ τῆς τοῦ πατρὸς ἀποδυρομένου ἐπιβουλῆς καὶ λέγοντος, ὡς οὐδὲν ἀδικήσας οὔτ’ ἐξαμαρτὼν σπουδάζοιτο ὑπὸ τοῦ πατρὸς αὐτοῦ φονευθῆναι, μήθ’ ἑαυτῷ τοῦθ’ ὑπονοοῦντι πιστεύειν παρεκάλει μήτε τοῖς διαβάλλουσιν, εἴ τινες ἄρα εἰσὶν οἱ τοῦτο πράττοντες, ἀλλ’ αὐτῷ προσέχειν καὶ θαρρεῖν· μηδὲν γὰρ τοιοῦτον ἐπ’ αὐτῷ φρονεῖν τὸν πατέρα· φράσαι γὰρ ἂν αὐτῷ περὶ τούτου καὶ σύμβουλον παραλαβεῖν τῇ κοινῇ γνώμῃ καὶ τἆλλα πράττοντα. ὁ δὲ Δαυίδης ὤμνυεν ἦ μὴν οὕτως ἔχειν, καὶ πιστεύοντ’ ἠξίου προνοεῖν αὐτοῦ μᾶλλον ἢ καταφρονοῦντ’ ἐπ’ ἀληθέσι τοῖς λόγοις τότε ἀληθὲς ὑπολαβεῖν, ὅταν ἢ θεάσηται [πεφονευμένον αὐτὸν] ἢ πύθηται· μηδὲν λέγειν δ’ αὐτῷ τὸν πατέρα περὶ τούτων ἔφασκεν εἰδότα τὴν πρὸς αὐτὸν φιλίαν καὶ διάθεσιν.", "st": "6.11.6"}, {"sp": "N", "t": "Λυπηθεὶς δ’ ἐφ’ ὅτῳ πιστωσάμενος τὴν τοῦ Σαούλου προαίρεσιν Ἰωνάθης οὐκ ἔπεισεν ἐπηρώτα, τίνος ἐξ αὐτοῦ βούλεται τυχεῖν. ὁ δέ οἶδα γάρ, ἔφη, πάντα σε χαρίζεσθαί μοι καὶ παρέχειν ἐθέλοντα· νουμηνία μὲν εἰς τὴν ἐπιοῦσάν ἐστιν, ἔθος δ’ ἔχω δειπνεῖν σὺν τῷ βασιλεῖ καθήμενος· εἰ δή σοι δοκεῖ πορευθεὶς ἔξω τῆς πόλεως ἐν τῷ πεδίῳ λανθάνων διαμενῶ, σὺ δ’ ἐπιζητήσαντος αὐτοῦ λέγε πορευθῆναί με εἰς τὴν πατρίδα Βηθλέεμ’ ἑορτήν μου τῆς φυλῆς ἀγούσης προστιθεὶς ὅτι σύ μοι συγκεχώρηκας. κἂν μὲν οἷον εἰκὸς καὶ σύνηθές ἐστι λέγειν ἐπὶ φίλοις ἀποδημοῦσιν ἐπ’ ἀγαθῷ βεβάδικεν εἴπῃ, ἴσθι μηδὲν ὕπουλον παρ’ αὐτοῦ εἶναι μηδ’ ἐχθρόν· ἂν δ’ ὡς ἄλλως ἀποκρίνηται τοῦτ’ ἔσται τεκμήριον τῶν κατ’ ἐμοῦ βεβουλευμένων. μηνύσεις δέ μοι τὴν διάνοιαν τὴν τοῦ πατρὸς οἴκτῳ τε νέμων τοῦτο καὶ φιλίᾳ, δι’ ἣν πίστεις τε παρ’ ἐμοῦ λαβεῖν ἠξίωκας αὐτός τε ἐμοὶ δοῦναι δεσπότης ὤν. εἰ δ’ εὑρίσκεις τι ἐν ἐμοὶ πονηρόν, αὐτὸς ἄνελε καὶ φθάσον τὸν πατέρα.", "st": "6.11.7"}, {"sp": "N", "t": "Πρὸς δὲ τὸ τελευταῖον δυσχεράνας τῶν λόγων Ἰωνάθης ποιήσειν ταῦτ’ ἐπηγγείλατο κἄν τι σκυθρωπὸν ὁ πατὴρ αὐτοῦ καὶ τὴν ἀπέχθειαν ἐμφανίζον ἀποκρίνηται μηνύσειν. ἵνα δ’ αὐτῷ θαρρῇ μᾶλλον, ἐξαγαγὼν αὐτὸν εἰς ὕπαιθρον καὶ καθαρὸν ἀέρα οὐδὲν παρήσειν ὑπὲρ τῆς Δαυίδου σωτηρίας ὤμνυε· τὸν γὰρ θεόν, εἶπε, τοῦτον ὃν πολὺν ὁρᾷς καὶ πανταχοῦ κεχυμένον, καὶ πρὶν ἑρμηνεῦσαί με τοῖς λόγοις τὴν διάνοιαν ἤδη μου ταύτην εἰδότα, μάρτυρα ποιοῦμαι τῶν πρὸς σὲ συνθηκῶν, ὡς οὐκ ἀνήσω τὸν πατέρα πολλάκις αὐτοῦ τῆς προαιρέσεως διάπειραν λαμβάνων, πρὶν ἢ καταμαθεῖν ἥτις ἐστὶ καὶ παρὰ τοῖς ἀπορρήτοις αὐτοῦ τῆς ψυχῆς γενέσθαι. καταμαθὼν δ’ οὐκ ἀποκρύψομαι, καταμηνύσω δὲ πρὸς σὲ καὶ πρᾷον ὄντα καὶ δυσμενῶς διακείμενον. οἶδε δὲ οὗτος ὁ θεός, πῶς αὐτὸν εἶναι μετὰ σοῦ διὰ παντὸς εὔχομαι· ἔστι μὲν γὰρ νῦν καὶ οὐκ ἀπολείψει σε, ποιήσει δέ σε τῶν ἐχθρῶν ἄντε ὁ πατὴρ ὁ ἐμὸς ᾖ ἄντ’ ἐγὼ κρείττονα. σὺ μόνον μνημόνευε τούτων, κἂν ἀποθανεῖν μοι γένηται τὰ τέκνα μου σῶζε, καὶ τὴν ὑπὲρ τῶν παρόντων μοι ἀμοιβὴν εἰς ἐκεῖνα κατάθου. ταῦτ’ ἐπομόσας ἀπολύει τὸν Δαυίδην εἴς τινα τόπον ἀπελθεῖν τοῦ πεδίου φράσας, ἐν ᾧ γυμναζόμενος διατελεῖ· γνοὺς γὰρ τὰ παρὰ τοῦ πατρὸς ἥξειν πρὸς αὐτὸν ἔφησεν ἐκεῖ μόνον ἐπαγόμενος παῖδα. καὶ τρία ἀκόντια δὲ βαλὼν ἐπὶ τὸν σκοπὸν κομίσαι τῷ παιδὶ προστάσσω τὰ ἀκόντια· κεῖσθαι γὰρ ἔμπροσθεν αὐτοῦ. καὶ ἂν ταῦτα, φησίν, ἀκούσῃς γίνωσκε μηδὲν εἶναι φαῦλον παρὰ τοῦ πατρός· ἂν δὲ τὰ ἐναντία τούτων ἀκούσῃς μου λέγοντος, καὶ τὰ ἐναντία παρὰ τοῦ βασιλέως προσδόκα. τῆς μέντοι γε ἀσφαλείας τεύξῃ παρ’ ἐμοῦ καὶ οὐδὲν μὴ πάθῃς ἄτοπον· ὅπως δὲ μνησθῇς τούτων παρὰ τὸν τῆς εὐπραγίας καιρὸν σκόπει καὶ τοῖς υἱοῖς μου γενοῦ χρήσιμος. Δαυίδης μὲν οὖν ταύτας λαβὼν παρὰ Ἰωνάθου τὰς πίστεις εἰς τὸ συγκείμενον ἀπηλλάγη χωρίον.", "st": "6.11.8"}, {"sp": "N", "t": "Τῇ δ’ ἐχομένῃ, νεομηνία δ’ ἦν, ἁγνεύσας ὡς ἔθος εἶχεν ὁ βασιλεὺς ἧκεν ἐπὶ τὸ δεῖπνον, καὶ παρακαθεσθέντων αὐτῷ τοῦ μὲν παιδὸς Ἰωνάθου ἐκ δεξιῶν Ἀβενήρου δὲ τοῦ ἀρχιστρατήγου ἐκ τῶν ἑτέρων, ἰδὼν τὴν τοῦ Δαβίδου καθέδραν κενὴν ἡσύχασεν ὑπονοήσας οὐ καθαρεύσαντα αὐτὸν ἀπὸ συνουσίας ὑστερεῖν. ὡς δὲ καὶ τῇ δευτέρᾳ τῆς νουμηνίας οὐ παρῆν ἐπυνθάνετο παρὰ τοῦ παιδὸς Ἰωνάθου, ὅτι καὶ τῇ παρελθούσῃ καὶ ταύτῃ τοῦ δείπνου καὶ τῆς ἑστιάσεως ὁ τοῦ Ἰεσσαίου παῖς ἀπολέλειπται. ὁ δὲ πεπορεῦσθαι κατὰ τὰς συνθήκας ἔφησεν αὐτὸν εἰς τὴν ἑαυτοῦ πατρίδα τῆς φυλῆς ἑορτὴν ἀγούσης ἐπιτρέψαντος αὐτοῦ· παρακαλέσαι μέντοι καὶ αὐτὸν ἐλθεῖν ἐπὶ τὴν θυσίαν καὶ εἰ συγχωρηθείη φησὶν ἀπέρχεσθαι· τὴν γὰρ εὔνοιάν μου τὴν πρὸς αὐτὸν ἐπίστασαι. τότε τὴν πρὸς Δαυίδην τοῦ πατρὸς Ἰωνάθης ἐπέγνω δυσμένειαν καὶ τρανῶς τὴν ὅλην αὐτοῦ βούλησιν εἶδεν· οὐ γὰρ κατέσχε Σαοῦλος τῆς ὀργῆς, ἀλλὰ βλασφημῶν ἐξ αὐτομόλων γεγενημένον καὶ πολέμιον ἀπεκάλει καὶ κοινωνὸν τοῦ Δαυίδου καὶ συνεργὸν ἔλεγεν καὶ μήτ’ αὐτὸν αἰδεῖσθαι μήτε τὴν μητέρα αὐτοῦ ταῦτα φρονοῦντα καὶ μηδὲ βουλόμενον πεισθῆναι τοῦθ’, ὅτι μέχρις οὗ περίεστι Δαυίδης ἐπισφαλῶς αὐτοῖς τὰ τῆς βασιλείας ἔχει. μετάπεμψαι τοιγαροῦν αὐτόν, ἔφησεν, ἵνα δῷ δίκην. ὑποτυχόντος δ’ Ἰωνάθου, τί δ’ ἀδικοῦντα κολάσαι θέλεις; οὐκέτ’ εἰς λόγους καὶ βλασφημίας τὴν ὀργὴν ὁ Σαοῦλος ἐξήνεγκεν, ἀλλὰ ἁρπάσας τὸ δόρυ ἀνεπήδησεν ἐπ’ αὐτὸν ἀποκτεῖναι θέλων. καὶ τὸ μὲν ἔργον οὐκ ἔδρασε διακωλυθεὶς ὑπὸ τῶν φίλων, φανερὸς δ’ ἐγένετο τῷ παιδὶ μισῶν τὸν Δαυίδην καὶ διαχρήσασθαι ποθῶν, ὡς παρὰ μικρὸν δι’ ἐκεῖνον αὐτόχειρ καὶ τοῦ παιδὸς γεγονέναι.", "st": "6.11.9"}, {"sp": "N", "t": "Καὶ τότε μὲν ὁ τοῦ βασιλέως παῖς ἐκπηδήσας [ἀπὸ] τοῦ δείπνου καὶ μηδὲν ὑπὸ λύπης προσενέγκασθαι δυνηθείς, κλαίων αὑτὸν μὲν τοῦ παρὰ μικρὸν ἀπολέσθαι τοῦ κατακεκρίσθαι δ’ ἀποθανεῖν Δαυίδην διενυκτέρευσεν. ἅμα δὲ ἡμέρᾳ πρὸ τῆς πόλεως εἰς τὸ πεδίον ὡς γυμνασόμενος μὲν δηλώσων δὲ τῷ φίλῳ τὴν τοῦ πατρὸς διάθεσιν, ὡς συνέθετο, πρόεισι. ποιήσας δὲ ὁ Ἰωνάθης τὰ συγκείμενα τὸν μὲν ἑπόμενον ἀπολύει εἰς τὴν πόλιν παῖδα, ἦν δ’ ἠρεμία τῷ Δαυίδῃ παρελθεῖν εἰς ὄψιν αὐτῷ καὶ λόγους. ἀναφανεὶς δ’ οὗτος πίπτει πρὸ τῶν Ἰωνάθου ποδῶν καὶ προσκυνῶν σωτῆρα αὐτοῦ τῆς ψυχῆς ἀπεκάλει. ἀνίστησι δ’ ἀπὸ τῆς γῆς αὐτόν, καὶ περιπλακέντες ἀλλήλους μακρά τε ἠσπάζοντο καὶ δεδακρυμένα τήν τε ἡλικίαν ἀποθρηνοῦντες αὑτῶν καὶ τὴν ἐφθονημένην ἑταιρίαν καὶ τὸν μέλλοντα διαχωρισμόν, ὃς οὐδὲν αὐτοῖς ἐδόκει θανάτου διαφέρειν. μόλις δ’ ἐκ τῶν θρήνων ἀνανήψαντες καὶ μεμνῆσθαι τῶν ὅρκων ἀλλήλοις παρακελευσάμενοι διελύθησαν.", "st": "6.11.10"}, {"sp": "N", "t": "Δαυίδης δὲ φεύγων τὸν βασιλέα καὶ τὸν ἐξ αὐτοῦ θάνατον εἰς Ναβὰν παραγίνεται πόλιν πρὸς Ἀβιμέλεχον τὸν ἀρχιερέα, ὃς ἐπὶ τῷ μόνον ἥκοντα ἰδεῖν καὶ μήτε φίλον σὺν αὐτῷ μήτ’ οἰκέτην παρόντα ἐθαύμασε καὶ τὴν αἰτίαν τοῦ μηδένα εἶναι σὺν αὐτῷ μαθεῖν ἤθελεν. ὁ δὲ πρᾶξιν ἀπόρρητον ἐπιταγῆναι παρὰ τοῦ βασιλέως ἔφησεν, εἰς ἣν συνοδίας αὐτῷ βουλομένῳ λαθεῖν οὐκ ἔδει· τοὺς μέντοι θεράποντας εἰς τόνδε μοι τὸν τόπον ἀπαντᾶν προσέταξα. ἠξίου δὲ λαβεῖν ἐφόδια· φίλου γὰρ αὐτὸν ποιήσειν ἔργον παρασχόντα καὶ πρὸς τὸ προκείμενον συλλαμβανομένου. τυχὼν δὲ τούτων ᾔτει καὶ ὅπλον τι μετὰ χεῖρας ῥομφαίαν ἢ δοράτιον· παρῆν δὲ καὶ Σαούλου δοῦλος γένει μὲν Σύρος Δώηγος δὲ ὄνομα τὰς τοῦ βασιλέως ἡμιόνους νέμων· ὁ δ’ ἀρχιερεὺς ἔχειν μὲν αὐτὸς οὐδέν τι εἶπε τοιοῦτον, εἶναι δὲ τὴν Γολιάθου ῥομφαίαν, ἣν ἀποκτείνας τὸν Παλαιστῖνον αὐτὸς ἀναθείη τῷ θεῷ.", "st": "6.12.1"}, {"sp": "N", "t": "λαβὼν δὲ ταύτην ὁ Δαβίδης ἔξω τῆς τῶν Ἑβραίων χώρας εἰς Γίτταν διέφυγε τὴν Παλαιστίνων, ἧς Ἄγχους ἐβασίλευεν. ἐπιγνωσθεὶς δὲ ὑπὸ τῶν τοῦ βασιλέως οἰκετῶν καὶ φανερὸς αὐτῷ γενόμενος μηνυόντων ἐκείνων, ὅτι Δαυίδης ὁ πολλὰς ἀποκτείνας Παλαιστίνων μυριάδας εἴη, δείσας μὴ πρὸς αὐτοῦ θάνῃ καὶ τὸν κίνδυνον ὃν ἐξέφυγε παρὰ Σαούλου παρ’ ἐκείνου πειράσῃ προσποιεῖται μανίαν καὶ λύσσαν, ὡς ἀφρὸν κατὰ τοῦ στόματος αὐτοῦ φερόμενον καὶ τὰ ἄλλα ὅσα συνίστησι μανίαν πίστιν παρὰ τῷ Γίττης βασιλεῖ γενέσθαι τῆς νόσου. καὶ τοῖς οἰκέταις ὁ βασιλεὺς προσδυσχεράνας ὡς ἔκφρονα πρὸς αὐτὸν ἀγάγοιεν ἄνθρωπον ἐκέλευσε τὸν Δαυίδην ὡς τάχος ἐκβάλλειν.", "st": "6.12.2"}, {"sp": "N", "t": "Διασωθεὶς δὲ οὗτος ἐκ τῆς Γίττης εἰς τὴν Ἰούδα παραγίνεται φυλὴν καὶ ἐν τῷ πρὸς Ἀδολλάμῃ πόλει σπηλαίῳ διατρίβων πέμπει πρὸς τοὺς ἀδελφοὺς δηλῶν αὐτοῖς ἔνθα εἴη. οἱ δὲ μετὰ πάσης συγγενείας ἧκον πρὸς αὐτόν· καὶ τῶν ἄλλων δὲ ὅσοις ἢ χρεία ἦν ἢ φόβος ἐκ Σαούλου τοῦ βασιλέως συνερρύησαν πρὸς αὐτὸν καὶ ποιεῖν τὰ ἐκείνῳ δοκοῦντα ἑτοίμως ἔχειν ἔλεγον. ἐγένοντο δὲ οἱ πάντες ὡσεὶ τετρακόσιοι. θαρρήσας δὲ ὡς καὶ χειρὸς αὐτῷ καὶ συνεργίας ἤδη γεγενημένης ἀπάρας ἐκεῖθεν ἀφικνεῖται πρὸς τὸν τῶν Μωαβιτῶν βασιλέα, καὶ τοὺς γονεῖς αὐτοῦ εἰς τὴν ἑαυτοῦ χώραν προσδεξάμενον ἕως οὗ ἐπὶ τὸ καθ’ αὑτὸν τέλος ἔχειν παρεκάλει· κατανεύσαντος δ’ αὐτοῦ τὴν χάριν καὶ πάσης τοὺς γονεῖς τοῦ Δαυίδου τιμὴς παρ’ ὃν ἐτύγχανον παρ’ αὐτῷ χρόνον", "st": "6.12.3"}, {"sp": "N", "t": "ἀξιώσαντος αὐτὸς τοῦ προφήτου κελεύσαντος αὐτὸν τὴν μὲν ἐρημίαν ἐκλιπεῖν, πορευθέντα δ’ εἰς τὴν κληρουχίαν τῆς Ἰούδα φυλῆς ἐν αὐτῇ διάγειν πείθεται καὶ παραγενόμενος εἰς Σάριν πόλιν ἐν αὐτῇ κατέμενε. Σαοῦλος δ’ ἀκούσας ὅτι μετὰ πλήθους ὀφθείη ὁ Δαυίδης οὐκ εἰς τυχόντα θόρυβον καὶ ταραχὴν ἐνέπεσεν, ἀλλ’ εἰδὼς τὸ φρόνημα τοῦ ἀνδρὸς καὶ τὴν εὐτολμίαν οὐδὲν ἐξ αὐτοῦ μικρὸν ἀνακύψειν ἔργον ἐφ’ οὗ κλαύσεσθαι πάντως καὶ πονήσειν ὑπενόησε. καὶ συγκαλέσας τοὺς φίλους καὶ τοὺς ἡγεμόνας καὶ τὴν φυλὴν ἐξ ἧς αὐτὸς ἦν πρὸς αὑτὸν ἐπὶ τὸν βουνὸν οὗ τὸ βασίλειον εἶχε, καὶ καθίσας ἐπ’ Ἀρούρης, τόπος ἦν τις τιμῆς, πολιτικῆς περὶ αὐτὸν οὔσης τάξεως σωματοφυλάκων λέγει πρὸς αὐτούς· ἄνδρες ὁμόφυλοι, μέμνησθε μὲν οἶδ’ ὅτι τῶν ἐμῶν εὐεργεσιῶν, ὅτι καὶ ἀγρῶν τινας ἐποίησα δεσπότας καὶ τιμῶν τῶν ἐν τῷ πλήθει καὶ τάξεων ἠξίωσα. πυνθάνομαι τοιγαροῦν, εἰ μείζονας τούτων δωρεὰς καὶ πλείονας παρὰ τοῦ Ἰεσσαίου παιδὸς προσδοκᾶτε· οἶδα γὰρ ὅτι πάντες ἐκείνῳ προστέθεισθε τοὐμοῦ παιδὸς Ἰωνάθου αὐτοῦ τε οὕτως φρονήσαντος καὶ ὑμᾶς ταῦτα πείσαντος· οὐ γὰρ ἀγνοῶ τοὺς ὅρκους καὶ τὰς συνθήκας τὰς πρὸς Δαυίδην αὐτῷ γεγενημένας, οὐδ’ ὅτι σύμβουλος μὲν καὶ συνεργὸς Ἰωνάθης ἐστὶ τῶν κατ’ ἐμοῦ συντεταγμένων, μέλει δὲ ὑμῶν οὐδενὶ περὶ τούτων, ἀλλὰ τὸ ἀποβησόμενον ἡσυχάζοντες σκοπεῖτε. σιωπήσαντος δὲ τοῦ βασιλέως ἄλλος μὲν οὐδεὶς ἀπεκρίνατο τῶν παρόντων, Δώηγος δ’ ὁ Σύρος ὁ τὰς ἡμιόνους αὐτοῦ βόσκων εἶπεν, ὡς ἴδοι τὸν Δαυίδην εἰς Ναβὰν πόλιν πρὸς Ἀβιμέλεχον ἐλθόντα τὸν ἀρχιερέα τά τε μέλλοντα παρ’ αὐτοῦ προφητεύσαντος μαθεῖν καὶ λαβόντα ἐφόδια καὶ τὴν ῥομφαίαν τοῦ Γολιάθου πρὸς οὓς ἐβούλετο μετὰ ἀσφαλείας προπεμφθῆναι.", "st": "6.12.4"}, {"sp": "N", "t": "Μεταπεμψάμενος οὖν τὸν ἀρχιερέα καὶ πᾶσαν αὐτοῦ τὴν γενεὰν Σαοῦλος τί παθὼν ἐξ ἐμοῦ, εἶπε, δεινὸν καὶ ἄχαρι τὸν Ἰεσσαίου παῖδα προσεδέξω καὶ σιτίων μὲν αὐτῷ μετέδωκας καὶ ὅπλων ὄντι τῆς ἐμῆς βασιλείας ἐπιβούλῳ, τί δὲ δὴ περὶ τῶν μελλόντων ἐχρημάτιζες; οὐ γὰρ δή σε φεύγων ἐμὲ καὶ μισῶν τὸν ἐμὸν οἶκον ἐλάνθανεν. ὁ δ’ ἀρχιερεὺς οὐκ ἐπ’ ἄρνησιν ἐτράπη τῶν γεγονότων, ἀλλὰ μετὰ παρρησίας ταῦτα παρασχεῖν ὡμολόγει οὐχὶ Δαυίδῃ χαριζόμενος, ἀλλ’ αὐτῷ· πολέμιον γὰρ σὸν οὐκ εἰδέναι ἔφασκε, πιστὸν δὲ ἐν τοῖς μάλιστα δοῦλον καὶ χιλίαρχον καὶ τὸ τούτων μεῖζον γαμβρόν τε ἤδη καὶ συγγενῆ. ταῦτα δ’ οὐκ ἐχθροῖς παρέχειν τοὺς ἀνθρώπους, ἀλλὰ τοῖς εὐνοίᾳ καὶ τιμῇ τῇ πρὸς αὐτοὺς ἀρίστοις. προφητεῦσαι δὲ οὐ νῦν πρῶτον αὐτῷ, πολλάκις δὲ καὶ ἄλλοτε τοῦτο πεποιηκέναι· φήσαντι δὲ ὑπὸ σοῦ πεμφθῆναι κατὰ πολλὴν σπουδὴν ἐπὶ πρᾶξιν τῷ μηδὲν παρασχεῖν ὧν ἐπεζήτει σοὶ μᾶλλον ἀντιλέγειν ἢ ἐκείνῳ περὶ αὐτῶν ἐλογιζόμην. διὸ μηδὲν πονηρὸν κατ’ ἐμοῦ φρονήσῃς μηδὲ πρὸς ἃ νῦν ἀκούεις Δαυίδην ἐγχειρεῖν πρὸς ταῦτα τὴν τότε μου δοκοῦσαν φιλανθρωπίαν ὑποπτεύσῃς· φίλῳ γὰρ καὶ γαμβρῷ σῷ καὶ χιλιάρχῳ παρέσχον, οὐ πολεμίῳ.", "st": "6.12.5"}, {"sp": "N", "t": "Ταῦτα λέγων ὁ ἀρχιερεὺς οὐκ ἔπεισε τὸν Σαοῦλον· δεινὸς γὰρ ὁ φόβος μηδ’ ἀληθεῖ πιστεύειν ἀπολογίᾳ· κελεύει δὲ τοῖς ὁπλίταις περιστᾶσιν αὐτὸν ἀποκτεῖναι. μὴ θαρρούντων δ’ ἐκείνων ἅψασθαι τοῦ ἀρχιερέως, ἀλλὰ τὸ θεῖον εὐλαβουμένων μᾶλλον ἢ τὸ παρακοῦσαι τοῦ βασιλέως, τῷ Σύρῳ Δωήγῳ προστάσσει τὸν φόνον. καὶ παραλαβὼν ὁμοίους αὑτῷ πονηροὺς ἐκεῖνος ἀποκτείνει τὸν Ἀβιμέλεχον καὶ τὴν γενεὰν αὐτοῦ· ἦσαν δὲ πάντες ὡσεὶ πέντε καὶ τριακόσιοι. πέμψας δὲ Σαοῦλος καὶ εἰς τὴν πόλιν τῶν ἱερέων Ναβὰν πάντας τε αὐτοὺς ἀπέκτεινεν οὐ γυναικῶν οὐ νηπίων οὐδ’ ἄλλης ἡλικίας φεισάμενος, αὐτὴν δὲ ἐνέπρησε. διασώζεται δὲ παῖς [εἷς] Ἀβιμελέχου Ἀβιάθαρος ὄνομα. ταῦτα μέντοι συνέβη, καθὼς προεφήτευσεν ὁ θεὸς τῷ ἀρχιερεῖ Ἠλὶ διὰ τὰς τῶν υἱῶν αὐτοῦ δύο παρανομίας εἰπὼν διαφθαρήσεσθαι τοὺς ἐγγόνους.", "st": "6.12.6"}, {"sp": "N", "t": "Σαοῦλος δὲ ὁ βασιλεὺς ὠμὸν οὕτως ἔργον διαπραξάμενος καὶ γενεὰν ὅλην ἀρχιερατικῆς ἀποσφάξας τιμῆς καὶ μήτ’ ἐπὶ νηπίοις λαβὼν οἶκτον μήτ’ ἐπὶ γέρουσιν αἰδῶ, καταβαλὼν δὲ καὶ τὴν πόλιν, ἣν πατρίδα καὶ τροφὸν τῶν ἱερέων καὶ προφητῶν αὐτόθι τὸ θεῖον ἐπελέξατο καὶ μόνην εἰς τὸ τοιούτους φέρειν ἄνδρας ἀπέδειξε, μαθεῖν ἅπασι παρέσχε καὶ κατανοῆσαι τὸν ἀνθρώπινον τρόπον, ὅτι μέχρις οὗ μέν εἰσιν ἰδιῶταί τινες καὶ ταπεινοὶ τῷ μὴ δύνασθαι χρῆσθαι τῇ φύσει μηδὲ τολμᾶν ὅσα θέλουσιν ἐπιεικεῖς εἰσι καὶ μέτριοι καὶ μόνον διώκουσι τὸ δίκαιον, καὶ πρὸς αὐτῷ τὴν πᾶσαν εὔνοιάν [τε] καὶ σπουδὴν ἔχουσι τότε, καὶ περὶ τοῦ θείου πεπιστεύκασιν, ὅτι πᾶσι τοῖς γινομένοις ἐν τῷ βίῳ πάρεστι καὶ οὐ τὰ ἔργα μόνον ὁρᾷ τὰ πραττόμενα, ἀλλὰ καὶ τὰς διανοίας ἤδη σαφῶς οἶδεν, ἀφ’ ὧν μέλλει ταῦτα ἔσεσθαι· ὅταν δὲ εἰς ἐξουσίαν παρέλθωσι καὶ δυναστείαν, τότε πάντ’ ἐκεῖνα μετεκδυσάμενοι καὶ ὥσπερ ἐπὶ σκηνῆς προσωπεῖα τὰ ἤθη καὶ τοὺς τρόπους ἀποθέμενοι μεταλαμβάνουσι τόλμαν ἀπόνοιαν καταφρόνησιν ἀνθρωπίνων τε καὶ θείων, καὶ ὅτε μάλιστα δεῖ τῆς εὐσεβείας αὐτοῖς καὶ τῆς δικαιοσύνης ἔγγιστα τοῦ φθονεῖσθαι γεγενημένοις καὶ πᾶσι φανεροῖς ἐφ’ οἷς ἂν νοήσωσιν ἢ πράξωσι καθεστῶσι, τόθ’ ὡς οὐκέτι βλέποντος αὐτοὺς τοῦ θεοῦ ἢ διὰ τὴν ἐξουσίαν δεδιότος οὕτως ἐμπαροινοῦσι τοῖς πράγμασιν. ἃ δ’ ἂν ἢ φοβηθῶσιν ἀκούσαντες ἢ μισῶσι θελήσαντες ἢ στέρξωσιν ἀλόγως, ταῦτα κύρια καὶ βέβαια καὶ ἀληθῆ καὶ ἀνθρώποις ἀρεστὰ καὶ τῷ θεῷ δοκοῦσι, τῶν δὲ μελλόντων λόγος αὐτοῖς οὐδὲ εἷς· ἀλλὰ τιμῶσι μὲν [τοὺς] πολλὰ ταλαιπωρήσαντας, τιμήσαντες δὲ φθονοῦσι, καὶ παραγαγόντες εἰς ἐπιφάνειαν οὐ ταύτης ἀφαιροῦνται μόνον τοὺς τετυχηκότας, ἀλλὰ διὰ ταύτην καὶ τοῦ ζῆν ἐπὶ πονηραῖς αἰτίαις καὶ δι’ ὑπερβολὴν αὐτῶν ἀπιθάνοις· κολάζουσι δ’ οὐκ ἐπ’ ἔργοις δίκης ἀξίοις, ἀλλ’ ἐπὶ διαβολαῖς καὶ κατηγορίαις ἀβασανίστοις, οὐδ’ ὅσους ἔδει τοῦτο παθεῖν, ἀλλ’ ὅσους ἀποκτεῖναι δύνανται. τοῦτο Σαοῦλος ἡμῖν ὁ Κείσου παῖς, ὁ πρῶτος μετὰ τὴν ἀριστοκρατίαν [καὶ] τὴν ἐπὶ τοῖς κριταῖς πολιτείαν Ἑβραίων βασιλεύσας, φανερὸν πεποίηκε τριακοσίους ἀποκτείνας ἱερέας καὶ προφήτας ἐκ τῆς πρὸς Ἀβιμέλεχον ὑποψίας, ἐπικαταβαλὼν δὲ αὐτοῖς καὶ τὴν πόλιν καὶ τὸν ἐν τρόπῳ τινὶ ναὸν σπουδάσας ἱερέων καὶ προφητῶν ἔρημον καταστῆσαι τοσούτους μὲν ἀνελών, μεῖναι δ’ ἐάσας οὐδὲ τὴν πατρίδα αὐτῶν πρὸς τὸ καὶ μετ’ ἐκείνους ἄλλους γενέσθαι.", "st": "6.12.7"}, {"sp": "N", "t": "Ὁ δ’ Ἀβιάθαρος ὁ τοῦ Ἀβιμελέχου παῖς ὁ μόνος δυνηθεὶς ἐκ τοῦ γένους τῶν ὑπὸ τοῦ Σαούλου φονευθέντων ἱερέων φυγὼν πρὸς Δαυίδην τὴν τῶν οἰκείων αὐτοῦ συμφορὰν ἐδήλωσε καὶ τὴν τοῦ πατρὸς ἀναίρεσιν. ὁ δ’ οὐκ ἀγνοεῖν ἔφη ταῦτα περὶ αὐτοὺς ἐσόμενα ἰδὼν τὸν Δώηγον· ὑπονοῆσαι γὰρ διαβληθήσεσθαι πρὸς αὐτοῦ τὸν ἀρχιερέα τῷ βασιλεῖ, καὶ τῆς ἀτυχίας ταύτης αὐτοῖς αὑτὸν ᾐτιᾶτο. μένειν δ’ αὐτόθι καὶ σὺν αὐτῷ διατρίβειν ὡς οὐκ ἐν ἄλλῳ τόπῳ λησόμενον οὕτως ἠξίου.", "st": "6.12.8"}, {"sp": "N", "t": "Κατὰ δὲ τοῦτον τὸν καιρὸν ἀκούσας ὁ Δαυίδης τοὺς Παλαιστίνους ἐμβεβληκότας εἰς τὴν Κιλλανῶν χώραν καὶ ταύτην διαρπάζοντας δίδωσιν ἑαυτὸν στρατεύειν ἐπ’ αὐτοὺς τοῦ θεοῦ διὰ τοῦ προφήτου πυθόμενος εἰ ἐπιτρέπει νίκην. τοῦ δὲ σημαίνειν φήσαντος ἐξώρμησεν ἐπὶ τοὺς Παλαιστίνους μετὰ τῶν ἑταίρων καὶ φόνον τε αὐτῶν πολὺν ἐξέχεε καὶ λείαν ἤλασεν. καὶ παραμείνας τοῖς Κιλλανοῖς ἕως οὗ τὰς ἅλως καὶ τὸν καρπὸν συνεῖλον ἀδεῶς Σαούλῳ τῷ βασιλεῖ μηνύεται παρ’ αὐτοῖς ὤν· τὸ γὰρ ἔργον καὶ τὸ κατόρθωμα οὐκ ἔμεινε παρ’ οἷς ἐγένετο, φήμῃ δ’ ἐπίπαν εἴς τε τὰς τῶν ἄλλων ἀκοὰς καὶ πρὸς τὰς τοῦ βασιλέως διεκομίσθη αὑτό τε συνιστάνον καὶ τὸν πεποιηκότα. χαίρει δὲ Σαοῦλος ἀκούσας ἐν Κίλλα τὸν Δαυίδην, καί θεὸς ἤδη χερσὶ ταῖς ἐμαῖς ὑπέθετο αὐτόν, εἰπών, ἐπεὶ καὶ συνηνάγκασεν ἐλθεῖν εἰς πόλιν τείχη καὶ πύλας καὶ μοχλοὺς ἔχουσαν, τῷ λαῷ παντὶ προσέταξεν ἐπὶ τὴν Κίλλαν ἐξορμῆσαι καὶ πολιορκήσαντι καὶ ἑλόντι τὸν Δαυίδην ἀποκτεῖναι. ταῦτα δὲ αἰσθόμενος ὁ Δαυίδης καὶ μαθὼν παρὰ τοῦ θεοῦ, ὅτι μείναντα παρ’ αὐτοῖς οἱ Κιλλῖται ἐκδώσουσι τῷ Σαούλῳ, παραλαβὼν τοὺς τετρακοσίους ἀπῆρεν ἀπὸ τῆς πόλεως εἰς τὴν ἔρημον ἐπάνω τῆς Ἐνγεδὼν λεγομένης. καὶ ὁ μὲν βασιλεὺς ἀκούσας αὐτὸν πεφευγότα παρὰ τῶν Κιλλιτῶν ἐπαύσατο τῆς ἐπ’ αὐτὸν στρατείας.", "st": "6.13.1"}, {"sp": "N", "t": "Δαυίδης δὲ ἐκεῖθεν ἄρας εἴς τινα τόπον Καινὴν καλουμένην τῆς Ζιφήνης παραγίνεται, εἰς ὃν Ἰωνάθης ὁ τοῦ Σαούλου παῖς συμβαλὼν αὐτῷ καὶ κατασπασάμενος θαρρεῖν τε καὶ χρηστὰς περὶ τῶν μελλόντων ἔχειν ἐλπίδας παρεκάλει καὶ μὴ κάμνειν τοῖς παροῦσι· βασιλεύσειν γὰρ αὐτὸν καὶ πᾶσαν τὴν Ἑβραίων δύναμιν ἕξειν ὑφ’ ἑαυτῷ, φιλεῖν δὲ τὰ τοιαῦτα σὺν μεγάλοις ἀπαντᾶν πόνοις. πάλιν δ’ ὅρκους ποιησάμενος τῆς εἰς ἅπαντα τὸν βίον πρὸς ἀλλήλους εὐνοίας καὶ πίστεως καὶ τὸν θεὸν μάρτυρα καλέσας, ὧν ἐπηράσατο αὑτῷ παραβάντι τὰ συγκείμενα καὶ μεταβαλλομένῳ πρὸς τἀναντία, τὸν μὲν αὐτόθι καταλείπει μικρὰ τῶν φροντίδων καὶ τοῦ δέους ἐπικουφίσας, αὐτὸς δὲ πρὸς αὑτὸν ἐπανέρχεται. οἱ δὲ Ζιφηνοὶ χαριζόμενοι τῷ Σαούλῳ μηνύουσιν αὐτῷ παρ’ αὐτοῖς διατρίβειν τὸν Δαυίδην καὶ παραδώσειν ἔφασαν ἐπ’ αὐτὸν ἐλθόντι· καταληφθέντων γὰρ τῶν τῆς Ζιφηνῆς στενῶν οὐκ εἶναι φυγεῖν αὐτὸν πρὸς ἄλλους. ὁ δὲ βασιλεὺς ἐπῄνεσεν αὐτοὺς χάριν ἔχειν ὁμολογήσας τὸν ἐχθρὸν αὐτῷ μεμηνυκόσι, καὶ οὐκ εἰς μακρὰν ἀμείψεσθαι τῆς εὐνοίας ὑποσχόμενος αὐτοὺς ἔπεμψε τοὺς ζητήσοντας τὸν Δαυίδην καὶ τὴν ἐρημίαν ἐξερευνήσοντας, αὐτὸς δ’ ἀκολουθήσειν ἀπεκρίνατο. καὶ οἱ μὲν ἐπὶ τὴν θήραν καὶ τὴν σύλληψιν τοῦ Δαυίδου προῆγον τὸν βασιλέα σπουδάζοντες μὴ μόνον αὐτῷ μηνῦσαι τὸν ἐχθρὸν [αὐτῷ τὴν εὔνοιαν], ἀλλὰ καὶ τῷ παρασχεῖν αὐτὸν εἰς ἐξουσίαν φανερωτέραν καταστῆσαι· διήμαρτον δὲ τῆς ἀδίκου καὶ πονηρᾶς ἐπιθυμίας, οἳ μηδὲν κινδυνεύειν ἔμελλον ἐκ τοῦ μὴ ταῦτ’ ἐμφανίσαι τῷ Σαούλῳ, διὰ δὲ κολακείαν καὶ κέρδους προσδοκίαν παρὰ τοῦ βασιλέως ἄνδρα θεοφιλῆ καὶ παρὰ δίκην ζητούμενον ἐπὶ θανάτῳ καὶ λανθάνειν δυνάμενον διέβαλλον καὶ παραδώσειν ὑπέσχοντο· γνοὺς γὰρ ὁ Δαυίδης τὴν τῶν Ζιφηνῶν κακοήθειαν καὶ τὴν τοῦ βασιλέως ἔφοδον ἐκλείπει μὲν τὰ στενὰ τῆς ἐκείνων χώρας, φεύγει δὲ ἐπὶ τὴν μεγάλην πέτραν τὴν οὖσαν ἐν τῇ Σίμωνος ἐρήμῳ.", "st": "6.13.2"}, {"sp": "N", "t": "Ὥρμησεν δὲ ἐπ’ ἐκείνην διώκειν Σαοῦλος· κατὰ γὰρ τὴν ὁδὸν ἀναχωρήσαντα ἐκ τῶν στενῶν μαθὼν τὸν Δαυίδην ἐπὶ τὸ ἕτερον μέρος τῆς πέτρας ἀπῆρεν. ἀντιπεριέσπασαν δὲ τὸν Σαοῦλον ἀπὸ τῆς διώξεως τοῦ Δαυίδου μέλλοντος ἤδη συλλαμβάνεσθαι Παλαιστῖνοι πάλιν ἐπὶ τὴν Ἑβραίων ἐστρατευκέναι χάραν ἀκουσθέντες· ἐπὶ γὰρ τούτους ἀνέστρεψε φύσει πολεμίους ὄντας αὐτοὺς ἀμύνασθαι κρίνας ἀναγκαιότερον, ἢ τὸν ἴδιον σπουδάζοντα λαβεῖν ἐχθρὸν ὑπεριδεῖν τὴν γῆν κακωθεῖσαν.", "st": "6.13.3"}, {"sp": "N", "t": "Καὶ Δαυίδης μὲν οὕτως ἐκ παραλόγου τὸν κίνδυνον διαφυγὼν εἰς τὰ στενὰ τῆς Ἐνγεδηνῆς ἀφικνεῖται· Σαούλῳ δὲ ἐκβαλόντι τοὺς Παλαιστίνους ἧκον ἀπαγγέλλοντές τινες τὸν Δαυίδην ἐν τοῖς Ἐγγεδηνῆς διατρίβειν ὅροις. λαβὼν δὲ τρισχιλίους ἐπιλέκτους ὁπλίτας ἐπ’ αὐτὸν ἠπείγετο, καὶ γενόμενος οὐ πόρρω τῶν τόπων ὁρᾷ παρὰ τὴν ὁδὸν σπήλαιον βαθὺ καὶ κοῖλον εἰς πολὺ καὶ μῆκος ἀνεῳγὸς καὶ πλάτος, ἔνθα συνέβαινε τὸν Δαυίδην μετὰ τῶν τετρακοσίων κεκρύφθαι· ἐπειγόμενος οὖν ὑπὸ τῶν κατὰ φύσιν εἴσεισιν εἰς αὐτὸ μόνος θεαθεὶς ὑπό τινος τῶν μετὰ Δαυίδου· καὶ φράσαντος τοῦ θεασαμένου πρὸς τὸν ἐχθρὸν αὐτοῦ παρὰ τοῦ θεοῦ καιρὸν ἔχειν ἀμύνης καὶ συμβουλεύοντος τοῦ Σαούλου ἀποτεμεῖν τὴν κεφαλὴν καὶ τῆς πολλῆς ἄλης αὑτὸν ἀπαλλάξαι καὶ ταλαιπωρίας, ἀναστὰς ἀναίρει μὲν τὴν κροκύδα τοῦ ἱματίου μόνον οὗ Σαοῦλος ἀμπείχετο, μετανοήσας δ’ εὐθύς οὐ δίκαιον, εἶπε, φονεύειν τὸν αὑτοῦ δεσπότην, οὐδὲ τὸν ὑπὸ τοῦ θεοῦ βασιλείας ἀξιωθέντα· καὶ γὰρ εἰ πονηρὸς οὗτος εἰς ἡμᾶς, ἀλλ’ οὐκ ἐμὲ δεῖ τοιοῦτον εἶναι πρὸς αὐτόν. τοῦ δὲ Σαούλου τὸ σπήλαιον ἐκλιπόντος προελθὼν ὁ Δαυίδης ἔκραγεν ἀκοῦσαι τὸν Σαοῦλον ἀξιῶν. ἐπιστραφέντος δὲ τοῦ βασιλέως προσκυνεῖ τε αὐτὸν πεσὼν ἐπὶ πρόσωπον, ὡς ἔθος, καί φησιν· οὐ πονηροῖς, ὦ βασιλεῦ, καὶ ψευδεῖς πλάττουσι διαβολὰς παρέχοντα δεῖ τὰς ἀκοὰς χαρίζεσθαι μὲν ἐκείνοις τὸ πιστεύειν αὐτοῖς, εἰς δὲ τοὺς φιλτάτους ὑπονοίας ἔχειν, ἀλλὰ τοῖς ἔργοις σκοπεῖν τὴν ἁπάντων διάθεσιν. διαβολὴ μὲν γὰρ ἀπατᾷ, σαφὴς δ’ ἀπόδειξις εὐνοίας τὰ πραττόμενα· καὶ λόγος μὲν ἐπ’ ἀμφότερα πέφυκεν ἀληθής τε καὶ ψευδής, τὰ δὲ ἔργα γυμνὴν ὑπ’ ὄψει τὴν διάνοιαν τίθησιν. ἴσθι τοίνυν ἐκ τούτων καλῶς ἔχειν με πρὸς σὲ καὶ τὸν σὸν οἶκον ἐμοὶ πιστεῦσαι δεῖ, καὶ μὴ τοῖς κατηγοροῦσιν ἃ μήτε εἰς νοῦν ἐβαλόμην μήτε δύναται γενέσθαι προσθέμενον μεταδιώκειν τὴν ἐμὴν ψυχὴν καὶ μηδὲν μήθ’ ἡμέρας μήτε νυκτὸς ἔχειν διὰ φροντίδος ἢ τὴν ἐμὴν ἀναίρεσιν, ἣν ἀδίκως μεταπορεύῃ· πῶς γὰρ οὐχὶ ψευδῆ περὶ ἐμοῦ δόξαν εἴληφας ὡς ἀποκτεῖναί σε θέλοντος; ἢ πῶς οὐκ ἀσεβεῖς εἰς τὸν θεὸν ἄνθρωπον τήμερον αὑτῷ τιμωρῆσαι δυνάμενον καὶ παρὰ σοῦ λαβεῖν δίκην καὶ μὴ θελήσαντα μηδὲ τῷ καιρῷ χρησάμενον, ὃν εἰ σοὶ κατ’ ἐμοῦ περιέπεσεν οὐκ ἂν αὐτὸς παρῆκας, διαχρήσασθαι ποθῶν καὶ νομίζων πολέμιον; ὅτε γάρ σου τὴν πτέρυγα τοῦ ἱματίου ἀπέτεμον, τότε σου καὶ τὴν κεφαλὴν ἠδυνάμην. ἐπιδείξας δὲ τὸ ῥάκος ἰδεῖν πιστεύειν παρεῖχεν. ἀλλ’ ἐγὼ μὲν ἀπεσχόμην δικαίας ἀμύνης, φησί, σὺ δὲ μῖσος ἄδικον οὐκ αἰδῇ κατ’ ἐμοῦ τρέφων. ὁ θεὸς ταῦτα δικάσειε καὶ τὸν ἑκατέρου τρόπον ἡμῶν ἐλέγξειε. Σαοῦλος δὲ ἐπὶ τῷ παραδόξῳ τῆς σωτηρίας θαυμάσας καὶ τὴν τοῦ νεανίσκου μετριότητα καὶ φύσιν ἐκπλαγεὶς ἀνῴμωξε· τὸ δ’ αὐτὸ κἀκείνου ποιήσαντος αὐτὸν εἶναι δίκαιον στένειν ἀπεκρίνατο· σὺ μὲν γάρ, φησίν, ἀγαθῶν αἴτιος ἐμοὶ γέγονας, ἐγὼ δὲ σοὶ συμφορῶν. ἐπεδείξω δὲ σήμερον τὴν ἀρχαίων ἔχοντα σαυτὸν δικαιοσύνην, οἳ τοὺς ἐχθροὺς ἐν ἐρημίᾳ λαβόντες σώζειν παρήγγελλον. πέπεισμαι δὴ νῦν, ὅτι σοὶ τὴν βασιλείαν ὁ θεὸς φυλάττει καὶ περιμένει σε τὸ πάντων τῶν Ἑβραίων κράτος. δὸς δέ μοι πίστεις ἐνόρκους μή μου τὸ γένος ἐξαφανίσαι μηδ’ ἐμοὶ μνησικακοῦντα τοὺς ἐμοὺς ἐγγόνους ἀπολέσαι, τηρῆσαι δέ μοι καὶ σῶσαι τὸν οἶκον. ὀμόσας δὲ καθὼς ἠξίωκε Δαυίδης Σαοῦλον μὲν εἰς τὴν ἰδίαν ἀπέλυσε βασιλείαν, αὐτὸς δὲ μετὰ τῶν σὺν αὐτῷ εἰς τὴν Μασθηρῶν ἀνέβη στενήν.", "st": "6.13.4"}, {"sp": "N", "t": "Ἀποθνήσκει δὲ κατὰ τοῦτον τὸν καιρὸν καὶ Σαμουῆλος ὁ προφήτης, ἀνὴρ οὐ τῆς τυχούσης ἀπολαύων παρὰ τοῖς Ἑβραίοις τιμῆς· ἐνεφάνισε γὰρ τὴν ἀρετὴν αὐτοῦ καὶ τὴν τοῦ πλήθους πρὸς αὐτὸν εὔνοιαν τὸ πένθος, ὃ ἐπὶ πολὺν χρόνον ὁ λαὸς ἤγετο, καὶ ἡ περὶ τὴν ταφὴν αὐτοῦ καὶ τὴν τῶν νομιζομένων ἀναπλήρωσιν φιλοτιμία τε καὶ σπουδή. θάπτουσι γὰρ αὐτὸν ἐν τῇ πατρίδι Ἀρμεθᾶ καὶ ἐπὶ πολλὰς πάνυ ἡμέρας ἔκλαυσαν, οὐ κοινὸν τοῦτο πάσχοντες ὡς ἐπ’ ἀλλοτρίου τελευτῇ, ὡς οἰκεῖον δ’ ἕκαστος ἴδιον ποθῶν. ἐγένετο δ’ ἀνὴρ δίκαιος καὶ χρηστὸς τὴν φύσιν καὶ διὰ τοῦτο μάλιστα φίλος τῷ θεῷ. ἦρξε δὲ καὶ προέστη τοῦ λαοῦ μετὰ τὴν Ἠλεὶ τοῦ ἀρχιερέως τελευτὴν μόνος μὲν ἔτη δώδεκα, μετὰ δὲ Σαούλου τοῦ βασιλέως δέκα πρὸς τοῖς ὀκτώ. καὶ τὰ μὲν περὶ Σαμουῆλον οὕτω πέρας ἔσχεν.", "st": "6.13.5"}, {"sp": "N", "t": "Ἦν δέ τις τῶν Ζιφηνῶν ἐκ πόλεως Ἐμμᾶν πλούσιος καὶ πολυθρέμματος· τρισχιλίων μὲν γὰρ αὐτῷ ποίμνη προβάτων ἐνέμετο, χιλίων δ’ αἰγῶν. ταῦτα Δαυίδης ἀσινῆ τηρεῖν τε καὶ ἀβλαβῆ παρήγγελλε τοῖς σὺν αὐτῷ καὶ μήτε ὑπὸ ἐπιθυμίας μήτε ὑπὸ ἐνδείας μήτε ὑπὸ τῆς ἐρημίας καὶ τοῦ δύνασθαι λανθάνειν καταβλάπτειν, τούτων δ’ ἁπάντων ἐπάνω τίθεσθαι τὸ μηδέν’ ἀδικεῖν καὶ τὸ τῶν ἀλλοτρίων ἅπτεσθαι δεινὸν ἡγεῖσθαι καὶ πρόσαντες τῷ θεῷ. ταῦτα δ’ ἐδίδασκεν αὐτοὺς οἰόμενος ἀνθρώπῳ χαρίζεσθαι ἀγαθῷ καὶ ταύτης τυγχάνειν ἀξίῳ τῆς προνοίας. ἦν δὲ Νάβαλος, τοῦτο γὰρ εἶχεν ὄνομα, σκληρὸς καὶ πονηρὸς τοῖς ἐπιτηδεύμασιν ἐκ κυνικῆς ἀσκήσεως πεποιημένος τὸν βίον, γυναικὸς δ’ ἀγαθῆς καὶ σώφρονος καὶ τὸ εἶδος ὡραίας λελαχώς. πρὸς οὖν τὸν Νάβαλον τοῦτον καθ’ ὃν ἔκειρε τὰ πρόβατα καιρὸν πέμψας ὁ Δαυίδης ἄνδρας δέκα τῶν σὺν αὐτῷ διὰ τούτων αὐτὸν ἀσπάζεται καὶ συνεύχεται τοῦτο ποιεῖν ἐπ’ ἔτη πολλά· παρασχεῖν δὲ ἐξ ὧν δυνατός ἐστιν αὐτῷ παρεκάλει μαθόντα παρὰ τῶν ποιμένων, ὅτι μηδὲν αὐτοὺς ἠδίκησαν, ἀλλὰ φύλακες αὐτῶν τε καὶ τῶν ποιμνίων γεγόνασι πολὺν ἐν τῇ ἐρήμῳ διατρίβοντες ἤδη χρόνον· μετανοήσει δ’ οὐδὲν Δαυίδῃ παρασχόμενος. ταῦτα δὲ τῶν πεμφθέντων διακονησάντων πρὸς τὸν Νάβαλον ἀπανθρώπως σφόδρα καὶ σκληρῶς ἀπήντησεν· ἐρωτήσας γὰρ αὐτούς, τίς ἐστι Δαυίδης, ὡς τὸν υἱὸν ἤκουσεν Ἰεσσαίου, νῦν ἄρα, εἶπε, μέγα φρονοῦσιν ἐφ’ αὑτοῖς οἱ δραπέται καὶ σεμνύνονται τοὺς δεσπότας καταλιπόντες. ὀργίζεται δ’ αὐτῶν φρασάντων ὁ Δαυίδης καὶ τετρακοσίους μὲν ὡπλισμένους αὐτῷ κελεύσας ἕπεσθαι, διακοσίους δὲ φύλακας τῶν σκευῶν καταλιπών, ἤδη γὰρ εἶχεν ἑξακοσίους, ἐπὶ τὸν Νάβαλον ἐβάδιζεν ὀμόσας ἐκείνῃ τῇ νυκτὶ τὸν οἶκον αὐτοῦ καὶ τὴν κτῆσιν ὅλην ἀφανίσειν· οὐ γὰρ ἄχθεσθαι μόνον ὅτι γέγονεν ἀχάριστος ἐπ’ αὐτοὺς μηδὲν ἐπιδοὺς πολλῇ φιλανθρωπίᾳ πρὸς αὐτὸν χρησαμένοις, ἀλλ’ ὅτι καὶ προσεβλασφήμησε καὶ κακῶς εἶπε μηδὲν ὑπ’ αὐτῶν λελυπημένος.", "st": "6.13.6"}, {"sp": "N", "t": "Δούλου δέ τινος τῶν τὰ ποίμνια φυλασσόντων τὰ τοῦ Ναβάλου πρὸς τὴν δέσποιναν μὲν ἑαυτοῦ γυναῖκα δ’ ἐκείνου κατειπόντος, ὅτι πέμψας ὁ Δαυίδης αὐτῆς πρὸς τὸν ἄνδρα μηδενὸς τύχοι τῶν μετρίων, ἀλλὰ καὶ προσυβρισθείη βλασφημίαις δειναῖς πάσῃ περὶ αὐτοὺς προνοίᾳ καὶ φυλακῇ τῶν ποιμνίων χρησάμενος, γέγονε δὲ τοῦτο ἐπὶ κακῷ τῷ τοῦ δεσπότου καὶ ταῦτ’ ἐκείνου φήσαντος Ἀβιγαία, προσηγορεύετο γὰρ οὕτως, ἐπισάξασα τοὺς ὄνους καὶ πληρώσασα παντοίων ξενίων καὶ μηδὲν εἰποῦσα τἀνδρί, ὑπὸ γὰρ μέθης ἀναίσθητος ἦν, ἐπορεύετο πρὸς Δαυίδην· καταβαινούσῃ δὲ τὰ στενὰ τοῦ ὄρους ἀπήντησε Δαυίδης μετὰ τῶν τετρακοσίων ἐπὶ Νάβαλον ἐρχόμενος. θεασαμένη δ’ αὐτὸν ἡ γυνὴ κατεπήδησε καὶ πεσοῦσα ἐπὶ πρόσωπον προσεκύνησε καὶ τῶν μὲν Ναβάλου λόγων ἐδεῖτο μὴ μνημονεύειν [οὐ γὰρ ἀγνοεῖν] αὐτὸν ὅμοιον ὄντα τῷ ὀνόματι, Νάβαλος γὰρ κατὰ τὴν Ἑβραίων γλῶτταν ἀφροσύνην δηλοῖ, αὐτὴ δ’ ἀπελογεῖτο μὴ θεάσασθαι τοὺς πεμφθέντας ὑπ’ αὐτοῦ· διὸ συγγίνωσκέ μοι, φησί, καὶ τῷ θεῷ χάριν ἔχε κωλύοντί σε μιανθῆναι ἀνθρωπίνῳ αἵματι· μένοντα γάρ σε καθαρὸν ἐκεῖνος αὐτὸς ἐκδικήσει παρὰ τῶν πονηρῶν· ἃ γὰρ ἐκδέχεται κακὰ Νάβαλον ταῦτα καὶ ταῖς τῶν ἐχθρῶν σου κεφαλαῖς ἐμπέσοι. γενοῦ δὲ εὐμενής μοι κρίνας ἀξίαν τοῦ παρ’ ἐμοῦ ταῦτα δέξασθαι, καὶ τὸν θυμὸν καὶ τὴν ὀργὴν τὴν ἐπὶ τὸν ἄνδρα μου καὶ τὸν οἶκον αὐτοῦ εἰς τὴν ἐμὴν τιμὴν ἄφες· πρέπει γὰρ ἡμέρῳ σοι καὶ φιλανθρώπῳ τυγχάνειν, καὶ ταῦτα μέλλοντι βασιλεύειν. ὁ δὲ τὰ δῶρα δεξάμενος ἀλλά σε, φησίν, ὦ γύναι, θεὸς εὐμενὴς ἤγαγε πρὸς ἡμᾶς τήμερον· οὐ γὰρ ἂν τὴν ἐπερχομένην ἡμέραν εἶδες, ἐμοῦ τὸν οἶκον τὸν Ναβάλου διὰ τῆσδε τῆς νυκτὸς ὀμόσαντος ἀπολέσαι καὶ μηδένα ὑμῶν ἀπολείψειν ἀπὸ ἀνδρὸς [ἕως τετραπόδου] πονηροῦ καὶ ἀχαρίστου πρὸς ἐμὲ καὶ τοὺς ἐμοὺς ἑταίρους γενομένου. νῦν δὲ φθάσασα προέλαβες καταμειλίξασθαί μου τὸν θυμὸν κηδομένου σου θεοῦ. ἀλλὰ Νάβαλος μὲν κἂν ἀφεθῇ διὰ σὲ νῦν τῆς τιμωρίας οὐ φεύξεται τὴν δίκην, ἀλλ’ ὁ τρόπος αὐτὸν ἀπολεῖ λαβὼν αἰτίαν ἄλλην.", "st": "6.13.7"}, {"sp": "N", "t": "Ταῦτ’ εἰπὼν ἀπολύει τὴν γυναῖκα· ἡ δ’ εἰς τὸν οἶκον ἐλθοῦσα καὶ καταλαβοῦσα τὸν ἄνδρα μετὰ πολλῶν εὐωχούμενον καὶ κεκαρωμένον ἤδη τότε μὲν οὐδὲν τῶν γεγενημένων διεσάφει, τῇ δὲ ἐπιούσῃ νήφοντι ἅπαντα δηλώσασα παρεθῆναι καὶ πᾶν αὐτῷ νεκρωθῆναι τὸ σῶμα ὑπὸ τῶν λόγων καὶ τῆς ἐπ’ αὐτοῖς λύπης ἐποίησε· καὶ δέκα οὐ πλείους ἐπιζήσας ἡμέρας τὸν βίον κατέστρεψεν ὁ Νάβαλος. ἀκούσας δ’ αὐτοῦ τὴν τελευτὴν ὁ Δαυίδης ἐκδικηθῆναι μὲν αὑτὸν ὑπὸ τοῦ θεοῦ καλῶς ἔλεγεν· ἀποθανεῖν γὰρ Νάβαλον ὑπὸ τῆς ἰδίας πονηρίας καὶ δοῦναι δίκην αὐτῷ καθαρὰν ἔχοντι τὴν δεξιάν· ἔγνω δὲ καὶ τότε τοὺς πονηροὺς ἐλαυνομένους ὑπὸ τοῦ θεοῦ μηδενὸς τῶν ἐν ἀνθρώποις ὑπερορῶντος, διδόντος δὲ τοῖς μὲν ἀγαθοῖς τὰ ὅμοια, τοῖς δὲ πονηροῖς ὀξεῖαν ἐπιφέροντος τὴν ποινήν. πέμψας δ’ αὐτοῦ πρὸς τὴν γυναῖκα συνοικήσουσαν καὶ γαμηθησομένην ἐκάλει πρὸς αὑτόν· ἡ δὲ ἀναξία μὲν εἶναι καὶ ποδῶν ἅψασθαι τῶν ἐκείνου πρὸς τοὺς παρόντας ἔλεγεν, ὅμως δὲ μετὰ πάσης τῆς θεραπείας ἧκε. καὶ συνῴκησε μὲν αὐτῷ ταύτην λαβοῦσα τὴν τιμὴν καὶ διὰ τὸ τὸν τρόπον σώφρονα εἶναι καὶ δίκαιον, τυχοῦσα δ’ αὐτῆς καὶ διὰ τὸ κάλλος. εἶχε δὲ Δαυίδης γυναῖκα πρότερον, ἣν ἐξ Ἀβισάρου πόλεως ἔγημε· Μελχὰν δὲ τὴν Σαούλου τοῦ βασιλέως θυγατέρα τὴν γενομένην τοῦ Δαυίδου γυναῖκα ὁ πατὴρ τῷ Φελτίῳ υἱῷ Λίσου συνέζευξεν ἐκ πόλεως ὄντι Γεθλᾶς.", "st": "6.13.8"}, {"sp": "N", "t": "Μετὰ ταῦτά τινες ἐλθόντες τῶν Ζιφηνῶν ἀπήγγειλαν τῷ Σαούλῳ, ὡς εἴη πάλιν ὁ Δαυίδης ἐν τῇ χώρᾳ αὐτῶν καὶ δύνανται συλλαβεῖν αὐτὸν βουλομένῳ συνεργῆσαι. ὁ δὲ μετὰ τρισχιλίων ὁπλιτῶν ἐβάδιζεν ἐπ’ αὐτὸν καὶ νυκτὸς ἐπελθούσης ἐστρατοπέδευσεν ἐπί τινι τόπῳ Σίκελλα λεγομένῳ. Δαυίδης δὲ ἀκούσας τὸν Σαοῦλον ἐπ’ αὐτὸν ἥκοντα πέμψας κατασκόπους ἐκέλευσε δηλοῦν αὐτῷ, ποῦ τῆς χώρας Σαοῦλος ἤδη προεληλύθοι. τῶν δ’ ἐν Σίκελλα φρασάντων διανυκτερεύειν διαλαθὼν τοὺς ἰδίους εἰς τὸ τοῦ Σαούλου στρατόπεδον παραγίνεται ἐπαγόμενος τὸν ἐκ τῆς ἀδελφῆς αὐτοῦ Σαρουίας Ἀβισαῖον καὶ Ἀβιμέλεχον τὸν Χετταῖον. τοῦ δὲ Σαούλου κοιμωμένου καὶ περὶ αὐτὸν ἐν κύκλῳ τῶν ὁπλιτῶν καὶ τοῦ στρατηγοῦ Ἀβενήρου κειμένων, ὁ Δαυίδης εἰσελθὼν εἰς τὸ στρατόπεδον τὸ τοῦ βασιλέως οὔτ’ αὐτὸς ἀναιρεῖ τὸν Σαοῦλον ἐπιγνοὺς αὐτοῦ τὴν κοίτην ἐκ τοῦ δόρατος, τοῦτο γὰρ αὐτῷ παρεπεπήγει, οὔτε τὸν Ἀβισαῖον βουλόμενον φονεῦσαι καὶ πρὸς τοῦτο ὡρμηκότα εἴασεν, ἀλλὰ τὸν ὑπὸ τοῦ θεοῦ κεχειροτονημένον βασιλέα φήσας εἶναι δεινὸν ἀποκτεῖναι κἂν ᾖ πονηρός, ἥξειν γὰρ αὐτῷ παρὰ τοῦ δόντος τὴν ἀρχὴν σὺν χρόνῳ τὴν δίκην, ἐπέσχε τῆς ὁρμῆς. σύμβολον δὲ τοῦ κτεῖναι δυνηθεὶς ἀποσχέσθαι λαβὼν αὐτοῦ τὸ δόρυ καὶ τὸν φακὸν τοῦ ὕδατος, ὃς ἦν παρ’ αὐτῷ κείμενος τῷ Σαούλῳ, μηδενὸς αἰσθομένου τῶν ἐν τῷ στρατοπέδῳ πάντων δὲ κατακοιμωμένων ἐξῆλθεν, ἀδεῶς πάντ’ ἐργασάμενος, ὅσα καὶ τοῦ καιροῦ δόντος αὐτῷ καὶ τῆς τόλμης διέθηκε τοὺς τοῦ βασιλέως. διαβὰς δὲ τὸν χείμαρρον καὶ ἐπὶ τὴν κορυφὴν ἀνελθὼν τοῦ ὄρους, ὅθεν ἔμελλεν ἐξάκουστος εἶναι, ἐμβοήσας τοῖς στρατιώταις τοῦ Σαούλου καὶ τῷ στρατηγῷ Ἀβενήρῳ διανίστησιν αὐτὸν ἀπὸ τοῦ ὕπνου τοῦτόν τε ἐφώνει καὶ τὸν λαόν. ἐπακούσαντος δὲ τοῦ στρατηγοῦ καὶ τίς ὁ καλέσας αὐτόν ἐστιν ἐρομένου Δαυίδης εἶπεν· ἐγώ, παῖς μὲν Ἰεσσαίου, φυγὰς δὲ ὑμέτερος. ἀλλὰ τί δήποτε μέγας τε ὢν καὶ τὴν πρώτην ἔχων παρὰ τῷ βασιλεῖ τιμὴν οὕτως ἀμελῶς τὸ τοῦ δεσπότου φυλάσσεις σῶμα, καὶ ὕπνος ἡδίων ἐστί σοι τῆς τούτου σωτηρίας καὶ προνοίας; θανάτου γὰρ ἄξια ταῦτα καὶ τιμωρίας, οἵ γε μικρὸν ἔμπροσθεν εἰσελθόντας τινὰς ὑμῶν εἰς τὸ στρατόπεδον οὐκ ἐνοήσατε. ζήτησον οὖν τὸ δόρυ τοῦ βασιλέως καὶ τὸν φακὸν τοῦ ὕδατος καὶ μαθήσῃ, πηλίκον ὑμᾶς ἔλαθε κακὸν ἐντὸς γενόμενον. Σαοῦλος δὲ γνωρίσας τὴν τοῦ Δαυίδου φωνὴν καὶ μαθών, ὅτι λαβὼν αὐτὸν ἔκδοτον ὑπὸ τοῦ ὕπνου καὶ τῆς τῶν φυλασσόντων ἀμελείας οὐκ ἀπέκτεινεν, ἀλλ’ ἐφείσατο δικαίως ἂν αὐτὸν ἀνελών, χάριν ἔχειν αὐτῷ τῆς σωτηρίας ἔλεγε καὶ παρεκάλει θαρροῦντα καὶ μηδὲν ἔτι πείσεσθαι δεινὸν ἐξ αὐτοῦ φοβούμενον ἀναχωρεῖν ἐπὶ τὰ οἰκεῖα· πεπεῖσθαι γάρ, ὅτι μηδ’ αὐτὸν οὕτως ἀγαπήσειεν, ὡς ὑπ’ ἐκείνου στέργεται· ὃς τὸν μὲν φυλάττειν αὐτὸν δυνάμενον καὶ πολλὰ δείγματα τῆς εὐνοίας παρεσχημένον ἐλαύνοι καὶ τοσοῦτον ἐν φυγῇ χρόνον καὶ ταῖς περὶ τὴν ψυχὴν ἀγωνίαις ἠνάγκασε ζῆσαι φίλων καὶ συγγενῶν ἔρημον· αὐτὸς δ’ οὐ παύεται ὑπ’ αὐτοῦ σωζόμενος, [οὐδὲ τὴν ψυχὴν] φανερῶς ἀπολλυμένην λαμβάνων. ὁ δὲ Δαυίδης πέμψαντα ἀπολαβεῖν ἐκέλευσε τὸ δόρυ καὶ τὸν φακὸν τοῦ ὕδατος ἐπειπών, [ὡς] ὁ θεὸς ἑκατέρῳ τῆς ἰδίας φύσεως καὶ τῶν κατ’ αὐτὴν πεπραγμένων ἔσται δικαστής, ὃς ὅτι καὶ κατὰ τὴν παροῦσαν ἡμέραν ἀποκτεῖναί σε δυνηθεὶς ἀπεσχόμην οἶδε.", "st": "6.13.9"}, {"sp": "N", "t": "Καὶ Σαοῦλος μὲν δεύτερον διαφυγὼν τὰς Δαυίδου χεῖρας εἰς τὰ βασίλεια καὶ τὴν οἰκείαν ἀπηλλάσσετο, φοβηθεὶς δὲ Δαυίδης, μὴ μένων αὐτόθι συλληφθῇ ὑπὸ τοῦ Σαούλου, συμφέρειν ἔκρινεν εἰς τὴν Παλαιστίνην ἀναβὰς διατρίβειν ἐν αὐτῇ, καὶ μετὰ τῶν ἑξακοσίων, οἳ περὶ αὐτὸν ἦσαν παραγίνεται πρὸς Ἀγχοῦν τὸν Γίττης βασιλέα· μία δ’ ἦν αὕτη τῶν πέντε πόλεων. δεξαμένου δ’ αὐτὸν τοῦ βασιλέως σὺν τοῖς ἀνδράσι καὶ δόντος οἰκητήριον ἔχων ἅμα καὶ τὰς δύο γυναῖκας Ἀχιμὰν καὶ Ἀβιγαίαν διῆγεν ἐν τῇ Γίττῃ. Σαούλῳ δὲ ταῦτ’ ἀκούσαντι λόγος οὐκέτ’ ἦν πέμπειν ἐπ’ αὐτὸν ἢ βαδίζειν· δὶς γὰρ ἤδη κινδυνεῦσαι παρὰ μικρὸν ἐπ’ ἐκείνῳ γενόμενον συλλαβεῖν αὐτὸν σπουδάσαντα. Δαυίδῃ δ’ οὐκ ἔδοξεν ἐν τῇ πόλει τῶν Γιττῶν μένειν, ἀλλ’ ἐδεήθη τοῦ βασιλέως αὐτῶν, ἵν’ ἐπειδὴ φιλανθρώπως αὐτὸν ὑπεδέξατο καὶ τοῦτο χαρίσηται, τόπον τινὰ τῆς χώρας δοὺς αὐτῷ πρὸς κατοίκησιν· αἰδεῖσθαι γὰρ διατρίβων ἐν τῷ πόλει βαρὺς αὐτῷ καὶ φορτικὸς εἶναι. δίδωσι δὲ Ἀγχοῦς αὐτῷ κώμην τινὰ Σέκελλαν καλουμένην, ἣν βασιλεύσας ὁ Δαυίδης ἀγαπῶν ἴδιον κτῆμα ἐτίμησεν εἶναι καὶ οἱ παῖδες αὐτοῦ. ἀλλὰ περὶ μὲν τούτων ἐν ἄλλοις δηλώσομεν· ὁ δὲ χρόνος, ὃν κατῴκησε Δαυίδης ἐν Σεκέλλα τῆς Παλαιστίνης, ἐγένετο μῆνες τέσσαρες πρὸς ταῖς εἴκοσιν ἡμέραις. ἐπερχόμενος δὲ λάθρα τοῖς πλησιοχώροις τῶν Παλαιστίνων Σερρίταις καὶ Ἀμαληκίταις διήρπαζεν αὐτῶν τὴν χώραν καὶ λείαν πολλὴν κτηνῶν καὶ καμήλων λαμβάνων ὑπέστρεφεν· ἀνθρώπων γὰρ ἀπείχετο δεδιὼς μὴ καταμηνύσωσιν αὐτὸν πρὸς Ἀγχοῦν τὸν βασιλέα, τὸ μέντοι γε τῆς λείας μέρος αὐτῷ δωρεὰν ἔπεμπε. τοῦ δὲ βασιλέως πυθομένου, τίσιν ἐπιθέμενος τὴν λείαν ἀπήλασε; τοῖς πρὸς τὸν νότον τῶν Ἰουδαίων τετραμμένοις καὶ ἐν τῇ πεδιάδι κατοικοῦσιν εἰπὼν πείθει τὸν Ἀγχοῦν φρονῆσαι οὕτως· [ἤλπισε γὰρ οὗτος,] ὅτι Δαυίδης ἐμίσησε τὸ ἴδιον ἔθνος, καὶ δοῦλον ἕξειν παρ’ ὃν ζῇ χρόνον ἐν τοῖς αὐτοῦ καταμένοντα.", "st": "6.13.10"}, {"sp": "N", "t": "Κατὰ δὲ τὸν αὐτὸν καιρὸν τῶν Παλαιστίνων ἐπὶ τοὺς Ἰσραηλίτας στρατεύειν διεγνωκότων καὶ περιπεμψάντων πρὸς τοὺς συμμάχους ἅπαντας, ἵνα παρῶσιν αὐτοῖς εἰς τὸν πόλεμον εἰς Ῥεγάν, ἔνθεν ἔμελλον ἀθροισθέντες ἐξορμᾶν ἐπὶ τοὺς Ἑβραίους, ὁ τῶν Γιττῶν βασιλεὺς Ἀγχοῦς συμμαχῆσαι τὸν Δαυίδην αὐτῷ μετὰ τῶν ἰδίων ὁπλιτῶν ἐκέλευσε. τοῦ δὲ προθύμως ὑποσχομένου καὶ φήσαντος παραστῆναι καιρόν, ἐν ᾧ τὴν ἀμοιβὴν αὐτῷ τῆς εὐεργεσίας καὶ τῆς ξενίας ἀποδώσει, ποιήσειν αὐτὸν καὶ φύλακα τοῦ σώματος μετὰ τὴν νίκην καὶ τοὺς ἀγῶνας τοὺς πρὸς τοὺς πολεμίους κατὰ νοῦν χωρήσαντας αὐτοῖς ἐπηγγείλατο, τῆς τιμῆς καὶ πίστεως ὑποσχέσει τὸ πρόθυμον αὐτοῦ μᾶλλον αὔξων.", "st": "6.14.1"}, {"sp": "N", "t": "Ἔτυχε δὲ Σαοῦλος ὁ τῶν Ἑβραίων βασιλεὺς τοὺς μάντεις καὶ τοὺς ἐγγαστριμύθους καὶ πᾶσαν τὴν τοιαύτην τέχνην ἐκ τῆς χώρας ἐκβεβληκὼς ἔξω τῶν προφητῶν. ἀκούσας δὲ τοὺς Παλαιστίνους ἤδη παρόντας καὶ ἔγγιστα Σούνης πόλεως ἐν τῷ πεδίῳ ἐστρατοπεδευκότας ἐξώρμησεν ἐπ’ αὐτοὺς μετὰ τῆς δυνάμεως. καὶ παραγενόμενος πρὸς ὄρει τινὶ Γελβουὲ καλουμένῳ βάλλεται στρατόπεδον ἀντικρὺ τῶν πολεμίων. ταράττει δ’ αὐτὸν οὐχ ὡς ἔτυχεν ἡ τῶν ἐχθρῶν δύναμις πολλή τε οὖσα καὶ τῆς οἰκείας κρείττων ὑπονοουμένη, καὶ τὸν θεὸν διὰ τῶν προφητῶν ἐρωτᾷ περὶ τῆς μάχης καὶ τοῦ περὶ ταύτην ἐσομένου τέλους προειπεῖν. οὐκ ἀποκρινομένου δὲ τοῦ θεοῦ ἔτι μᾶλλον ὁ Σαοῦλος κατέδεισε καὶ τὴν ψυχὴν ἀνέπεσε, τὸ κακὸν οἷον εἰκὸς οὐ παρόντος αὐτῷ κατὰ χεῖρα τοῦ θείου προορώμενος. ζητηθῆναι δ’ αὑτῷ κελεύει γύναιόν τι τῶν ἐγγαστριμύθων καὶ τῶν τεθνηκότων ψυχὰς ἐκκαλουμένων ὡς οὕτως γνωσομένῳ, ποῖ χωρεῖν αὐτῷ μέλλει τὰ πράγματα· τὸ γὰρ τῶν ἐγγαστριμύθων γένος ἀνάγον τὰς τῶν νεκρῶν ψυχὰς δι’ αὐτῶν προλέγει τοῖς δεομένοις τὰ ἀποβησόμενα. μηνυθέντος δ’ αὐτῷ παρά τινος τῶν οἰκετῶν εἶναί τι γύναιον τοιοῦτον ἐν πόλει Δώρῳ, λαθὼν πάντας τοὺς ἐν τῷ στρατοπέδῳ καὶ μετεκδὺς τὴν βασιλικὴν ἐσθῆτα δύο παραλαβὼν οἰκέτας, οὓς ᾔδει πιστοτάτους ἄνδρας, ἧκεν εἰς τὴν Δῶρον πρὸς τὴν γυναῖκα καὶ παρεκάλει μαντεύεσθαι καὶ ἀνάγειν αὐτῷ ψυχὴν οὗπερ ἂν αὐτὸς εἴπῃ. τῆς δὲ γυναικὸς ἀπομαχομένης καὶ λεγούσης οὐ καταφρονήσειν τοῦ βασιλέως, ὃς τοῦτο τὸ γένος τῶν μάντεων ἐξήλασεν, οὐδ’ αὐτὸν δὲ ποιεῖν καλῶς ἀδικηθέντα μηδὲν ὑπ’ αὐτῆς, ἐνεδρεύοντα δὲ εἰς τὰ κεκωλυμένα λαβεῖν αὐτὴν ἵνα δῷ δίκην, ὤμοσε μηδένα γνώσεσθαι μηδὲ παρ’ ἄλλον ἄγειν αὐτῆς τὴν μαντείαν, ἔσεσθαι δ’ ἀκίνδυνον. ὡς δὲ τοῖς ὅρκοις αὐτὴν ἔπεισε μὴ δεδιέναι, κελεύει τὴν Σαμουήλου ψυχὴν ἀναγαγεῖν αὐτῷ. ἡ δ’ ἀγνοοῦσα τὸν Σαμουῆλον ὅστις ἦν καλεῖ τοῦτον ἐξ ᾅδου· φανέντος δ’ αὐτοῦ θεασάμενον τὸ γύναιον ἄνδρα σεμνὸν καὶ θεοπρεπῆ ταράττεται, καὶ πρὸς τὴν ὄψιν ἐκπλαγέν, οὐ σύ, φησίν, ὁ βασιλεὺς εἶ Σαοῦλος; ἐδήλωσε γὰρ αὐτὸν Σαμουῆλος. ἐπινεύσαντος δ’ ἐκείνου καὶ τὴν ταραχὴν αὐτῆς ἐρομένου πόθεν γένοιτο, βλέπειν εἶπεν ἀνελθόντα τῷ θεῷ τινα τὴν μορφὴν ὅμοιον. τοῦ δὲ τὴν εἰκόνα φράζειν [εἰπόντος] καὶ τὸ σχῆμα τοῦ θεαθέντος καὶ τὴν ἡλικίαν [κελεύσαντος] γέροντα μὲν ἤδη καὶ ἔνδοξον ἐσήμαινεν, ἱερατικὴν δὲ περικείμενον διπλοΐδα. ἐγνώρισεν ἐκ τούτων ὁ βασιλεὺς τὸν Σαμουῆλον ὄντα καὶ πεσὼν ἐπὶ τὴν γῆν ἠσπάζετο καὶ προσεκύνησε· τῆς δὲ Σαμουήλου ψυχῆς πυθομένης, διὰ τί κινήσειεν αὐτὴν καὶ ἀναχθῆναι ποιήσειεν ἀνάγκην, ἀπωδύρετο τοὺς πολεμίους ἐπικεῖσθαι βαρεῖς αὐτῷ, αὐτὸν δὲ ἀμηχανεῖν τοῖς παροῦσιν ἐγκαταλελειμμένον ὑπὸ τοῦ θεοῦ καὶ μηδὲ προρρήσεως τυγχάνοντα μήτε διὰ προφητῶν μήτε δι’ ὀνειράτων καὶ διὰ τοῦτο ἐπὶ σὲ τὸν ἐμοῦ προνοησόμενον κατέφυγον. Σαμουῆλος δὲ τέλος αὐτὸν ἔχοντα ἤδη τῆς μεταβολῆς ὁρῶν περισσὸν μέν, εἶπεν, ἔτι καὶ παρ’ ἐμοῦ βούλεσθαι μαθεῖν τοῦ θεοῦ καταλελοιπότος αὐτόν· ἄκουέ γε μήν, ὅτι βασιλεῦσαι δεῖ Δαυίδην καὶ κατορθῶσαι τὸν πόλεμον, σὲ δὲ καὶ τὴν ἀρχὴν καὶ τὴν ζωὴν ἀπολέσαι τοῦ θεοῦ παρακούσαντα ἐν τῷ πρὸς Ἀμαληκίτας πολέμῳ καὶ τὰς ἐντολὰς αὐτοῦ μὴ φυλάξαντα, καθὼς προεφήτευσά σοι καὶ ζῶν. ἴσθι τοίνυν καὶ τὸν λαὸν ὑποχείριον τοῖς ἐχθροῖς γενησόμενον καὶ σαυτὸν μετὰ τῶν τέκνων αὔριον πεσόντα ἐπὶ τῆς μάχης μετ’ ἐμοῦ γενησόμενον.", "st": "6.14.2"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας Σαοῦλος ἄφωνος ὑπὸ λύπης ἐγένετο καὶ κατενεχθεὶς εἰς τοὔδαφος, εἴτε διὰ τὴν προσπεσοῦσαν ἐκ τῶν δεδηλωμένων ὀδύνην, εἴτε διὰ τὴν ἔνδειαν, οὐ γὰρ προσενήνεκτο τροφὴν τῇ παρελθούσῃ ἡμέρᾳ τε καὶ νυκτί, ῥᾳδίως ἔκειτο νέκυς ὥς τις. μόλις δὲ ἑαυτοῦ γενόμενον συνηνάγκασεν ἡ γυνὴ γεύσασθαι ταύτην αἰτουμένη παρ’ αὐτοῦ τὴν χάριν ἀντὶ τῆς παραβόλου μαντείας, ἣν οὐκ ἐξὸν αὐτῇ ποιήσασθαι διὰ τὸν ἐξ αὐτοῦ φόβον ἀγνοουμένου τίς ἦν, ὅμως ὑπέστη καὶ παρέσχεν. ἀνθ’ ὧν παρεκάλει τράπεζάν τε αὐτῷ παραθεῖναι καὶ τροφήν, ὡς ἂν τὴν ἰσχὺν συλλεξάμενος εἰς τὸ τῶν οἰκείων ἀποσωθῇ στρατόπεδον· ἀντέχοντα δὲ καὶ τελέως ἀπεστραμμένον ὑπὸ ἀθυμίας ἐβιάσατο καὶ συνέπεισεν. ἔχουσα δὲ μόσχον ἕνα συνήθη καὶ τῆς κατ’ οἶκον ἐπιμελείας καὶ τροφῆς ἀξιούμενον ὑπ’ αὐτῆς, ὡς γυνὴ χερνῆτις καὶ τούτῳ μόνῳ προσαναπαυομένη τῷ κτήματι, κατασφάξασα τοῦτον καὶ τὰ κρέα παρασκευάσασα τοῖς οἰκέταις αὐτοῦ καὶ αὐτῷ παρατίθησι. καὶ Σαοῦλος μὲν διὰ τῆς νυκτὸς ἦλθεν εἰς τὸ στρατόπεδον.", "st": "6.14.3"}, {"sp": "N", "t": "Δίκαιον δὲ ἀποδέξασθαι τῆς φιλοτιμίας τὴν γυναῖκα, ὅτι καίπερ τῇ τέχνῃ κεκωλυμένη χρήσασθαι ὑπὸ τοῦ βασιλέως, παρ’ ἧς ἂν αὐτῇ τὰ κατὰ τὸν οἶκον ἦν ἀμείνω καὶ διαρκέστερα, καὶ μηδέποτε αὐτὸν πρότερον τεθεαμένη οὐκ ἐμνησικάκησε τῆς ἐπιστήμης ὑπ’ αὐτοῦ καταγνωσθείσης, οὐκ ἀπεστράφη δὲ ὡς ξένον καὶ μηδέποτε ἐν συνηθείᾳ γεγενημένον, ἀλλὰ συνεπάθησέ τε καὶ παρεμυθήσατο καὶ πρὸς ἃ διέκειτο λίαν ἀηδῶς προετρέψατο, καὶ τὸ μόνον αὐτῇ παρὸν ὡς ἐν πενίᾳ τοῦτο παρέσχεν ἐκτενῶς καὶ φιλοφρόνως, οὔθ’ ὑπὲρ εὐεργεσίας ἀμειβομένη τινὸς γεγενημένης οὔτε χάριν μέλλουσαν θηρωμένη, τελευτήσοντα γὰρ [αὐτὸν] ἠπίστατο, φύσει τῶν ἀνθρώπων ἢ πρὸς τοὺς ἀγαθόν τι παρεσχημένους φιλοτιμουμένων, ἢ παρ’ ὧν ἂν δύνωνται λαβεῖν ὄφελος τούτους προθεραπευόντων. καλὸν οὖν ἐστι μιμεῖσθαι τὴν γυναῖκα καὶ ποιεῖν εὖ πάντας τοὺς ἐν χρείᾳ γενομένους καὶ μηδὲν ὑπολαμβάνειν ἄμεινον μηδὲ μᾶλλόν τι προσήκειν τῷ τῶν ἀνθρώπων γένει τούτου μηδ’ ἐφ’ ᾧ τὸν θεὸν εὐμενῆ καὶ χορηγὸν τῶν ἀγαθῶν ἕξομεν. καὶ τὰ μὲν περὶ τῆς γυναικὸς ἐν τοσούτοις ἀρκεῖ δεδηλῶσθαι· τὸν δὲ πόλεσι καὶ δήμοις καὶ ἔθνεσι συμφέροντα λόγον καὶ προσήκοντα τοῖς ἀγαθοῖς, ὑφ’ οὗ προαχθήσονται πάντες ἀρετὴν διώξειν καὶ ζηλοῦν δόξαν καὶ μνήμην αἰώνιον παρασχεῖν δυνησόμενον, ποιήσομαι, πολλὴν καὶ βασιλεῦσιν ἐθνῶν καὶ ἄρχουσι πόλεων ἐπιθυμίαν καὶ σπουδὴν τῶν καλῶν ἐνθήσοντα, καὶ πρός τε κινδύνους καὶ τὸν ὑπὲρ τῶν πατρίδων θάνατον προτρεψόμενον, καὶ πάντων καταφρονεῖν διδάξοντα τῶν δεινῶν. ἔχω δ’ αἰτίαν τοῦ λόγου τούτου Σαοῦλον τὸν τῶν Ἑβραίων βασιλέα· οὗτος γὰρ καίπερ εἰδὼς τὰ συμβησόμενα καὶ τὸν ἐπικείμενον θάνατον τοῦ προφήτου προειρηκότος οὐκ ἔγνω φυγεῖν αὐτὸν οὐδὲ φιλοψυχήσας προδοῦναι μὲν τοὺς οἰκείους τοῖς πολεμίοις καθυβρίσαι δὲ τὸ τῆς βασιλείας ἀξίωμα, ἀλλὰ παραδοὺς αὑτὸν πανοικὶ μετὰ τῶν τέκνων τοῖς κινδύνοις καλὸν ἡγήσατο εἶναι πεσεῖν μετὰ τούτων ὑπὲρ τῶν βασιλευομένων μαχόμενος, καὶ τοὺς παῖδας ἀποθανεῖν μᾶλλον ἀγαθοὺς ὄντας, ἢ καταλιπεῖν ἐπ’ ἀδήλῳ τῷ ποδαποὶ γενήσονται τὸν τρόπον· διάδοχον γὰρ καὶ γένος τὸν ἔπαινον καὶ τὴν ἀγήρω μνήμην ἕξειν. οὗτος οὖν δίκαιος καὶ ἀνδρεῖος καὶ σώφρων ἔμοι γε δοκεῖ μόνος καὶ εἴ τις γέγονε τοιοῦτος ἢ γενήσεται τὴν μαρτυρίαν ἐπ’ ἀρετῇ καρποῦσθαι παρὰ πάντων ἄξιος· τοὺς γὰρ μετ’ ἐλπίδων ἐπὶ πόλεμον ἐξελθόντας ὡς καὶ κρατήσοντας καὶ σῶς ἐπιστρέψοντας, ἐπειδάν τι διαπράξωνται λαμπρόν, οὔ μοι δοκοῦσι καλῶς ποιεῖν ἀνδρείους ἀποκαλοῦντες, ὅσοι περὶ τῶν τοιούτων ἐν ταῖς ἱστορίαις καὶ τοῖς ἄλλοις συγγράμμασιν εἰρήκασιν· ἀλλὰ δίκαιοι μέν εἰσι κἀκεῖνοι τυγχάνειν ἀποδοχῆς, εὔψυχοι δὲ καὶ μεγαλότολμοι καὶ τῶν δεινῶν καταφρονηταὶ μόνοι δικαίως ἂν λέγοιντο πάντες οἱ Σαοῦλον μιμησάμενοι. τὸ μὲν γὰρ οὐκ εἰδότας τί μέλλει συμβήσεσθαι κατὰ τὸν πόλεμον αὐτοῖς μὴ μαλακισθῆναι περὶ αὐτόν, ἀλλ’ ἀδήλῳ τῷ μέλλοντι παραδόντας αὑτοὺς ἐπ’ αὐτοῦ σαλεύειν οὔπω γενναῖον, κἂν ἔργα πολλὰ διαπραξάμενοι τύχωσι· τὸ δὲ μηδὲν ἐν τῇ διανοίᾳ χρηστὸν προσδοκῶντας, ἀλλὰ προειδότας ὡς δεῖ θανεῖν καὶ τοῦτο παθεῖν μαχομένους εἶτα μὴ φοβηθῆναι μηδὲ καταπλαγῆναι τὸ δεινόν, ἀλλ’ ἐπ’ αὐτὸ χωρῆσαι προγινωσκόμενον, τοῦτ’ ἀνδρείου ἀληθῶς τεκμήριον ἐγὼ κρίνω. Σαοῦλος τοίνυν τοῦτο ἐποίησεν ἐπιδείξας ὅτι πάντας μὲν προσήκει τῆς μετὰ τὸν θάνατον εὐφημίας γλιχομένους ταῦτα ποιεῖν, ἐξ ὧν ἂν αὑτοῖς ταύτην καταλείποιεν, μάλιστα δὲ τοὺς βασιλέας, ὡς οὐκ ἐξὸν αὐτοῖς διὰ τὸ μέγεθος τῆς ἀρχῆς οὐ μόνον οὐ κακοῖς εἶναι περὶ τοὺς ἀρχομένους, ἀλλ’ οὐδὲ μετρίως χρηστοῖς. ἔτι τούτων πλείω περὶ Σαούλου καὶ τῆς εὐψυχίας λέγειν ἠδυνάμην ὕλην ἡμῖν χορηγησάσης τῆς ὑποθέσεως, ἀλλ’ ἵνα μὴ φανῶμεν ἀπειροκάλως αὐτοῦ χρῆσθαι τοῖς ἐπαίνοις, ἐπάνειμι πάλιν ἀφ’ ὧν εἰς τούτους ἐξέβην.", "st": "6.14.4"}, {"sp": "N", "t": "Κατεστρατοπεδευκότων γὰρ τῶν Παλαιστίνων, ὡς προεῖπον, καὶ κατὰ ἔθνη καὶ βασιλείας καὶ σατραπείας ἐξαριθμούντων τὴν δύναμιν, τελευταῖος βασιλεὺς παρῆλθεν Ἀγχοῦς μετὰ τῆς ἰδίας στρατιᾶς καὶ Δαυίδης μετὰ τῶν ἑξακοσίων ὁπλιτῶν εἵπετο. θεασάμενοι δὲ αὐτὸν οἱ στρατηγοὶ τῶν Παλαιστίνων, πόθεν εἴησαν ἥκοντες οἱ Ἑβραῖοι καὶ τίνων καλεσάντων ἠρώτων τὸν βασιλέα. ὁ δὲ Δαυίδην ἔλεγεν εἶναι τὸν φυγόντα Σαοῦλον τὸν ἑαυτοῦ δεσπότην καὶ πρὸς αὐτὸν ἐλθόντα δέξασθαι, καὶ νῦν τῆς χάριτος ἀμοιβὴν ἐκτεῖσαι βουλόμενον καὶ τιμωρήσασθαι τὸν Σαοῦλον συμμαχεῖν αὐτοῖς. ἐμέμφθη δὲ ὑπὸ τῶν στρατηγῶν ἄνδρα παρειληφὼς ἐπὶ συμμαχίᾳ πολέμιον καὶ ἀποπέμπειν συνεβούλευον, μὴ καὶ λάθῃ μέγα δι’ αὐτὸν κακὸν τοὺς φίλους ἐργασάμενος· καὶ γὰρ οὕτω παρέξειν καταλλαγῆναι πρὸς τὸν δεσπότην κακώσαντα τὴν ἡμετέραν δύναμιν. ὃ δὴ καὶ προορώμενον εἰς τὸν τόπον ὃν ἔδωκεν αὐτῷ κατοικεῖν ἐκέλευον ἀποπέμπειν σὺν τοῖς ἑξακοσίοις ὁπλίταις· τοῦτον γὰρ εἶναι τὸν Δαυίδην, ὃν ᾄδουσιν αἱ παρθένοι πολλὰς μυριάδας Παλαιστίνων ἀπολέσαντα. ταῦτ’ ἀκούσας ὁ τῶν Γιττῶν βασιλεὺς καὶ καλῶς εἰρῆσθαι λογισάμενος καλέσας τὸν Δαυίδην ἐγὼ μέν, εἶπε, μαρτυρῶ σοι πολλὴν περὶ ἐμὲ σπουδὴν καὶ εὔνοιαν καὶ διὰ τοῦτό σε σύμμαχον ἐπηγόμην· οὐ δοκεῖ δὲ ταὐτὸ τοῖς στρατηγοῖς. ἀλλ’ ἄπιθι μεθ’ ἡμέραν εἰς ὃν ἔδωκά σοι τόπον μηδὲν ὑπονοῶν ἄτοπον, κἀκεῖ φύλασσέ μοι τὴν χώραν, μή τινες εἰς αὐτὴν τῶν πολεμίων ἐμβάλωσιν. ἔστι δὲ καὶ τοῦτο συμμαχίας μέρος. καὶ Δαυίδης μέν, ὡς ἐκέλευσεν ὁ τῶν Γιττῶν βασιλεύς, ἧκεν εἰς Σίκελλαν. καθ’ ὃν δὲ καιρὸν ἐξ αὐτῆς συμμαχήσων τοῖς Παλαιστίνοις ἀπῆλθε τὸ τῶν Ἀμαληκιτῶν ἔθνος ἐπελθὸν αἱρεῖ τὴν Σίκελλαν κατὰ κράτος, καὶ ἐμπρήσαντες καὶ πολλὴν λείαν ἄλλην ἔκ τ’ αὐτῆς ἐκείνης καὶ τῆς ἄλλης τῶν Παλαιστίνων χώρας λαβόντες ἀνεχώρησαν.", "st": "6.14.5"}, {"sp": "N", "t": "Ἐκπεπορθημένην δὲ τὴν Σίκελλαν καταλαβὼν ὁ Δαυίδης καὶ διηρπαγμένα πάντα καὶ τὰς γυναῖκας [τὰς] ἑαυτοῦ, δύο γὰρ ἦσαν, καὶ τὰς γυναῖκας τῶν ἑταίρων σὺν τοῖς τέκνοις ᾐχμαλωτισμένας, περιρρήγνυται εὐθὺς τὴν ἐσθῆτα. κλαίων δὲ καὶ ὀδυρόμενος μετὰ τῶν φίλων ἐπὶ τοσοῦτον παρείθη τοῖς κακοῖς, ὥστε αὐτὸν ἐπιλιπεῖν ἤδη καὶ τὰ δάκρυα, κινδυνεῦσαι δὲ καὶ βληθεὶς ὑπὸ τῶν ἑταίρων ἀλγούντων ἐπὶ ταῖς αἰχμαλωσίαις τῶν γυναικῶν καὶ τῶν τέκνων ἀποθανεῖν· αὐτὸν γὰρ τῶν γεγονότων ᾐτιῶντο. ἀνασχὼν δ’ ἐκ τῆς λύπης καὶ τὴν διάνοιαν πρὸς τὸν θεὸν ἀναστήσας παρεκάλεσε τὸν ἀρχιερέα Ἀβιάθαρον ἐνδύσασθαι τὴν ἱερατικὴν στολὴν καὶ ἐπερωτῆσαι τὸν θεὸν καὶ προφητεῦσαι, εἰ διώξαντι τοὺς Ἀμαληκίτας δίδωσι καταλαβεῖν καὶ σῶσαι μὲν τὰς γυναῖκας καὶ τὰ τέκνα, τιμωρήσασθαι δὲ τοὺς ἐχθρούς. τοῦ δ’ ἀρχιερέως διώκειν κελεύσαντος ἐκπηδήσας μετὰ τῶν ἑξακοσίων ὁπλιτῶν εἵπετο τοῖς πολεμίοις· παραγενόμενος δ’ ἐπί τινα χειμάρρουν Βάσελον λεγόμενον καὶ πλανωμένῳ τινὶ περιπεσὼν Αἰγυπτίῳ μὲν τὸ γένος ὑπ’ ἐνδείας δὲ καὶ λιμοῦ παρειμένῳ, τρισὶ γὰρ ἡμέραις ἐν τῇ ἐρημίᾳ πλανώμενος ἄσιτος διεκαρτέρησε, πρῶτον αὐτὸν ποτῷ καὶ τροφῇ παραστησάμενος καὶ ἀναλαβὼν ἐπύθετο, τίς τε εἴη καὶ πόθεν. ὁ δὲ γένος μὲν ἐσήμαινεν Αἰγύπτιος ὤν, καταλειφθῆναι δὲ ὑπὸ τοῦ δεσπότου κατ’ ἀρρωστίαν ἕπεσθαι μὴ δυνάμενον· ἐδήλου δ’ αὑτὸν τῶν καταπρησάντων καὶ διηρπακότων ἄλλα τε τῆς Ἰουδαίας καὶ τὴν Σίκελλαν εἶναι. χρησάμενος οὖν ὁ Δαυίδης τούτῳ ἐπὶ τοὺς Ἀμαληκίτας ὁδηγῷ καὶ καταλαβὼν [αὐτοὺς] ἐπὶ γῆς ἐρριμμένους, καὶ τοὺς μὲν ἀριστῶντας, τοὺς δὲ καὶ μεθύοντας ἤδη καὶ λελυμένους ὑπὸ τοῦ οἴνου καὶ τῶν λαφύρων καὶ τῆς λείας ἀπολαύοντας, ἐπιπεσὼν αἰφνιδίως πολὺν αὐτῶν φόνον εἰργάσατο· γυμνοὶ γὰρ ὄντες καὶ μηδὲν προσδοκῶντες τοιοῦτον, ἀλλὰ πρὸς τὸ πιεῖν καὶ εὐωχεῖσθαι τετραμμένοι πάντες ἦσαν εὐκατέργαστοι. καὶ οἱ μὲν αὐτῶν ἔτι τῶν τραπεζῶν παρακειμένων ἐπικαταλαμβανόμενοι παρ’ αὐταῖς ἀνῃροῦντο καὶ παρέσυρεν αὐτοῖς τὰ σιτία καὶ τὴν τροφὴν τὸ αἷμα, τοὺς δὲ δεξιουμένους ἀλλήλους ταῖς προπόσεσι διέφθειρεν, ἐνίους δὲ καὶ πρὸς ὕπνον ὑπὸ τοῦ ἀκράτου κατενηνεγμένους. ὁπόσοι δ’ ἔφθασαν περιθέμενοι τὰς πανοπλίας ἐξ ἐναντίας τ’ αὐτῷ στῆναι, τούτους οὐδὲν ἧττον εὐχερῶς τῶν γυμνῶν κατακειμένων ἀπέσφαττον. διέμειναν δὲ οἱ σὺν τῷ Δαυίδῃ καὶ αὐτοὶ ἀναιροῦντες ἀπὸ πρώτης ὥρας ἕως ἑσπέρας, ὡς μὴ περιλειφθῆναι τῶν Ἀμαληκιτῶν πλείονας ἢ τετρακοσίους· καὶ οὗτοι δὲ δρομάσι καμήλοις ἐπιβάντες διέφυγον. ἀνέσωσε δὲ τἆλλα πάντα ἃ διήρπασαν αὐτῶν οἱ πολέμιοι καὶ τάς τε αὐτοῦ γυναῖκας καὶ τὰς τῶν ἑταίρων. ὡς δὲ ἀναστρέφοντες ἧκον ἐπὶ τὸν τόπον, ἔνθα διακοσίους μὴ δυναμένους αὐτοῖς ἕπεσθαι καταλελοίπεσαν ἐπὶ τῶν σκευῶν, οἱ μὲν τετρακόσιοι τῆς μὲν ἄλλης ὠφελείας τε καὶ λείας οὐκ ἠξίουν αὐτοῖς ἀπομερίζειν· οὐ συνακολουθήσαντας γὰρ ἀλλὰ μαλακισθέντας περὶ τὴν δίωξιν ἀγαπήσειν ἀνασεσωσμένας τὰς γυναῖκας ἀπολαμβάνοντας ἔλεγον· Δαυίδης δὲ πονηρὰν καὶ ἄδικον αὐτῶν ταύτην ἀπέφηνε τὴν γνώμην· εἶναι γὰρ ἀξίους, τοῦ θεοῦ παρασχόντος αὐτοῖς ἀμύνασθαι μὲν τοὺς πολεμίους, κομίσασθαι δὲ πάντα τὰ αὑτῶν, πᾶσιν ἐξ ἴσου τοῖς συστρατευσαμένοις μερίζεσθαι τὴν ὠφέλειαν, καὶ ταῦτ’ ἐπὶ φυλακῇ τῶν σκευῶν μεμενηκότων. καὶ ἐξ ἐκείνου νόμος οὗτος ἐκράτησε παρ’ αὐτοῖς, ἵνα ταὐτὰ τοῖς μαχομένοις λαμβάνωσιν οἱ τὰ σκεύη φυλάσσοντες. γενόμενος δ’ ἐν Σικέλλα Δαυίδης διέπεμψε πᾶσι τοῖς ἐν τῇ Ἰούδα φυλῇ συνήθεσι καὶ φίλοις ἀπομοίρας τῶν λαφύρων. καὶ τὰ μὲν περὶ τὴν Σικέλλων πόρθησιν καὶ Ἀμαληκιτῶν ἀναίρεσιν οὕτως ἐγένετο.", "st": "6.14.6"}, {"sp": "N", "t": "Τῶν δὲ Παλαιστίνων συμβαλόντων καὶ καρτερᾶς μάχης γενομένης νικῶσιν οἱ Παλαιστῖνοι καὶ πολλοὺς ἀναιροῦσι τῶν ἐναντίων, Σαοῦλος δὲ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς καὶ οἱ παῖδες αὐτοῦ γενναίως ἀγωνιζόμενοι καὶ πάσῃ προθυμίᾳ χρώμενοι, ὡς ἐν μόνῳ τῷ καλῶς ἀποθανεῖν καὶ παραβόλως διακινδυνεῦσαι τοῖς πολεμίοις τῆς ὅλης αὐτοῖς δόξης ἀποκειμένης, οὐδὲν γὰρ τούτου περισσότερον εἶχον, ἐπιστρέφουσι πᾶσαν εἰς αὑτοὺς τὴν τῶν ἐχθρῶν φάλαγγα καὶ περικυκλωθέντες ἀποθνήσκουσι πολλοὺς τῶν Παλαιστίνων καταβαλόντες. ἦσαν δὲ οἱ παῖδες Ἰωνάθης καὶ Ἀμινάδαβος καὶ Μέλχισος. τούτων πεσόντων τρέπεται τὸ τῶν Ἑβραίων πλῆθος καὶ ἀκοσμία καὶ σύγχυσις γίνεται καὶ φόνος ἐπικειμένων τῶν πολεμίων. Σαοῦλος δὲ φεύγει τὸ καρτερὸν ἔχων περὶ αὑτόν, καὶ τῶν Παλαιστίνων ἐπιπεμψάντων ἀκοντιστὰς καὶ τοξότας πάντας μὲν ἀποβάλλει πλὴν ὀλίγων, αὐτὸς δὲ λαμπρῶς ἀγωνισάμενος καὶ πολλὰ τραύματα λαβών, ὡς μηκέτι διακαρτερεῖν μηδ’ ἀντέχειν ταῖς πληγαῖς, ἀποκτεῖναι μὲν αὑτὸν ἠσθένει, κελεύει δὲ τὸν ὁπλοφόρον σπασάμενον τὴν ῥομφαίαν ταύτην αὐτοῦ διελάσαι, πρὶν ζῶντα συλλαβεῖν αὐτὸν τοὺς πολεμίους. μὴ τολμῶντος δὲ τοῦ ὁπλοφόρου κτεῖναι τὸν δεσπότην, αὐτὸς τὴν ἰδίαν σπασάμενος καὶ στήσας ἐπὶ τὴν ἀκμὴν ῥίπτει κατ’ αὐτῆς ἑαυτόν· ἀδυνατῶν δὲ μήθ’ ἵστασθαι μήτ’ ἐπερείσας διαβαλεῖν αὑτοῦ τὸν σίδηρον ἐπιστρέφεται, καὶ νεανίσκου τινὸς ἑστῶτος πυθόμενος τίς εἴη καὶ μαθὼν ὡς Ἀμαληκίτης ἐστὶ παρεκάλεσεν ἐπερείσαντα τὴν ῥομφαίαν διὰ τὸ μὴ ταῖς χερσὶν αὐτὸν δύνασθαι παρασχεῖν αὐτῷ τελευτὴν ὁποίαν αὐτὸς βούλεται. ποιήσας δὲ τοῦτο καὶ περιελόμενος τὸν περὶ τὸν βραχίονα αὐτοῦ χρυσὸν καὶ τὸν βασιλικὸν στέφανον ἐκποδὼν ἐγένετο. θεασάμενος δ’ ὁ ὁπλοφόρος Σαοῦλον ἀνῃρημένον ἀπέκτεινεν ἑαυτόν· διεσώθη δ’ οὐδεὶς τῶν σωματοφυλάκων τοῦ βασιλέως, ἀλλὰ πάντες ἔπεσον περὶ τὸ καλούμενον Γελβουὲ ὄρος. ἀκούσαντες δὲ τῶν Ἑβραίων οἱ τὴν κοιλάδα πέραν τοῦ Ἰορδάνου κατοικοῦντες καὶ οἱ ἐν τῷ πεδίῳ τὰς πόλεις ἔχοντες, ὅτι Σαοῦλος πέπτωκε καὶ οἱ παῖδες αὐτοῦ, καὶ τὸ σὺν αὐτῷ πλῆθος ἀπόλωλε, καταλιπόντες τὰς ἑαυτῶν πόλεις εἰς ὀχυρωτάτας ἔφυγον. οἱ δὲ Παλαιστῖνοι τὰς καταλελειμμένας ἐρήμους εὑρόντες κατῴκησαν.", "st": "6.14.7"}, {"sp": "N", "t": "Τῇ δ’ ἐπιούσῃ σκυλεύοντες οἱ Παλαιστῖνοι τοὺς τῶν πολεμίων νεκροὺς ἐπιτυγχάνουσι τοῖς Σαούλου καὶ τῶν παίδων αὐτοῦ σώμασι καὶ σκυλεύσαντες ἀποτέμνουσιν αὐτῶν τὰς κεφαλάς, καὶ κατὰ πᾶσαν περιήγγειλαν τὴν χώραν πέμψαντες, ὅτι πεπτώκασιν οἱ πολέμιοι· καὶ τὰς μὲν πανοπλίας αὐτῶν ἀνέθηκαν εἰς τὸ Ἀστάρτειον ἱερόν, τὰ δὲ σώματα ἀνεσταύρωσαν πρὸς τὰ τείχη τῆς Βηθσὰν πόλεως, ἣ νῦν Σκυθόπολις καλεῖται. ἐπεὶ δὲ ἤκουσαν οἱ ἐν Ἰάβει πόλει τῆς Γαλααδίτιδος κατοικοῦντες, ὅτι λελώβηνται τὸν Σαούλου νεκρὸν καὶ τοὺς τῶν παίδων αὐτοῦ, δεινὸν ἡγησάμενοι περιϊδεῖν ἀκηδεύτους ἐξελθόντες οἱ ἀνδρειότατοι καὶ τόλμῃ διαφέροντες, ἡ δὲ πόλις αὕτη καὶ σώμασιν ἀλκίμους καὶ ψυχαῖς φέρει, καὶ δι’ ὅλης τῆς νυκτὸς ὁδεύσαντες ἦλθον εἰς Βηθσάν, καὶ προσελθόντες τῷ τείχει τῶν πολεμίων καὶ καθελόντες τὸ σῶμα Σαούλου καὶ τὰ τῶν παίδων αὐτοῦ κομίζουσιν εἰς Ἰάβησαν μηδὲ τῶν πολεμίων αὐτοὺς κωλῦσαι τολμησάντων διὰ τὴν ἀνδρείαν. οἱ δὲ Ἰαβησηνοὶ πανδημεὶ κλαύσαντες θάπτουσι τὰ σώματα ἐν τῷ καλλίστῳ τῆς χώρας τόπῳ Ἀρούρης λεγομένῳ, καὶ πένθος ἐφ’ ἡμέρας ἑπτὰ σὺν γυναιξὶ καὶ τέκνοις ἐπ’ αὐτοῖς ἦγον κοπτόμενοι καὶ θρηνοῦντες τὸν βασιλέα καὶ τοὺς παῖδας αὐτοῦ μήτε τροφῆς μήτε ποτοῦ γευσάμενοι.", "st": "6.14.8"}, {"sp": "N", "t": "Τοῦτο Σαοῦλος τὸ τέλος ἔσχε προφητεύσαντος Σαμουήλου διὰ τὸ παρακοῦσαι τοῦ θεοῦ τῶν ἐπ’ Ἀμαληκίταις ἐντολῶν, καὶ ὅτι τὴν Ἀβιμελέχου τοῦ ἀρχιερέως γενεὰν καὶ Ἀβιμέλεχον αὐτὸν καὶ τὴν τῶν ἀρχιερέων πόλιν ἀνεῖλεν. ἐβασίλευσε δὲ Σαμουήλου ζῶντος ἔτη ὀκτὼ πρὸς τοῖς δέκα, τελευτήσαντος δὲ δύο καὶ εἴκοσι. καὶ Σαοῦλος μὲν οὕτω κατέστρεψε τὸν βίον.", "st": "6.14.9"}, {"sp": "HDR", "t": "Βιβλίον Ζʹ", "st": "7"}, {"sp": "N", "t": "Συνέβη δὲ ταύτην γενέσθαι τὴν μάχην καθ’ ἣν ἡμέραν καὶ Δαυίδης τοὺς Ἀμαληκίτας νικήσας εἰς Σίκελλαν ὑπέστρεψεν. ἤδη δὲ αὐτοῦ δύο ἡμέρας ἔχοντος ἐν τῇ Σικέλλα τῇ τρίτῃ παραγίνεται διασωθεὶς ἐκ τῆς μάχης τῆς πρὸς Παλαιστίνους ὁ τὸν Σαοῦλον ἀνελὼν τήν τε ἐσθῆτα περιερρηγμένος καὶ τὴν κεφαλὴν τέφρᾳ περιχεάμενος. καὶ προσκυνήσας αὐτὸν πυνθανομένῳ, πόθεν ἥκοι τοιοῦτος, ἀπὸ τῆς τῶν Ἰσραηλιτῶν μάχης ἔλεγε· γενέσθαι δ’ ἀτυχὲς αὐτῆς τὸ τέλος ἐδήλου πολλῶν μὲν ἀναιρεθεισῶν τοῖς Ἑβραίοις μυριάδων, πεσόντος δὲ καὶ τοῦ βασιλέως αὐτῶν Σαούλου μετὰ τῶν τέκνων· ταῦτα δὲ σημαίνειν ἔφασκεν αὐτὸς παρατυχὼν τῇ τροπῇ τῶν Ἑβραίων καὶ τῷ βασιλεῖ πεφευγότι παρών, ὃν καὶ κτεῖναι μέλλοντα ὑπὸ τῶν πολεμίων λαμβάνεσθαι παρακληθεὶς αὐτὸς ὡμολόγει· τῇ ῥομφαίᾳ γὰρ αὐτὸν ἐπιπεσόντα διὰ τὴν τῶν τραυμάτων ὑπερβολὴν αὑτὸν ἀσθενῆσαι κατεργάσασθαι. καὶ σύμβολα τῆς ἀναιρέσεως ἐπεδείκνυεν τόν τε περὶ τοῖς βραχίοσι χρυσὸν τοῦ βασιλέως καὶ τὸν στέφανον, ἃ περιδύσας τὸν Σαούλου νεκρὸν κομίσειεν αὐτῷ. Δαυίδης δὲ μηκέτ’ ἀπιστεῖν ἔχων ἀλλ’ ἐναργῆ τεκμήρια τοῦ Σαούλου θανάτου βλέπων καταρρηγνύει μὲν τὴν ἐσθῆτα, κλαίων δὲ καὶ ὀδυρόμενος μετὰ τῶν ἑταίρων ὅλην διεκαρτέρησε τὴν ἡμέραν. ποιεῖ δ’ αὐτῷ τὴν λύπην χαλεπωτέραν ὁ Σαούλου παῖς Ἰωνάθης πιστότατός τε ὢν φίλος αὐτῷ καὶ σωτηρίας αἴτιος γεγενημένος. τοσαύτην δ’ ἐπεδείξατο τὴν ἀρετὴν καὶ τὴν πρὸς τὸν Σαοῦλον εὔνοιαν, ὡς μὴ μόνον ἐπὶ τεθνηκότι χαλεπῶς ἐνεγκεῖν πολλάκις ὑπ’ αὐτοῦ κινδυνεύσας ἀφαιρεθῆναι τὸν βίον, ἀλλὰ καὶ τὸν ἀποκτείναντα κολάσαι. φήσας γὰρ πρὸς αὐτὸν, ὡς αὐτὸς γένοιτο κατήγορος ἀνελὼν τὸν βασιλέα, καὶ μαθών, ὡς εἴη πατρὸς Ἀμαληκίτου γένος, ἐκέλευσεν αὐτὸν ἀπολέσθαι. ἔγραψε δὲ καὶ θρήνους καὶ ἐπιταφίους ἐπαίνους Σαούλου καὶ Ἰωνάθου, οἳ καὶ μέχρις ἐμοῦ διαμένουσιν.", "st": "7.1.1"}, {"sp": "N", "t": "Ἐπεὶ δὲ τούτοις ἐξετίμησε τὸν βασιλέα παυσάμενος τοῦ πένθους ἤρετο τὸν θεὸν διὰ τοῦ προφήτου, τίνα δίδωσιν αὐτῷ κατοικῆσαι πόλιν τῆς Ἰούδα καλουμένης φυλῆς. φήσαντος δ’ αὐτοῦ διδόναι Γιβρῶνα καταλιπὼν τὴν Σίκελλαν εἰς ἐκείνην παραγίνεται τάς τε γυναῖκας ἐπαγόμενος τὰς αὑτοῦ, δύο δὲ ἦσαν, καὶ τοὺς ὁπλίτας τοὺς σὺν αὐτῷ. συνελθὼν δὲ πρὸς αὐτὸν πᾶς ὁ τῆς φυλῆς τῆς προειρημένης λαὸς ἀποδείκνυσιν αὐτὸν βασιλέα. ἀκούσας δ’ ὅτι τὸν Σαοῦλον καὶ τοὺς υἱοὺς αὐτοῦ θάψειαν οἱ ἐν Ἰαβησῷ τῆς Γαλααδίτιδος κατοικοῦντες, ἔπεμψε πρὸς αὐτοὺς ἐπαινῶν καὶ ἀποδεχόμενος αὐτῶν τὸ ἔργον, καὶ χάριτας ἀποδώσειν ἀντὶ τῆς πρὸς τοὺς τεθνηκότας σπουδῆς ὑπισχνούμενος, ἅμα δὲ καὶ δηλῶν ὡς ἡ Ἰούδα φυλὴ κεχειροτόνηκεν αὐτὸν βασιλέα.", "st": "7.1.2"}, {"sp": "N", "t": "Ὁ δὲ τοῦ Σαούλου μὲν ἀρχιστράτηγος Ἀβεννῆρος Νήρου δὲ παῖς ἀνὴρ δραστήριος καὶ ἀγαθὸς τὴν φύσιν, ὡς ἔγνω πεσόντα τὸν βασιλέα καὶ τὸν Ἰωνάθην καὶ τοὺς δύο τοὺς ἄλλους αὐτοῦ παῖδας, ἐπειχθεὶς εἰς τὴν παρεμβολὴν καὶ τὸν περιλειπόμενον ἐξαρπάσας υἱὸν αὐτοῦ, Ἰέβοσθος δ’ ἐκαλεῖτο, διαβιβάζει πρὸς τοὺς πέραν τοῦ Ἰορδάνου καὶ παντὸς ἀποδείκνυσι τοῦ πλήθους βασιλέα πάρεξ τῆς Ἰούδα φυλῆς. βασίλειον δ’ ἐποίησεν αὐτῷ τὴν κατὰ μὲν τὴν ἐπιχώριον γλῶτταν Μάναλιν, κατὰ δὲ τὴν Ἑλλήνων Παρεμβολὰς λεγομένην· ὥρμησε δ’ ἐκεῖθεν Ἀβεννῆρος μετὰ στρατιᾶς ἐπιλέκτου συμβαλεῖν τοῖς ἐκ τῆς Ἰούδα φυλῆς προαιρούμενος· ὤργιστο γὰρ αὐτοῖς βασιλέα τὸν Δαυίδην κεχειροτονηκόσιν. ἀπήντησε δ’ αὐτῷ πεμφθεὶς ὑπὸ Δαυίδου Σαρουίας μὲν παῖς, πατρὸς δὲ Σουρί, ἐκ δὲ τῆς ἀδελφῆς τῆς ἐκείνου γεγονὼς αὐτῷ Ἰώαβος ἀρχιστράτηγος ὢν αὐτοῦ, μετὰ καὶ τῶν ἀδελφῶν Ἀβεσσαίου καὶ Ἀσαήλου καὶ πάντων τῶν Δαυίδου ὁπλιτῶν. καὶ περιτυχὼν ἐπί τινος κρηνίδος ἐν Γαβαῶ πόλει παρατάσσεται πρὸς μάχην. τοῦ δ’ Ἀβεννήρου φήσαντος πρὸς αὐτὸν βούλεσθαι μαθεῖν, πότερος αὐτῶν ἀνδρειοτέρους στρατιώτας ἔχει, συντίθεται παρ’ ἀμφοτέρων δυοκαίδεκα μαχησομένους συμβαλεῖν. προελθόντες τοίνυν εἰς τὸ μεταξὺ τῶν παρατάξεων οἱ πρὸς τὴν μάχην ὑφ’ ἑκατέρων τῶν στρατηγῶν ἐξειλεγμένοι καὶ τὰς αἰχμὰς ἐπ’ ἀλλήλους ἀφέντες σπῶνται τὰς μαχαίρας καὶ τῶν κεφαλῶν ἐλλαμβανόμενοι κατέχοντες αὑτοὺς ἔπαιον εἰς τὰς πλευρὰς καὶ τὰς λαγόνας ἀλλήλους ταῖς ῥομφαίαις, ἕως οὗ πάντες ὥσπερ ἐκ συνθήματος ἀπώλοντο. πεσόντων δὲ τούτων συνέρρηξε καὶ ἡ λοιπὴ στρατιά, καὶ καρτερᾶς τῆς μάχης γενομένης ἡττήθησαν οἱ τοῦ Ἀβεννήρου· καὶ τραπέντας οὐκ ἀνίει διώκων Ἰώαβος, ἀλλ’ αὐτός τε ἐπέκειτο παρακελευόμενος τοὺς ὁπλίτας ἐκ ποδὸς ἕπεσθαι καὶ μὴ κάμνειν ἀναιροῦντας, οἵ τε ἀδελφοὶ προθύμως ἠγωνίσαντο, καὶ διαφανέστερος τῶν ἄλλων μάλιστα ὁ νεώτερος Ἀσάηλος, ὃς ἐπὶ ποδῶν ὠκύτητι κλέος εἶχεν· οὐ γὰρ ἀνθρώπους ἐνίκα μόνον, ἀλλὰ καὶ ἵππῳ καταστάντα εἰς ἅμιλλαν λέγουσι παραδραμεῖν, καὶ τὸν Ἀβεννῆρον ἐδίωκεν ὑπὸ ῥύμης καὶ τῆς ἐπ’ ὀρθὸν φορᾶς εἰς οὐδέτερον ἐγκλιθεὶς τῶν μερῶν. ἐπιστραφέντος δὲ τοῦ Ἀβεννήρου καὶ κατασοφίζεσθαι τὴν ὁρμὴν αὐτοῦ πειρωμένου καὶ ποτὲ μὲν εἰπόντος ἑνὸς τῶν αὐτοῦ στρατιωτῶν ἀφέμενος τῆς διώξεως ἀφελέσθαι τὴν πανοπλίαν, πάλιν δ’ ὡς οὐκ ἔπειθε τοῦτο ποιεῖν κατασχεῖν αὑτὸν καὶ μὴ διώκειν παραινοῦντος, μὴ κτείνας αὐτὸν ἀπολέσῃ τὴν πρὸς τὸν ἀδελφὸν αὐτοῦ παρρησίαν, οὐ προσιέμενον [δὲ] τοὺς λόγους, ἀλλ’ ἐπιμείναντα τὴν δίωξιν φεύγων ὡς εἶχε τὸ δόρυ πλήξας εἰς τοὐπίσω καιρίως παραχρῆμ’ ἀπέκτεινεν. οἱ δὲ μετ’ αὐτοῦ διώκοντες τὸν Ἀβεννῆρον ὡς ἦλθον ἐπὶ τὸν τόπον, οὗ κεῖσθαι συνέβαινε τὸν Ἀσάηλον, περιστάντες τὸν νεκρὸν οὐκέτι τοὺς πολεμίους ἐδίωκον· ὁ δὲ Ἰώαβος αὐτὸς καὶ ὁ ἀδελφὸς αὐτοῦ Ἀβεσσαῖος παραδραμόντες τὸ πτῶμα καὶ τῆς πλείονος ἐπὶ τὸν Ἀβεννῆρον σπουδῆς αἰτίαν τὴν ὑπὲρ τοῦ τετελευτηκότος ὀργὴν λαβόντες, ἀπίστῳ τάχει καὶ προθυμίᾳ χρώμενοι μέχρι τόπου τινός, Ὄμματον καλοῦσιν, ἐδίωξαν τὸν Ἀβεννῆρον ἤδη περὶ δυσμὰς ὄντος ἡλίου. ἀναβὰς δ’ ἐπί τινα βουνόν, ὅς ἐστιν ἐν ἐκείνῳ τῷ τόπῳ μετὰ τῆς Βενιαμίτιδος φυλῆς, αὐτούς τε κατεσκέπτετο καὶ τὸν Ἀβεννῆρον. τούτου δὲ ἀνακεκραγότος καὶ φήσαντος, μὴ δεῖν ἄνδρας ὁμοφύλους εἰς ἔριδα καὶ μάχην παροξύνειν, ἁμαρτεῖν δὲ καὶ τὸν ἀδελφὸν αὐτοῦ Ἀσάηλον, ὃς παραινοῦντος μὴ διώκειν οὐκ ἐπείσθη καὶ διὰ τοῦτο βληθεὶς ἀπέθανε, συμφρονήσας καὶ παράκλησιν ἡγησάμενος τούτους τοὺς λόγους ὁ Ἰώαβος ἀνακαλεῖ τῇ σάλπιγγι σημάνας τοὺς στρατιώτας καὶ τῆς ἐπὶ πολὺ διώξεως ἐπισχών. καὶ οὗτος μὲν ἐπ’ ἐκείνου καταστρατοπεδεύεται τοῦ τόπου τὴν νύκτα ταύτην, Ἀβεννῆρος δὲ δι’ ὅλης αὐτῆς ὁδεύσας καὶ περαιωσάμενος τὸν Ἰόρδανον ποταμὸν ἀφικνεῖται πρὸς τὸν τοῦ Σαούλου παῖδα εἰς τὰς Παρεμβολὰς Ἰέβωσθον. τῇ δ’ ἐχομένῃ τοὺς νεκροὺς ὁ Ἰώαβος ἐξαριθμήσας ἅπαντας ἐκήδευσεν. ἔπεσον δὲ τῶν μὲν Ἀβεννήρου στρατιωτῶν ὡς τριακόσιοι καὶ ἑξήκοντα, τῶν δὲ Δαυίδου δέκα πρὸς τοῖς ἐννέα καὶ Ἀσάηλος, οὗ τὸ σῶμα κομίσαντες ἐκεῖθεν Ἰώαβος καὶ Ἀβεσσαῖος εἰς Βηθλεέμην καὶ θάψαντες ἐν τῷ πατρῴῳ μνήματι πρὸς Δαυίδην εἰς Γιβρῶνα παρεγένοντο. ἤρξατο μὲν οὖν ἐξ ἐκείνου τοῦ χρόνου τοῖς Ἑβραίοις ἐμφύλιος πόλεμος καὶ διέμεινεν ἄχρι πολλοῦ, τῶν μὲν μετὰ Δαυίδου κρειττόνων ἀεὶ γινομένων καὶ πλεῖον ἐν τοῖς κινδύνοις φερομένων, τοῦ δὲ Σαούλου παιδὸς καὶ τῶν ὑπηκόων αὐτοῦ κατὰ πᾶσαν σχεδὸν ἡμέραν ἐλαττουμένων.", "st": "7.1.3"}, {"sp": "N", "t": "Ἐγένοντο δὲ κατὰ τοῦτον τὸν καιρὸν καὶ παῖδες Δαυίδῃ τὸν ἀριθμὸν ἓξ [ἐκ γυναικῶν τοσούτων], ὧν ὁ μὲν πρεσβύτατος ἐκ μητρὸς Ἀχίνας γενόμενος Ἀμνὼν ἐκλήθη, ὁ δὲ δεύτερος ἐκ γυναικὸς Ἀβιγαίας Δανίηλος, τῷ τρίτῳ δ’ ἐκ τῆς Θολομαίου θυγατρὸς Μαχάμης φύντι τοῦ Γεσσιρῶν βασιλέως Ἀψάλωμος ὄνομα, τὸν δὲ τέταρτον Ἀδωνίαν ἐκ γυναικὸς Ἀήθης προσηγόρευσε, τὸν πέμπτον δὲ Σαφατίαν τῆς Ἀβιτάλης καὶ τὸν ἕκτον Γεθερσὰν τῆς Γαλαὰδ ἐπωνόμασε. τοῦ δ’ ἐμφυλίου πολέμου συνεστῶτος καὶ συμπιπτόντων εἰς ἔργα καὶ μάχην πυκνῶς μεθ’ ἑκατέρου τῶν βασιλέων, Ἀβεννῆρος ὁ τοῦ Σαούλου παιδὸς ἀρχιστράτηγος συνετὸς ὢν καὶ σφόδρα εὔνουν ἔχων τὸ πλῆθος πάντας συμμεῖναι [τῷ Ἰεβόσθῳ] παρεσκεύασε· καὶ διέμειναν ἱκανὸν χρόνον τὰ ἐκείνου φρονοῦντες. ὕστερον δ’ ἐν ἐγκλήματι γενόμενος Ἀβεννῆρος καὶ λαβὼν αἰτίαν ὡς συνέλθοι τῇ Σαούλου παλλακῇ Ῥαισφᾶ μὲν τοὔνομα Σιβάτου δὲ θυγατρί, καὶ καταμεμφθεὶς ὑπὸ Ἰεβώσθου περιαλγήσας καὶ θυμωθείς, ὡς οὐ δικαίων τῶν παρ’ αὐτοῦ τυγχάνοι πάσῃ προνοίᾳ περὶ αὐτὸν χρώμενος, ἠπείλησε μὲν τὴν βασιλείαν εἰς Δαυίδην περιστήσειν, ἐπιδείξειν δὲ ὡς οὐχὶ διὰ τὴν ἰδίαν ῥώμην καὶ σύνεσιν ἄρχοι τῶν πέραν Ἰορδάνου, διὰ δὲ τὴν αὐτοῦ στρατηγίαν τε καὶ πίστιν. καὶ πέμψας εἰς Γιβρῶνα παρὰ Δαυίδην λαβεῖν ὅρκους τε καὶ πίστεις ἠξίου, ἦ μὴν ἕξειν αὐτὸν ἑταῖρον καὶ φίλον ἀναπείσαντα τὸν λαὸν τοῦ Σαούλου μὲν ἀποστῆναι παιδός, αὐτὸν δὲ ἀποδείξαντα πάσης τῆς χώρας βασιλέα. τοῦ δὲ Δαυίδου ποιησαμένου τὰς ὁμολογίας, ἥσθη γὰρ ἐφ’ οἷς Ἀβεννῆρος διεπρεσβεύσατο πρὸς αὐτόν, καὶ πρῶτον τεκμήριον παρασχεῖν τῶν συνθηκῶν ἀξιώσαντος ἀνασώσαντα πρὸς αὐτὸν [Μελχάλην] τὴν γυναῖκα μεγάλοις ὠνηθεῖσαν ὑπ’ αὐτοῦ κινδύνοις καὶ Παλαιστίνων κεφαλαῖς ἑξακοσίαις, ἃς ὑπὲρ αὐτῆς ἐκόμισε τῷ πατρὶ Σαούλῳ, πέμπει μὲν αὐτῷ τὴν Μελχάλην ἀποσπάσας Ὀφελτίου τοῦ τότε συνοικοῦντος αὐτῇ, πρὸς τοῦτο καὶ Ἰεβώσθου συμπράξαντος· ἐγεγράφει γὰρ αὐτῷ Δαυίδης τὴν γυναῖκα δικαίως ἀπολαβεῖν· συγκαλέσας δὲ τοὺς γεγηρακότας τοῦ πλήθους καὶ ταξιάρχους καὶ χιλιάρχους λόγους ἐποιήσατο πρὸς αὐτούς, ὡς ἔχοντας ἑτοίμως ἀποστῆναι μὲν Ἰεβώσθου Δαυίδῃ δὲ προσθέσθαι ταύτης ἀποστρέψειε τῆς ὁρμῆς, νῦν μέντοι γε ἐπιτρέποι χωρεῖν ᾗ βούλονται· καὶ γὰρ εἰδέναι τὸν θεὸν διὰ Σαμουήλου τοῦ προφήτου Δαυίδην χειροτονήσαντα πάντων Ἑβραίων βασιλέα, προειπεῖν δ’ ὅτι Παλαιστίνους ἐκεῖνος αὐτὸς τιμωρήσεται καὶ ποιήσει κρατήσας ὑποχειρίους. ταῦτ’ ἀκούσαντες οἱ πρεσβύτεροι καὶ ἡγεμόνες, ὡς τὴν Ἀβεννήρου γνώμην ᾗ πρότερον εἶχον αὐτοὶ περὶ τῶν πραγμάτων σύμφωνον προσέλαβον, τὰ Δαυίδου φρονεῖν μετεβάλοντο. πεισθέντων δὲ τούτων Ἀβεννῆρος συγκαλεῖ τὴν Βενιαμιτῶν φυλήν, οἱ γὰρ ἐκ ταύτης ἅπαντες Ἰεβώσθου σωματοφύλακες ἦσαν, καὶ ταὐτὰ πρὸς αὐτοὺς διαλεχθείς, ἐπειδὴ μὴ ἀντικρούοντας ἑώρα, προστιθεμένους δ’ οἷς ἐβούλετο, παραλαβὼν ὡς εἴκοσι τῶν ἑταίρων ἧκε πρὸς Δαυίδην τοὺς ὅρκους παρ’ αὐτοῦ ληψόμενος αὐτός, πιστότερα γὰρ τῶν δι’ ἄλλου πραττομένων ὅσα δι’ αὑτῶν ἕκαστοι ποιοῦμεν εἶναι δοκεῖ, καὶ προσέτι τοὺς γενομένους αὐτῷ λόγους πρός τε τοὺς ἡγεμόνας καὶ πρὸς τὴν φυλὴν ἅπασαν σημανῶν. ὑποδεξαμένου δ’ αὐτὸν φιλοφρόνως καὶ λαμπρᾷ καὶ πολυτελεῖ τραπέζῃ ξενίσαντος ἐπὶ πολλὰς ἡμέρας, ἠξίωσεν ἀφεθεὶς ἀγαγεῖν τὸ πλῆθος, ἵνα παρόντι καὶ βλεπομένῳ παραδῶσι τὴν ἀρχήν.", "st": "7.1.4"}, {"sp": "N", "t": "Ἐκπέμψαντος δὲ τοῦ Δαυίδου τὸν Ἀβεννῆρον οὐδὲ ὀλίγον διαλιπὼν εἰς Γιβρῶνα ἧκεν Ἰώαβος ὁ ἀρχιστράτηγος αὐτοῦ, καὶ μαθών, ὡς εἴη παρὼν πρὸς αὐτὸν Ἀβεννῆρος καὶ μικρὸν ἔμπροσθεν ἀπηλλαγμένος ἐπὶ συνθήκαις καὶ ὁμολογίαις τῆς ἡγεμονίας, δείσας μὴ τὸν μὲν ἐν τιμῇ καὶ τῇ πρώτῃ ποιήσεται τάξει συνεργόν τε τῆς βασιλείας ἐσόμενον καὶ τἆλλα δεινὸν ὄντα συνιδεῖν πράγματα καὶ τοὺς καιροὺς ὑποδραμεῖν, αὐτὸς δ’ ἐλαττωθείη καὶ τῆς στρατηγίας ἀφεθείη, κακοῦργον καὶ πονηρὰν ὁδὸν ἄπεισι. [καὶ] πρῶτον μὲν ἐπιχειρεῖ διαβαλεῖν αὐτὸν πρὸς τὸν βασιλέα φυλάττεσθαι παραινῶν καὶ μὴ προσέχειν οἷς Ἀβεννῆρος συντίθεται· πάντα γὰρ ποιεῖν αὐτὸν ἐπὶ τῷ βεβαιώσασθαι τῷ Σαούλου παιδὶ τὴν ἡγεμονίαν· ἐπὶ δὲ ἀπάτῃ καὶ δόλῳ πρὸς αὐτὸν ἐλθόντα μεθ’ ἧς ἐβούλετο νῦν ἐλπίδος καὶ οἰκονομίας τῶν κατασκευαζομένων ἀπελθεῖν. ὡς δ’ οὐκ ἔπειθε τὸν Δαυίδην τούτοις οὐδὲ παροξυνόμενον ἑώρα, τρέπεται ταύτης τολμηροτέραν ὁδὸν καὶ κρίνας Ἀβεννῆρον ἀποκτεῖναι πέμπει τοὺς ἐπιδιώξοντας, οἷς καταλαβοῦσι προσέταξεν αὐτὸν καλεῖν ἐκ τοῦ Δαυίδου ὀνόματος, ὡς ἔχοντος αὐτοῦ τινα περὶ τῶν πραγμάτων πρὸς αὐτὸν ἃ μὴ διεμνημόνευσε παρόντος εἰπεῖν. Ἀβεννῆρος δ’ ὡς ἤκουσε τὰ παρὰ τῶν ἀγγέλων, κατέλαβον αὐτὸν ἐν τόπῳ τινὶ Βησηρᾶ καλουμένῳ ἀπέχοντι τῆς Γιβρῶνος σταδίους εἴκοσι, μηδὲν ὑπιδόμενος τῶν συμβησομένων ὑπέστρεψεν. ἀπαντήσας δ’ αὐτῷ πρὸς τῇ πύλῃ Ἰώαβος καὶ δεξιωσάμενος ὡς μάλιστ’ εὔνους καὶ φίλος, ὑποκρίνονται γὰρ ἱκανῶς πολλάκις εἰς τὸ ἀνύποπτον τῆς ἐπιβουλῆς τὰ τῶν ἀληθῶς ἀγαθῶν οἱ πράγμασιν ἐγχειροῦντες ἀτόποις, ἀποσπᾷ μὲν τῶν οἰκείων αὐτὸν ὡς ἐν ἀπορρήτῳ διαλεξόμενος, παραγαγὼν δὲ εἰς τὸ ἐρημότερον τῆς πύλης μόνος αὐτὸς ὢν σὺν Ἀβεσσαίῳ τῷ ἀδελφῷ σπασάμενος τὴν μάχαιραν ὑπὸ τὴν λαγόνα παίει. καὶ τελευτᾷ μὲν Ἀβεννῆρος τοῦτον ἐνεδρευθεὶς τὸν τρόπον ὑπὸ Ἰωάβου, ὡς μὲν αὐτὸς ἔλεγε τιμωρήσαντος Ἀσαήλῳ τῷ ἀδελφῷ, ὃν διώκοντα λαβὼν Ἀβεννῆρος ἀπέκτεινεν ἐν τῇ πρὸς Γιβρῶνι μάχῃ, ὡς δὲ τἀληθὲς εἶχε δείσαντος περὶ τῆς στρατηγίας καὶ τῆς παρὰ τῷ βασιλεῖ τιμῆς, μὴ τούτων μὲν αὐτὸς ἀφαιρεθείη, λάβοι δὲ παρὰ Δαυίδου τὴν πρώτην τάξιν Ἀβεννῆρος. ἐκ τούτων ἄν τις κατανοήσειεν, ὅσα καὶ πηλίκα τολμῶσιν ἄνθρωποι πλεονεξίας ἕνεκα καὶ ἀρχῆς καὶ τοῦ μηδενὶ τούτων παραχωρῆσαι· κτήσασθαι γὰρ αὐτὰ ποθοῦντες διὰ μυρίων κακῶν λαμβάνουσι, καὶ δείσαντες ἀποβαλεῖν πολλῷ χείροσι τὸ βέβαιον αὑτοῖς τῆς παραμονῆς περιποιοῦσιν, ὡς οὐχ ὁμοίου δεινοῦ τυγχάνοντος πορίσασθαι τηλικοῦτον μέγεθος ἐξουσίας, καὶ συνήθη τοῖς ἀπ’ αὐτῆς ἀγαθοῖς γενόμενον ἔπειτ’ αὐτὴν ἀπολέσαι, τούτου δὲ ὑπερβολὴν ἔχοντος συμφορᾶς. καὶ διὰ τοῦτο χαλεπώτερα μηχανῶνται καὶ τολμῶσιν ἐν φόβῳ ἔργα πάντες τοῦτ’ ἀποβαλεῖν γενόμενοι. ἀλλὰ περὶ μὲν τούτων ἐν βραχέσιν ἀρκεῖ δεδηλῶσθαι.", "st": "7.1.5"}, {"sp": "N", "t": "Δαυίδης δ’ ἀκούσας ἀνῃρημένον τὸν Ἀβεννῆρον ἤλγησε μὲν τὴν ψυχήν, ἐμαρτύρατο δὲ πάντας ἀνατείνων εἰς τὸν θεὸν τὴν δεξιὰν καὶ βοῶν, ὡς οὔτε κοινωνὸς εἴη τῆς Ἀβεννήρου σφαγῆς, οὔτε κατ’ ἐντολὴν καὶ βούλησιν ἰδίαν ἀποθάνοι. ἀρὰς δὲ κατὰ τοῦ πεφονευκότος αὐτὸν δεινὰς ἐτίθετο καὶ τὸν οἶκον ὅλον αὐτοῦ καὶ τοὺς συμπράξαντας ὑπευθύνους ἐποιεῖτο ταῖς ὑπὲρ τοῦ τετελευτηκότος ποιναῖς· ἔμελε γὰρ αὐτῷ μὴ δόξαι παρὰ τὰς πίστεις καὶ τοὺς ὅρκους οὓς ἔδωκεν Ἀβεννήρῳ τοῦτο εἰργάσθαι. προσέταξε μέντοι γε παντὶ τῷ λαῷ κλαίειν καὶ πενθεῖν τὸν ἄνδρα καὶ τοῖς νομιζομένοις τιμᾶν αὐτοῦ τὸ σῶμα περιρρηξαμένῳ μὲν τὰς ἐσθῆτας ἐνδύντι δὲ σάκκους, ταῦτα δὲ ποιεῖν προάγοντας τὴν κλίνην. αὐτὸς δ’ ἐφείπετο μετὰ τῶν γεγηρακότων καὶ τῶν ἐν ἡγεμονίαις ὄντων κοπτόμενός τε καὶ τοῖς δακρύοις ἐνδεικνύμενος τό τε εὔνουν τὸ πρὸς [τὸν] ζῶντα καὶ τὴν ἐπὶ τεθνηκότι λύπην, καὶ ὅτι μὴ κατὰ τὴν αὐτοῦ γνώμην ἀνῄρηται. θάψας δ’ αὐτὸν ἐν Γιβρῶνι μεγαλοπρεπῶς καὶ ἐπιταφίους τε συγγραψάμενος θρήνους αὐτὸς ἐπὶ τοῦ τάφου στὰς πρῶτος ἀνεκλαύσατο καὶ παρέδωκε τοῖς ἄλλοις. οὕτως δ’ αὐτὸν ὁ Ἀβεννήρου συνέσχε θάνατος, ὡς μηδὲ τροφὴν ἀναγκαζόντων αὐτὸν τῶν ἑταίρων λαβεῖν, ἀλλ’ ὤμοσε γεύσεσθαι μηδενὸς ἄχρι ἡλίου δυσμῶν. ταῦτ’ εὔνοιαν αὐτῷ παρὰ τοῦ πλήθους ἐγέννησεν· οἵ τε γὰρ πρὸς τὸν Ἀβεννῆρον φιλοστόργως διακείμενοι σφόδρ’ αὐτοῦ τὴν πρὸς αὐτὸν τιμὴν ἀποθανόντα καὶ φυλακὴν τῆς πίστεως ἠγάπησαν, ὅτι πάντων αὐτὸν ἀξιώσειεν τῶν νομιζομένων ὡς συγγενῆ καὶ φίλον, ἀλλ’ οὐχ ὡς ἐχθρὸν γενόμενον ὑβρίσειεν ἀκόσμῳ ταφῇ καὶ ἠμελημένῃ· τό τε ἄλλο πᾶν ὡς ἐπὶ χρηστῷ καὶ ἡμέρῳ τὴν φύσιν ἔχαιρε, τὴν αὐτὴν ἑκάστου λογιζομένου πρόνοιαν εἰς αὑτὸν τοῦ βασιλέως ἐν τοῖς ὁμοίοις τυγχάνοντα τὸν Ἀβεννήρου νεκρὸν ἑώρα. πρὸς τούτοις οὖν μάλιστα Δαυίδην γλίχεσθαι δόξης ἀγαθῆς ποιούμενον πρόνοιαν ὡς εἰκὸς ἣν οὐθεὶς ὑπενόησεν ὑπ’ αὐτοῦ φονευθῆναι τὸν Ἀβεννῆρον· ἔλεξε δὲ καὶ πρὸς τὸ πλῆθος, ὡς αὐτῷ μὲν οὐχ ἡ τυχοῦσα λύπη γένοιτ’ ἀνδρὸς ἀγαθοῦ τετελευτηκότος, οὐ μικρὰ δὲ τοῖς Ἑβραίων πράγμασι βλάβη στερηθέντων αὐτοῦ καὶ συνέχειν αὐτὰ καὶ σώζειν βουλαῖς τε ἀρίσταις καὶ ῥώμῃ χειρῶν ἐν τοῖς πολεμικοῖς ἔργοις δυναμένου. ἀλλὰ θεὸς μέν, εἶπεν, ᾧ μέλει πάντων, οὐκ ἐάσει τοῦτον ἡμῖν ἀνεκδίκητον· ἐγὼ δ’ ἐπίστασθε, ὡς οὐδὲν Ἰώαβον καὶ Ἀβεσσαῖον τοὺς Σαρουίας παῖδας ποιεῖν ἱκανός εἰμι πλέον ἐμοῦ δυναμένους, ἀλλ’ ἀποδώσει τὴν ὑπὲρ τῶν τετολμημένων αὐτοῖς ἀμοιβὴν τὸ θεῖον. καὶ Ἀβεννῆρος μὲν εἰς τοιοῦτο κατέστρεψε τέλος τὸν βίον.", "st": "7.1.6"}, {"sp": "N", "t": "Ἀκούσας δὲ τὴν τελευτὴν αὐτοῦ ὁ Σαούλου παῖς Ἰέβωσθος οὐ πρᾴως ἤνεγκεν ἀνδρὸς ἐστερημένος συγγενοῦς καὶ τὴν βασιλείαν αὐτῷ παρασχόντος, ἀλλ’ ὑπερεπάθησε καὶ λίαν αὐτὸν ὠδύνησεν ὁ Ἀβεννήρου θάνατος. ἐπεβίω δ’ οὐδ’ αὐτὸς πολὺν χρόνον, ἀλλ’ ὑπὸ τῶν Ἐρέμμωνος υἱῶν Βανά, ἑτέρῳ δὲ Θαηνὸς ὄνομα ἦν, ἐπιβουλευθεὶς ἀπέθανεν. οὗτοι γὰρ ὄντες τὸ μὲν γένος Βενιαμῖται τοῦ δὲ πρώτου τάγματος, λογισάμενοι δ’ ὡς ἂν ἀποκτείνωσι τὸν Ἰέβωσθον μεγάλων παρὰ Δαυίδου τεύξονται δωρεῶν καὶ στρατηγίας ἤ τινος ἄλλης πίστεως τὸ ἔργον αὐτοῖς ἔσται παρ’ αὐτῷ αἴτιον, μόνον εὑρόντες μεσημβρίζοντα καὶ κοιμώμενον τὸν Ἰέβωσθον καὶ μήτε τοὺς φύλακας παρόντας μήτε τὴν θυρωρὸν ἐγρηγορυῖαν, ἀλλὰ καὶ αὐτὴν ὑπό τε τοῦ κόπου καὶ τῆς ἐργασίας ἣν μετεχειρίζετο καὶ τοῦ καύματος εἰς ὕπνον καταπεσοῦσαν, παρελθόντες εἰς τὸ δωμάτιον, ἐν ᾧ συνέβαινε κατακεκοιμῆσθαι τὸν Σαούλου παῖδα, κτείνουσιν αὐτόν. καὶ τὴν κεφαλὴν ἀποτεμόντες καὶ δι’ ὅλης νυκτὸς καὶ ἡμέρας ποιησάμενοι τὴν πορείαν, ὡς ἂν φεύγοντες ἐκ τῶν ἠδικημένων πρὸς τὸν ληψόμενόν τε τὴν χάριν καὶ παρέξοντα τὴν ἀσφάλειαν, εἰς Γιβρῶνα παρεγένοντο· καὶ τὴν κεφαλὴν ἐπιδείξαντες τῷ Δαυίδῃ τὴν Ἰεβώσθου συνίστων αὑτοὺς ὡς εὔνους καὶ τὸν ἐχθρὸν αὐτοῦ καὶ τῆς βασιλείας ἀνταγωνιστὴν ἀνῃρηκότας. ὁ δ’ οὐχ ὡς ἤλπιζον οὕτως αὐτῶν προσεδέξατο τὸ ἔργον, ἀλλ’ εἰπών, ὦ κάκιστοι καὶ παραχρῆμα δίκην ὑφέξοντες, οὐκ ἔγνωτε πῶς ἐγὼ τὸν Σαούλου φονέα καὶ τὸν κομίσαντά μοι τὸν χρυσοῦν αὐτοῦ στέφανον ἠμυνάμην, καὶ ταῦτα ἐκείνῳ χαριζόμενον τὴν ἀναίρεσιν, ἵνα μὴ συλλάβωσιν αὐτὸν οἱ πολέμιοι; ἦ μεταβεβλῆσθαί με καὶ μηκέτ’ εἶναι τὸν αὐτὸν ὑπωπτεύσατε, ὡς χαίρειν κακούργοις ἀνδράσι καὶ χάριτας ἡγήσασθαι τὰς κυριοκτόνους ὑμῶν πράξεις, ἀνῃρηκότων ἐπὶ τῆς αὑτοῦ κοίτης ἄνδρα δίκαιον καὶ μηδένα μηδὲν κακὸν εἰργασμένον, ὑμᾶς δὲ καὶ διὰ πολλῆς εὐνοίας καὶ τιμῆς ἐσχηκότα; διὸ δώσετε ποινὴν μὲν αὐτῷ κολασθέντες, δίκην δ’ ἐμοὶ τοῦ νομίσαντας ἡδέως ἕξειν με τὴν Ἰεβώσθου τελευτὴν τοῦτον ἀνελεῖν· οὐ γὰρ ἐδύνασθε μᾶλλον ἀδικῆσαι τὴν ἐμὴν δόξαν ἢ τοῦθ’ ὑπολαβόντες. ταῦτ’ εἰπὼν πᾶσαν αἰκίαν αὐτοὺς αἰκισάμενος διεχρήσατο καὶ τὴν Ἰεβώσθου κεφαλὴν ἐν τῷ Ἀβεννήρου τάφῳ πάντων ἀξιώσας ἐκήδευσε.", "st": "7.2.1"}, {"sp": "N", "t": "Τούτων δὲ τοιοῦτον λαβόντων τέλος ἧκον ἅπαντες οἱ τοῦ λαοῦ τῶν Ἑβραίων πρῶτοι πρὸς Δαυίδην εἰς Γιβρῶνα οἵ τε χιλίαρχοι καὶ ἡγεμόνες αὐτῶν, καὶ παρεδίδοσαν αὑτοὺς τήν τε εὔνοιαν, ἣν ἔτι καὶ Σαούλου ζῶντος εἶχον πρὸς αὐτόν, ὑπομιμνήσκοντες καὶ τὴν τιμήν, ἣν γενόμενον τότε χιλίαρχον τιμῶντες οὐ διέλιπον, ὅτι τε βασιλεὺς ὑπὸ τοῦ θεοῦ διὰ Σαμουήλου τοῦ προφήτου χειροτονηθείη καὶ παῖδες αὐτοῦ καὶ ὡς τὴν Ἑβραίων χώραν αὐτῷ σῶσαι καταγωνισαμένῳ Παλαιστίνους δέδωκεν ὁ θεὸς ἐμφανίζοντες. ὁ δὲ ταύτης τε ἀποδέχεται τῆς προθυμίας αὐτοὺς καὶ παρακαλέσας διαμένειν, οὐ γὰρ ἔσεσθαι μετάνοιαν αὐτοῖς ἐκ τοῦ τοιούτου, καὶ κατευωχήσας καὶ φιλοφρονησάμενος ἔπεμψε τὸν λαὸν παρ’ αὐτὸν ἄξοντας ἅπαντα. καὶ συνῆλθον ἐκ μὲν τῆς Ἰούδα φυλῆς ὁπλιτῶν ὡς ὀκτακόσιοι καὶ ἑξακισχίλιοι φοροῦντες ὅπλα θυρεὸν καὶ σιρομάστην· οὗτοι δὲ τῷ Σαούλου παιδὶ παρέμενον· τούτων γὰρ χωρὶς ἡ Ἰούδα φυλὴ τὸν Δαυίδην ἀπέδειξε βασιλέα. ἐκ δὲ τῆς Συμεωνίδος φυλῆς ἑπτακισχίλιοι καὶ ἑκατόν. ἐκ δὲ τῆς Ληουίτιδος τετρακισχίλιοι καὶ ἑπτακόσιοι ἔχοντες ἄρχοντα Ἰώδαμον· μετὰ τούτοις ἦν ὁ ἀρχιερεὺς Σάδωκος σὺν εἴκοσι δύο συγγενέσιν ἡγεμόσιν. ἐκ δὲ τῆς Βενιαμίτιδος φυλῆς ὁπλῖται τετρακισχίλιοι· ἡ γὰρ φυλὴ περιέμενεν ἔτι τῶν τοῦ γένους Σαούλου τινὰ βασιλεύσειν προσδοκῶσα. ἐκ δὲ τῆς Ἐφραίμου φυλῆς δισμύριοι καὶ ὀκτακόσιοι τῶν δυνατωτάτων καὶ κατ’ ἰσχὺν διαφερόντων. ἐκ δὲ τῆς Μανασσήτιδος φυλῆς τοῦ ἡμίσους μύριοι ὀκτακισχίλιοι [τῶν δυνατωτάτων]. ἐκ δὲ τῆς Ἰσαχάρου φυλῆς διακόσιοι μὲν οἱ προγινώσκοντες τὰ μέλλοντα, ὁπλῖται δὲ δισμύριοι. ἐκ δὲ τῆς Ζαβουλωνίτιδος φυλῆς ὁπλιτῶν ἐπιλέκτων πέντε μυριάδες· αὕτη γὰρ ἡ φυλὴ μόνη πᾶσα πρὸς Δαυίδην συνῆλθεν· οὗτοι πάντες τὸν αὐτὸν ὁπλισμὸν εἶχον τοῖς τῆς Γάδου φυλῆς. ἐκ δὲ τῆς Νεφθαλίδος φυλῆς ἐπίσημοι καὶ ἡγεμόνες χίλιοι ὅπλοις χρώμενοι θυρεῷ καὶ δόρατι, ἠκολούθει δὲ φυλὴ ἀναρίθμητος οὖσα. ἐκ δὲ τῆς Δανίτιδος φυλῆς ἐκλεκτοὶ δισμύριοι ἑπτακισχίλιοι ἑξακόσιοι. ἐκ δὲ τῆς Ἀσήρου φυλῆς μυριάδες τέσσαρες. ἐκ δὲ τῶν δύο φυλῶν τῶν πέραν τοῦ Ἰορδάνου καὶ τοῦ λοιποῦ τῆς Μανασσήτιδος φυλῆς ὡπλισμένων θυρεὸν καὶ δόρυ καὶ περικεφαλαίαν καὶ ῥομφαίαν μυριάδες δώδεκα· καὶ αἱ λοιπαὶ φυλαὶ ῥομφαίαις ἐχρῶντο. τοῦτο δὴ πᾶν τὸ πλῆθος εἰς Γιβρῶνα πρὸς Δαυίδην συνῆλθε μετὰ πολλῆς παρασκευῆς σιτίων καὶ οἴνου καὶ τῶν πρὸς τροφὴν πάντων καὶ μιᾷ γνώμῃ βασιλεύειν τὸν Δαυίδην ἐκύρωσαν. ἐπὶ δὲ τρεῖς ἡμέρας ἑορτάσαντος τοῦ λαοῦ καὶ κατευωχηθέντος ἐν Γιβρῶνι, ὁ Δαυίδης μετὰ πάντων ἐκεῖθεν ἄρας ἧκεν εἰς Ἱεροσόλυμα.", "st": "7.2.2"}, {"sp": "N", "t": "Τῶν δὲ κατοικούντων τὴν πόλιν Ἰεβουσαίων, γένος δ’ εἰσὶν οὗτοι Χαναναίων, ἀποκλεισάντων αὐτῷ τὰς πύλας καὶ τοὺς πεπηρωμένους τὰς ὄψεις καὶ τὰς βάσεις καὶ πᾶν τὸ λελωβημένον στησάντων ἐπὶ χλεύῃ τοῦ βασιλέως ἐπὶ τοῦ τείχους καὶ λεγόντων κωλύσειν αὐτὸν εἰσελθεῖν τοὺς ἀναπήρους, ταῦτα δ’ ἔπραττον καταφρονοῦντες τῇ τῶν τειχῶν ὀχυρότητι, ὀργισθεὶς πολιορκεῖν ἤρξατο τὰ Ἱεροσόλυμα. καὶ πολλῇ σπουδῇ καὶ προθυμίᾳ χρησάμενος ὡς διὰ τοῦ ταύτην ἑλεῖν εὐθὺς ἐμφανίζων τὴν ἰσχὺν καὶ καταπληξόμενος εἴ τινες ἄρα καὶ ἄλλοι τὸν αὐτὸν ἐκείνοις τρόπον διέκειντο πρὸς αὐτόν, λαμβάνει κατὰ κράτος τὴν κάτω πόλιν. ἔτι δὲ τῆς ἄκρας λειπομένης ἔγνω τιμῆς ὑποσχέσει καὶ γερῶν ὁ βασιλεὺς προθυμοτέρους ἐπὶ τὰ ἔργα τοὺς στρατιώτας παρασκευάσαι, καὶ τῷ διὰ τῶν ὑποκειμένων φαράγγων ἐπὶ τὴν ἄκραν ἀναβάντι καὶ ταύτην ἑλόντι στρατηγίαν ἅπαντος τοῦ λαοῦ δώσειν ἐπηγγείλατο. πάντων δὲ φιλοτιμουμένων ἀναβῆναι καὶ μηδένα πόνον ὀκνούντων ὑφίστασθαι δι’ ἐπιθυμίαν τῆς στρατηγίας, ὁ Σαρουίας παῖς Ἰώαβος ἔφθη τοὺς ἄλλους, καὶ ἀναβὰς ἐβόησε πρὸς τὸν βασιλέα τὴν στρατηγίαν ἀπαιτῶν.", "st": "7.3.1"}, {"sp": "N", "t": "Ἐκβαλὼν δὲ τοὺς Ἰεβουσαίους ἐκ τῆς ἄκρας καὶ αὐτὸς ἀνοικοδομήσας τὰ Ἱεροσόλυμα πόλιν αὐτὴν Δαυίδου προσηγόρευσε, καὶ τὸν ἅπαντα χρόνον ἐν αὐτῇ διέτριβε βασιλεύων. ὁ δὲ χρόνος ὃν τῆς Ἰούδα φυλῆς ἦρξε μόνης ἐν Γιβρῶνι ἐγένετο ἔτη ἑπτὰ καὶ μῆνες ἕξ. ἀποδείξας δὲ βασίλειον τὰ Ἱεροσόλυμα λαμπροτέροις αἰεὶ καὶ μᾶλλον ἐχρῆτο τοῖς πράγμασι τοῦ θεοῦ προνοουμένου κρείττω ποιεῖν αὐτὰ καὶ λαμβάνειν ἐπίδοσιν. πέμψας δὲ πρὸς αὐτὸν καὶ Ἱέρωμος ὁ Τυρίων βασιλεὺς φιλίαν καὶ συμμαχίαν συνέθετο· ἔπεμψε δ’ αὐτῷ καὶ δωρεὰς ξύλα κέδρινα καὶ τεχνίτας ἄνδρας τέκτονας καὶ οἰκοδόμους, οἳ κατεσκεύασαν βασίλειον ἐν Ἱεροσολύμοις. Δαυίδης δὲ τήν τε ἄνω πόλιν παραλαβὼν καὶ τὴν ἄκραν συνάψας αὐτῇ ἐποίησεν ἓν σῶμα, καὶ περιτειχίσας ἐπιμελητὴν τῶν τειχῶν κατέστησεν Ἰώαβον. πρῶτος οὖν Δαυίδης τοὺς Ἰεβουσαίους ἐξ Ἱεροσολύμων ἐκβαλὼν ἀφ’ ἑαυτοῦ προσηγόρευσε τὴν πόλιν· ἐπὶ γὰρ Ἁβράμου τοῦ προγόνου ἡμῶν Σόλυμα ἐκαλεῖτο, μετὰ ταῦτα δὲ αὐτήν φασί τινες, ὅτι καὶ Ὅμηρος ταῦτ’ ὠνόμασεν Ἱεροσόλυμα· τὸ γὰρ ἱεροῦ κατὰ τὴν Ἑβραίων γλῶτταν ὠνόμασε τὰ Σόλυμα ὅ ἐστιν ἀσφάλεια. ἦν δὲ πᾶς ὁ χρόνος ἀπὸ τῆς Ἰησοῦ τοῦ στρατηγοῦ ἐπὶ Χαναναίους στρατείας καὶ τοῦ πολέμου, καθ’ ὃν κρατήσας αὐτῶν κατένειμε ταύτην τοῖς Ἑβραίοις καὶ οὐκέτι τοὺς Χαναναίους ἐκβαλεῖν ἐξ Ἱεροσολύμων ἐδυνήθησαν οἱ Ἰσραηλῖται, μέχρις ὁ Δαυίδης αὐτοὺς ἐξεπολιόρκησεν, ἔτη πεντακόσια καὶ δέκα καὶ πέντε.", "st": "7.3.2"}, {"sp": "N", "t": "Ποιήσομαι δὲ καὶ μνήμην Ὀρόνα πλουσίου μὲν ἀνδρὸς τῶν Ἰεβουσαίων, οὐκ ἀναιρεθέντος δὲ ἐν τῇ Ἱεροσολύμων πολιορκίᾳ ὑπὸ Δαυίδου διὰ τὴν πρὸς τοὺς Ἑβραίους εὔνοιαν αὐτοῦ καί τινα καὶ χάριν καὶ σπουδὴν πρὸς αὐτὸν γενομένην τὸν βασιλέα, ἣν μικρὸν ὕστερον εὐκαιρότερον σημανῶ. ἔγημε δὲ καὶ ἄλλας γυναῖκας πρὸς ταῖς οὔσαις αὐτῷ Δαυίδης καὶ παλλακὰς ἔσχεν. ἐποιήσατο δὲ καὶ παῖδας ἐννέα τὸν ἀριθμόν, οὓς προσηγόρευσεν Ἀμασέ, Ἀμνου, Σεβάν, Νάθαν, Σολομῶνα, Ἰεβαρῆ, Ἐλιήν, Φαλναγέην, Ναφήν, Ἰεναέ, Ἐλιφαλέ, ἔτι δὲ καὶ θυγατέρα Θαμάραν. τούτων οἱ μὲν ἐννέα ἐξ εὐγενίδων ἦσαν γεγονότες, οὓς δὲ τελευταίους εἰρήκαμεν δύο ἐκ τῶν παλλακίδων. Θαμάρα δὲ ὁμομήτριος Ἀψαλώμῳ ἦν.", "st": "7.3.3"}, {"sp": "N", "t": "Γνόντες δ’ οἱ Παλαιστῖνοι τὸν Δαυίδην βασιλέα ὑπὸ τῶν Ἑβραίων ἀποδεδειγμένον στρατεύουσιν ἐπ’ αὐτὸν εἰς Ἱεροσόλυμα· καὶ καταλαβόμενοι τὴν κοιλάδα τῶν Γιγάντων καλουμένην, τόπος δέ ἐστιν οὐ πόρρω τῆς πόλεως, ἐν αὐτῇ στρατοπεδεύονται. ὁ δὲ τῶν Ἰουδαίων βασιλεύς, οὐδὲν γὰρ ἄνευ προφητείας καὶ τοῦ κελεῦσαι τὸν θεὸν καὶ περὶ τῶν ἐσομένων λαβεῖν ἐγγυητὴν ἐκεῖνον ἑαυτῷ ποιεῖν ἐπέτρεπεν, ἐκέλευσε τὸν ἀρχιερέα τί δοκεῖ τῷ θεῷ καὶ ποδαπὸν ἔσται τὸ τέλος τῆς μάχης προλέγειν αὐτῷ. προφητεύσαντος δὲ νίκην καὶ κράτος ἐξάγει τὴν δύναμιν ἐπὶ τοὺς Παλαιστίνους· καὶ γενομένης συμβολῆς αὐτὸς κατόπιν αἰφνιδίως ἐπιπεσὼν τοῖς πολεμίοις τοὺς μὲν αὐτῶν ἀπέκτεινε, τοὺς δὲ εἰς φυγὴν ἐτρέψατο. ὑπολάβῃ δὲ μηδεὶς ὀλίγην τὴν τῶν Παλαιστίνων στρατιὰν ἐλθεῖν ἐπὶ τοὺς Ἑβραίους τῷ τάχει τῆς ἥττης καὶ τῷ μηδὲν ἔργον ἐπιδείξασθαι γενναῖον μηδὲ μαρτυρίας ἄξιον στοχαζόμενος αὐτῶν τὴν βραδυτῆτα καὶ τὴν ἀγέννειαν, ἀλλὰ γινωσκέτω Συρίαν τε ἅπασαν καὶ Φοινίκην καὶ πρὸς τούτοις ἄλλα ἔθνη πολλὰ καὶ μάχιμα συστρατεῦσαι αὐτοῖς καὶ τοῦ πολέμου κοινωνῆσαι, ὃ καὶ μόνον ἦν αἴτιον τοσαυτάκις αὐτοῖς νικωμένοις καὶ πολλὰς ἀποβαλοῦσι μυριάδας μετὰ μείζονος ἐπιέναι τοῖς Ἑβραίοις δυνάμεως. ἀμέλει καὶ ταύταις πταίσαντες ταῖς μάχαις τριπλάσιος στρατὸς ἐπῆλθε τῷ Δαυίδῃ καὶ εἰς ταὐτὸ χωρίον ἐστρατοπεδεύσατο. πάλιν δὲ τοῦ βασιλέως τῶν Ἰσραηλιτῶν ἐρομένου τὸν θεὸν περὶ τῆς περὶ τὴν μάχην ἐξόδου, προφητεύει ὁ ἀρχιερεὺς ἐν τοῖς ἄλσεσι τοῖς καλουμένοις Κλαυθμῶσι κατέχειν τὴν στρατιὰν οὐκ ἄπωθεν τοῦ τῶν πολεμίων στρατοπέδου, κινεῖν δ’ αὐτὸν μὴ πρότερον μηδ’ ἄρχεσθαι τῆς μάχης. πρὶν ἢ τὰ ἄλση σαλεύεσθαι μὴ πνέοντος ἀνέμου. ὡς δ’ ἐσαλεύθη τὰ ἄλση καὶ ὃν αὐτῷ καιρὸν προεῖπεν ὁ θεὸς παρῆν, οὐδὲν ἐπισχὼν ἐφ’ ἑτοίμην ἤδη καὶ φανερὰν ἐξῆλθε τὴν νίκην· οὐ γὰρ ὑπέμειναν αὐτὸν αἱ τῶν πολεμίων φάλαγγες, ἀλλ’ εὐθὺς ἀπὸ τῆς πρώτης συμβολῆς τραπέντας ἐνέκειτο κτείνων· καὶ διώκει μὲν αὐτοὺς ἄχρι πόλεως Γαζάρων, ἡ δ’ ἐστὶν ὅρος αὐτῶν τῆς χώρας, διαρπάζει δ’ αὐτῶν τὴν παρεμβολὴν καὶ πολὺν εὑρὼν ἐν αὐτῇ πλοῦτον καὶ τοὺς θεοὺς αὐτῶν διέφθειρε.", "st": "7.4.1"}, {"sp": "N", "t": "Τοιαύτης δ’ ἀποβάσης καὶ ταύτης τῆς μάχης ἔδοξε Δαυίδῃ συμβουλευσαμένῳ μετὰ τῶν γερόντων καὶ ἡγεμόνων καὶ χιλιάρχων μεταπέμψασθαι τῶν ὁμοφύλων ἐξ ἁπάσης τῆς χώρας πρὸς αὑτὸν τοὺς ἐν ἀκμῇ τῆς ἡλικίας, ἔπειτα τοὺς ἱερεῖς καὶ Ληουίτας [καὶ] πορευθέντας εἰς Καριαθιάριμα μετακομίσαι τὴν τοῦ θεοῦ κιβωτὸν ἐξ αὐτῆς εἰς Ἱεροσόλυμα καὶ θρησκεύειν ἐν αὐτῇ λοιπὸν ἔχοντας αὐτὴν θυσίαις καὶ ταῖς ἄλλαις τιμαῖς, αἷς χαίρει τὸ θεῖον· εἰ γὰρ ἔτι Σαούλου βασιλεύοντος τοῦτ’ ἔπραξαν, οὐκ ἂν δεινὸν οὐδὲν ἔπαθον. συνελθόντος οὖν τοῦ λαοῦ παντός, καθὼς ἐβουλεύσαντο, παραγίνεται ὁ βασιλεὺς ἐπὶ τὴν κιβωτόν, ἣν βαστάξαντες ἐκ τῆς Ἀμιναδάβου οἰκίας οἱ ἱερεῖς καὶ ἐπιθέντες ἐφ’ ἅμαξαν καινὴν ἕλκειν ἀδελφοῖς τε καὶ παισὶν ἐπέτρεψαν μετὰ τῶν βοῶν. προῆγε δ’ ὁ βασιλεὺς καὶ πᾶν σὺν αὐτῷ τὸ πλῆθος ὑμνοῦντες τὸν θεὸν καὶ ᾄδοντες πᾶν εἶδος μέλους ἐπιχώριον σύν τε ἤχῳ ποικίλῳ κρουσμάτων τε καὶ ὀρχήσεων καὶ ψαλμῶν ἔτι δὲ σάλπιγγος καὶ κυμβάλων κατάγοντες τὴν κιβωτὸν εἰς Ἱεροσόλυμα. ὡς δ’ ἄχρι τῆς Χειδῶνος ἅλωνος τόπου τινὸς οὕτω καλουμένου προῆλθον, τελευτᾷ Ὀζᾶς κατ’ ὀργὴν τοῦ θεοῦ· τῶν βοῶν γὰρ ἐπινευσάντων τὴν κιβωτὸν ἐκτείναντα τὴν χεῖρα καὶ κατασχεῖν ἐθελήσαντα, ὅτι μὴ ὢν ἱερεὺς ἥψατο ταύτης, ἀποθανεῖν ἐποίησε. καὶ ὁ μὲν βασιλεὺς καὶ ὁ λαὸς ἐδυσφόρησαν ἐπὶ τῷ θανάτῳ τοῦ Ὀζᾶ, ὁ δὲ τόπος ἐν ᾧ ἐτελεύτησεν Ὀζᾶ διακοπὴ καλεῖται. δείσας δ’ ὁ Δαυίδης καὶ λογισάμενος, μὴ ταὐτὸ πάθῃ τῷ Ὀζᾶ δεξάμενος τὴν κιβωτὸν παρ’ αὑτὸν ἐν τῇ πόλει, ἐκείνου διότι μόνον ἐξέτεινε τὴν χεῖρα πρὸς αὐτὴν οὕτως ἀποθανόντος, οὐκ εἰσδέχεται μὲν αὐτὴν πρὸς αὑτὸν εἰς τὴν πόλιν, ἀλλ’ ἐκνεύσας εἴς τι χωρίον ἀνδρὸς δικαίου, Ὠβαδάρου ἄνομα Ληουίτου τὸ γένος, παρ’ αὐτῷ τὴν κιβωτὸν τίθησιν· ἔμεινε δ’ ἐπὶ τρεῖς ὅλους μῆνας αὐτόθι καὶ τὸν οἶκον τὸν Ὠβαδάρου ηὔξησέ τε καὶ πολλῶν αὐτῷ μετέδωκεν ἀγαθῶν. ἀκούσας δὲ ὁ βασιλεὺς ὅτι ταῦτα συμβέβηκεν Ὠβαδάρῳ καὶ ἐκ πενίας καὶ ταπεινότητος ἀθρόως εὐδαίμων καὶ ζηλωτὸς γέγονε παρὰ πᾶσι τοῖς ὁρῶσι καὶ πυνθανομένοις τὴν οἰκίαν αὐτοῦ, θαρσήσας ὡς οὐδενὸς κακοῦ πειρασόμενος τὴν κιβωτὸν πρὸς αὑτὸν μετακομίζει, τῶν μὲν ἱερέων βασταζόντων αὐτήν, ἑπτὰ δὲ χορῶν οὓς διεκόσμησεν ὁ βασιλεὺς προαγόντων, αὐτοῦ δ’ ἐν κινύρᾳ παίζοντος καὶ κροτοῦντος, ὥστε καὶ τὴν γυναῖκα Μιχάλην Σαούλου δὲ θυγατέρα τοῦ πρώτου βασιλέως ἰδοῦσαν αὐτὸν τοῦτο ποιοῦντα χλευάσαι. εἰσκομίσαντες δὲ τὴν κιβωτὸν τιθέασιν ὑπὸ τὴν σκηνήν, ἣν Δαυίδης ἔπηξεν αὐτῇ, καὶ θυσίας τελείας καὶ εἰρηνικὰς ἀνήνεγκε, καὶ τὸν ὄχλον εἱστίασε πάντα καὶ γυναιξὶ καὶ ἀνδράσι καὶ νηπίοις διαδοὺς κολλυρίδα ἄρτου καὶ ἐσχαρίτην καὶ λάγανον τηγανιστὸν καὶ μερίδα θύματος. καὶ τὸν μὲν λαὸν οὕτως κατευωχήσας ἀπέπεμψεν, αὐτὸς δ’ εἰς τὸν οἶκον [τὸν] αὑτοῦ παραγίνεται.", "st": "7.4.2"}, {"sp": "N", "t": "Παραστᾶσα δὲ αὐτῷ Μιχάλη ἡ γυνὴ Σαούλου δὲ θυγάτηρ τά τε ἄλλα αὐτῷ κατηύχετο καὶ παρὰ τοῦ θεοῦ γενέσθαι ᾔτει πάνθ’ ὅσα παρασχεῖν αὐτῷ δυνατὸν εὐμενεῖ τυγχάνοντι, καὶ δὴ κατεμέμψατο, ὡς ἀκοσμήσειεν ὀρχούμενος ὁ τηλικοῦτος βασιλεὺς καὶ γυμνούμενος ὑπὸ τῆς ὀρχήσεως καὶ [ἐν δούλοις καὶ ἐν] θεραπαινίσιν. ὁ δ’ οὐκ αἰδεῖσθαι ταῦτα ποιήσας εἰς τὸ τῷ θεῷ κεχαρισμένον ἔφασκεν, ὃς αὐτὸν καὶ τοῦ πατρὸς αὐτῆς καὶ τῶν ἄλλων ἁπάντων προετίμησε, παίζειν τε καὶ πολλάκις χορεῦσαι μηδένα τοῦ δόξαι ταῖς θεραπαινίσιν αἰσχρὸν καὶ αὐτῇ τὸ γινόμενον ποιησάμενος λόγον. ἡ Μιχάλη αὕτη Δαυίδῃ μὲν συνοικοῦσα παῖδας οὐκ ἐποιήσατο, γαμηθεῖσα δὲ ὕστερον ᾧ παρέδωκεν αὐτὴν ὁ πατὴρ Σαοῦλος, τότε δὲ ἀποσπάσας αὐτὸς εἶχε, πέντε παῖδας ἔτεκε. καὶ περὶ μὲν τούτων κατὰ χώραν δηλώσομεν.", "st": "7.4.3"}, {"sp": "N", "t": "Ὁρῶν δ’ ὁ βασιλεὺς κατὰ πᾶσαν αὐτῷ τὰ πράγματα σχεδὸν ἡμέραν ἀμείνω γινόμενα ἐκ τῆς τοῦ θεοῦ βουλήσεως ἐνόμιζεν ἐξαμαρτάνειν αὑτὸν, εἰ μένων αὐτὸς ἐν οἴκοις ἐκ κέδρου πεποιημένοις ὑψηλοῖς τε καὶ καλλίστην τὴν ἄλλην κατασκευὴν ἔχουσι περιορᾷ τὴν κιβωτὸν ἐν σκηνῇ κειμένην· ἐβούλετο δὲ τῷ θεῷ κατασκευάσαι ναόν, ὡς Μωυσῆς εἶπε, καὶ περὶ τούτων Νάθᾳ τῷ προφήτῃ διαλεχθείς, ἐπεὶ ποιεῖν ὅτιπερ ὥρμηται προσέταξεν αὐτὸν ὡς τοῦ θεοῦ πρὸς ἅπαντ’ αὐτῷ συνεργοῦ παρόντος, εἶχεν ἤδη περὶ τὴν τοῦ ναοῦ κατασκευὴν προθυμότερον. τοῦ θεοῦ δὲ κατ’ ἐκείνην τὴν νύκτα τῷ Νάθᾳ φανέντος καὶ φράσαι κελεύσαντος τῷ Δαυίδῃ, ὡς τὴν μὲν προαίρεσιν αὐτοῦ καὶ τὴν ἐπιθυμίαν ἀποδέχεται, μηδενὸς μὲν πρότερον εἰς νοῦν βαλομένου ναὸν αὐτῷ κατασκευάσαι. τούτου δὲ ταύτην τὴν διάνοιαν λαβόντος· οὐκ ἐπιτρέπειν δὲ πολλοὺς πολέμους ἠγωνισμένῳ καὶ φόνῳ τῶν ἐχθρῶν μεμιασμένῳ ποιῆσαι ναὸν αὐτῷ. μετὰ μέντοι γε τὸν θάνατον αὐτοῦ γηράσαντος καὶ μακρὸν ἀνύσαντος βίον γενήσεσθαι τὸν ναὸν ὑπὸ τοῦ παιδὸς τοῦ μετ’ αὐτὸν τὴν βασιλείαν παραληψομένου κληθησομένου δὲ Σολομῶνος, οὗ προστήσεσθαι καὶ προνοήσειν ὡς πατὴρ υἱοῦ κατεπηγγέλλετο, τὴν μὲν βασιλείαν τέκνων ἐγγόνοις φυλάξων καὶ παραδώσων, αὐτὸν δὲ τιμωρήσων, ἂν ἁμαρτὼν τύχῃ, νόσῳ καὶ γῆς ἀφορίᾳ. μαθὼν ταῦτα παρὰ τοῦ προφήτου Δαυίδης καὶ περιχαρὴς γενόμενος ἐπὶ τῷ τοῖς ἐγγόνοις αὐτοῦ τὴν ἀρχὴν διαμένουσαν ἐγνωκέναι βεβαίως καὶ τὸν οἶκον αὐτοῦ λαμπρὸν ἐσόμενον καὶ περιβόητον πρὸς τὴν κιβωτὸν παραγίνεται, καὶ πεσὼν ἐπὶ πρόσωπον ἤρξατο προσκυνεῖν καὶ περὶ πάντων εὐχαριστεῖν τῷ θεῷ, ὧν τε αὐτῷ παρέσχηκεν ἤδη ἐκ ταπεινοῦ καὶ ποιμένος εἰς τηλικοῦτο μέγεθος ἡγεμονίας τε καὶ δόξης ἀναγαγών, ὧν τε τοῖς ἐγγόνοις αὐτοῦ καθυπέσχετο, τῆς προνοίας, ἣν Ἑβραίων καὶ τῆς τούτων ἐλευθερίας ἐποιήσατο. ταῦτ’ εἰπὼν καὶ τὸν θεὸν ὑμνήσας ἀπαλλάσσεται.", "st": "7.4.4"}, {"sp": "N", "t": "Διαλιπὼν δὲ ὀλίγον χρόνον ἔγνω δεῖν ἐπὶ τοὺς Παλαιστίνους ἐκστρατεύειν, καὶ μηδὲν ἀργὸν μηδὲ ῥᾴθυμον ἐν τοῖς πράγμασιν ὁρᾶν γινόμενον, ἵν’ ὡς τὸ θεῖον αὐτῷ προεῖπε καταστρεψάμενος τοὺς πολεμίους ἐν εἰρήνῃ τὸ λοιπὸν τοὺς ἐκγόνους αὐτοῦ βασιλεύοντας καταλείποι. καὶ συγκαλέσας πάλιν τὴν στρατιὰν καὶ παραγγείλας αὐτῇ πρὸς πόλεμον ἑτοίμῃ καὶ παρεσκευασμένῃ τυγχάνειν, ὅτ’ ἔδοξεν αὐτῷ καλῶς ἔχειν τὰ παρ’ αὐτῆς ἄρας ἐκ τῶν Ἱεροσολύμων ἐπὶ τοὺς Παλαιστίνους ἧκε. κρατήσας δ’ αὐτῶν τῇ μάχῃ καὶ πολλὴν τῆς χώρας ἀποτεμόμενος καὶ προσορίσας τῇ τῶν Ἑβραίων ἐπὶ τοὺς Μωαβίτας τὸν πόλεμον μετήγαγε, καὶ τὰ μὲν δύο μέρη τῆς στρατιᾶς αὐτῶν τῇ μάχῃ νικήσας διέφθειρε, τὸ δὲ λειπόμενον αἰχμάλωτον ἔλαβε. φόρους δὲ αὐτοῖς ἐπιτάξας κατ’ ἔτος τελεῖν ἐπὶ Ἀρτάζαρον τὸν Ἀραοῦ μὲν υἱὸν βασιλέα δὲ τῆς Σωφηνῆς ἐστράτευσε, καὶ συμβαλὼν αὐτῷ παρὰ τὸν Εὐφράτην ποταμὸν τῶν μὲν πεζῶν αὐτοῦ διέφθειρεν ὡσεὶ δισμυρίους, τῶν δ’ ἱπποτῶν ὡς πεντακισχιλίους. ἔλαβε δὲ καὶ αὐτοῦ ἅρματα χίλια, καὶ τὰ πλείω μὲν αὐτῶν ἠφάνισεν, ἑκατὸν δὲ μόνα προσέταξεν αὑτῷ φυλαχθῆναι.", "st": "7.5.1"}, {"sp": "N", "t": "Ἀκούσας δὲ ὁ Δαμασκοῦ καὶ Σύρων βασιλεὺς Ἄδαδος, ὅτι πολεμεῖ Δαυίδης τὸν Ἀρτάζαρον, φίλος ὢν αὐτῷ μετὰ δυνάμεως ἧκεν ἰσχυρᾶς συμμαχήσων· ἀπήλλαξε δ’ ὡς προσεδόκα συμβαλὼν πρὸς τῷ Εὐφράτῃ ποταμῷ, πταίσας δὲ τῇ μάχῃ πολλοὺς ἀπέβαλε τῶν στρατιωτῶν· ἔπεσον γὰρ ὑπὸ τῶν Ἑβραίων ἀναιρούμενοι τῆς Ἀδάδου δυνάμεως δισμύριοι, οἱ δὲ λοιποὶ πάντες ἔφυγον. μέμνηται δὲ τούτου τοῦ βασιλέως καὶ Νικόλαος ἐν τῇ τετάρτῃ τῶν ἱστοριῶν αὐτοῦ λέγων οὕτως· μετὰ δὲ ταῦτα πολλῷ χρόνῳ ὕστερον τῶν ἐγχωρίων τις Ἄδαδος ὄνομα πλεῖον ἰσχύσας Δαμασκοῦ τε καὶ τῆς ἄλλης Συρίας ἔξω Φοινίκης ἐβασίλευσε. πόλεμον δ’ ἐξενέγκας πρὸς Δαυίδην τὸν βασιλέα τῆς Ἰουδαίας καὶ πολλαῖς μάχαις κριθείς, ὑστάτῃ δὲ παρὰ τὸν Εὐφράτην, ἐν ᾗ ἡττᾶτο, ἄριστος ἔδοξεν εἶναι βασιλέων ῥώμῃ καὶ ἀνδρείᾳ. πρὸς τούτοις δὲ καὶ περὶ τῶν ἀπογόνων αὐτοῦ φησιν, ὡς μετὰ τὴν ἐκείνου τελευτὴν ἐξεδέχοντο παρ’ ἀλλήλων καὶ τὴν βασιλείαν καὶ τὸ ὄνομα, λέγων οὕτως· τελευτήσαντος δὲ ἐκείνου ἀπόγονοι ἐπὶ δέκα γενεὰς ἐβασίλευον ἑκάστου παρὰ τοῦ πατρὸς ἅμα καὶ τὴν ἀρχὴν καὶ τοὔνομα [τούτου] ἐκδεχομένου, ὥσπερ οἱ Πτολεμαῖοι ἐν Αἰγύπτῳ. μέγιστον δὲ ἁπάντων δυνηθεὶς ὁ τρίτος ἀναμαχέσασθαι βουλόμενος τὴν τοῦ προπάτορος ἧτταν στρατεύσας ἐπὶ τοὺς Ἰουδαίους ἐπόρθησε τὴν νῦν Σαμαρεῖτιν καλουμένην γῆν. οὐ διήμαρτε δὲ τῆς ἀληθείας· οὗτος γάρ ἐστιν Ἄδαδος ὁ στρατευσάμενος ἐπὶ Σαμάρειαν Ἀχάβου βασιλεύοντος τῶν Ἰσραηλιτῶν, περὶ οὗ κατὰ χώραν ἐροῦμεν.", "st": "7.5.2"}, {"sp": "N", "t": "Δαυίδης δὲ στρατευσάμενος ἐπὶ Δαμασκὸν καὶ τὴν ἄλλην Συρίαν πᾶσαν αὐτὴν ὑπήκοον ἐποιήσατο, καὶ φρουρὰς ἐν τῇ χώρᾳ καταστήσας καὶ φόρους αὐτοῖς τελεῖν ὁρίσας ὑπέστρεψε· καὶ τάς τε χρυσᾶς φαρέτρας καὶ τὰς πανοπλίας, ἃς οἱ τοῦ Ἀδάδου σωματοφύλακες ἐφόρουν, ἀνέθηκε τῷ θεῷ εἰς Ἱεροσόλυμα, ἃς ὕστερον ὁ τῶν Αἰγυπτίων βασιλεὺς Σούσακος στρατεύσας ἐπὶ τὸν υἱωνὸν αὐτοῦ Ῥοβόαμον ἔλαβε καὶ πολὺν ἄλλον ἐκ τῶν Ἱεροσολύμων ἐξεφόρησε πλοῦτον· ταῦτα μὲν ὅταν ἔλθωμεν ἐπὶ τὸν οἰκεῖον αὐτῶν τόπον δηλώσομεν. ὁ δὲ τῶν Ἑβραίων βασιλεὺς τοῦ θεοῦ συμπνέοντος αὐτῷ καὶ τοὺς πολέμους συγκατορθοῦντος καὶ ταῖς καλλίσταις τῶν Ἀνδραζάρου πόλεων ἐπεστράτευσε Βατταίᾳ καὶ Μάχωνι, καὶ λαβὼν αὐτὰς κατὰ κράτος διήρπασε. χρυσὸς δ’ ἐν αὐταῖς εὑρέθη πάμπολυς καὶ ἄργυρος ἔτι δὲ καὶ χαλκός, ὃν τοῦ χρυσοῦ κρείττον’ ἔλεγον, ἐξ οὗ καὶ Σολόμων τὸ μέγα σκεῦος θάλασσαν δὲ καλούμενον ἐποίησε καὶ τοὺς καλλίστους ἐκείνους λουτῆρας, ὅτε τῷ θεῷ τὸν ναὸν κατεσκεύασεν.", "st": "7.5.3"}, {"sp": "N", "t": "Ὡς δὲ ὁ τῆς Ἀμάθης βασιλεὺς τὰ περὶ τὸν Ἀνδράζαρον ἐπύθετο καὶ τὴν δύναμιν αὐτοῦ διεφθαρμένην ἤκουσε, δείσας περὶ αὑτῷ καὶ τὸν Δαυίδην πρὶν ἐπ’ αὐτὸν ἔλθοι φιλίᾳ καὶ πίστει γνοὺς ἐνδήσασθαι, πέμπει πρὸς αὐτὸν Ἀδώραμον υἱὸν αὐτοῦ καὶ περὶ τοῦ τὸν Ἀνδράζαρον ἐχθρὸν ὄντ’ αὐτῷ πολεμῆσαι χάριν ἔχειν ὁμολογῶν, καὶ συμμαχίαν πρὸς αὐτὸν καὶ φιλίαν ποιούμενος. ἔπεμψε δ’ αὐτῷ καὶ δῶρα σκεύη τῆς ἀρχαίας κατασκευῆς χρύσεα καὶ ἀργύρεα καὶ χάλκεα. Δαυίδης δὲ ποιησάμενος τὴν συμμαχίαν πρὸς τὸν Θαῖνον, τοῦτο γὰρ ἦν ὄνομα τῷ βασιλεῖ τῆς Ἀμάθης, καὶ τὰ δῶρα δεξάμενος ἀπέλυσεν αὐτοῦ τὸν υἱὸν μετὰ τιμῆς τῆς πρεπούσης ἑκατέροις. τὰ δὲ πεμφθέντα ὑπ’ αὐτοῦ καὶ τὸν ἄλλον χρυσὸν καὶ ἄργυρον, ὃν ἐκ τῶν πόλεων εἰλήφει καὶ τῶν κεχειρωμένων ἐθνῶν, φέρων ἀνατίθησι τῷ θεῷ. οὐκ αὐτῷ δὲ πολεμοῦντι μόνον καὶ τῆς στρατιᾶς ἡγουμένῳ τὸ νικᾶν καὶ κατορθοῦν παρεῖχεν ὁ θεός, ἀλλὰ καὶ πέμψαντος αὐτοῦ μετὰ δυνάμεως εἰς τὴν Ἰδουμαίαν Ἀβεσσαῖον τὸν Ἰωάβου τοῦ ἀρχιστρατήγου ἀδελφὸν δι’ ἐκείνου τὴν τῶν Ἰδουμαίων νίκην ἔδωκε· μυρίους γὰρ αὐτῶν καὶ ὀκτακισχιλίους Ἀβεσσαῖος διέφθειρε τῇ μάχῃ. καὶ τὴν Ἰδουμαίαν ἅπασαν φρουραῖς διαλαβὼν ὁ βασιλεὺς φόρους ὑπέρ τε τῆς χώρας καὶ τῆς ἑκάστου κεφαλῆς παρ’ αὐτῶν ἐδέχετο. ἦν δὲ καὶ δίκαιος τὴν φύσιν καὶ τὰς κρίσεις πρὸς τὴν ἀλήθειαν ἀφορῶν ἐποιεῖτο. στρατηγὸν δὲ ἁπάσης εἶχε τῆς στρατιᾶς τὸν Ἰώαβον· ἐπὶ δὲ τῶν ὑπομνημάτων Ἰωσάφατον υἱὸν Ἀχίλου κατέστησεν· ἀπέδειξε δ’ ἐκ τῆς Φινεέσου οἰκίας τὸν Σάδωκον ἀρχιερέα μετ’ Ἀβιαθάρου, φίλος γὰρ ἦν αὐτῷ· γραμματέα δὲ Σισὰν ἐποίησε· Βαναίᾳ δὲ τῷ Ἰωάδου τὴν τῶν σωματοφυλάκων ἀρχὴν παραδίδωσιν· οἱ δὲ πρεσβύτεροι παῖδες αὐτοῦ περὶ τὸ σῶμα καὶ τὴν τούτου φυλακὴν ἦσαν.", "st": "7.5.4"}, {"sp": "N", "t": "Ἐμνήσθη δὲ καὶ τῶν πρὸς Ἰωνάθην τὸν Σαούλου παῖδα συνθηκῶν καὶ ὅρκων καὶ τῆς ἐκείνου πρὸς αὐτὸν φιλίας τε καὶ σπουδῆς· πρὸς γὰρ τοῖς ἄλλοις ἅπασιν ἀγαθοῖς οἷς εἶχεν ἔτι καὶ μνημονικώτατος τῶν εὖ ποιησάντων παρὰ τὸν ἄλλον χρόνον ὑπῆρχε. προσέταξεν οὖν ἀναζητεῖν εἴ τις ἐκ τοῦ γένους αὐτοῦ σώζεται, ᾧ τὰς ἀμοιβὰς ἃς ὤφειλεν Ἰωνάθῃ τῆς ἑταιρίας ἀποδώσει· ἀχθέντος οὖν τινος ἠλευθερωμένου μὲν ὑπὸ Σαούλου δυναμένου δὲ γινώσκειν τοὺς ἐκ τοῦ γένους αὐτοῦ περιόντας, ἀνέκρινεν εἴ τινα ἔχοι λέγειν τῶν Ἰωνάθῃ προσηκόντων ζῶντα καὶ κομίσασθαι τὰς τῶν εὐεργεσιῶν χάριτας δυνάμενον, ὧν καὶ αὐτὸς ἔτυχε παρὰ Ἰωνάθου. φήσαντος δ’ υἱὸν αὐτοῦ περιλείπεσθαι Μεμφίβοσθον ὄνομα πεπηρωμένον τὰς βάσεις, τῆς γὰρ τροφοῦ μετὰ τὸ προσαγγελθῆναι τὸν πατέρα τοῦ παιδίου καὶ τὸν πάππον ἐν τῇ μάχῃ πεσόντας ἁρπασαμένης καὶ φευγούσης, ἀπὸ τῶν ὤμων αὐτὸ κατενεχθῆναι καὶ βλαβῆναι τὰς βάσεις, μαθὼν ὅπου καὶ παρὰ τίνι τρέφεται πέμψας πρὸς τὸν Μάχειρον εἰς Λάβαθα πόλιν, παρὰ τούτῳ γὰρ ὁ Ἰωνάθου παῖς ἐτρέφετο, μεταπέμπεται πρὸς αὑτόν. ἐλθὼν δ’ ὁ Μεμφίβοσθος πρὸς τὸν βασιλέα πεσὼν ἐπὶ πρόσωπον προσεκύνησεν αὐτόν. ὁ δὲ Δαυίδης θαρρεῖν τε προυτρέπετο καὶ τὰ βελτίω προσδοκᾶν· δίδωσι δ’ αὐτῷ καὶ τὸν πατρῷον οἶκον καὶ πᾶσαν τὴν οὐσίαν, ἣν ὁ πάππος αὐτοῦ Σαοῦλος ἐκτήσατο, σύσσιτόν τε καὶ ὁμοτράπεζον ἐκέλευσεν εἶναι καὶ μηδεμίαν ἡμέραν ἀπολείπεσθαι τῆς σὺν αὐτῷ διαίτης. τοῦ δὲ παιδὸς προσκυνήσαντος ἐπί τε τοῖς λόγοις καὶ ταῖς δωρεαῖς, καλέσας τὸν Σιβὰν τὸν πατρῷον οἶκον ἔλεγε δεδωρῆσθαι τῷ παιδὶ καὶ πᾶσαν τὴν Σαούλου κτῆσιν, αὐτόν τε ἐκέλευσεν ἐργαζόμενον αὐτοῦ τὴν γῆν καὶ προνοούμενον ἁπάντων τὴν πρόσοδον εἰς Ἱεροσόλυμα κομίζειν, ἄγειν τε αὐτὸν καθ’ ἑκάστην ἡμέραν ἐπὶ τὴν αὐτοῦ τράπεζαν αὐτὸν Σιβὰν καὶ τοὺς υἱοὺς αὐτοῦ, ἦσαν δ’ οὗτοι πεντεκαίδεκα, καὶ τοὺς οἰκέτας αὐτοῦ τὸν ἀριθμὸν ὄντας εἴκοσι τῷ παιδὶ χαρίζεται Μεμφιβόσθῳ. ταῦτα διαταξαμένου τοῦ βασιλέως ὁ μὲν Σιβὰς προσκυνήσας καὶ πάντα ποιήσειν εἰπὼν ἀνεχώρησεν, ὁ δὲ Ἰωνάθου παῖς ἐν Ἱεροσολύμοις κατῴκει συνεστιώμενος τῷ βασιλεῖ καὶ πάσης ὡς υἱὸς αὐτοῦ θεραπείας τυγχάνων· ἐγένετο δ’ αὐτῷ καὶ παῖς, ὃν Μίχανον προσηγόρευσε.", "st": "7.5.5"}, {"sp": "N", "t": "Καὶ οἱ μὲν περιλειφθέντες ἐκ τοῦ Σαούλου γένους καὶ Ἰωνάθου τούτων ἔτυχον παρὰ Δαυίδου τῶν τιμῶν. τελευτήσαντος δὲ κατ’ ἐκεῖνον τὸν χρόνον τοῦ τῶν Ἀμμανιτῶν βασιλέως Ναάσου, φίλος δ’ ἦν οὗτος αὐτῷ, καὶ διαδεξαμένου τὴν βασιλείαν Ἀννὼν τοῦ παιδός, πέμψας Δαυίδης πρὸς αὐτὸν παρεμυθήσατο πρᾴως τε φέρειν ἐπὶ τῷ θανάτῳ τοῦ πατρὸς παραινῶν καὶ τὴν αὐτὴν φιλίαν διαμενεῖν, ἣ πρὸς ἐκεῖνον ἦν, τούτῳ προσδοκᾶν. οἱ δὲ τῶν Ἀμμανιτῶν ἄρχοντες κακοήθως ἀλλ’ οὐ κατὰ τὸν Δαυίδου τρόπον ταῦτ’ ἐδέξαντο, καὶ παρώτρυναν τὸν βασιλέα λέγοντες κατασκόπους πεπομφέναι τῆς χώρας Δαυίδην καὶ τῆς αὑτῶν δυνάμεως ἐπὶ προφάσει φιλανθρωπίας, φυλάττεσθαί τε συνεβούλευον καὶ μὴ προσέχειν τοῖς λόγοις αὐτοῦ, μὴ καὶ σφαλεὶς ἀπαρηγορήτῳ συμφορᾷ περιπέσῃ. ταῦτ’ οὖν δόξας πιθανώτερα λέγειν τοὺς ἄρχοντας ἢ τἀληθὲς εἶχεν ὁ τῶν Ἀμμανιτῶν βασιλεὺς Ἀννὼν τοὺς παρὰ τοῦ Δαυίδου πεμφθέντας πρέσβεις χαλεπῶς περιύβρισε· ξυρήσας γὰρ αὐτῶν τὰ ἡμίση τῶν γενείων καὶ τὰ ἡμίση τῶν ἱματίων περιτεμὼν ἔργοις ἀπέλυσε κομίζοντας οὐ λόγοις τὰς ἀποκρίσεις. ἰδὼν δὲ ταῦθ’ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς ἠγανάκτησε καὶ δῆλος ἦν οὐ περιοψόμενος τὴν ὕβριν καὶ τὸν προπηλακισμόν, ἀλλὰ πολεμήσων τοῖς Ἀμμανίταις καὶ τιμωρίαν αὐτῶν τῆς παρανομίας τῆς πρὸς τοὺς πρεσβευτὰς εἰσπραξόμενος τὸν βασιλέα. συνέντες δὲ οἵ τε ἀναγκαῖοι καὶ οἱ ἡγεμόνες, ὅτι παρεσπονδήκασι καὶ δίκην ὑπὲρ τούτων ὀφείλουσι, προπαρασκευάζονται εἰς τὸν πόλεμον· καὶ πέμψαντες πρὸς Σύρον τὸν τῶν Μεσοποταμιτῶν βασιλέα χίλια τάλαντα σύμμαχον αὐτὸν ἐπὶ τούτῳ γενέσθαι τῷ μισθῷ παρεκάλεσαν καὶ Σουβάν· ἦσαν δὲ τοῖς βασιλεῦσι τούτοις πεζοῦ δύο μυριάδες. προσεμισθώσαντο δὲ καὶ τὸν ἐκ τῆς Μιχᾶς καλουμένης χώρας βασιλέα καὶ τέταρτον Ἴστοβον ὄνομα, καὶ τούτους ἔχοντας μυρίους καὶ δισχιλίους ὁπλίτας.", "st": "7.6.1"}, {"sp": "N", "t": "Οὐ κατεπλάγη δὲ τὴν συμμαχίαν καὶ τὴν τῶν Ἀμμανιτῶν δύναμιν ὁ Δαυίδης, τῷ δὲ θεῷ πεποιθὼς καὶ τῷ δικαίως αὐτοῖς ἀνθ’ ὧν ὑβρίσθη πολεμεῖν μέλλειν, Ἰώαβον τὸν ἀρχιστράτηγον δοὺς αὐτῷ τῆς στρατιᾶς τὸ ἀκμαιότατον ἐξ αὐτῆς ἔπεμψεν ἐπ’ αὐτούς. ὁ δὲ πρὸς τῇ μητροπόλει τῶν Ἀμμανιτῶν Ἀραβαθᾶ κατεστρατοπεδεύσατο. τῶν δὲ πολεμίων ἐξελθόντων καὶ παραταξαμένων οὐχ ὁμοῦ διχῇ δέ, τὸ μὲν γὰρ ἐπικουρικὸν ἐν τῷ πεδίῳ καθ’ αὑτὸ ἐτάχθη, τὸ δὲ τῶν Ἀμμανιτῶν στράτευμα πρὸς ταῖς πύλαις ἀντικρὺ τῶν Ἑβραίων, ἰδὼν τοῦτο Ἰώαβος ἀντιμηχανᾶται· καὶ τοὺς μὲν ἀνδρειοτάτους ἐπιλεξάμενος ἀντιπαρατάσσεται τῷ Σύρῳ καὶ τοῖς μετ’ αὐτοῦ βασιλεῦσι, τὸ δ’ ἄλλο παραδοὺς Ἀβεσσαίῳ τῷ ἀδελφῷ τοῖς Ἀμμανίταις ἐκέλευσεν ἀντιπαρατάξασθαι, εἰπὼν ἂν τοὺς Σύρους ἴδῃ βιαζομένους αὐτὸν καὶ πλέον δυναμένους μεταγαγόντα τὴν φάλαγγα βοηθεῖν αὐτῷ, τὸ δ’ αὐτὸ τοῦτο ποιήσειν καὶ αὐτός, ἂν ὑπὸ τῶν Ἀμμανιτῶν αὐτὸν καταπονούμενον θεάσηται. προτρεψάμενος οὖν τὸν ἀδελφὸν καὶ παρακαλέσας εὐψύχως καὶ μετὰ προθυμίας ἀνδράσιν αἰσχύνην φοβουμένοις πρεπούσης ἀγωνίσασθαι τὸν μὲν ἀπέλυσε τοῖς Ἀμμανίταις μαχησόμενον, αὐτὸς δὲ τοῖς Σύροις συνέβαλε. καὶ πρὸς ὀλίγον ἀντισχόντων αὐτῶν καρτερῶς πολλοὺς μὲν αὐτῶν ἀπέκτεινεν Ἰώαβος, ἅπαντας δ’ ἠνάγκασεν εἰς φυγὴν τραπῆναι. τοῦτο ἰδόντες οἱ Ἀμμανῖται καὶ δείσαντες τὸν Ἀβεσσαῖον καὶ τὴν μετ’ αὐτοῦ στρατιὰν οὐκ ἔμειναν, ἀλλὰ μιμησάμενοι τοὺς συμμάχους εἰς τὴν πόλιν ἔφυγον. κρατήσας οὖν τῶν πολεμίων Ἰώαβος εἰς Ἱεροσόλυμα πρὸς τὸν βασιλέα λαμπρῶς ὑπέστρεψε.", "st": "7.6.2"}, {"sp": "N", "t": "Τοῦτο τὸ πταῖσμα τοὺς Ἀμμανίτας οὐκ ἔπεισεν ἠρεμεῖν οὐδὲ μαθόντας τοὺς κρείττονας ἡσυχίαν ἄγειν, ἀλλὰ πέμψαντες πρὸς Χαλαμὰν τὸν τῶν πέραν Εὐφράτου Σύρων βασιλέα μισθοῦνται τοῦτον ἐπὶ συμμαχίᾳ, ἔχοντα μὲν ἀρχιστράτηγον Σέβεκον, πεζῶν δὲ μυριάδας ὀκτὼ καὶ ἱππέων μυρίους. γνοὺς δ’ ὁ τῶν Ἑβραίων βασιλεὺς πάλιν ἐπ’ αὐτὸν τοὺς Ἀμμανίτας τοσαύτην δύναμιν συνηθροικότας οὐκέτι διὰ στρατηγῶν αὐτοῖς πολεμεῖν ἔκρινεν, ἀλλ’ αὐτὸς σὺν ἁπάσῃ τῇ δυνάμει διαβὰς τὸν Ἰόρδανον ποταμὸν καὶ ὑπαντήσας αὐτοῖς συνάψας εἰς μάχην ἐνίκησε· καὶ ἀναιρεῖ μὲν αὐτῶν πεζῶν μὲν εἰς τέσσαρας μυριάδας ἱππέων δὲ εἰς ἑπτακισχιλίους, ἔτρωσε δὲ καὶ τὸν στρατηγὸν τοῦ Χαλαμᾶ Σέβεκον, ὃς ἐκ τῆς πληγῆς ἀπέθανεν. οἱ δὲ Μεσοποταμῖται τοιούτου γενομένου τοῦ τέλους τῆς μάχης αὑτοὺς Δαυίδῃ παρέδοσαν καὶ δῶρα ἔπεμψαν αὐτῷ. καὶ ὁ μὲν ὥρᾳ χειμῶνος ἀνέστρεψεν εἰς Ἱεροσόλυμα, ἀρχομένου δὲ τοῦ ἔαρος ἔπεμψε τὸν ἀρχιστράτηγον Ἰώαβον πολεμήσοντα τοῖς Ἀμμανίταις. ὁ δὲ τήν τε γῆν αὐτῶν ἅπασαν ἐπερχόμενος διέφθειρε καὶ αὐτοὺς εἰς τὴν μητρόπολιν συγκλείσας Ἀραβαθὰ ἐπολιόρκει.", "st": "7.6.3"}, {"sp": "N", "t": "Συνέπεσε δὲ καὶ Δαυίδῃ πταῖσμα δεινὸν ὄντι φύσει δικαίῳ καὶ θεοσεβεῖ καὶ τοὺς πατρίους νόμους ἰσχυρῶς φυλάσσοντι· θεασάμενος γὰρ δείλης ὀψίας ἀπὸ τοῦ στέγους τῶν βασιλείων, ἐν ᾧ περιπατεῖν κατ’ ἐκεῖνο τῆς ὥρας ἦν ἔθος, γυναῖκα λουομένην ἐν τῇ αὑτῆς οἰκίᾳ ψυχρῷ ὕδατι καλλίστην τὸ εἶδος καὶ πασῶν διαφέρουσαν, ὄνομα αὐτῇ ἦν Βεεθσαβή, ἡττᾶται τοῦ κάλλους τῆς γυναικός· καὶ τῆς ἐπιθυμίας κατασχεῖν οὐ δυνάμενος αὐτῇ συνέρχεται. γενομένης δ’ ἐγκύου τῆς γυναικὸς καὶ πεμψάσης πρὸς τὸν βασιλέα, ὅπως τῷ ἁμαρτήματι σκέψηταί τινα τοῦ λαθεῖν ὁδόν, ἀποθανεῖν γὰρ αὐτὴν κατὰ τοὺς πατρίους καθήκει νόμους μεμοιχευμένην, μετακαλεῖται τὸν Ἰωάβου μὲν ὁπλοφόρον ἐκ τῆς πολιορκίας ἄνδρα δὲ τῆς γυναικὸς Οὐρίαν ὄνομα, καὶ παραγενόμενον περί τε τῆς στρατιᾶς καὶ τῆς πολιορκίας ἀνέκρινε. λέγοντος δὲ πάντα κατὰ νοῦν αὐτοῖς κεχωρηκέναι τὰ πράγματα βαστάσας ἐκ τοῦ δείπνου μέρη προσδίδωσιν αὐτῷ, καὶ κελεύει πρὸς τὴν γυναῖκα ἀπελθόντα ἀναπαύσασθαι σὺν αὐτῇ. ὁ δὲ Οὐρίας τοῦτο μὲν οὐκ ἐποίησε, παρεκοιμήθη δὲ τῷ βασιλεῖ σὺν τοῖς ἄλλοις ὁπλοφόροις. ὡς δὲ γνοὺς τοῦθ’ ὁ βασιλεὺς ἀνέκρινεν αὐτόν, ὅτι μὴ πρὸς [αὑτὸν εἰς] τὴν οἰκίαν ἔλθοι μηδὲ πρὸς τὴν γυναῖκα διὰ τοσούτου χρόνου πάντων ἀνθρώπων ταύτην ἐχόντων τὴν φύσιν ὅταν ἔλθωσιν ἐξ ἀποδημίας, οὐκ εἶναι δίκαιον ἔφη τῶν συστρατιωτῶν αὐτοῦ καὶ τοῦ στρατηγοῦ χαμαὶ κοιμωμένων ἐν παρεμβολῇ καὶ τῇ τῶν πολεμίων χώρᾳ μετὰ γυναικὸς αὐτὸν ἀναπαύεσθαι καὶ τρυφᾶν. ταῦτ’ εἰπόντα μεῖναι τὴν ἡμέραν ἐκείνην ἐκέλευσεν αὐτόθι ὡς εἰς τὴν ἐπιοῦσαν ἀπολύσων αὐτὸν πρὸς τὸν ἀρχιστράτηγον. κληθεὶς δ’ ἐπὶ δεῖπνον ὑπὸ τοῦ βασιλέως Οὐρίας καὶ μέχρι μέθης προελθὼν ἐν τῷ πότῳ δεξιουμένου τοῦ βασιλέως αὐτὸν ἐπίτηδες ταῖς προπόσεσιν, οὐδὲν ἧττον πάλιν πρὸ τῶν τοῦ βασιλέως θυρῶν ἐκοιμήθη μηδεμίαν λαβὼν τῆς γυναικὸς ἐπιθυμίαν. ἐπὶ τούτοις δὲ δυσανασχετήσας ὁ βασιλεὺς ἔγραψε τῷ Ἰωάβῳ κολάσαι προστάττων τὸν Οὐρίαν, ἁμαρτεῖν γὰρ αὐτὸν ἐδήλου, καὶ τὸν τρόπον τῆς τιμωρίας ἵνα μὴ γένηται φανερὸς αὐτὸς τοῦτο βουληθεὶς ὑπέθετο· κατὰ γὰρ τὸ δυσμαχώτατον αὐτὸν ἐκέλευσε μέρος τῶν πολεμίων τάξαι καὶ καθ’ ὃ κινδυνεύσει μαχόμενος ἀπολειφθεὶς μόνος· [τοὺς γὰρ] συμπαραστάτας ἀναχωρῆσαι ἐκ τῆς μάχης γινομένης ἐκέλευσε. ταῦτα γράψας καὶ σημηνάμενος τῇ αὑτοῦ σφραγῖδι τὴν ἐπιστολὴν ἔδωκεν Οὐρίᾳ κομίσαι πρὸς Ἰώαβον. δεξάμενος δὲ Ἰώαβος τὰ γράμματα καὶ τὴν τοῦ βασιλέως προαίρεσιν ἀναγνούς, καθ’ ὃν ᾔδει τόπον τοὺς πολεμίους χαλεποὺς αὐτῷ γενομένους, κατὰ τοῦτον ἔστησε τὸν Οὐρίαν δοὺς αὐτῷ τινας τῶν ἀρίστων τῆς στρατιᾶς· αὐτὸς δ’ ἁπάσῃ τῇ δυνάμει προσεπιβοηθήσειν ἔφησεν, εἰ δυνηθεῖεν ἀνατρέψαντές τι τοῦ τείχους εἰσελθεῖν εἰς τὴν πόλιν. ὄντα δ’ αὐτὸν γενναῖον στρατιώτην καὶ δόξαν ἔχοντα παρά τε τῷ βασιλεῖ καὶ πᾶσι τοῖς ὁμοφύλοις ἐπ’ ἀνδρείᾳ χαίρειν τοῖς μεγάλοις πόνοις ἀλλὰ μὴ προσαγανακτεῖν ἠξίου. τοῦ δ’ Οὐρία προθύμως ὑποστάντος τὸ ἔργον, τοῖς μετ’ αὐτοῦ παρατασσομένοις ἰδίᾳ καταλιπεῖν ὅταν ἐξορμήσαντας ἴδωσι τοὺς πολεμίους ἐδήλωσε. προσβαλόντων οὖν τῇ πόλει τῶν Ἑβραίων δείσαντες οἱ Ἀμμανῖται, μὴ κατ’ ἐκεῖνον τὸν τόπον, καθ’ ὃν Οὐρίαν συνέβαινε τετάχθαι, φθάσαντες ἀναβῶσιν οἱ πολέμιοι, προστησάμενοι τοὺς ἀνδρειοτάτους αὐτῶν καὶ τὴν πύλην ἀνοίξαντες αἰφνιδίως καὶ μετὰ ῥύμης καὶ δρόμου πολλοῦ τοῖς ἐχθροῖς ἐπεξῆλθον. ἰδόντες δὲ αὐτοὺς οἱ σὺν τῷ Οὐρίᾳ πάντες ἀνεχώρησαν ὀπίσω, καθὼς Ἰώαβος αὐτοῖς προεῖπεν· αἰσχυνθεὶς δ’ Οὐρίας φυγεῖν καὶ τὴν τάξιν καταλιπεῖν ὑπέμεινε τοὺς πολεμίους· καὶ τὴν ὁρμὴν αὐτῶν ἐκδεξάμενος ἀναιρεῖ μὲν οὐκ ὀλίγους, κυκλωθεὶς δὲ καὶ ληφθεὶς ἐν μέσῳ ἅμα δ’ αὐτῷ τινες καὶ ἄλλοι τελευτᾷ συγκαταπεσόντων ἑτέρων.", "st": "7.7.1"}, {"sp": "N", "t": "Τούτων οὕτως γενομένων ἔπεμψεν ἀγγέλους Ἰώαβος πρὸς τὸν βασιλέα λέγειν ἐντειλάμενος αὐτοῖς, ὡς σπουδάσειε μὲν ταχέως ἑλεῖν τὴν πόλιν, προσβαλὼν δὲ τῷ τείχει καὶ πολλοὺς ἀπολέσας ἀναχωρῆσαι βιασθείη· προστιθέναι δὲ τούτοις ἂν ὀργιζόμενον ἐπ’ αὐτοῖς βλέπωσι καὶ τὸν Οὐρία θάνατον. τοῦ δὲ βασιλέως ἀκούσαντος παρὰ τῶν ἀγγέλων ταῦτα καὶ δυσφοροῦντος φάσκοντος ἁμαρτεῖν αὐτοὺς τῷ τείχει προσβαλόντας, δέον ὑπονόμοις καὶ μηχανήμασιν ἑλεῖν πειρᾶσθαι τὴν πόλιν, καὶ ταῦτ’ ἔχοντας παράδειγμα τὸν Γεδεῶνος υἱὸν Ἀβιμέλεχον, ὃς ἐπεὶ τὸν ἐν Θήβαις πύργον ἑλεῖν ἐβούλετο βίᾳ, βληθεὶς ὑπὸ πρεσβύτιδος πέτρῳ κατέπεσε καὶ ἀνδρειότατος ὢν διὰ τὸ δυσχερὲς τῆς ἐπιβολῆς αἰσχρῶς ἀπέθανεν· οὗ μνημονεύοντας ἔδει μὴ προσιέναι τῷ τείχει τῶν πολεμίων· ἄριστον γὰρ ἁπάντων τῶν ἐν πολέμῳ πραχθέντων καὶ καλῶς καὶ ὡς ἑτέρως ἐνίοις αὐτοῖς κινδύνοις μνήμην ἔχειν, ὡς τὰ μὲν μιμεῖσθαι τὰ δὲ φυλάττεσθαι. ἐπεὶ δὲ οὕτως ἔχοντι καὶ τὸν Οὐρία θάνατον ἐδήλωσεν ὁ ἄγγελος, παύεται μὲν τῆς ὀργῆς, Ἰωάβῳ δ’ ἐκέλευσεν ἀπελθόντα λέγειν ἀνθρώπινον εἶναι τὸ συμβεβηκὸς καὶ τὰ τοῦ πολέμου φύσιν ἔχειν τοιαύτην, ὥστε ποτὲ μὲν τοῖς ἐναντίοις εὖ πράττειν συμβαίνειν κατ’ αὐτόν, ποτὲ δὲ τοῖς ἑτέροις· τοῦ λοιποῦ μέντοι γε προνοεῖν τῆς πολιορκίας, ὅπως μηδὲν ἔτι πταίσωσι κατ’ αὐτήν, ἀλλὰ χώμασι καὶ μηχαναῖς ἐκπολιορκήσαντας καὶ παραστησαμένους τὴν μὲν πόλιν κατασκάψαι, ἅπαντας δ’ ἀπολέσαι τοὺς ἐν αὐτῇ. καὶ ὁ μὲν ἄγγελος τὰ ὑπὸ τοῦ βασιλέως ἐντεταλμένα κομίζων πρὸς Ἰώαβον ἠπείγετο. ἡ δὲ τοῦ Οὐρία γυνὴ Βεεθσαβὴ τὸν θάνατον τἀνδρὸς πυθομένη ἐπὶ συχνὰς αὐτὸν ἡμέρας ἐπένθησεν, παυσαμένην δὲ τῆς λύπης καὶ τῶν ἐπ’ Οὐρίᾳ δακρύων ὁ βασιλεὺς εὐθὺς ἄγεται γυναῖκα, καὶ παῖς ἄρρην ἐξ αὐτῆς γίνεται αὐτῷ.", "st": "7.7.2"}, {"sp": "N", "t": "Τοῦτον οὐχ ἡδέως ἐπεῖδεν ὁ θεὸς τὸν γάμον, ἀλλὰ δι’ ὀργῆς ἔχων τὸν Δαυίδην τῷ προφήτῃ Νάθᾳ φανεὶς κατὰ τοὺς ὕπνους ἐμέμφετο τὸν βασιλέα. ὁ δὲ Νάθας ἀστεῖος καὶ συνετὸς ὢν ἀνήρ, λογισάμενος ὡς οἱ βασιλεῖς ὅταν εἰς ὀργὴν ἐμπέσωσι ταύτῃ πλέον ἢ τῷ δικαίῳ νέμουσι, τὰς μὲν παρὰ τοῦ θεοῦ γεγενημένας ἀπειλὰς ἡσυχάζειν ἔκρινεν, ἄλλους δὲ λόγους χρηστοὺς πρὸς αὐτὸν διεξῆλθε, καὶ δὴ τοιοῦτόν τινα τρόπον περὶ οὗ καὶ τί φρονεῖ ποιῆσαι σαφὲς αὐτῷ παρεκάλει· δύο γάρ, ἔφησεν, ἄνδρες τὴν αὐτὴν κατῴκουν πόλιν, ὧν ὁ μὲν πλούσιος ἦν καὶ πολλὰς εἶχεν ἀγέλας ὑποζυγίων τε καὶ θρεμμάτων καὶ βοῶν, τῷ πένητι δ’ ἀμνὰς ὑπῆρχε μία. ταύτην μετὰ τῶν τέκνων αὐτοῦ ἀνέτρεφε συνδιαιρούμενος αὐτῇ τὰ σιτία καὶ φιλοστοργίᾳ πρὸς αὐτὴν χρώμενος ᾗ τις ἂν χρήσαιτο καὶ πρὸς θυγατέρα. ξένου δ’ ἐπελθόντος τῷ πλουσίῳ τῶν μὲν ἰδίων οὐδὲν ἠξίωσεν ἐκεῖνος βοσκημάτων καταθύσας εὐωχῆσαι τὸν φίλον, πέμψας δὲ τὴν ἀμνάδα τοῦ πένητος ἀπέσπασε, καὶ ταύτην παρασκευάσας εἱστίασε τὸν ξένον. σφόδρα ἐλύπησεν ὁ λόγος οὗτος τὸν βασιλέα καὶ πονηρὸν πρὸς τὸν Νάθαν τὸν ἄνθρωπον ἐκεῖνον, ὃς δὴ τοῦτο τὸ ἔργον ἐτόλμησεν, ἀπεφήνατο καὶ τετραπλὴν ἀποτῖσαι τὴν ἀμνάδα δίκαιον εἶναι καὶ πρὸς τούτῳ θανάτῳ κολασθῆναι. Νάθας δ’ ὑποτυχὼν αὐτὸν ἔλεγεν ἐκεῖνον εἶναι τὸν ἄξιον ταῦτα παθεῖν ὑφ’ ἑαυτοῦ κεκριμένον τολμήσαντα μέγα καὶ δεινὸν ἔργον. ἀνεκάλυπτε δ’ αὐτῷ καὶ παρεγύμνου τὴν ὀργὴν τοῦ θεοῦ ποιήσαντος μὲν αὐτὸν βασιλέα πάσης τῆς Ἑβραίων δυνάμεως καὶ τῶν ἐν κύκλῳ πάντων ἐθνῶν πολλῶν καὶ μεγάλων κύριον, ῥυσαμένου δ’ ἔτι πρὸ τούτων ἐκ τῶν Σαούλου χειρῶν, δόντος δ’ αὐτῷ καὶ γυναῖκας ἃς δικαίως καὶ νομίμως ἠγάγετο, καταφρονηθέντος δ’ ὑπ’ αὐτοῦ καὶ ἀσεβηθέντος, ὃς ἀλλοτρίαν τε γήμας ἔχει γυναῖκα καὶ τὸν ἄνδρα αὐτῆς ἀποκτείνειεν ἐκδοὺς τοῖς πολεμίοις· δώσειν οὖν αὐτὸν ἀντὶ τούτων δίκας τῷ θεῷ καὶ βιασθήσεσθαι μὲν αὐτοῦ τὰς γυναῖκας ὑφ’ ἑνὸς τῶν παίδων, ἐπιβουλευθήσεσθαι δὲ καὶ αὐτὸν ὑπ’ ἐκείνου, καὶ τὸ ἁμάρτημα τοῦτο κρύφα δράσαντα φανερὰν τὴν ἐπ’ αὐτῷ δίκην ὑφέξειν· τεθνήξεσθαι δὲ καὶ τὸν παῖδά σοι παραχρῆμα τὸν ἐξ αὐτῆς γεγενημένον. ταραχθέντος δ’ ἐπὶ τούτοις τοῦ βασιλέως καὶ συσχεθέντος ἱκανῶς καὶ μετὰ δακρύων καὶ λύπης ἀσεβῆσαι λέγοντος, ἦν γὰρ ὁμολογουμένως θεοσεβὴς καὶ μηδὲν ἁμαρτὼν ὅλως περὶ τὸν βίον ἢ τὰ περὶ τὴν Οὐρία γυναῖκα, ᾤκτειρεν ὁ θεὸς καὶ διαλλάττεται φυλάξειν αὐτῷ καὶ τὴν ζωὴν καὶ τὴν βασιλείαν ἐπαγγειλάμενος· μετανοοῦντι γὰρ περὶ τῶν γεγενημένων οὐκέτι χαλεπῶς ἔχειν ἔφασκε. καὶ Νάθας μὲν ταῦτα τῷ βασιλεῖ προφητεύσας οἴκαδε ἐπανῆλθε.", "st": "7.7.3"}, {"sp": "N", "t": "Τῷ δ’ ἐκ τῆς Οὐρία γυναικὸς γενομένῳ παιδὶ Δαυίδῃ νόσον ἐνσκήπτει χαλεπὴν τὸ θεῖον, ἐφ’ ᾗ δυσφορῶν ὁ βασιλεὺς τροφὴν μὲν ἐφ’ ἡμέρας ἑπτὰ καίτοι γε ἀναγκαζόντων τῶν οἰκείων οὐ προσηνέγκατο, μέλαιναν δὲ περιθέμενος ἐσθῆτα πεσὼν ἐπὶ σάκκου κατὰ γῆς ἔκειτο τὸν θεὸν ἱκετεύων ὑπὲρ τῆς τοῦ παιδὸς σωτηρίας· σφόδρα γὰρ ἔστεργεν αὐτοῦ τὴν μητέρα. τῇ δ’ ἑβδόμῃ τῶν ἡμερῶν τελευτήσαντος τοῦ παιδὸς οὐκ ἐτόλμων τῷ βασιλεῖ τοῦτο μηνύειν οἱ θεράποντες λογιζόμενοι, μὴ γνοὺς ἔτι μᾶλλον ἀπόσχηται καὶ τροφῆς καὶ τῆς ἄλλης ἐπιμελείας ὡς ἂν ἐπὶ ποθεινοῦ τέκνου τετελευτηκότος, ὅτε καὶ νοσοῦντος οὕτως ὑπὸ τῆς λύπης ἑαυτὸν ἐκάκου. ταραττομένων δ’ αἰσθόμενος τῶν οἰκετῶν ὁ βασιλεὺς καὶ ταῦτα πασχόντων, ἃ μάλιστα συγκρύψαι τι θέλουσι συμβαίνει, συνεὶς ὅτι τέθνηκεν ὁ παῖς προσφωνήσας ἕνα τῶν οἰκετῶν καὶ μαθὼν τἀληθὲς ἀνίσταται καὶ λουσάμενος καὶ λαβὼν ἐσθῆτα λευκὴν εἰς τὴν σκηνὴν τοῦ θεοῦ παραγίνεται, καὶ κελεύσας δεῖπνον αὑτῷ παραθεῖναι πολλὴν ἐπὶ τῷ παραλόγῳ τοῖς τε συγγενέσι καὶ τοῖς οἰκέταις ἔκπληξιν παρεῖχεν, ὅτι μηδὲν τούτων ἐπὶ νοσοῦντι τῷ παιδὶ ποιήσας πάνθ’ ὁμοῦ τετελευτηκότος ἔπραττε. τήν τε αἰτίαν, δεηθέντες ἐπιτρέψαι πρῶτον αὐτοῖς πυθέσθαι, παρεκάλουν [εἰπεῖν] τῶν γεγενημένων. ὁ δὲ ἀμαθεῖς εἰπὼν αὐτοὺς ἐδίδασκεν, ὡς ἔτι μὲν ζῶντος τοῦ παιδὸς ἔχων ἐλπίδα σωτηρίας αὐτοῦ δεόντως πάντ’ ἐποίει τὸν θεὸν ἡγούμενος τούτοις εὐμενῆ καταστήσειν, ἀποθανόντος δ’ οὐκέτι χρείαν εἶναι λύπης ματαίας. ταῦτ’ εἰπόντος ἐπῄνεσαν τὴν σοφίαν καὶ τὴν διάνοιαν τοῦ βασιλέως. συνελθὼν δὲ τῇ γυναικὶ Βεεθσαβῇ ἔγκυον αὐτὴν ἐποίησε, καὶ γεννησαμένης ἄρρεν παιδίον Σολόμωνα τοῦτον προσηγόρευσεν, οὕτως Νάθα τοῦ προφήτου κελεύσαντος.", "st": "7.7.4"}, {"sp": "N", "t": "Ἰώαβος δὲ τῇ πολιορκίᾳ τοὺς Ἀμμανίτας ἰσχυρῶς ἐκάκου τῶν τε ὑδάτων αὐτοὺς ἀποτεμνόμενος καὶ τῆς τῶν ἄλλων εὐπορίας, ὡς πάνυ ταλαιπωρεῖν ἐνδείᾳ ποτοῦ καὶ τροφῆς. ἐξ ὀλίγου γὰρ φρέατος ἤρτηντο καὶ ταμείας ὡς μὴ τελέως αὐτοὺς ἐπιλιπεῖν τὴν πηγὴν δαψιλέστερον χρωμένους. γράφει δὴ τῷ βασιλεῖ ταῦτα δηλῶν καὶ παρακαλῶν αὐτὸν ἐπὶ τὴν αἵρεσιν τῆς πόλεως ἐλθεῖν, ἵνα τὴν νίκην αὐτὸς ἐπιγραφῇ. ταῦτα Ἰωάβου γράψαντος ἀποδεξάμενος αὐτὸν τῆς εὐνοίας καὶ τῆς πίστεως ὁ βασιλεὺς παραλαβὼν τὴν σὺν αὐτῷ δύναμιν ἧκεν ἐπὶ τὴν τῆς Ῥαβαθᾶς πόρθησιν, καὶ κατὰ κράτος ἑλὼν διαρπάσαι τοῖς στρατιώταις ἐφῆκεν. αὐτὸς δὲ τὸν τοῦ βασιλέως τῶν Ἀμμανιτῶν λαμβάνει στέφανον ἕλκοντα χρυσοῦ τάλαντον καὶ πολυτελῆ λίθον ἔχοντα ἐν μέσῳ σαρδόνυχος· ἐφόρει δ’ αὐτὸν ἐπὶ τῆς κεφαλῆς διαπαντὸς Δαυίδης. πολλὰ δὲ καὶ ἄλλα σκῦλα λαμπρὰ καὶ πολύτιμα εὗρεν ἐν τῇ πόλει· τοὺς δ’ ἄνδρας αἰκισάμενος διέφθειρε. ταὐτὰ δὲ καὶ τὰς ἄλλας τῶν Ἀμμανιτῶν πόλεις διέθηκεν ἑλὼν αὐτὰς κατὰ κράτος.", "st": "7.7.5"}, {"sp": "N", "t": "Ἀναστρέψαντος δὲ εἰς Ἱεροσόλυμα τοῦ βασιλέως πταῖσμα αὐτοῦ τὴν οἰκίαν ἐξ αἰτίας τοιαύτης καταλαμβάνει· θυγάτηρ γὰρ ἦν αὐτῷ παρθένος μὲν ἔτι τὸ δὲ κάλλος εὐπρεπής, ὡς ἁπάσας ὑπερβάλλειν τὰς εὐμορφοτάτας γυναῖκας, Θήμαρ ὄνομα, τῆς δ’ αὐτῆς Ἀψαλώμῳ μητρὸς κεκοινωνηκυῖα. ταύτης ὁ πρεσβύτατος τῶν Δαυίδου παίδων Ἀμνὼν ἐρασθείς, ὡς οὔτε διὰ τὴν παρθενίαν αὐτῆς οὔτε διὰ τὴν φυλακὴν τυχεῖν τῆς ἐπιθυμίας ἐδύνατο χαλεπῶς διέκειτο, καὶ τό τε σῶμα τῆς ὀδύνης αὐτὸν κατεσθιούσης κατισχναίνετο καὶ τὴν χρόαν μετέβαλλε. δῆλος δὲ γίνεται ταῦτα πάσχων Ἰωνάθῃ τινὶ συγγενεῖ καὶ φίλῳ· συνετὸς δ’ ἦν οὗτος ἐν τοῖς μάλιστα καὶ τὴν διάνοιαν ὀξύς. ὁρῶν οὖν καθ’ ἑκάστην πρωίαν τὸν Ἀμνῶνα μὴ κατὰ φύσιν ἔχοντα τῷ σώματι προσελθὼν ἠρώτα φράσαι τὴν αἰτίαν αὐτῷ, εἰκάζειν μέντοι γε οὕτως ἔλεγεν ἐξ ἐρωτικῆς αὐτὸν ἔχειν ἐπιθυμίας. τοῦ δὲ Ἀμνῶνος ὁμολογήσαντος τὸ πάθος ὅτι τῆς ἀδελφῆς ἐρᾷ τυγχανούσης ὁμοπατρίας, ὁδὸν αὐτῷ καὶ μηχανὴν εἰς τὸ περιγενέσθαι τῶν εὐκταίων ὑπέθετο· νόσον γὰρ ὑποκρίνασθαι παρῄνεσεν, ἐλθόντα δὲ πρὸς αὐτὸν τὸν πατέρα πέμψαι τὴν ἀδελφὴν αὐτῷ διακονησομένην ἐκέλευσε παρακαλέσαι· ῥᾴω γὰρ ἔσεσθαι καὶ ταχέως ἀπαλλαγήσεσθαι τῆς νόσου τούτου γενομένου. πεσὼν οὖν ὁ Ἀμνὼν ἐπὶ τὴν κλίνην νοσεῖν προσεποιήσατο κατὰ τὰς Ἰωνάθου ὑποθήκας. παραγενομένου δὲ τοῦ πατρὸς καὶ σκεπτομένου πῶς ἔχοι, τὴν ἀδελφὴν ἐδεῖτο πέμψαι πρὸς αὐτόν· ὁ δ’ εὐθὺς ἐκέλευσεν ἀχθῆναι. ἡκούσῃ δὲ προσέταξεν ἄρτους αὐτῷ ποιῆσαι τηγανιστοὺς αὐτουργῷ γενομένῃ· προσοίσεσθαι γὰρ ἥδιον ἐκ τῶν ἐκείνης χειρῶν. ἡ δ’ ἐμβλέποντος τἀδελφοῦ φυράσασα τὸ ἄλευρον καὶ πλάσασα κολλυρίδας καὶ τηγανίσασα προσήνεγκεν αὐτῷ· ὁ δὲ τότε μὲν οὐκ ἐγεύσατο, προσέταξε δὲ τοῖς οἰκέταις παραιτήσασθαι πάντας πρὸ τοῦ δωματίου· βούλεσθαι γὰρ ἀναπαύσασθαι θορύβου καὶ ταραχῆς ἀπηλλαγμένος. ὡς δὲ τὸ κελευσθὲν ἐγένετο, τὴν ἀδελφὴν ἠξίωσεν εἰς τὸν ἐνδοτέρω τὸ δεῖπνον οἶκον αὐτῷ παρενεγκεῖν· ποιησάσης δὲ τοῦτο τῆς κόρης λαβόμενος αὐτῆς συνελθεῖν αὐτῷ πείθειν ἐπειρᾶτο. ἀνακραγοῦσα δ’ ἡ παῖς ἀλλὰ μὴ σύ γε τοῦτο βιάσῃ με μηδὲ ἀσεβήσῃς, εἶπεν, ἀδελφέ, τοὺς νόμους παραβὰς καὶ δεινῇ περιβαλὼν σαυτὸν αἰσχύνῃ· παῦσαι δ’ οὕτως ἀδίκου καὶ μιαρᾶς ἐπιθυμίας, ἐξ ἧς ὀνείδη καὶ κακοδοξίαν ὁ οἶκος ἡμῶν κερδανεῖ. συνεβούλευέ τε περὶ τούτου διαλεχθῆναι τῷ πατρί· συγχωρήσειν γὰρ ἐκεῖνον. ταῦτα δ’ ἔλεγε βουλομένη τὴν ὁρμὴν αὐτοῦ τῆς ὀρέξεως πρὸς τὸ παρὸν διαφυγεῖν. ὁ δ’ οὐ πείθεται, τῷ δὲ ἔρωτι καιόμενος καὶ τοῖς τοῦ πάθους κέντροις μυωπιζόμενος βιάζεται τὴν ἀδελφήν. μῖσος δ’ εὐθέως μετὰ τὴν κορείαν εἰσέρχεται τὸν Ἀμνῶνα καὶ προσλοιδορησάμενος ἐκέλευσεν ἀναστᾶσαν ἀπιέναι. τῆς δὲ χείρω τὴν ὕβριν καὶ διὰ τοῦτο ἀποκαλούσης, εἰ βιασάμενος αὐτὸς μηδ’ ἄχρι νυκτὸς ἐπιτρέπει μεῖναι παραχρῆμα δ’ ἀπαλλάττεσθαι κελεύει ἐν ἡμέρᾳ καὶ φωτί, ἵνα καὶ μάρτυσι τῆς αἰσχύνης περιπέσοι, προσέταξεν αὐτὴν ἐκβαλεῖν τῷ οἰκέτῃ. ἡ δὲ περιαλγὴς ἐπὶ τῇ ὕβρει καὶ τῇ βίᾳ γενομένη περιρρήξασα τὸν χιτωνίσκον, ἐφόρουν γὰρ αἱ τῶν ἀρχαίων παρθένοι χειριδωτοὺς ἄχρι τῶν σφυρῶν πρὸς τὸ μὴ βλέπεσθαι χιτῶνας, καὶ σποδὸν καταχεαμένη τῆς κεφαλῆς ἀπῄει διὰ τῆς πόλεως μέσης βοῶσα καὶ ὀδυρομένη τὴν βίαν. περιτυχὼν δ’ αὐτῇ ὁ ἀδελφὸς Ἀψάλωμος ἀνέκρινε, τίνος αὐτῇ δεινοῦ συμβάντος οὕτως ἔχει, κατειπούσης δ’ αὐτῆς πρὸς αὐτὸν τὴν ὕβριν ἡσυχάζειν καὶ μετρίως φέρειν παρηγόρει καὶ μὴ νομίζειν ὑβρίσθαι φθαρεῖσαν ὑπ’ ἀδελφοῦ. πεισθεῖσα οὖν παύεται τῆς βοῆς καὶ τοῦ πρὸς πολλοὺς τὴν βίαν ἐκφέρειν, καὶ πολὺν χρόνον χηρεύουσα παρὰ Ἀψαλώμῳ τῷ ἀδελφῷ διεκαρτέρησε.", "st": "7.8.1"}, {"sp": "N", "t": "Γνοὺς δὲ τοῦθ’ ὁ πατὴρ Δαυίδης τοῖς μὲν πεπραγμένοις ἤχθετο, φιλῶν δὲ τὸν Ἀμνῶνα σφόδρα, πρεσβύτατος γὰρ ἦν αὐτῷ υἱός, μὴ λυπεῖν αὐτὸν ἠναγκάζετο. ὁ δὲ Ἀψάλωμος ἐμίσει χαλεπῶς αὐτὸν καὶ λανθάνων καιρὸν εἰς ἄμυναν αὐτοῦ τῆς ἁμαρτίας ἐπιτήδειον παρεφύλαττεν. ἔτος δ’ ἤδη τοῖς περὶ τὴν ἀδελφὴν αὐτοῦ πταίσμασιν διεληλύθει δεύτερον, καὶ μέλλων ἐπὶ τὴν τῶν ἰδίων κουρὰν ἐξιέναι θρεμμάτων εἰς Βελσεφών, πόλις δ’ ἐστὶν αὕτη τῆς Ἐφράμου κληρουχίας, παρακαλεῖ τὸν πατέρα σὺν καὶ τοῖς ἀδελφοῖς ἐλθεῖν πρὸς αὐτὸν ἐφ’ ἑστίασιν. παραιτησαμένου δ’ ὡς μὴ βαρὺς αὐτῷ γένοιτο, τοὺς ἀδελφοὺς ἀποστεῖλαι παρεκάλεσε. πέμψαντος δὲ τοῖς ἰδίοις ἐκέλευσεν ὁπηνίκ’ ἂν ἴδωσι τὸν Ἀμνῶνα μέθῃ παρειμένον καὶ κάρῳ, νεύσαντος αὐτοῦ φονεύσωσι μηδένα φοβηθέντες.", "st": "7.8.2"}, {"sp": "N", "t": "Ὡς δ’ ἐποίησαν τὸ προσταχθὲν ἔκπληξις καὶ ταραχὴ τοὺς ἀδελφοὺς λαμβάνει, καὶ δείσαντες τοῖς αὑτῶν ἐμπηδήσαντες ἵπποις ἐφέροντο πρὸς τὸν πατέρα. φθάσας δέ τις αὐτοὺς ἅπαντας ὑπὸ Ἀψαλώμου πεφονεῦσθαι τῷ πατρὶ προσήγγειλεν. ὁ δ’ ὡς ἐπὶ παισὶν ὁμοῦ τοσούτοις ἀπολωλόσι καὶ τοῦθ’ ὑπ’ ἀδελφοῦ τῆς λύπης κἀπὶ τῷ κτεῖναι [δυναμένης] δοκοῦντι γινομένης πικρότερον, συναρπαγεὶς ὑπὸ τοῦ πάθους οὔτε τὴν αἰτίαν ἀνέκρινεν οὔτ’ ἄλλο τι μαθεῖν οἷον εἰκὸς τηλικούτου προσηγγελμένου κακοῦ καὶ δι’ ὑπερβολὴν ἀπιστίαν ἔχοντος περιέμεινεν, ἀλλὰ καταρρηξάμενος τὴν ἐσθῆτα καὶ ῥίψας ἑαυτὸν ἐπὶ τὴν γῆν ἔκειτο πενθῶν τοὺς υἱοὺς ἅπαντας καὶ τοὺς ἀποθανεῖν δεδηλωμένους καὶ τὸν ἀνῃρηκότα. ὁ δὲ Σαμᾶ τοῦ ἀδελφοῦ αὐτοῦ παῖς Ἰωνάθης ἀνεῖναί τι τῆς λύπης παρεκάλει καὶ περὶ μὲν τῶν ἄλλων μὴ πιστεύειν ὡς τεθνᾶσιν, οὐδὲ γὰρ αἰτίαν εὑρίσκειν ὑπολαμβάνειν, περὶ δ’ Ἀμνῶνος ἐξετάζειν ἔφη δεῖν· εἰκὸς γὰρ διὰ τὴν Θημάρης ὕβριν ἀποτολμῆσαι τὸν Ἀψάλωμον τὴν ἀναίρεσιν τὴν ἐκείνου. μεταξὺ δὲ κτύπος ἵππων καὶ θόρυβος προσιόντων τινῶν αὐτοὺς ἐπέστρεψεν· ἦσαν δ’ οἱ τοῦ βασιλέως παῖδες οἱ διαδράντες ἀπὸ τῆς ἑστιάσεως. ὑπαντᾷ δ’ αὐτοῖς ὁ πατὴρ θρηνοῦσι λυπούμενος καὶ παρ’ ἐλπίδας ὁρῶν οὓς ἀκηκόει μικρὸν ἔμπροσθεν ἀπολωλότας. ἦν δὲ παρὰ πάντων δάκρυα καὶ στόνος, τῶν μὲν ὡς ἐπ’ ἀδελφῷ τετελευτηκότι, τοῦ δὲ βασιλέως ὡς ἐπὶ παιδὶ κατεσφαγμένῳ. φεύγει δ’ Ἀψάλωμος εἰς Γεσσούραν πρὸς τὸν πάππον τὸν πρὸς μητρὸς δυναστεύοντα τῆς ἐκεῖ χώρας, καὶ τρισὶν ὅλοις ἔτεσι παρ’ αὐτῷ καταμένει.", "st": "7.8.3"}, {"sp": "N", "t": "Τοῦ δὲ Δαυίδου προαίρεσιν ἔχοντος ἐπὶ τὸν υἱὸν Ἀψάλωμον πέμπειν, οὐκ ἐπὶ τιμωρίᾳ κατελευσόμενον, ἀλλ’ ὅπως εἴη σὺν αὐτῷ, καὶ γὰρ τὰ τῆς ὀργῆς ὑπὸ τοῦ χρόνου λελωφήκει, πρὸς τοῦτο μᾶλλον αὐτὸν Ἰώαβος ὁ ἀρχιστράτηγος παρώρμησε· γύναιον γάρ τι τὴν ἡλικίαν ἤδη προβεβηκὸς ἐποίησεν αὐτῷ προσελθεῖν ἐν σχήματι πενθίμῳ, ὡς παίδων ἐπὶ τῆς ἀγροικίας αὐτῇ διενεχθέντων καὶ πρὸς φιλονεικίαν τραπέντων οὐδενὸς τοῦ καταπαῦσαι δυναμένου παραφανέντος ἔλεγεν ὑπὸ θατέρου τὸν ἕτερον πληγέντα ἀποθανεῖν· ἠξίου τε τῶν συγγενῶν ἐπὶ τὸν ἀνῃρηκότα ὡρμηκότων καὶ ζητούντων αὐτὸν ἀνελεῖν, χαρίσασθαι τὴν σωτηρίαν αὐτῇ τοῦ παιδὸς καὶ μὴ τὰς ἐπιλοίπους τῆς γηρωκομίας ἐλπίδας προσαφαιρεθῆναι· τοῦτο δ’ αὐτῇ κωλύσαντα τοὺς βουλομένους ἀποκτεῖναι τὸν υἱὸν αὐτῆς παρέξειν· οὐ γὰρ ἐφέξειν ἐκείνους ἄλλῳ τινὶ τῆς σπουδῆς ἢ τῷ παρ’ αὐτοῦ φόβῳ. τοῦ δὲ συγκαταινέσαντος οἷς τὸ γύναιον ἱκέτευσεν, ὑπολαβὸν πάλιν πρὸς τὸν βασιλέα χάρις μέν, εἶπεν, ἤδη σου τῇ χρηστότητι κατοικτείραντός μου τὸ γῆρας καὶ τὴν παρὰ μικρὸν ἀπαιδίαν, ἀλλ’ ἵνα βέβαια τὰ παρὰ τῆς σῆς μοι ᾖ φιλανθρωπίας, τῷ σαυτοῦ παιδὶ πρῶτον καταλλάγηθι καὶ τὴν πρὸς αὐτὸν ὀργὴν ἄφες· πῶς γὰρ ἂν πεισθείην ἐμοί σε ταύτην [ἀληθῶς] δεδωκέναι τὴν χάριν αὐτοῦ σοῦ μέχρι νῦν ἐφ’ ὁμοίοις ἀπεχθανομένου τῷ παιδί; τελέως δ’ ἀνόητον εἶναι προσθεῖναι τῷ παρὰ γνώμην ἀποθανόντι υἱῷ ἄλλον ἑκουσίως. συνίησι δὲ ὁ βασιλεὺς ὑπόβλητον οὖσαν τὴν σκῆψιν ἐξ Ἰωάβου καὶ τῆς τούτου σπουδῆς· καὶ ἐπειδὴ παρὰ τῆς πρεσβύτιδος πυθόμενος οὕτως ἔχον τἀληθὲς ἔμαθε, προσκαλεσάμενος τὸν Ἰώαβον ἐπιτυχεῖν τε τοῦ προκειμένου κατὰ νοῦν ἔφασκε καὶ τὸν Ἀψάλωμον ἄγειν ἐκέλευεν· οὐ γὰρ ἔτι χαλεπῶς ἔχειν πρὸς αὐτόν, ἀλλ’ ἤδη τὴν ὀργὴν καὶ τὸν θυμὸν ἀφεικέναι. ὁ δὲ προσκυνήσας τὸν βασιλέα καὶ τοὺς λόγους ἀσπασάμενος ἐξώρμησεν εἰς τὴν Γεσσούραν παραυτίκα καὶ τὸν Ἀψάλωμον παραλαβὼν ἧκεν εἰς Ἱεροσόλυμα.", "st": "7.8.4"}, {"sp": "N", "t": "Προέπεμψε δὲ ὁ βασιλεὺς πρόσθεν πρὸς τὸν υἱόν, ἤκουσε γὰρ παραγενόμενον, καὶ πρὸς ἑαυτὸν ἐκέλευσε χωρεῖν· οὔπω γὰρ οὕτως ἔχειν ὥστ’ εὐθὺς ἰδεῖν κατελθόντα. καὶ ὁ μὲν τοῦτο τοῦ πατρὸς κελεύσαντος ἐξέκλινε τὴν ὄψιν αὐτοῦ καὶ διετέλει τῆς παρὰ τῶν οἰκείων θεραπείας τυγχάνων. οὐκ ἐπιβέβλαπτο δ’ εἰς τὸ κάλλος ὑπό τε τῆς λύπης καὶ τοῦ μὴ τυγχάνειν τῆς προσηκούσης ἐπιμελείας υἱῷ βασιλέως, ἀλλ’ ἔτι γὰρ ἐξεῖχε καὶ διέπρεπε πᾶν τῷ τε εἴδει καὶ τῷ μεγέθει τοῦ σώματος καὶ τοὺς ἐν πολλῇ τρυφῇ διαιτωμένους ὑπερέβαλλε. τοσοῦτον μέντοι γε ἦν τὸ βάθος τῆς κόμης, ὡς μόλις αὐτὴν ἡμέραις ἀποκείρειν ὀκτὼ σταθμὸν ἕλκουσαν σίκλους διακοσίους· οὗτοι δ’ εἰσὶ πέντε μναῖ. διέτριψε μέντοι γε ἐν Ἱεροσολύμοις ἔτη δύο τριῶν μὲν ἀρρένων πατὴρ γενόμενος μιᾶς δὲ θυγατρὸς τὴν μορφὴν ἀρίστης, ἣν ὁ Σολόμωνος υἱὸς Ῥοβόαμος ὕστερον λαμβάνει, καὶ γίνεται παιδίον ἐξ αὐτῆς Ἀβίας ὄνομα. πέμψας δ’ αὐτὸς Ἀψάλωμος πρὸς Ἰώαβον ἐδεῖτ’ αὐτοῦ τελέως καταπραῧναι τὸν πατέρα καὶ δεηθῆναι, ὅπως αὐτῷ συγχωρήσῃ πρὸς αὐτὸν ἐλθόντι θεάσασθαί τε καὶ προσειπεῖν. καταμελήσαντος δὲ Ἰωάβου τῶν ἰδίων τινὰς ἀποστείλας τὴν ὁμοροῦσαν αὐτῷ χώραν ἐπυρπόλησεν. ὁ δὲ τὸ πραχθὲν μαθὼν ἧκε πρὸς τὸν Ἀψάλωμον ἐγκαλῶν τε αὐτῷ καὶ τὴν αἰτίαν πυνθανόμενος. ὁ δέ στρατήγημα τοῦτ’, εἶπεν, εὗρον ἀγαγεῖν σε πρὸς ἡμᾶς δυνάμενον ἀμελοῦντα τῶν ἐντολῶν, ἃς ἵνα μοι τὸν πατέρα διαλλάξῃς ἐποιούμην. καὶ δὴ δέομαί σου παρόντος ἡμερῶσαί μοι τὸν γεγεννηκότα· ὡς ἔγωγε δεινοτέραν τῆς φυγῆς κρίνω τὴν κάθοδον ἔτι τοῦ πατρὸς ἐν ὀργῇ μένοντος. πεισθεὶς δ’ ὁ Ἰώαβος καὶ τὴν ἀνάγκην αὐτοῦ κατοικτείρας ἐμεσίτευσε πρὸς τὸν βασιλέα καὶ διαλεχθεὶς περὶ τοῦ παιδὸς οὕτως αὐτὸν ἡδέως διατίθησιν, ὡς εὐθέως καλέσαι πρὸς αὑτόν. τοῦ δὲ ῥίψαντος αὑτὸν ἐπὶ τοὔδαφος καὶ συγγνώμην αἰτουμένου τῶν ἡμαρτημένων ἀνίστησί τε καὶ τῶν γεγονότων ἀμνηστίαν ἐπαγγέλλεται.", "st": "7.8.5"}, {"sp": "N", "t": "Ὁ δὲ Ἀψάλωμος τοιούτων αὐτῷ τῶν παρὰ τοῦ πατρὸς ἀποβάντων πολλοὺς μὲν ἵππους ἐν ὀλίγῳ πάνυ χρόνῳ πολλὰ δ’ ἅρματα ἐκέκτητο, καὶ ὁπλοφόροι περὶ αὐτὸν ἦσαν πεντήκοντα· καθ’ ἑκάστην δ’ ἡμέραν ὄρθριος πρὸς τὰ βασίλεια παρεγίνετο καὶ τοῖς ἐπὶ τὰς κρίσεις ἥκουσι καὶ ἐλαττουμένοις πρὸς ἡδονὴν ὁμιλῶν, ὡς παρὰ τὸ μὴ συμβούλους ἀγαθοὺς εἶναι τῷ πατρὶ τάχ’ αὐτῷ καὶ ἀδίκως ἐπταικότων τῶν περὶ τὴν κρίσιν, εὔνοιαν αὑτῷ παρὰ πάντων κατεσκεύαζε λέγων, ὡς αὐτὸς ἂν εἰ ταύτην εἶχε τὴν ἐξουσίαν πολλὴν αὐτοῖς ἐβράβευσεν εὐνομίαν. τούτοις δημαγωγῶν τὸ πλῆθος ὡς βεβαίαν ἤδη τὴν παρὰ τῶν ὄχλων εὔνοιαν ἐνόμιζε, μετὰ δὲ τὴν τοῦ πατρὸς αὐτοῦ καταλλαγὴν τεσσάρων ἐτῶν ἤδη διεληλυθότων, ἐδεῖτο προσελθὼν εἰς Γιβρῶνα συγχωρῆσαι πορευθέντι θυσίαν ἀποδοῦναι τῷ θεῷ· φεύγοντα γὰρ αὐτὸν εὔξασθαι. τοῦ δὲ Δαυίδου τὴν ἀξίωσιν ἐφέντος πορεύεται, καὶ πολὺς ἐπισυνέρρευσεν ὄχλος ἐπὶ πολλοὺς αὐτοῦ διαπέμψαντος.", "st": "7.9.1"}, {"sp": "N", "t": "Παρῆν δὲ καὶ ὁ Δαυίδου σύμβουλος ὁ Γελμωναῖος Ἀχιτόφελος καὶ διακόσιοί τινες ἐξ αὐτῶν Ἱεροσολύμων οὐκ εἰδότες μὲν τὴν ἐπιχείρησιν, ὡς δ’ ἐπὶ θυσίαν μετεσταλμένοι· καὶ βασιλεὺς ὑπὸ πάντων ἀποδείκνυται τοῦτο γενέσθαι στρατηγήσας. ὡς δ’ ἀπηγγέλη ταῦτα Δαυίδῃ καὶ παρ’ ἐλπίδας αὐτῷ τὰ παρὰ τοῦ παιδὸς ἠκούσθη, δείσας ἅμα καὶ τῆς ἀσεβείας καὶ τῆς τόλμης αὐτὸν θαυμάσας, ὅτι μηδὲ τῆς ἐπὶ τοῖς ἡμαρτημένοις συγγνώμης ἐμνημόνευσεν, ἀλλ’ ἐκείνων πολὺ χείροσι καὶ παρανομωτέροις ἐπεβάλετο βασιλείᾳ πρῶτον μὲν ὑπὸ θεοῦ οὐ δεδομένῃ, δεύτερον δὲ ἐπ’ ἀφαιρέσει τοῦ γεγεννηκότος, ἔγνω φεύγειν εἰς τὰ πέραν τοῦ Ἰορδάνου. καὶ συγκαλέσας τῶν φίλων τοὺς ἐπιτηδειοτάτους καὶ περὶ τῆς τοῦ παιδὸς ἀπονοίας κοινολογησάμενος αὐτοῖς καὶ περὶ πάντων ἐπιτρέψας κριτῇ τῷ θεῷ, καταλιπὼν τὰ βασίλεια φυλάσσειν δέκα παλλακίσιν ἀπῆρεν ἐκ τῶν Ἱεροσολύμων, τοῦ τε ἄλλου πλήθους αὐτῷ συνεξορμήσαντος καὶ τῶν ἑξακοσίων ὁπλιτῶν, οἳ καὶ τῆς πρώτης φυγῆς ἐκοινώνουν, ὅτ’ ἔζη Σαοῦλος. τὸν δὲ Ἀβιάθαρον καὶ Σάδωκον τοὺς ἀρχιερεῖς συναπαίρειν διεγνωκότας καὶ Λευίτας ἅπαντας μετὰ τῆς κιβωτοῦ μένειν ἔπεισεν, ὡς τοῦ θεοῦ καὶ μὴ μετακομιζομένης αὐτῆς ῥυσομένου. ἐνετείλατο δ’ ἕκαστα τῶν γινομένων λάθρα διαγγέλλειν αὐτῷ· πιστοὺς δ’ ἔσχε πρὸς πάντα διακόνους παῖδας Ἀχίμανον μὲν Σαδώκου Ἰωνάθην δὲ Ἀβιαθάρου. Ἔθις δ’ ὁ Γιτταῖος συνεξώρμησεν αὐτῷ βιασάμενος τὴν Δαυίδου βούλησιν, μένειν γὰρ αὐτὸν ἀνέπειθε, καὶ διὰ τοῦτο μᾶλλον εὔνους αὐτῷ κατεφάνη. ἀναβαίνοντος δ’ αὐτοῦ διὰ τοῦ Ἐλαιῶνος ὄρους γυμνοῖς τοῖς ποσὶ καὶ πάντων σὺν αὐτῷ δακρυόντων, ἀγγέλλεται καὶ ὁ Ἀχιτόφελος συνὼν τῷ Ἀψαλώμῳ καὶ τὰ τούτου φρονῶν. ἐπέτεινε δ’ αὐτῷ τὸ λυπηρὸν τοῦτ’ ἀκουσθέν, καὶ τὸν θεὸν ἐπεκαλεῖτο δεόμενος ἀπαλλοτριῶσαι τὴν Ἀψαλώμου διάνοιαν πρὸς τὸν Ἀχιτόφελον. ἐδεδίει γάρ, μὴ τἀναντία συμβουλεύων πείσειεν αὐτὸν ἀνὴρ ὢν φρενήρης καὶ συνιδεῖν τὸ λυσιτελὲς ὀξύτατος. γενόμενος δ’ ἐπὶ τῆς κορυφῆς τοῦ ὄρους ἀπεσκόπει τὴν πόλιν καὶ μετὰ πολλῶν δακρύων ὡς ἂν βασιλείας ἐκπεσὼν ηὔχετο τῷ θεῷ· συνήντησε δ’ αὐτῷ φίλος ἀνὴρ καὶ βέβαιος Χουσὶς ὄνομα. τοῦτον ὁρῶν τὴν ἐσθῆτα κατερρηγμένον καὶ τὴν κεφαλὴν σποδοῦ πλήρη καὶ θρηνοῦντα τὴν μεταβολὴν παρηγορεῖ καὶ παύσασθαι τῆς λύπης παρακαλεῖ καὶ τέλος ἱκέτευσεν ἀπελθόντα πρὸς Ἀψάλωμον ὡς τὰ ἐκείνου φρονοῦντα τά τε ἀπόρρητα τῆς διανοίας αὐτοῦ κατανοεῖν καὶ ταῖς Ἀχιτοφέλου συμβουλίαις ἀντιπράσσειν· οὐ γὰρ τοσοῦτον ὠφελήσειν αὐτῷ συνερχόμενον, ὅσον παρ’ ἐκείνῳ γενόμενον. καὶ ὁ μὲν πεισθεὶς τῷ Δαυίδῃ, καταλιπὼν αὐτὸν ἧκεν εἰς Ἱεροσόλυμα· ἀφικνεῖται δ’ εἰς αὐτὰ μετ’ οὐ πολὺ καὶ Ἀψάλωμος.", "st": "7.9.2"}, {"sp": "N", "t": "Ὀλίγον δὲ τῷ Δαυίδῃ προελθόντι Σιβᾶς ὁ τοῦ Μεμφιβόσθου δοῦλος συνήντησεν, ὃν προνοησόμενον ἀπεστάλκει τῶν κτήσεων ἃς δεδώρητο τῷ Ἰωνάθου τοῦ Σαούλου παιδὸς υἱῷ, μετὰ ζεύγους ὄνων καταπεφορτισμένων τοῖς ἐπιτηδείοις, ἐξ ὧν ἐκέλευσε λαμβάνειν ὧν αὐτός τε καὶ οἱ σὺν αὐτῷ δέοιντο. πυνθανομένου δέ, ποῦ καταλέλοιπε τὸν Μεμφίβοσθον, ἐν Ἱεροσολύμοις ἔλεγε προσδοκῶντα χειροτονηθήσεσθαι βασιλέα διὰ τὴν ὑπάρχουσαν ταραχὴν εἰς μνήμην ὧν εὐηργέτησεν αὐτοὺς Σαοῦλος. ἀγανακτήσας δ’ ἐπὶ τούτῳ πάνθ’ ὅσα τῷ Μεμφιβόσθῳ παρεχώρησε Σιβᾷ χαρίζεται πολὺ γὰρ δικαιότερον αὐτὸν ἐκείνου ταῦτ’ ἔχειν ἐπέγνωκε· καὶ ὁ μὲν Σιβᾶς περιχαρὴς ἦν.", "st": "7.9.3"}, {"sp": "N", "t": "Δαυίδῃ δὲ γενομένῳ κατὰ Χώρανον τόπον οὕτως καλούμενον ἐπέρχεται τοῦ Σαούλου συγγενὴς Σαμούις μὲν ὄνομα υἱὸς δὲ Γηρᾶ, καὶ λίθοις τε ἔβαλλεν αὐτὸν καὶ ἐκακηγόρει. περιστάντων δὲ τῶν φίλων καὶ σκεπόντων ἔτι μᾶλλον ὁ Σαμούις βλασφημῶν διετέλει, μιαιφόνον καὶ πολλῶν ἀρχηγὸν κακῶν ἀποκαλῶν. ἐκέλευε δὲ καὶ τῆς γῆς ὡς ἐναγῆ καὶ ἐπάρατον ἐξιέναι, καὶ τῷ θεῷ χάριν ὡμολόγει τῆς βασιλείας αὐτὸν ἀφελομένῳ καὶ διὰ παιδὸς ἰδίου τὴν ὑπὲρ ὧν ἥμαρτεν εἰς τὸν αὑτοῦ δεσπότην δίκην αὐτὸν εἰσπραξαμένῳ. πάντων δ’ ἐπ’ αὐτὸν ἠρεθισμένων ὑπ’ ὀργῆς καὶ μάλιστα Ἀβεσσαίου διαχρήσασθαι βουλομένου τὸν Σαμούιν Δαυίδης αὐτὸν τῆς ὀργῆς ἐπέσχε, μὴ τοῖς παροῦσι κακοῖς ἑτέραν προσεξεργασώμεθα, φησί, καινοτέραν ἀφορμήν· οὐ γὰρ δὴ τοῦ προσλυσσῶντός μοι τούτου κυνὸς αἰδώς τις ἢ φροντὶς ὑπέρχεται, τῷ θεῷ δὲ εἴκω, δι’ ὃν οὗτος ἐφ’ ἡμᾶς ἀπενοήθη. θαυμαστὸν δ’ οὐδὲν ὑπὸ τούτου με ταῦτα πάσχειν, ὅπου γε καὶ παιδὸς ἀσεβοῦς πεπείραμαι. ἀλλ’ ἔσται τις οἶκτος ἡμῖν ἐκ θεοῦ καὶ κρατήσομεν τῶν ἐχθρῶν τούτου θελήσαντος. ἤνυεν οὖν τὴν ὁδὸν οὐ φροντίζων τοῦ Σαμούι παρὰ τὸ ἕτερον μέρος τοῦ ὄρους διατρέχοντος καὶ πολλὰ κακηγοροῦντος· παραγενόμενος δ’ ἐπὶ τὸν Ἰόρδανον ἀνελάμβανε τοὺς ἰδίους ἐνταῦθα κεκοπωμένους.", "st": "7.9.4"}, {"sp": "N", "t": "Ἀψαλώμου δὲ καὶ Ἀχιτοφέλου τοῦ συμβούλου παραγενομένων εἰς Ἱεροσόλυμα σὺν ἅπαντι τῷ λαῷ, καὶ ὁ Δαυίδου φίλος ἧκε πρὸς αὐτοὺς καὶ προσκυνήσας αὐτὸν συνηύχετο τὴν βασιλείαν εἰς αἰῶνα καὶ τὸν πάντα παραμεῖναι χρόνον. φήσαντος δ’ ἐκείνου πρὸς αὐτόν, τί δήποτε φίλος ἐν τοῖς μάλιστα τοῦ πατρὸς αὐτοῦ γεγενημένος καὶ πρὸς ἅπαντα πιστὸς εἶναι δόξας οὐ σὺν αὐτῷ νῦν ἐστιν, ἀλλὰ καταλιπὼν ἐκεῖνον μεταβαίη πρὸς αὐτόν, δεξιῶς ἀποκρίνεται καὶ σωφρόνως· εἶπε γὰρ ἕπεσθαι δεῖν αὐτὸν τῷ θεῷ καὶ τῷ παντὶ πλήθει. τούτων οὖν μετὰ σοῦ, ὦ δέσποτα, γεγενημένων εἰκότως ἕπομαι κἀγώ· τὴν γὰρ βασιλείαν ἔλαβες παρὰ τοῦ θεοῦ. τὴν αὐτὴν μέντοι γε πίστιν καὶ εὔνοιαν ἐνδείξομαι πιστευόμενος εἶναι φίλος, ἣν οἶσθά με τῷ πατρί σου παρεσχημένον. ἀγανακτεῖν δ’ οὐδὲν προσῆκε τοῖς παροῦσιν· οὐ γὰρ εἰς ἄλλην οἰκίαν ἡ βασιλεία μεταβέβηκε, μεμένηκε δ’ ἐπὶ τῆς αὐτῆς υἱοῦ παραλαβόντος. ταῦτα λέγων ἔπειθεν· ὕποπτον γὰρ αὐτὸν εἶχε. καὶ καλέσας τὸν Ἀχιτόφελον συνεβουλεύετο αὐτῷ τί δεῖ ποιεῖν· ὁ δὲ παρῄνεσε ταῖς τοῦ πατρὸς αὐτὸν παλλακαῖς συνελθεῖν· ἐκ τούτου γὰρ εἴσεσθαι τὸν λαὸν ἔλεγε πιστεύσαντα, ὡς ἀδιάλλακτά σοι τὰ πρὸς αὐτόν ἐστι, καὶ μετὰ πολλῆς συστρατεύσεσθαι προθυμίας ἐπὶ τὸν πατέρα· μέχρι δεῦρο γὰρ φανερὰν ἔχθραν ἀναλαμβάνειν δεδιέναι προσδοκῶντας ὑμᾶς ὁμονοήσειν. πεισθεὶς δὲ τῇ συμβουλίᾳ κελεύει σκηνὴν αὑτῷ πῆξαι τοὺς οἰκέτας ἐπὶ τοῦ βασιλείου τοῦ πλήθους ὁρῶντος, καὶ παρελθὼν συνέρχεται ταῖς τοῦ πατρὸς παλλακαῖς. ταῦτα δ’ ἐγένετο κατὰ τὴν Νάθα προφητείαν, ἣν τῷ Δαυίδῃ σημαίνων τὴν ἐκ τοῦ παιδὸς ἐσομένην ἐπίθεσιν προεφήτευσε.", "st": "7.9.5"}, {"sp": "N", "t": "Ποιήσας δ’ Ἀψάλωμος τὰ παραινεθέντα αὐτῷ ὑπὸ τοῦ Ἀχιτοφέλου δεύτερον αὐτὸν ἠξίου συμβουλεύειν περὶ τοῦ πολέμου τοῦ πρὸς τὸν πατέρα. μυρίους δ’ αὐτὸν ἐπιλέκτους αἰτήσαντος ἐκείνου καὶ τόν τε πατέρα κτενεῖν αὐτοῦ καὶ τοὺς σὺν αὐτῷ ζωοὺς ἀνάξειν ὑποσχομένου καὶ βεβαίαν τότε τὴν βασιλείαν ἔσεσθαι φήσαντος Δαυίδου μηκέτι ζῶντος, ἀρεσθεὶς τῇ γνώμῃ μετακαλεῖται καὶ τὸν Χουσὶν τὸν Δαυίδου ἀρχίφιλον· οὕτως γὰρ αὐτὸν ἐκεῖνος ἐκάλει· καὶ τὴν Ἀχιτοφέλου γνώμην αὐτῷ δηλώσας, τί καὶ αὐτῷ δοκεῖ περὶ αὐτῆς ἐπυνθάνετο. συνιδὼν δ’, ὅτι γενομένων ὧν Ἀχιτόφελος συνεβούλευσε κινδυνεύσει Δαυίδης συλληφθεὶς ἀποθανεῖν, γνώμην εἰσφέρειν ἐναντίαν ἐπειρᾶτο· οὐ γὰρ ἀγνοεῖς εἶπεν, ὦ βασιλεῦ, τὴν τοῦ πατρὸς καὶ τὴν τῶν συνόντων αὐτῷ ἀνδρείαν, ὅτι καὶ πολλοὺς πολέμους πεπολέμηκε καὶ πάντοτε κρατῶν τῶν ἐχθρῶν ἀπήλλακται. νῦν δὲ εἰκὸς αὐτὸν ἐπὶ στρατοπέδου μένειν· στρατηγῆσαι γὰρ ἱκανώτατος καὶ προϊδεῖν ἀπάτην ἐπερχομένων πολεμίων· ἀλλὰ κατὰ τὴν ἑσπέραν ἀπολιπὼν τοὺς ἰδίους ἢ εἴς τινα τῶν αὐλώνων ἑαυτὸν ἀποκρύψει ἢ πρὸς πέτρᾳ τινὶ λοχήσει· συμβαλόντων δὲ τῶν ἡμετέρων οἱ μὲν ἐκείνου πρὸς μικρὸν ὑποχωρήσουσιν, αὐτοὶ δὲ θαρσήσαντες ὡς τοῦ βασιλέως αὐτοῖς ἐγγὺς ὄντος ἀντιστήσονται, καὶ μεταξὺ τούτων μαχομένων ὁ πατὴρ ἐπιφανεὶς ἐξαίφνης τοῖς μὲν εὐψυχίαν πρὸς τοὺς κινδύνους παρασκευάσει τοὺς δὲ σοὺς καταπλήξεται. παράθου δὴ τοίνυν καὶ τὴν ἐμὴν συμβουλίαν τῷ λογισμῷ καὶ ταῦτ’ ἐπιγνοὺς ἄριστα τὴν μὲν Ἀχιτοφέλου γνώμην παραίτησαι, πέμψας δ’ εἰς πᾶσαν τὴν χώραν τῶν Ἑβραίων παράγγειλον αὐτοῖς τὴν ἐπὶ τὸν πατέρα σου στρατείαν, καὶ παραλαβὼν αὐτὸς τὴν δύναμιν τοῦ πολέμου γίνου στρατηγὸς καὶ μὴ πιστεύσῃς τοῦτον ἑτέρῳ. νικήσειν γὰρ προσδόκα ῥᾳδίως αὐτόν, ἂν ἐν φανερῷ καταλάβῃς ὄντα μετ’ ὀλίγων αὐτὸς πολλὰς ἔχων μυριάδας βουλομένων τὴν περὶ σὲ σπουδὴν ἐπιδείξασθαι καὶ προθυμίαν. ἂν δ’ ὁ πατὴρ αὑτὸν εἰς πολιορκίαν περικλείσῃ, μηχανήμασι καὶ ὀρύγμασιν ὑπονόμοις καθαιρήσομεν ἐκείνην τὴν πόλιν. ταῦτ’ εἰπὼν εὐδοκίμησε μᾶλλον Ἀχιτοφέλου· τῆς γὰρ ἐκείνου γνώμης ἡ τούτου προεκρίθη παρ’ Ἀψαλώμου. θεὸς μέντοι γε ἦν ὁ τούτου τῇ διανοίᾳ τὴν τοῦ Χουσὶ συμβουλίαν συστήσας ἀμείνω εἶναι δοκεῖν.", "st": "7.9.6"}, {"sp": "N", "t": "Σπεύσας δὲ πρὸς τοὺς ἀρχιερέας Σάδωκον καὶ Ἀβιάθαρον καὶ τήν τε Ἀχιτοφέλου γνώμην ἐξειπὼν αὐτοῖς καὶ τὴν ἑαυτοῦ καὶ ὅτι δέδοκται τὰ ὑπ’ αὐτοῦ παραινεθέντα πράττειν, ἐκέλευσε μηνύειν πέμψαντας Δαυίδῃ καὶ φανερὰ ποιεῖν τὰ συμβεβουλευμένα καὶ προσπαρακελεύσασθαι ταχέως διαβῆναι τὸν Ἰόρδανον, μὴ μεταγνοὺς ὁ παῖς αὐτοῦ διώκειν ὁρμήσῃ καὶ πρὶν ἐν ἀσφαλείᾳ γένηται φθάσας καταλάβῃ. οἱ δὲ ἀρχιερεῖς ἐξεπίτηδες τοὺς υἱοὺς ἔξω τῆς πόλεως κεκρυμμένους εἶχον, ὅπως διακομίσωσι πρὸς τὸν Δαυίδην τὰ πραττόμενα· πέμψαντες οὖν πιστὴν θεραπαινίδα πρὸς αὐτοὺς φέρουσαν τὰ βεβουλευμένα ὑπὸ τοῦ Ἀψαλώμου προσέταξαν μετὰ σπουδῆς ταῦτα Δαυίδῃ σημαίνειν. οἱ δ’ οὐδὲν εἰς ἀναβολὰς καὶ μέλλησιν ὑπερέθεντο, λαβόντες δὲ τὰς τῶν πατέρων ἐντολὰς εὐσεβεῖς ἅμα καὶ πιστοὶ γίνονται διάκονοι· καὶ τῆς ὑπηρεσίας τὸ τάχος καὶ τὴν ὀξύτητα κρίναντες ἄριστα εἶναι ἠπείγοντο συμβαλεῖν Δαυίδῃ. γενομένους δ’ αὐτοὺς ἀπὸ σταδίων τῆς πόλεως δύο θεῶνταί τινες ἱππεῖς καὶ διαβάλλουσι πρὸς τὸν Ἀψάλωμον· ὁ δ’ εὐθὺς ἔπεμψε τοὺς συλληψομένους. νοήσαντες δὲ τοῦτο οἱ τῶν ἀρχιερέων παῖδες ἐκτραπέντες τῆς ὁδοῦ παραχρῆμα εἰς κώμην τινὰ τῶν Ἱεροσολύμων οὐκ ἄπωθεν αὑτοὺς ἔδωκαν, Βοκχόρης ἦν ὄνομα τῇ πόλει, καὶ γυναικὸς ἐδεήθησάν τινος κρύψαι καὶ παρασχεῖν αὐτοῖς τὴν ἀσφάλειαν. ἡ δὲ καθιμήσασα τοὺς νεανίσκους εἰς φρέαρ καὶ πλάκας ἄνωθεν ἐρίων ἐρίων ἐπιβαλοῦσα, ὡς ἧκον οἱ διώκοντες αὐτοὺς καὶ περὶ αὐτῶν ἀνέκριναν εἰ θεάσαιτο, ἰδεῖν οὐκ ἠρνήσατο, πιόντας γὰρ παρ’ αὐτῇ πάλιν ἀπελθεῖν, εἰ μέντοι γε συντόνως διώξουσι καταλήψεσθαι προύλεγεν. ὡς δ’ ἐπὶ πολὺ διώξαντες οὐ κατέλαβον, ἀνέστρεψαν εἰς τοὐπίσω. θεασαμένη δ’ αὐτοὺς ἀναζεύξαντας ἡ γυνὴ καὶ μηδένα φόβον τοῖς νεανίσκοις ἀπ’ αὐτῶν ἔτι συλλήψεως εἶναι, ἀνιμήσασα τὴν προκειμένην ὁδὸν ἀνύειν παρεκελεύσατο· καὶ πολλῇ σπουδῇ καὶ τάχει χρησάμενοι περὶ τὴν ὁδοιπορίαν ἧκον πρὸς Δαυίδην καὶ πάντ’ ἀκριβῶς ἐδήλωσαν τὰ παρ’ Ἀψαλώμου βεβουλευμένα. ὁ δὲ διαβῆναι τὸν Ἰόρδανον τοὺς μεθ’ ἑαυτοῦ προσέταξεν ἤδη νυκτὸς οὔσης καὶ μηδὲν ὀκνεῖν δι’ αὐτήν.", "st": "7.9.7"}, {"sp": "N", "t": "Ἀχιτόφελος δὲ τῆς γνώμης αὐτοῦ παρευδοκιμηθείσης ἐπιβὰς τοῦ κτήνους ἐξώρμησεν εἰς Γελμὼν τὴν πατρίδα· καὶ συγκαλέσας τοὺς οἰκείους ἅπαντας ἃ συνεβούλευσεν Ἀψαλώμῳ ταῦτ’ αὐτοῖς διεξῆλθε, καὶ ὡς οὐ πεισθεὶς φανερός ἐστιν οὐκ εἰς μακρὰν ἀπολούμενος· Δαυίδην δὲ κρατήσειν ἔλεγεν [καὶ] ἐπανήξειν ἐπὶ τὴν βασιλείαν. ἄμεινον οὖν ἔφησεν εἶναι τοῦ ζῆν αὑτὸν ἐξαγαγεῖν ἐλευθέρως καὶ μεγαλοφρόνως ἢ παρασχεῖν αὑτὸν εἰς κόλασιν Δαυίδῃ, καθ’ οὗ πάντα συνέπραττεν Ἀψαλώμῳ. ταῦτα διαλεχθεὶς καὶ παρελθὼν εἰς τὸ μυχαίτατον τῆς οἰκίας ἀνήρτησεν ἑαυτόν. καὶ τὸν μὲν Ἀχιτόφελον τοιούτου θανάτου δικαστὴν αὑτῷ γενόμενον καθελόντες ἐκ τῆς ἀγχόνης ἐκήδευσαν οἱ προσήκοντες. ὁ δὲ Δαυίδης διαβὰς τὸν Ἰόρδανον, καθὼς προειρήκαμεν, εἰς Παρεμβολὰς καλλίστην καὶ ὀχυρωτάτην πόλιν παραγίνεται· δέχονται δὲ αὐτὸν ἀσμενέστατα πάντες οἱ πρῶτοι τῆς χώρας κατά τε αἰδῶ τῆς τότε φυγῆς καὶ κατὰ τιμὴν τῆς προτέρας εὐπραγίας. ἦσαν δὲ οὗτοι Βερζελαῖος ὁ Γαλαδίτης καὶ Σειφὰρ ὁ τῆς Ἀμμανίτιδος δυνάστῃς καὶ Μάχειρος ὁ τῆς Γαλαδίτιδος χώρας πρῶτος. οὗτοι πᾶσαν αὐτῷ καὶ τοῖς ἐκείνου τῶν ἐπιτηδείων ἐκτένειαν παρέσχον, ὡς μήτε κλίνας ἐπιλιπεῖν ἐστρωμένας μήτε ἄρτους καὶ οἶνον, ἀλλὰ καὶ θυμάτων ἀφθονίαν χορηγῆσαι καὶ τῶν εἰς ἀνάπαυσιν ἤδη κεκοπωμένοις καὶ τροφὴν χρησίμων εὐπορίαν διαρκῆ παρασχεῖν.", "st": "7.9.8"}, {"sp": "N", "t": "Καὶ οἱ μὲν ἐν τούτοις ἦσαν· Ἀψάλωμος δ’ ἀθροίσας μεγάλην στρατιὰν τῶν Ἑβραίων ἐπὶ τὸν πατέρα καὶ διαβὰς τὸν Ἰόρδανον ποταμὸν οὐ πόρρω κατέζευξε τῶν Παρεμβολῶν ἐν τῇ Γαλαδιτῶν χώρᾳ, καταστήσας στρατηγὸν πάσης τῆς δυνάμεως Ἀμασᾶν εἰς τὴν Ἰωάβου τάξιν τοῦ συγγενοῦς αὐτοῦ· πατρὸς μὲν γὰρ ἦν Ἰεθράου μητρὸς δὲ Ἀβιγαίας, αὕτη δὲ καὶ Σουρία ἡ Ἰωάβου μήτηρ ἀδελφαὶ ἦσαν Δαυίδου. ὡς δ’ ἐξαριθμήσας τοὺς σὺν αὐτῷ Δαυίδης περὶ τετρακισχιλίους εὗρεν ὄντας, οὐκ ἔγνω μένειν, πότ’ ἐπ’ αὐτὸν Ἀψάλωμος ἔλθῃ, προσθεὶς δὲ τοῖς οὖσι χιλιάρχους καὶ ἑκατοντάρχους καὶ διελὼν εἰς τρία μέρη τὸ μὲν τῷ στρατηγῷ παρέδωκεν Ἰωάβῳ, τὸ δὲ τῷ ἀδελφῷ αὐτοῦ Ἀβεσσαίῳ, τὴν δὲ τρίτην μοῖραν ἐνεχείρισεν Ἐσθαίῳ συνήθει μὲν ὄντι καὶ φίλῳ ἐκ δὲ τῆς Γιττῶν πόλεως ὑπάρχοντι. βουλόμενον δὲ συνεκστρατεύειν αὐτὸν οὐκ εἴασαν οἱ φίλοι γνώμῃ κατασχόντες σοφωτάτῃ· νικηθέντες μὲν γὰρ σὺν αὐτῷ πᾶσαν ἀποβαλεῖν ἐλπίδα χρηστὴν ἔφασκον, ἂν δὲ ἡττηθέντες ἑνὶ μέρει τῆς δυνάμεως τῷ λοιπῷ πρὸς αὐτὸν φύγωσιν ἀμείνονα παρασκευάσειν αὐτὸν ἰσχύν· ὑπονοήσειν δὲ καὶ τοὺς πολεμίους εἰκός ἐστιν ἄλλο μετ’ αὐτοῦ στράτευμα εἶναι. πεισθεὶς δὲ τῇ συμβουλίᾳ ταύτῃ μένειν μὲν αὐτὸς ἐν ταῖς Παρεμβολαῖς ἔκρινεν, ἐκπέμπων δὲ τοὺς φίλους καὶ τοὺς στρατηγοὺς ἐπὶ τὸν πόλεμον παρεκάλει προθυμίαν ἐναποδείξασθαι καὶ πίστιν καὶ μνήμην, εἴ τινος τῶν μετρίως ἐχόντων παρ’ αὐτοῦ ἔτυχον· φείσασθαι δὲ καὶ τοῦ παιδὸς Ἀψαλώμου κρατήσαντας ἠντιβόλει, μὴ κακὸν αὑτὸν ἐργάσηταί τι τελευτήσαντος αὐτοῦ. καὶ ὁ μὲν νίκην αὐτοῖς ἐπευξάμενος ἐκπέμπει τὴν στρατιάν.", "st": "7.10.1"}, {"sp": "N", "t": "Ἰωάβου δὲ παρατάξαντος τὴν δύναμιν ἀντικρὺ τῶν πολεμίων ἐν πεδίῳ μεγάλῳ ἐξόπισθεν περιβεβλημένῳ δρυμὸν ἀντεξάγει τὴν στρατιὰν καὶ Ἀψάλωμος. καὶ συμβολῆς γενομένης ἔργα μεγάλα χειρῶν τε καὶ τόλμης παρ’ ἀμφοτέρων ἐπεδείκνυτο, τῶν μὲν ὑπὲρ τοῦ τὴν βασιλείαν ἀπολαβεῖν Δαυίδην παρακινδυνευόντων καὶ πάσῃ προθυμίᾳ χρωμένων, τῶν δ’ ἵνα μὴ ταύτην Ἀψάλωμος ἀφαιρεθῇ καὶ δῷ τῷ πατρὶ δίκας κολασθεὶς ἀνθ’ ὧν ἐτόλμησεν οὐδὲν ὀκνούντων οὔτε ποιεῖν οὔτε πάσχειν, ἔτι δὲ τῶν μὲν πλειόνων ἵνα μὴ κρατηθῶσιν ὑπὸ τῶν σὺν Ἰωάβῳ καὶ τοῖς σὺν αὐτῷ στρατηγοῖς ὄντων ὀλίγων, αἰσχύνην γὰρ αὐτοῖς τοῦτο εἶναι μεγίστην, τῶν δὲ Δαυίδου στρατιωτῶν ἵνα τοσούτων μυριάδων κρατήσωσι φιλοτιμουμένων, ἔρις ἐγένετο καρτερά, καὶ νικῶσιν οἱ Δαυίδου ῥώμῃ τε προύχοντες καὶ τῇ τῶν πολεμικῶν ἐπιστήμῃ. φεύγοντας δὲ διὰ δρυμῶν καὶ φαράγγων ἑπόμενοι τοὺς μὲν ἐλάμβανον πολλοὺς δὲ ἀνῄρουν, ὡς φεύγοντας πεσεῖν πλείονας ἢ μαχομένους· ἔπεσον γὰρ ὡς δισμύριοι ἐπ’ ἐκείνης τῆς ἡμέρας. οἱ δὲ τοῦ Δαυίδου πάντες ὥρμησαν ἐπὶ τὸν Ἀψάλωμον· φανερὸς γὰρ αὐτοῖς ὑπό τε τοῦ κάλλους καὶ τοῦ μεγέθους ἐγένετο. δείσας δέ, μὴ καταλάβωσιν αὐτὸν οἱ πολέμιοι, ἐπιβὰς τῆς ἡμιόνου τῆς βασιλικῆς ἔφευγε· φερόμενος δὲ μετὰ ῥύμης καὶ ὑπὸ τοῦ σάλου καὶ τῆς κινήσεως κοῦφος ὤν, ἐμπλακείσης αὐτῷ τῆς κόμης τραχεῖ δένδρῳ μεγάλοις ἐπὶ πολὺ κλάδοις ἐκτεταμένῳ παραδόξως ἀνακρεμνᾶται. καὶ τὸ μὲν κτῆνος ὑπ’ ὀξύτητος ὡς ἐπικείμενον τὸν δεσπότην ἔτι φέρον ἐχώρει προσωτέρω, ὁ δ’ ἐκ τῶν κλάδων αἰωρούμενος ἐκρατεῖτο τοῖς πολεμίοις. τοῦτό τις ἰδὼν τῶν Δαυίδου στρατιωτῶν ἐδήλωσεν Ἰωάβῳ, καὶ πεντήκοντα σίκλους ἂν αὐτῷ δεδωκέναι τοῦ στρατηγοῦ φήσαντος, εἰ βαλὼν ἀπέκτεινε τὸν Ἀψάλωμον, οὐδ’ εἰ χιλίους, εἶπεν, ἔμελλές μοι παρέξειν, τοῦτ’ ἂν διέθηκά μου τὸν τοῦ δεσπότου παῖδα, καὶ ταῦτ’ ἐκείνου πάντων ἡμῶν ἀκουόντων φείσασθαι τοῦ νεανίσκου δεηθέντος. ὁ δὲ κελεύσας αὐτῷ δεῖξαι ποῦ κρεμάμενον ἴδοι τὸν Ἀψάλωμον τοξεύσας κατὰ τῆς καρδίας ἀπέκτεινεν· οἱ δὲ τὰ τοῦ Ἰωάβου κομίζοντες ὅπλα περιστάντες ἐν κύκλῳ τὸ δένδρον κατασπῶσι τὸν νεκρόν· καὶ τὸν μὲν εἰς χάσμα βαθὺ καὶ ἀχανὲς ῥίψαντες ἐπιβάλλουσιν αὐτῷ λίθους, ὥστε ἀναπληρωθῆναι καὶ τὸ σχῆμα τάφου καὶ μέγεθος λαβεῖν, σημήνας δὲ ἀνακλητικὸν ὁ Ἰώαβος ἐπέσχε τοῦ διώκειν τοὺς οἰκείους στρατιώτας τὴν τῶν πολεμίων δύναμιν φειδόμενος τῶν ὁμοφύλων.", "st": "7.10.2"}, {"sp": "N", "t": "Ἔστησε δ’ Ἀψάλωμος ἐν τῇ κοιλάδι τῇ βασιλικῇ στήλην λίθου μαρμαρίνου δύο σταδίους ἀπέχουσαν Ἱεροσολύμων, ἣν προσηγόρευσεν ἰδίαν χεῖρα λέγων, ὡς καὶ τῶν τέκνων αὐτοῦ διαφθαρέντων ἐν τῇ στήλῃ μενεῖ τὸ ὄνομα· τέκνα γὰρ ἦν αὐτῷ τρία μὲν ἄρρενα, θυγάτηρ δὲ μία Θωμάρα τοὔνομα, ὡς προειρήκαμεν. συνοικησάσης δ’ αὐτῆς τῷ Σολόμωνος υἱῷ Ῥοβοάμῳ γίνεται παῖς ὁ διαδεξάμενος τὴν βασιλείαν Ἀβίας. καὶ περὶ μὲν τούτων ἐν ὑστέροις οἰκειότερον τῇ ἱστορίᾳ δηλώσομεν. μετὰ δὲ τὴν Ἀψαλώμου τελευτὴν ὁ μὲν λαὸς εἰς τὰ οἰκεῖα διεσπάρη.", "st": "7.10.3"}, {"sp": "N", "t": "Ἀχιμᾶς δὲ ὁ Σαδώκου τοῦ ἀρχιερέως υἱὸς Ἰωάβῳ προσελθὼν ἐδεῖτο αὐτοῦ τὴν νίκην ἐπιτρέψαι πορευθέντι Δαυίδῃ μηνῦσαι, καὶ ὅτι τῆς παρὰ τοῦ θεοῦ βοηθείας ἔτυχε καὶ προνοίας εὐαγγελίσασθαι. καὶ τὸν μέν, οὐ προσήκειν εἰπὼν αὐτῷ καλῶν ἄγγελον ἀεὶ γεγενημένον νῦν ἀπιέναι δηλώσοντα θάνατον τῷ βασιλεῖ τοῦ παιδὸς αὐτοῦ, μένειν ἠξίου, καλέσας δὲ τὸν Χουσὶν ἐκείνῳ προσέταξε τὸ ἔργον, ἵν’ ὅπερ αὐτὸς εἶδε τοῦτο μηνύσειε τῷ βασιλεῖ. τοῦ δ’ Ἀχιμᾶ πάλιν δεηθέντος αὐτῷ τὴν ἀγγελίαν ἐφεῖναι, περὶ μόνης γὰρ αὐτὴν ποιήσεσθαι τῆς νίκης ἡσυχάσειν δὲ περὶ τῆς Ἀψαλώμου τελευτῆς, ἐπέτρεψεν αὐτῷ τὴν πρὸς τὸν Δαυίδην ἄφιξιν. καὶ τὴν ἐπιτομωτέραν ἐκβαλὼν τῶν ὁδῶν, καὶ γὰρ μόνος αὐτὴν ἐγίνωσκε, τὸν Χουσὶν φθάνει. καθεζομένῳ δὲ Δαυίδῃ μεταξὺ τῶν πυλῶν καὶ περιμένοντι, πότ’ αὐτῷ τις ἐλθὼν ἀπὸ τῆς μάχης ἀγγείλῃ τὰ κατ’ αὐτήν, τῶν σκοπῶν τις ἰδὼν τὸν Ἀχιμᾶν τρέχοντα καὶ μήπω τίς ἐστι γνωρίσαι δυνάμενος εἶπε πρὸς τὸν Δαυίδην βλέπειν τινὰ παραγινόμενον πρὸς αὐτόν. τοῦ δ’ ἄγγελον εἶναι φήσαντος ἀγαθῶν, μετ’ ὀλίγον ἕπεσθαί τινα καὶ ἕτερον ἐδήλωσεν αὐτῷ. κἀκεῖνον δὲ ἄγγελον εἰπόντος, ἰδὼν τὸν Ἀχιμᾶν ὁ σκοπὸς ἤδη ἐγγὺς γεγενημένον τὸν Σαδώκου παῖδα τοῦ ἀρχιερέως προστρέχειν ἐσήμαινεν. ὁ δὲ Δαυίδης περιχαρὴς γενόμενος ἀγαθῶν ἄγγελον τοῦτον ἔφησεν εἶναι καί τι τῶν εὐκταίων αὐτῷ φέρειν ἀπὸ τῆς μάχης.", "st": "7.10.4"}, {"sp": "N", "t": "Καὶ μεταξὺ ταῦτα λέγοντος τοῦ βασιλέως φανεὶς ὁ Ἀχιμᾶς προσκυνεῖ τὸν βασιλέα, καὶ πυθομένῳ περὶ τῆς μάχης νίκην εὐαγγελίζεται καὶ κράτος. ἐρομένῳ δ’ εἴ τι καὶ περὶ τοῦ παιδὸς ἔχοι λέγειν αὐτὸς μὲν ἔφασκεν εὐθὺς ὁρμῆσαι πρὸς αὐτὸν τῆς τροπῆς τῶν πολεμίων γενομένης, ἀκοῦσαι δὲ μεγάλης φωνῆς διωκόντων τὸν Ἀψάλωμον καὶ πλεῖον τούτου μηδὲν δεδυνῆσθαι μαθεῖν διὰ τὸ πεμφθέντα ὑπὸ Ἰωάβου δηλῶσαι τὴν νίκην ἐπείγεσθαι. παραγενομένου δὲ τοῦ Χουσὶ καὶ προσκυνήσαντος καὶ τὴν νίκην σημήναντος, περὶ τοῦ παιδὸς αὐτὸν ἀνέκρινεν. ὁ δ’ ἐχθροῖς, εἶπε, τοῖς σοῖς οἷα συμβέβηκεν Ἀψαλώμῳ γένοιτο. οὗτος ὁ λόγος οὐδὲ τὴν ἐπὶ τῇ νίκῃ χαρὰν εἴασεν οὔτ’ αὐτῷ μεῖναι μεγίστην οὖσαν οὔτε τοῖς στρατιώταις· αὐτὸς μὲν γὰρ ἀναβὰς ἐπὶ τὸ ὑψηλότατον τῆς πόλεως ἀπεκλαίετο τὸν υἱὸν τυπτόμενος τὰ στέρνα καὶ τὴν κεφαλὴν σπαραττόμενος καὶ παντοίως αὑτὸν αἰκιζόμενος καὶ τέκνον, ἐκβοῶν, εἴθε μοι τὸν θάνατον ἐπελθεῖν ἐγένετο καὶ ἅμα σοι τελευτῆσαι· φύσει γὰρ ὢν φιλόστοργος πρὸς ἐκεῖνον μᾶλλον συμπαθῶς εἶχεν. ἡ στρατιὰ δὲ καὶ Ἰώαβος ἀκούσαντες, ὅτι πενθεῖ τὸν υἱὸν οὕτως ὁ βασιλεύς, ᾐσχύνθησαν μετὰ τοῦ τῶν νενικηκότων σχήματος εἰσελθεῖν εἰς τὴν πόλιν, κατηφεῖς δὲ καὶ δεδακρυμένοι πάντες ὡς ἀφ’ ἥττης παρῆλθον. κατακαλυψαμένου δὲ τοῦ βασιλέως καὶ στένοντος τὸν υἱὸν εἴσεισι πρὸς αὐτὸν Ἰώαβος καὶ παρηγορῶν ὦ δέσποτα, φησί, λανθάνεις διαβάλλων σαυτὸν οἷς ποιεῖς, ὅτι τοὺς μὲν ἀγαπῶντάς σε καὶ περὶ σοῦ κινδυνεύοντας καὶ σαυτὸν καὶ τὴν σὴν γενεὰν δοκεῖς μισεῖν, στέργειν δὲ τοὺς ἐχθροτάτους καὶ ποθεῖν οὐκέτ’ ὄντας, οἳ δίκῃ τεθνήκασιν· εἰ γὰρ Ἀψάλωμος ἐκράτησε καὶ τὴν βασιλείαν βεβαίως κατέσχεν, οὐδενὸς ἂν ἡμῶν ὑπελείφθη λείψανον, ἀλλὰ πάντες ἂν ἀπὸ σοῦ καὶ τῶν σῶν ἀρξάμενοι τέκνων ἀπωλώλειμεν οἰκτρῶς, οὐ κλαιόντων ἡμᾶς τῶν πολεμίων ἀλλὰ καὶ χαιρόντων καὶ τοὺς ἐλεοῦντας ἐπὶ τοῖς κακοῖς κολαζόντων. σὺ δ’ οὐκ αἰσχύνῃ ταῦτα ποιῶν ἐπὶ μᾶλλον ἐχθρῷ, ὅτι σὸς υἱὸς ὢν ἀσεβὴς οὕτως ἐγένετο. παυσάμενος οὖν τῆς ἀδίκου λύπης προελθὼν ὄφθητι τοῖς σαυτοῦ στρατιώταις καὶ τῆς νίκης αὐτοῖς καὶ τῆς περὶ τοὺς ἀγῶνας προθυμίας εὐχαρίστησον. ὡς ἐγὼ τήμερον, ἂν ἐπιμένῃς τοῖς ἄρτι πραττομένοις, ἀναπείσας ἀποστῆναί σου τὸν λαὸν καὶ τὴν βασιλείαν ἑτέρῳ παραδοῦναι, τότε σοι πικρότερον καὶ ἀληθὲς ποιήσω τὸ πένθος. ταῦτ’ εἰπὼν Ἰώαβος ἀπέστρεψεν ἀπὸ τῆς λύπης καὶ ἤγαγεν εἰς τὸν περὶ τῶν πραγμάτων λογισμὸν τὸν βασιλέα· μετασχηματίσας γὰρ ἑαυτὸν Δαυίδης καὶ ποιήσας ἐπιτήδειον εἰς τὴν τοῦ πλήθους θέαν πρὸς ταῖς πύλαις ἐκάθισεν, ὡς ἅπαντα τὸν λαὸν ἀκούσαντα συνδραμεῖν πρὸς αὐτὸν καὶ κατασπάσασθαι. καὶ ταῦτα μὲν τοῦτον ἔσχε τὸν τρόπον.", "st": "7.10.5"}, {"sp": "N", "t": "Οἱ δ’ ἐκ τῆς μάχης ἀναχωρήσαντες τῶν Ἑβραίων τῶν μετ’ Ἀψαλώμου γενόμενοι παρ’ αὑτοῖς ἕκαστοι διεπέμποντο κατὰ πόλεις ὑπομιμνήσκοντες αὑτοὺς ὧν εὐηργέτησε Δαυίδης καὶ τῆς ἐλευθερίας, ἣν ἐκ πολλῶν καὶ μεγάλων ῥυσάμενος αὐτοὺς πολέμων παρέσχε, μεμφόμενοι δ’ ὅτι τῆς βασιλείας αὐτὸν ἐκβαλόντες ἄλλῳ ταύτην ἐνεχείρισαν καὶ νῦν τεθνηκότος τοῦ κατασταθέντος ὑπ’ αὐτῶν ἡγεμόνος οὐ παρακαλοῦσι Δαυίδην παύσασθαι μὲν τῆς ὀργῆς, εὐνοϊκῶς δὲ πρὸς αὐτοὺς ἔχειν, τῶν δὲ πραγμάτων καθὼς ἤδη καὶ πρότερον ποιεῖσθαι πρόνοιαν τὴν βασιλείαν ἀπολαβόντα. ταῦτα μὲν οὖν συνεχέστερον ἀπηγγέλλετο Δαυίδῃ· κἀκεῖνος οὐδὲν ἧττον ἔπεμψε πρὸς Σάδωκον καὶ Ἀβιάθαρον τοὺς ἀρχιερέας, ἵνα τοῖς ἄρχουσι τῆς Ἰούδα φυλῆς διαλεχθῶσιν, ὡς αἰσχρὸν αὐτοῖς ἄλλας φυλὰς πρὸ ἐκείνης Δαυίδην χειροτονῆσαι βασιλέα, καὶ ταῦθ’ ὑμῶν συγγενῶν ὄντων καὶ κοινὸν αἷμα πρὸς αὐτὸν κεκληρωμένων. τὰ δ’ αὐτὰ καὶ Ἀμασᾷ τῷ στρατηγῷ προσέταξεν αὐτοὺς λέγειν, ὅτι τῆς ἀδελφῆς υἱὸς ὢν αὐτοῦ μὴ πείθει τὸ πλῆθος Δαυίδῃ τὴν βασιλείαν ἀποδοῦναι· προσδοκᾶν δὲ παρ’ αὐτοῦ μὴ διαλλαγὴν μόνον, τοῦτο γὰρ ἤδη γέγονεν, ἀλλὰ καὶ τὴν παντὸς τοῦ λαοῦ στρατηγίαν, ἣν αὐτῷ καὶ Ἀψάλωμος παρέσχε. καὶ οἱ μὲν ἀρχιερεῖς ἃ μὲν τοῖς τῆς φυλῆς ἄρχουσι διειλέχθησαν ἃ δὲ τὸν Ἀμασὰν ἔπεισαν τὰ παρὰ τοῦ βασιλέως πρὸς αὐτὸν εἰπόντες ἐγχειρεῖν ταῖς ὑπὲρ αὐτοῦ φροντίσι. καὶ πείθει γε τὴν φυλὴν παραχρῆμα πέμψαι πρὸς Δαυίδην πρέσβεις παρακαλοῦντας εἰς τὴν ἰδίαν αὐτὸν ἐπανελθεῖν βασιλείαν. τὸ δ’ αὐτὸ καὶ πάντες ἐποίουν οἱ Ἰσραηλῖται προτρεψαμένου τοῦ Ἀμασᾶ.", "st": "7.11.1"}, {"sp": "N", "t": "Τῶν δὲ πρέσβεων ἀφικομένων πρὸς αὐτὸν εἰς Ἱεροσόλυμα παρεγένετο. πάντας δὲ τοὺς ἄλλους ἔφθασεν ἡ Ἰούδα φυλὴ πρὸς τὸν Ἰόρδανον ποταμὸν ἀπαντῆσαι τῷ βασιλεῖ καὶ ὁ Γήρα παῖς Σαμούις μετὰ χιλίων ἀνδρῶν, οὓς ἐκ τῆς Βενιαμίδος φυλῆς ἐπήγετο, καὶ Σιβᾶς δὲ ὁ ἀπελεύθερος Σαούλου καὶ οἱ παῖδες αὐτοῦ πεντεκαίδεκα τὸν ἀριθμὸν ὄντες μετὰ οἰκετῶν εἴκοσιν. οὗτοι σὺν τῇ Ἰούδα φυλῇ τὸν ποταμὸν ἐγεφύρωσαν, ἵνα ῥᾷστα διαβῇ μετὰ τῶν ἰδίων ὁ βασιλεύς. ὡς δὲ ἧκεν ἐπὶ τὸν Ἰόρδανον ἠσπάσατο μὲν αὐτὸν ἡ Ἰούδα φυλή, προσπεσὼν δ’ ἀναβάντι ἐπὶ τὴν γέφυραν Σαμούις καὶ κατασχὼν αὐτοῦ τοὺς πόδας ἐδεῖτο συγγνῶναι περὶ τῶν εἰς αὐτὸν ἡμαρτημένων καὶ μὴ γενέσθαι πικρὸν αὐτῷ μηδὲ τοῦτο πρῶτον ἡγήσασθαι τὴν τιμωρίαν ἐν ἐξουσίᾳ γενόμενον, λογίσασθαι δ’ ὅτι καὶ μετανοήσας ἐφ’ οἷς ἐσφάλη πρῶτος ἐλθεῖν πρὸς αὐτὸν ἔσπευσε. ταῦτα δ’ ἀντιβολοῦντος αὐτοῦ καὶ οἰκτιζομένου Ἀβεσσαῖος ὁ Ἰωάβου ἀδελφός, διὰ τοῦτο οὖν, εἶπεν, οὐ τεθνήξῃ βλασφημήσας τὸν ὑπὸ τοῦ θεοῦ κατασταθέντα βασιλεύειν; Δαυίδης δ’ ἐπιστραφεὶς πρὸς αὐτόν, οὐ παύσεσθ’, εἶπεν, ὦ Σαρουίας παῖδες; μὴ κινήσητε πάλιν ἡμῖν καινὰς ἐπὶ ταῖς πρώταις ταραχὰς καὶ στάσεις· οὐ γὰρ ἀγνοεῖν ὑμᾶς προσῆκεν, ὅτι σήμερον ἄρχομαι τῆς βασιλείας. διὸ πᾶσιν ἀφιέναι τὰς κολάσεις τοῖς ἀσεβήσασιν ὄμνυμι καὶ μηδενὶ τῶν ἁμαρτόντων ἐπεξελθεῖν. σύ τε, εἶπεν, ὦ Σαμούι, θάρρει καὶ δείσῃς μηδὲν ὡς τεθνηξόμενος. ὁ δὲ προσκυνήσας αὐτὸν προῆγεν.", "st": "7.11.2"}, {"sp": "N", "t": "Ἀπήντησε δ’ αὐτῷ καὶ ὁ Σαούλου υἱωνὸς Μεμφίβοσθος ῥυπαράν τε τὴν ἐσθῆτα περικείμενος καὶ τὴν κόμην βαθεῖαν καὶ κατημελημένην ἔχων· μετὰ γὰρ τὴν Δαυίδου φυγὴν οὔτε ἀπεκείρατο λυπούμενος οὔτ’ ἐκάθηρε τὴν ἐσθῆτα κατακρίνας αὑτοῦ συμφορὰν ταύτην ἐπὶ τῇ τοῦ βασιλέως μεταβολῇ· διεβέβλητο δὲ καὶ ὑπὸ τοῦ ἐπιτρόπου Σιβᾶ πρὸς αὐτὸν ἀδίκως. ἀσπασαμένου δὲ αὐτοῦ καὶ προσκυνήσαντος ἤρξατο πυνθάνεσθαι, τί δήποτ’ οὐ συνεξῆλθεν αὐτῷ καὶ κοινωνὸς ἦν τῆς φυγῆς; ὁ δ’ ἀδίκημα τοῦτ’ ἔλεγεν εἶναι Σιβᾶ· κελευσθεὶς γὰρ παρασκευάσαι τὰ πρὸς τὴν ἔξοδον οὐκ ἐφρόντισεν, ἀλλ’ ὥσπερ ἀνδραπόδου τινὸς οὕτως παρήκουσεν. εἰ μέντοι γε τὰς βάσεις εἶχον ἐρρωμένας, οὐκ ἂν ἀπελείφθην σου χρῆσθαι πρὸς τὴν φυγὴν ταύταις δυνάμενος. οὐ τοῦτο δὲ μόνον ἠδίκησέ μου τὴν πρὸς σέ, δέσποτα, εὐσέβειαν, ἀλλὰ καὶ προσδιέβαλε καὶ κατεψεύσατο κακουργῶν. ἀλλ’ οἶδα γάρ, ὅτι τούτων οὐδὲν ἡ σὴ διάνοια προσίεται δικαία τε οὖσα καὶ τὴν ἀλήθειαν ἐνισχύειν βουλομένη καὶ τὸ θεῖον ἀγαπῶσα· μείζονα γὰρ κινδυνεύσας παθεῖν ὑπὸ τοῦ πάππου τοὐμοῦ καὶ τῆς ὅλης ἡμῶν γενεᾶς ὀφειλούσης εἰς ἐκεῖνα ἀπολωλέναι, σύ τε μέτριος καὶ χρηστὸς ἐγένου τότε μάλιστα πάντων ἐκείνων λήθην ποιησάμενος, ὅτ’ ἐξουσίαν τῆς ὑπὲρ αὐτῶν τιμωρίας εἶχεν ἡ μνήμη. φίλον δὲ σὸν ἔκρινας ἐμὲ καὶ ἐπὶ τῆς τραπέζης εἶχες ὁσημέραι, καὶ οὐδὲν ἀπέλειπον τῶν συγγενῶν τοῦ μάλιστα τιμωμένου. ταῦτ’ εἰπόντος οὔτε τὸν Μεμφίβοσθον ἔγνω κολάζειν οὔθ’ ὡς καταψευσαμένου τοῦ Σιβᾶ πρὸς αὐτὸν καταδικάζειν, ἀλλ’ ὑπὲρ μὲν τοῦ [μὴ μετὰ] Σιβᾶ ἐλθεῖν ἐκείνῳ πάντα χαρίσασθαι φήσας αὐτῷ συγγινώσκειν ὑπέσχετο τὰ ἡμίση τῆς οὐσίας αὐτῷ κελεύσας ἀποδοθῆναι. ὁ δὲ Μεμφίβοσθος πάντ’ ἐχέτω μέν, εἶπε, Σιβάς, ἐμοὶ δ’ ἀπόχρη τὸ σὲ τὴν βασιλείαν ἀπολαβεῖν.", "st": "7.11.3"}, {"sp": "N", "t": "Βεέρζελον δὲ τὸν Γαλαδίτην ἄνδρα μέγαν καὶ καλὸν καὶ πολλὰ παρεσχημένον ἐν ταῖς Παρεμβολαῖς αὐτῷ Δαυίδης προπέμψαντα μέχρι τοῦ Ἰορδάνου παρεκάλει συνελθεῖν ἕως τῶν Ἱεροσολύμων· γηρωκομήσειν γὰρ αὐτὸν ἐν πάσῃ τιμῇ καὶ ὡς πατρὸς ἐπιμεληθήσεσθαι καὶ προνοήσειν ἐπηγγέλλετο. ὁ δὲ πόθῳ τῶν οἴκοι παρῃτεῖτο τὴν μετ’ αὐτοῦ διατριβήν· καὶ τὸ γῆρας λέγων τοιοῦτον αὐτῷ τυγχάνειν, ὥστε μὴ ἀπολαύειν τῶν ἡδέων εἰς ὀγδοήκοντα ἔτη προβεβηκότος, ἀλλ’ ὥστε καταλύσεως ἤδη καὶ ταφῆς προνοεῖν, ἐπὶ ταύτην ἠξίου βουλόμενον αὐτῷ χαρίζεσθαι τὰ κατ’ ἐπιθυμίαν αὐτὸν ἀπολῦσαι· οὔτε γὰρ τροφῆς οὔτε ποτοῦ συνιέναι διὰ τὸν χρόνον, ἀποκεκλεῖσθαι δ’ αὐτῷ καὶ τὰς ἀκοὰς ἤδη πρὸς αὐλῶν ἤχους καὶ μέλη τῶν ἄλλων ὀργάνων, ὅσα παρὰ βασιλεῦσι τέρπει τοὺς συνδιαιτωμένους. οὕτως δὲ λιπαρῶς δεομένου, σὲ μέν, εἶπεν, ἀπολύω, τὸν δ’ υἱὸν Ἀχίμανον ἄφες μοι· πάντων γὰρ αὐτῷ μεταδώσω τῶν ἀγαθῶν. καὶ Βεέρζελος μὲν καταλιπὼν τὸν υἱὸν καὶ προσκυνήσας τὸν βασιλέα καὶ πάντων ἐπευξάμενος αὐτῷ τέλος ὧν ἔχει κατὰ ψυχὴν οἴκαδ’ ὑπέστρεψε. παραγίνεται δ’ εἰς Γάλγαλα Δαυίδης τοῦ λαοῦ παντὸς ἤδη τὸ ἥμισυ περὶ αὑτὸν ἔχων καὶ τὴν Ἰούδα φυλήν.", "st": "7.11.4"}, {"sp": "N", "t": "Ἀφικνοῦνται δ’ εἰς Γάλγαλα πρὸς αὐτὸν οἱ πάσης φυλῆς πρῶτοι μετὰ πολλοῦ πλήθους καὶ τὴν Ἰούδα φυλὴν κατεμέμφοντο λάθρα πρὸς αὐτὸν ἐλθοῦσαν, ὡς δεῖν ὁμοῦ πάντας μιᾷ γνώμῃ ποιεῖσθαι τὴν ἀπάντησιν. οἱ δ’ ἄρχοντες τῆς Ἰούδα φυλῆς μὴ δυσχεραίνειν αὐτοὺς ἠξίουν προληφθέντας· καὶ γὰρ συγγενεῖς ὄντες αὐτοῦ καὶ διὰ τοῦτο μᾶλλον προνοούμενοι καὶ στέργοντες φθάσαι, οὐ μέντοι γε διὰ τὸ προελθεῖν δῶρα λαβεῖν αὐτούς, ἵν’ ἔχωσιν ἐπὶ τούτῳ δυσφορεῖν ὕστεροι πρὸς αὐτὸν ἐλθόντες. ταῦτα τῶν τῆς Ἰούδα φυλῆς ἡγεμόνων εἰπόντων οἱ τῶν ἄλλων ἄρχοντες οὐχ ἡσύχασαν, ἀλλ’ ἡμεῖς μέν, ἔφασαν, ὦ ἀδελφοί, θαυμάζομεν ὑμᾶς αὑτῶν ἀποκαλοῦντας μόνων συγγενῆ τὸν βασιλέα· ὁ γὰρ τὴν ἁπάντων ἐξουσίαν παρὰ τοῦ θεοῦ λαβὼν πάντων ἡμῶν εἶναι συγγενὴς κρίνεται. καὶ διὰ τοῦθ’ ὁ μὲν λαὸς ἕνδεκα μοίρας ἔχει, μίαν δ’ ὑμεῖς, καὶ πρεσβύτεροι ἐσμέν, καὶ οὐκ ἐποιήσατε δίκαια λεληθότως ἐλθόντες πρὸς τὸν βασιλέα.", "st": "7.11.5"}, {"sp": "N", "t": "Τοιαῦτα τῶν ἡγεμόνων πρὸς ἀλλήλους διαλεχθέντων ἀνήρ τις πονηρὸς καὶ στάσει χαίρων, ὄνομα Σαβαῖος υἱὸς δὲ Βοχορίου τῆς Βενιαμίτιδος φυλῆς, στὰς ἐν μέσῳ πρὸς τὸ πλῆθος μέγα βοήσας εἶπεν· οὔτ’ ἔχει τις ἡμῶν παρὰ Δαυίδου μοίρας οὔτε κλῆρον παρὰ τῷ Ἰεσσαίου παιδί. καὶ μετὰ τοὺς λόγους σαλπίσας κέρατι σημαίνει πόλεμον πρὸς τὸν βασιλέα, καὶ πάντες ἠκολούθησαν ἐκείνῳ Δαυίδην καταλιπόντες· μόνη δ’ αὐτῷ παρέμεινεν ἡ Ἰούδα φυλὴ καὶ κατέστησεν αὐτὸν εἰς τὸ ἐν Ἱεροσολύμοις βασίλειον. καὶ τὰς μὲν παλλακάς, αἷς ὁ υἱὸς αὐτοῦ συνῆλθεν Ἀψάλωμος, εἰς ἄλλην μετήγαγεν οἰκίαν πάντα προστάξας αὐταῖς χορηγεῖν τὰ ἐπιτήδεια τοὺς ἐπιμελομένους, αὐτὸς δ’ οὐκέτ’ ἐπλησίαζεν αὐταῖς. ἀποδείκνυσι δὲ καὶ τὸν Ἀμασὰν στρατηγὸν καὶ τὴν τάξιν αὐτῷ ἐφ’ ἧς Ἰώαβος ἦν δίδωσιν ἐκέλευσέ τε στρατιὰν ὅσην δύναται συναγαγόντ’ ἐκ τῆς Ἰούδα φυλῆς μεθ’ ἡμέρας τρεῖς ὡς αὐτὸν ἐλθεῖν, ἵνα παραδοὺς αὐτῷ πᾶσαν τὴν δύναμιν ἐκπέμψῃ πολεμήσοντα τὸν υἱὸν τοῦ Βοχορίου. ἐξελθόντος δὲ τοῦ Ἀμασᾶ καὶ περὶ τὴν ἄθροισιν τῆς στρατιᾶς βραδύνοντος, ὡς οὐκ ἐπανῄει τῇ τρίτῃ τῶν ἡμερῶν ὁ βασιλεὺς πρὸς τὸν Ἰώαβον ἔλεγεν οὐκ εἶναι σύμφορον ἀνοχὴν τῷ Σαβαίῳ διδόναι, μὴ γενόμενος ἐν πλείονι παρασκευῇ μειζόνων κακῶν καὶ πραγμάτων αἴτιος, ἢ Ἀψάλωμος αὐτοῖς κατέστη, γένηται. μὴ περίμενε τοίνυν μηδένα, ἀλλὰ τὴν οὖσαν παραλαβὼν δύναμιν καὶ τοὺς ἑξακοσίους μετὰ Ἀβεσσαίου τοῦ Ἀδελφοῦ σου δίωκε τὸν πολέμιον. καὶ ὅπου ποτ’ ἂν αὐτὸν καταλάβῃς ὄντα πειράθητι συμβαλεῖν· σπούδασον δ’ αὐτὸν φθάσαι, μὴ πόλεις ὀχυρὰς καταλαβόμενος ἀγῶνας ἡμῖν καὶ πολλοὺς ἱδρῶτας παρασκευάσῃ.", "st": "7.11.6"}, {"sp": "N", "t": "Ἰώαβος δ’ οὐκέτι μέλλειν ἔκρινεν, ἀλλὰ τόν τε ἀδελφὸν καὶ τοὺς ἑξακοσίους παραλαβὼν καὶ ὅση λοιπὴ δύναμις ἦν ἐν τοῖς Ἱεροσολύμοις ἕπεσθαι κελεύσας ἐξώρμησεν ἐπὶ τὸν Σαβαῖον. ἤδη δ’ ἐν Γαβαών, κώμη δ’ ἐστὶν αὕτη σταδίους ἀπέχουσα τεσσαράκοντα τῶν Ἱεροσολύμων, γεγενημένος πολλὴν Ἀμασᾶ δύναμιν ἀγαγόντος ἀπήντησεν αὐτῷ διεζωσμένος μάχαιραν καὶ θώρακα ἐνδεδυμένος ὁ Ἰώαβος· προσιόντος δὲ ἀσπάσασθαι τοῦ Ἀμασᾶ φιλοτεχνεῖ τὴν μάχαιραν αὐτομάτως ἐκ τῆς θήκης ἐκπεσεῖν, βαστάσας δ’ αὐτὴν ἀπὸ τῆς γῆς καὶ τῇ ἑτέρᾳ τὸν Ἀμασᾶν ἐγγὺς γενόμενον ὡς καταφιλήσων τοῦ γενείου λαβόμενος οὐ προϊδόμενον εἰς τὴν γαστέρα πλήξας ἀπέκτεινεν, ἀσεβὲς ἔργον διαπραξάμενος καὶ παντελῶς ἀνόσιον, ἀγαθὸν νεανίαν καὶ συγγενῆ καὶ μηδὲν ἀδικήσαντα ζηλοτυπήσας τῆς στρατηγίας καὶ τῆς παρὰ τῷ βασιλεῖ πρὸς αὐτὸν ἰσοτιμίας. διὰ ταύτην γὰρ τὴν αἰτίαν καὶ τὸν Ἀβενῆρον ἐφόνευσεν. ἀλλ’ ἐκεῖνο μὲν αὐτοῦ τὸ παρανόμημα πρόφασις εὐπρεπὴς συγγνωστὸν ἐδόκει ποιεῖν, ὁ ἀδελφὸς Ἀσάηλος ἐκδεδικῆσθαι νομιζόμενος, τοῦ δ’ Ἀμασᾶ φόνου οὐδὲν τοιοῦτον ἔσχε παρακάλυμμα. ἀποκτείνας δὲ τὸν συστράτηγον ἐδίωκε τὸν Σαβαῖον καταλιπὼν ἕνα πρὸς τῷ νεκρῷ βοᾶν ἐντειλάμενος πρὸς τὴν στρατιάν, ὅτι τέθνηκεν Ἀμασᾶς δικαίως καὶ μετ’ αἰτίας κολαζούσης· εἰ δὲ φρονεῖτε τὰ τοῦ βασιλέως, ἕπεσθε τῷ στρατηγῷ αὐτοῦ Ἰωάβῳ καὶ Ἀβεσσαίῳ τῷ τούτου ἀδελφῷ. κειμένου δὲ τοῦ σώματος ἐπὶ τῆς ὁδοῦ καὶ παντὸς τοῦ πλήθους ἐπ’ αὐτῷ συρρέοντος καὶ οἷον ὄχλος φιλεῖ ἐθαύμαζον ἠλέουν προϊστάμενοι· βαστάσας δ’ ἐκεῖθεν ὁ φύλαξ καὶ κομίσας εἴς τι χωρίον ἀπωτάτω τῆς ὁδοῦ τίθησιν αὐτόθι καὶ καλύπτει ἱματίῳ. τούτου γενομένου πᾶς ὁ λαὸς ἠκολούθησε τῷ Ἰωάβῳ. διώξαντι δ’ αὐτῷ διὰ πάσης τῆς Ἰσραηλιτῶν χώρας τὸν Σαβαῖον δηλοῖ τις ἐν ὀχυρᾷ πόλει τυγχάνειν Ἀβελωχέᾳ λεγομένῃ. παραγενόμενος δ’ ἐκεῖ καὶ τῇ στρατιᾷ περικαθίσας τὴν πόλιν καὶ χαράκωμα περὶ αὐτὴν πηξάμενος ὑπορύσσειν ἐκέλευσε τοῖς στρατιώταις τὰ τείχη καὶ καταβάλλειν αὐτά· μὴ δεξαμένων γὰρ αὐτὸν τῶν ἐν τῇ πόλει χαλεπῶς πρὸς αὐτοὺς διετέθη.", "st": "7.11.7"}, {"sp": "N", "t": "Γύναιον δέ τι σῶφρον καὶ συνετὸν ἐν ἐσχάτοις ἤδη τὴν πατρίδα κειμένην θεασάμενον ἀναβὰν ἐπὶ τὸ τεῖχος προσκαλεῖται διὰ τῶν ὁπλιτῶν τὸν Ἰώαβον. προσελθόντος δ’ ἤρξατο λέγειν, ὡς ὁ θεὸς τοὺς βασιλεῖς καὶ τοὺς στρατηγοὺς ἀποδείξειεν, ἵνα τοὺς πολεμίους τοὺς Ἑβραίων ἐξαιρῶσι καὶ παρέχωσιν αὐτοῖς εἰρήνην ἀπ’ αὐτῶν· σὺ δὲ σπουδάζεις μητρόπολιν Ἰσραηλιτῶν καταβαλεῖν καὶ πορθῆσαι μηδὲν ἐξαμαρτοῦσαν. ὁ δὲ ἵλεων μὲν εὔχεται τὸν θεὸν αὐτῷ διαμένειν, αὐτὸς δ’ οὕτως ἔχειν εἶπεν, ὡς μηδένα τοῦ λαοῦ φονεῦσαι, οὐχ ὅτι πόλιν ἐξελεῖν βούλεσθαι τηλικαύτην· λαβὼν μέντοι παρ’ αὐτῶν τὸν ἀντάραντα τῷ βασιλεῖ πρὸς τιμωρίαν Σαβαῖον υἱὸν δὲ Βοχορίου παύσεσθαι τῆς πολιορκίας καὶ τὴν στρατιὰν ἀπάξειν. ὡς δ’ ἤκουσεν ἡ γυνὴ τὰ παρὰ τοῦ Ἰωάβου μικρὸν ἐπισχεῖν δεηθεῖσα, τὴν γὰρ κεφαλὴν εὐθέως αὐτῷ ῥιφήσεσθαι τὴν τοῦ πολεμίου, καταβαίνει πρὸς τοὺς πολίτας καὶ βούλεσθ’, εἰποῦσα, κακοὶ κακῶς ἀπολέσθαι μετὰ τέκνων καὶ γυναικῶν ὑπὲρ ἀνθρώπου πονηροῦ καὶ μηδὲ τίς ἐστι γνωριζομένου καὶ τοῦτον ἔχειν ἀντὶ Δαυίδου τοῦ τοσαῦτ’ εὐεργετήσαντος ὑμᾶς βασιλέα καὶ πρὸς δύναμιν τοσαύτην καὶ τηλικαύτην ἀνταίρειν μίαν πόλιν; πείθει τὴν κεφαλὴν ἀποτεμόντας τοῦ Σαβαίου ῥῖψαι ταύτην εἰς τὸ τοῦ Ἰωάβου στράτευμα. τούτου γενομένου σημήνας ἀνακλητικὸν ὁ τοῦ βασιλέως στρατηγὸς ἔλυσε τὴν πολιορκίαν καὶ παραγενόμενος εἰς Ἱεροσόλυμα παντὸς ἀποδείκνυται πάλιν τοῦ λαοῦ στρατηγός. καθίστησι δὲ καὶ Βαναῖον ὁ βασιλεὺς ἐπὶ τῶν σωματοφυλάκων καὶ τῶν ἑξακοσίων, Ἀδώραμον δ’ ἐποίησεν ἐπὶ τῶν φόρων καὶ Ἰωσάφατον υἱὸν Ἀχίλου ἐπὶ τῶν ὑπομνημάτων, Σουσὰν δὲ γραμματέα, Σάδωκον δὲ καὶ Ἀβιάθαρον ἀπέφηνεν ἱερεῖς.", "st": "7.11.8"}, {"sp": "N", "t": "Μετὰ δὲ ταῦτα τῆς χώρας λιμῷ φθειρομένης ἱκέτευε Δαυίδης τὸν θεὸν ἐλεῆσαι τὸν λαὸν καὶ τὴν αἰτίαν αὐτῷ καὶ τὴν ἴασιν φανερὰν ποιῆσαι τῆς νόσου. τῶν δὲ προφητῶν εἰπόντων βούλεσθαι τὸν θεὸν ἐκδικίας τυχεῖν τοὺς Γαβαωνίτας, οὓς Σαοῦλος ὁ βασιλεὺς ἀποκτείνας ἠσέβησεν ἐξαπατήσας καὶ τοὺς ὅρκους αὐτοῖς, οὓς ὁ στρατηγὸς Ἰησοῦς ὤμοσε καὶ ἡ γερουσία, μὴ φυλάξας· ἐὰν τοίνυν δίκην ἣν αὐτοὶ θέλουσιν οἱ Γαβαωνῖται λαβεῖν ὑπὲρ τῶν ἀνῃρημένων ταύτην αὐτοῖς παράσχῃ, διαλλαγήσεσθαι καὶ τὸν ὄχλον ἀπαλλάξειν τῶν κακῶν ἐπηγγέλλετο. ὡς οὖν ταῦτα παρὰ τῶν προφητῶν ἔμαθεν ἐπιζητεῖν τὸν θεόν, μεταπέμπεται τοὺς Γαβαωνίτας καὶ τίνος βούλονται τυχεῖν ἐπηρώτα. τῶν δ’ ἐκ τοῦ γένους τοῦ Σαούλου παραλαβεῖν ἑπτὰ παῖδας ἀξιωσάντων πρὸς τιμωρίαν, ὁ βασιλεὺς ἀναζητήσας παρέδωκεν αὐτοῖς Ἰεβόσθου φεισάμενος τοῦ Ἰωνάθου παιδός. παραλαβόντες δ’ οἱ Γαβαωνῖται τοὺς ἄνδρας ὡς ἐβούλοντο ἐκόλασαν. ἤρξατο δ’ ὕειν παραχρῆμα ὁ θεὸς καὶ τὴν γῆν πρὸς γονὴν καρπῶν ἀνακαλεῖν ἀπολύσας τοῦ πρότερον αὐχμοῦ· καὶ πάλιν εὐθήνησεν ἡ τῶν Ἑβραίων χώρα. Στρατεύεται δὲ μετ’ οὐ πολὺν χρόνον ὁ βασιλεὺς ἐπὶ Παλαιστίνους, καὶ συνάψας μάχην αὐτοῖς καὶ τρεψάμενος ἐμονώθη διώκων καὶ γενόμενος ἔκλυτος ὤφθη ὑπό τινος τῶν πολεμίων Ἄκμονος μὲν τοὔνομα Ἀράφου δὲ παιδός· οὗτος ἦν μὲν καὶ ἀπόγονος τῶν Γιγάντων, ἔχων δὲ καὶ ξυστόν, οὗ τὴν λαβὴν συνέλκειν σταθμὸν σίκλους τριακοσίους, καὶ θώρακα ἁλυσιδωτὸν καὶ ῥομφαίαν ὥρμησεν ἐπιστραφεὶς ὡς ἀποκτενῶν τὸν τῶν πολεμίων βασιλέα· παρεῖτο γὰρ ὑπὸ τοῦ κόπου. ἐπιφανεὶς δ’ ἐξαίφνης Ἀβεσσαῖος ὁ Ἰωάβου ἀδελφὸς τὸν βασιλέα μὲν ὑπερήσπισε περιβὰς κείμενον, ἀπέκτεινε δὲ τὸν πολέμιον. ἤνεγκε δ’ ἐπὶ τῷ παρ’ ὀλίγον κινδυνεῦσαι τὸν βασιλέα χαλεπῶς τὸ πλῆθος· καὶ οἱ ἡγεμόνες ὥρκωσαν αὐτὸν μηκέτι εἰς μάχην ἀπαντῆσαι σὺν αὐτοῖς, μὴ δι’ ἀνδρείαν καὶ προθυμίαν παθών τι τῶν δεινῶν στερήσῃ τὸν λαὸν τῶν δι’ αὐτὸν ἀγαθῶν, ὅσα τε ἤδη παρέσχηκε καὶ ὅσων ἔτι μεθέξουσι πολὺν βιώσαντος χρόνον.", "st": "7.12.1"}, {"sp": "N", "t": "Συνελθόντων δὲ τῶν Παλαιστίνων εἰς Γάζαρα πόλιν ἀκούσας ὁ βασιλεὺς ἔπεμψεν ἐπ’ αὐτοὺς στρατιάν. ἠρίστευσε δὲ τότε καὶ σφόδρ’ ηὐδοκίμησε Σαβρήχης ὁ Χετταῖος εἷς τῶν περὶ Δαυίδην ἀνδρειοτάτων· ἀπέκτεινε γὰρ πολλοὺς τῶν αὐχούντων προγόνους τοὺς Γίγαντας καὶ μέγα ἐπ’ ἀνδρείᾳ φρονούντων, αἴτιός τε τῆς νίκης τοῖς Ἑβραίοις ἐγένετο. καὶ μετ’ ἐκείνην τὴν ἧτταν πάλιν ἐπολέμησαν οἱ Παλαιστῖνοι· καὶ στρατιὰν ἐπ’ αὐτοὺς Δαυίδου πέμψαντος ἠρίστευσεν Ἐφὰν ὁ συγγενὴς αὐτοῦ· μονομαχήσας γὰρ τῷ πάντων ἀνδρειοτάτῳ Παλαιστίνων ἀπέκτεινεν αὐτὸν καὶ τοὺς ἄλλους εἰς φυγὴν ἔτρεψε, πολλοί τε αὐτῶν ἀπέθανον μαχόμενοι. διαλιπόντες δ’ ὀλίγον χρόνον ἐστρατοπεδεύσαντο πρὸς τῇ πόλει τῶν ὅρων τῆς Ἑβραίων χώρας οὐκ ἄπωθεν. ἦν δ’ αὐτοῖς ἀνὴρ τὸ μὲν ὕψος ἓξ πηχῶν, δακτύλους δ’ ἐν ἑκατέρῳ τῶν βάσεων καὶ τῶν χειρῶν ἑνὶ περισσοτέρους εἶχε τῶν κατὰ φύσιν. ἐκ τῆς οὖν πεμφθείσης ἐπ’ αὐτοὺς ὑπὸ Δαυίδου στρατιᾶς τούτῳ μονομαχήσας Ἰωνάθης ὁ Σουμᾶ υἱὸς ἀνεῖλέ τε αὐτὸν καὶ τῆς ὅλης νίκης ῥοπὴ γενόμενος δόξαν ἀριστείας ἀπηνέγκατο· καὶ γὰρ οὗτος ὁ Παλαιστῖνος ηὔχει τῶν Γιγάντων ἀπόγονος εἶναι. μετὰ δὲ ταύτην τὴν μάχην οὐκέτι τοῖς Ἰσραηλίταις ἐπολέμησαν.", "st": "7.12.2"}, {"sp": "N", "t": "Ἀπηλλαγμένος δ’ ἤδη πολέμων ὁ Δαυίδης καὶ κινδύνων καὶ βαθείας ἀπολαύων τὸ λοιπὸν εἰρήνης ᾠδὰς εἰς τὸν θεὸν καὶ ὕμνους συνετάξατο μέτρου ποικίλου· τοὺς μὲν γὰρ τριμέτρους, τοὺς δὲ πενταμέτρους ἐποίησεν. ὄργανά τε κατασκευάσας ἐδίδαξε πρὸς αὐτὰ τοὺς Ληουίτας ὑμνεῖν τὸν θεὸν κατά τε τὴν τῶν καλουμένων σαββάτων ἡμέραν καὶ κατὰ τὰς ἄλλας ἑορτάς. ἡ δὲ τῶν ὀργάνων ἐστὶν ἰδέα τοιαύτη τις τὸν τρόπον· ἡ μὲν κινύρα δέκα χορδαῖς ἐξημμένη τύπτεται πλήκτρῳ, ἡ δὲ νάβλα δώδεκα φθόγγους ἔχουσα τοῖς δακτύλοις κρούεται, κύμβαλά τε ἦν πλατέα καὶ μεγάλα χάλκεα. καὶ περὶ μὲν τούτων ἐπὶ τοσοῦτον ἡμῖν, ὥστε μὴ τελέως ἀγνοεῖν τὴν τῶν προειρημένων ὀργάνων φύσιν, ἀρκείσθω λελέχθαι.", "st": "7.12.3"}, {"sp": "N", "t": "Τῷ δὲ βασιλεῖ πάντες ἦσαν οἱ περὶ αὐτὸν ἀνδρεῖοι· τούτων δ’ οἱ διασημότατοι καὶ λαμπροὶ τὰς πράξεις ὀκτὼ καὶ τριάκοντα, ὧν πέντε μόνων διηγήσομαι τὰ ἔργα· φανερὰς γὰρ καὶ τὰς τῶν ἄλλων ἀρετὰς ἀρκέσουσιν οὗτοι ποιῆσαι· δυνατοὶ γὰρ ἦσαν οὗτοι καὶ χώραν ὑπάγεσθαι καὶ μεγάλων ἐθνῶν κρατῆσαι. πρῶτος μὲν οὖν Ἴσεβος υἱὸς Ἀχεμαίου, ὃς πολλάκις εἰς τὴν παράταξιν ἐμπηδῶν τῶν πολεμίων οὐ πρὶν ἀνεπαύετο μαχόμενος πρὶν ἐνακοσίους αὐτῶν καταβαλεῖν. μετ’ αὐτὸν ἦν Ἐλεάζαρος υἱὸς Δωδείου, ὃς ἦν μετὰ τοῦ βασιλέως ἐν Ἐρασαμῷ· οὗτός ποτε τῶν Ἰσραηλιτῶν καταπλαγέντων τὸ πλῆθος τῶν Παλαιστίνων καὶ φευγόντων μόνος ἔμεινε καὶ συμπεσὼν τοῖς πολεμίοις ἀπέκτεινεν αὐτῶν πολλούς, ὡς ὑπὸ τοῦ αἵματος προσκολληθῆναι τὴν ῥομφαίαν αὐτοῦ τῇ δεξιᾷ καὶ τοὺς Ἰσραηλίτας ἰδόντας τετραμμένους ὑπ’ αὐτοῦ τοὺς Παλαιστίνους καταβάντας διώκειν καὶ θαυμαστὴν καὶ διαβόητον τότε νίκην ἄρασθαι, τοῦ μὲν Ἐλεαζάρου κτείνοντος ἑπομένου δὲ τοῦ πλήθους καὶ σκυλεύοντος τοὺς ἀνῃρημένους. τρίτος δὲ ἦν Ἠλοῦ μὲν υἱὸς Σαβαίας δὲ ὄνομα. καὶ οὗτος ἐν τοῖς πρὸς Παλαιστίνους ἀγῶσιν εἰς τόπον Σιαγόνα λεγόμενον αὐτῶν παραταξαμένων, ὡς οἱ Ἑβραῖοι πάλιν τὴν δύναμιν φοβηθέντες οὐχ ὑπέμειναν, ὑπέστη μόνος ὡς στράτευμα καὶ τάξις, καὶ τοὺς μὲν αὐτῶν κατέβαλε τοὺς δ’ οὐ καρτερήσαντας αὐτοῦ τὴν ἰσχὺν καὶ τὴν βίαν ἀλλ’ εἰς φυγὴν ἀποστραφέντας ἐδίωκε. ταῦτα μὲν ἔργα χειρῶν καὶ μάχης οἱ τρεῖς ἐπεδείξαντο. καθ’ ὃν δὲ καιρὸν ἐν Ἱεροσολύμοις ὄντος τοῦ βασιλέως ἐπῆλθεν ἡ τῶν Παλαιστίνων δύναμις πολεμῆσαι, Δαυίδης μὲν ἐπὶ τὴν ἀκρόπολιν ἀνῆλθεν, ὡς προειρήκαμεν, πευσόμενος τοῦ θεοῦ περὶ τοῦ πολέμου, τῆς δὲ τῶν ἐχθρῶν παρεμβολῆς ἐν τῇ κοιλάδι κειμένης, ἣ μέχρι Βηθλεέμης πόλεως διατείνει σταδίους Ἱεροσολύμων ἀπεχούσης εἴκοσιν, ὁ Δαυίδης τοῖς ἑταίροις καλὸν ὕδωρ, εἶπεν, ἔχομεν ἐν τῇ πατρίδι μου· καὶ μάλιστα τὸ ἐν τῷ λάκκῳ τῷ πρὸς τῇ πύλῃ θαυμάζων, εἴ τις ἐξ αὐτοῦ πιεῖν αὐτῷ κομίσειε μᾶλλον ἐθελήσειν ἢ εἰ πολλὰ χρήματα διδοῖ. ταῦτ’ ἀκούσαντες οἱ τρεῖς ἄνδρες οὗτοι παραχρῆμα ἐκδραμόντες καὶ διὰ μέσου τοῦ τῶν πολεμίων ὁρμήσαντες στρατοπέδου ἧκον εἰς Βηθλεέμην, καὶ τοῦ ὕδατος ἀρυσάμενοι πάλιν διὰ τῆς παρεμβολῆς ὑπέστρεψαν πρὸς τὸν βασιλέα, ὡς τοὺς Παλαιστίνους καταπλαγέντας αὐτῶν τὸ θράσος καὶ τὴν εὐψυχίαν ἠρεμῆσαι [καὶ μηδὲν ἐπ’ αὐτοὺς τολμῆσαι] καταφρονήσαντας τῆς ὀλιγότητος. κομισθέντος δὲ τοῦ ὕδατος οὐκ ἔπιεν ὁ βασιλεὺς κινδύνῳ καὶ αἵματι φήσας ἀνθρώπων αὐτὸ κεκομίσθαι καὶ διὰ τοῦτο μὴ προσήκειν αὐτῷ πιεῖν, ἔσπεισε δὲ ἀπ’ αὐτοῦ τῷ θεῷ καὶ περὶ τῆς σωτηρίας τῶν ἀνδρῶν εὐχαρίστησεν αὐτῷ. μετὰ τούτους ἦν ὁ Ἰωάβου ἀδελφὸς Ἀβεσσαῖος· καὶ γὰρ οὗτος μιᾷ ἡμέρᾳ τῶν πολεμίων ἑξακοσίους ἀπέκτεινε. πέμπτος Ναβαῖος ὁ ἱερεὺς τῷ γένει· προκληθεὶς γὰρ ὑπ’ ἀδελφῶν διασήμων ἐν τῇ Μωαβίτιδι χώρᾳ κατ’ ἀρετὴν ἐκράτησεν αὐτῶν. καὶ πάλιν αὐτὸν ἀνδρὸς Αἰγυπτίου τὸ γένος θαυμαστοῦ τὸ μέγεθος προκαλεσαμένου, γυμνὸς ὡπλισμένον τῷ δόρατι τῷ ἐκείνου βαλὼν ἀπέκτεινε· περιελόμενος γὰρ αὐτοῦ τὸν ἄκοντα καὶ ζῶντα ἔτι καὶ μαχόμενον σκυλεύσας τοῖς ἰδίοις αὐτὸν ὅπλοις διεχρήσατο. προσαριθμήσειε δὲ ἄν τις αὐτοῦ καὶ τοῦτο ταῖς προειρημέναις πράξεσιν ἢ ὡς πρῶτον αὐτῶν κατ’ εὐψυχίαν ἢ ὡς ὅμοιον· νίφοντος γὰρ τοῦ θεοῦ λέων εἴς τινα λάκκον ὀλισθὼν ἐνέπεσε· στενοῦ δ’ ὄντος τοῦ στομίου δῆλον ἦν ἀφανὲς ἐσόμενον ἐμφραγέντος αὐτοῦ τῇ χιόνι· πόρον οὖν οὐδένα βλέπων ἐξόδου καὶ σωτηρίας ἐβρυχᾶτο. τοῦ δὲ θηρὸς ἀκούσας ὁ Ναβαῖος, ὥδευε γὰρ τότε, καὶ πρὸς τὴν βοὴν ἐλθών, καταβὰς εἰς τὸ στόμιον πλήξας αὐτὸν μαχόμενον τῷ μετὰ χεῖρας ξύλῳ παραχρῆμα ἀπέκτεινε. καὶ οἱ λοιποὶ δὲ τοιοῦτοι τὰς ἀρετὰς ὑπῆρχον.", "st": "7.12.4"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Δαυίδης βουλόμενος γνῶναι πόσαι μυριάδες εἰσὶ τοῦ λαοῦ, τῶν Μωυσέος ἐντολῶν ἐκλαθόμενος, ὃς προεῖπεν ἐὰν ἐξαριθμηθῇ τὸ πλῆθος ὑπὲρ ἑκάστης κεφαλῆς αὐτοῦ τῷ θεῷ τελεῖν ἡμίσικλον, προσέταξεν Ἰωάβῳ τῷ στρατηγῷ πορευθέντι πάντα τὸν ὄχλον ἐξαριθμῆσαι. τοῦ δ’ οὐκ ἀναγκαῖον εἶναι φήσαντος τοῦτο ποιεῖν οὐκ ἐπείσθη, προσέταξε δὲ μηδὲν μελλήσαντα βαδίζειν ἐπὶ τὴν ἐξαρίθμησιν τῶν Ἑβραίων. Ἰώαβος δὲ τοὺς ἄρχοντας τῶν φυλῶν παραλαβὼν καὶ γραμματεῖς, ἐπιὼν τὴν τῶν Ἰσραηλιτῶν χώραν καὶ τὸ πλῆθος ὅσον ἐστὶ κατανοήσας ὑπέστρεψεν εἰς Ἱεροσόλυμα πρὸς τὸν βασιλέα μετὰ μῆνας ἐννέα καὶ ἡμέρας εἴκοσι καὶ τὸν ἀριθμὸν ἀπέδωκε τῷ βασιλεῖ τοῦ λαοῦ χωρὶς τῆς Βενιαμίτιδος φυλῆς· ἐξαριθμῆσαι γὰρ αὐτὴν οὐκ ἔφθασεν ἀλλ’ οὐδὲ τὴν Λευιτῶν φυλήν· μετενόησε γὰρ ὁ βασιλεὺς ὧν εἰς τὸν θεὸν ἥμαρτεν. ἦν δὲ τῶν ἄλλων Ἰσραηλιτῶν ἀριθμὸς ἐνενήκοντα μυριάδες ὅπλα βαστάζειν καὶ στρατεύεσθαι δυναμένων, ἡ δὲ Ἰούδα φυλὴ καθ’ ἑαυτὴν τεσσαράκοντα μυριάδες ἦσαν.", "st": "7.13.1"}, {"sp": "N", "t": "Τῶν δὲ προφητῶν δηλωσάντων τῷ Δαυίδῃ, ὅτι δι’ ὀργῆς ἐστιν ὁ θεὸς αὐτῷ, ἱκετεύειν ἤρξατο καὶ παρακαλεῖν εὐμενῆ γενέσθαι καὶ συγγινώσκειν ἡμαρτηκότι. Γάδον δὲ τὸν προφήτην ἔπεμψεν ὁ θεὸς πρὸς αὐτὸν τρεῖς αἱρέσεις κομίζοντα, ὅπως ἐκλέξηται τούτων ἣν ἂν δοκιμάσῃ· πότερον θέλει λιμὸν γενέσθαι κατὰ τὴν χώραν ἐπὶ ἔτη ἑπτά, ἢ τρεῖς μῆνας πολεμήσας ὑπὸ τῶν ἐχθρῶν ἡττηθῆναι, ἢ λοιμὸν ἐνσκῆψαι καὶ νόσον ἐπὶ τρεῖς ἡμέρας τοῖς Ἑβραίοις. ὁ δ’ εἰς ἀμήχανον ἐκλογὴν μεγάλων κακῶν ἐμπεσὼν ἐλυπεῖτο καὶ σφόδρ’ ἦν συγκεχυμένος. τοῦ δὲ προφήτου τοῦτο δεῖν ἐξ ἀνάγκης γενέσθαι φήσαντος καὶ κελεύοντος ἀποκρίνασθαι ταχέως, ἵνα ἀναγγείλῃ τὴν αἵρεσιν αὐτοῦ τῷ θεῷ, λογισάμενος ὁ βασιλεύς, ὡς εἰ λιμὸν αἰτήσει, δόξει τοῦτο πεποιηκέναι τοῖς ἄλλοις αὐτῷ μὲν ἀφόβως, ὅτι πολὺν αὐτὸς ἐγκεκλεισμένον ἔχοι σῖτον, ἐκείνοις δὲ βλαβερῶς· κἂν γένηται τοὺς τρεῖς μῆνας νικωμένους αὐτούς, ὅτι τοὺς ἀνδρειοτάτους ἔχων περὶ αὑτὸν καὶ φρούρια καὶ διὰ τοῦτο μηδὲν φοβούμενος εἵλετο τὸν πόλεμον, ᾐτήσατο πάθος κοινὸν καὶ βασιλεῦσι καὶ τοῖς ἀρχομένοις, ἐν ᾧ τὸ δέος ἶσον ἁπάντων γίνεται, προσειπὼν ὅτι πολὺ κρεῖττον εἰς τὰς τοῦ θεοῦ χεῖρας ἐμπεσεῖν ἢ τὰς τῶν πολεμίων.", "st": "7.13.2"}, {"sp": "N", "t": "Ταῦτ’ ἀκούσας ὁ προφήτης ἀπήγγειλε τῷ θεῷ· ὁ δὲ τὸν λοιμὸν καὶ τὴν φθορὰν ἔπεμψε τοῖς Ἑβραίοις. ἀπέθνησκον δ’ οὐ μονοτρόπως οὐδ’ ὥστε ῥᾴδιον κατανοῆσαι γενέσθαι τὴν νόσον, ἀλλὰ τὸ μὲν κακὸν ἓν ἦν, μυρίαις δ’ αὐτοὺς αἰτίαις καὶ προφάσεσιν οὐδ’ ἐπινοῆσαι δυναμένους ἀνήρπαζεν. ἄλλος γὰρ ἐπ’ ἄλλῳ διεφθείρετο, καὶ λανθάνον ἐπερχόμενον τὸ δεινὸν ὀξεῖαν τὴν τελευτὴν ἐπέφερεν, τῶν μὲν αἰφνιδίως μετ’ ἀλγημάτων σφοδρῶν καὶ πικρᾶς ὀδύνης τὴν ψυχὴν ἀφιέντων, ἐνίων δὲ καὶ μαραινομένων τοῖς παθήμασι καὶ μηδ’ εἰς κηδείαν ὑπολειπομένων, ἀλλ’ ἐν αὐτῷ τῷ κάμνειν εἰς τὸ παντελὲς δαπανωμένων· οἱ δ’ αἰφνίδιον σκότους αὐτοῖς τὰς ὄψεις ὑποδραμόντος περιπνιγεῖς ἀπῴμωζον, ἔνιοι δὲ τῶν οἰκείων τινὰ κηδεύοντες ἐναπέθνησκον ἀτελέσι ταῖς ταφαῖς. ἀπώλοντο δ’ ἀρξαμένης ἕωθεν τῆς λοιμικῆς νόσου φθείρειν αὐτοὺς ἕως ὥρας ἀρίστου μυριάδες ἑπτά. ἐξέτεινε δὲ ὁ ἄγγελος τὴν χεῖρα καὶ ἐπὶ τὰ Ἱεροσόλυμα τὸ δεινὸν κἀκεῖσε πέμπων. ὁ δὲ βασιλεὺς σάκκον ἐνδεδυμένος ἔκειτο κατὰ τῆς γῆς ἱκετεύων τὸν θεὸν καὶ δεόμενος ἤδη λωφῆσαι καὶ τοῖς ἀπολωλόσιν ἀρκεσθέντα παύσασθαι· ἀναβλέψας δ’ εἰς τὸν ἀέρα ὁ βασιλεὺς καὶ θεασάμενος τὸν ἄγγελον δι’ αὐτοῦ φερόμενον ἐπὶ τὰ Ἱεροσόλυμα καὶ μάχαιραν ἐσπασμένον εἶπε πρὸς τὸν θεόν, ὡς αὐτὸς εἴη κολασθῆναι δίκαιος ὁ ποιμήν, τὰ δὲ ποίμνια σώζεσθαι μηδὲν ἁμαρτόντα, καὶ ἠντιβόλει τὴν ὀργὴν εἰς αὐτὸν καὶ τὴν γενεὰν αὐτοῦ πᾶσαν ἀποσκήπτειν, φείδεσθαι δὲ τοῦ λαοῦ.", "st": "7.13.3"}, {"sp": "N", "t": "Κατακούσας δὲ ὁ θεὸς τῆς ἱκεσίας ἔπαυσε τὸν λοιμόν, καὶ πέμψας Γάδον τὸν προφήτην ἐκέλευσεν αὐτὸν ἀναβῆναι παραχρῆμα εἰς τὴν ἅλω τοῦ Ἰεβουσαίου Ὀροννᾶ καὶ οἰκοδομήσαντα βωμὸν ἐκεῖ τῷ θεῷ θυσίαν ἐπιτελέσαι. Δαυίδης δ’ ἀκούσας οὐκ ἠμέλησεν, ἀλλ’ εὐθὺς ἔσπευσεν ἐπὶ τὸν παρηγγελμένον αὐτῷ τόπον. Ὀροννᾶς δὲ τὸν σῖτον ἀλοῶν ἐπεὶ τὸν βασιλέα προσιόντα καὶ τοὺς παῖδας αὐτοῦ πάντας ἐθεάσατο, προσέδραμεν αὐτῷ καὶ προσεκύνησεν. ἦν δὲ τὸ μὲν γένος Ἰεβουσαῖος, φίλος δ’ ἐν τοῖς μάλιστα Δαυίδου· καὶ διὰ τοῦτ’ αὐτὸν οὐδὲν εἰργάσατο δεινόν, ὅτε τὴν πόλιν κατεστρέψατο, ὡς μικρὸν ἔμπροσθεν ἐδηλώσαμεν. τοῦ δὲ Ὀροννᾶ πυθομένου τί παρείη πρὸς τὸν δοῦλον ὁ δεσπότης, εἶπεν ὠνήσασθαι παρ’ αὐτοῦ τὴν ἅλω, ὅπως βωμὸν ἐν αὐτῇ κατασκευάσῃ τῷ θεῷ καὶ ποιήσῃ θυσίαν. ὁ δὲ καὶ τὴν ἅλω εἶπε καὶ τὰ ἄροτρα καὶ τοὺς βόας εἰς ὁλοκαύτωσιν χαρίζεσθαι καὶ τὸν θεὸν ἡδέως εὔχεσθαι τὴν θυσίαν προσέσθαι. ὁ δὲ βασιλεὺς ἀγαπᾶν μὲν αὐτὸν τῆς ἁπλότητος καὶ τῆς μεγαλοψυχίας ἔλεγε καὶ δέχεσθαι τὴν χάριν, τιμὴν δ’ αὐτὸν ἠξίου λαμβάνειν πάντων· οὐ γὰρ εἶναι δίκαιον προῖκα θυσίαν ἐπιτελεῖν. τοῦ δὲ Ὀροννᾶ φήσαντος ποιεῖν ὅ τι βούλεται πεντήκοντα σίκλων ὠνεῖται παρ’ αὐτοῦ τὴν ἅλω. καὶ οἰκοδομήσας τὸν βωμὸν ἱερούργησε καὶ ὡλοκαύτωσε καὶ θυσίας ἐπήνεγκεν εἰρηνικάς. καταπραΰνεται δὲ τούτοις τὸ θεῖον καὶ πάλιν εὐμενὲς γίνεται. συνέβη δ’ εἰς ἐκεῖνον ἀγαγεῖν τὸν τόπον Ἅβραμον τὸν υἱὸν αὐτοῦ Ἴσακον ὥστε ὁλοκαυτῶσαι, καὶ μέλλοντος ἀποσφάττεσθαι τοῦ παιδὸς κριὸν ἐξαίφνης ἀναφανῆναι παρεστῶτα τῷ βωμῷ, ὃν καὶ κατέθυσεν Ἅβραμος ἀντὶ τοῦ παιδός, ὡς προειρήκαμεν. ὁρῶν δ’ ὁ βασιλεὺς Δαυίδης τῆς εὐχῆς αὐτοῦ τὸν θεὸν ἐπήκοον γεγενημένον καὶ τὴν θυσίαν ἡδέως προσδεξάμενον ἔκρινε τὸν τόπον ἐκεῖνον ὅλον βωμὸν προσαγορεῦσαι τοῦ λαοῦ παντὸς καὶ οἰκοδομῆσαι ναὸν τῷ θεῷ. καὶ ταύτην εὐστόχως ἀφῆκεν εἰς τὸ γενησόμενον τὴν φωνήν· ὁ γὰρ θεὸς τὸν προφήτην ἀποστείλας πρὸς αὐτὸν ἐκεῖ ναὸν ἔλεγεν οἰκοδομήσειν αὐτοῦ τὸν υἱὸν τὸν μέλλοντα μετ’ αὐτὸν τὴν βασιλείαν διαδέχεσθαι.", "st": "7.13.4"}, {"sp": "N", "t": "Μετὰ δὴ ταύτην τὴν προφητείαν ἐκέλευσεν ὁ βασιλεὺς τοὺς παροίκους ἐξαριθμηθῆναι καὶ εὑρέθησαν εἰς ὀκτὼ μυριάδας καὶ δέκα. ἐκ τούτων ἀπέδειξε λατόμους μὲν τοὺς ὀκτακισμυρίους, τὸ δ’ ἄλλο πλῆθος παραφέρειν τοὺς λίθους, τρισχιλίους δὲ καὶ πεντακοσίους τοῖς ἐργαζομένοις ἐξ αὐτῶν ἐπέστησεν. ἡτοίμασε δὲ καὶ πολὺν σίδηρον καὶ χαλκὸν εἰς τὰ ἔργα καὶ ξύλα κέδρινα πολλὰ καὶ παμμεγεθέστατα, Τυρίων αὐτῷ ταῦτα πεμπόντων καὶ Σιδωνίων· ἐπεστάλκει γὰρ αὐτοῖς τὴν τῶν ξύλων χορηγίαν. πρός τε τοὺς φίλους ἔλεγε ταῦτα παρασκευάζεσθαι νῦν, ἵνα τῷ μέλλοντι παιδὶ βασιλεύειν μετ’ αὐτὸν ἑτοίμην τὴν ὕλην τῆς οἰκοδομίας καταλείπῃ καὶ μὴ τότε συμπορίζῃ νέος ὢν καὶ τῶν τοιούτων ἄπειρος διὰ τὴν ἡλικίαν, ἀλλ’ ἔχων παρακειμένην ἐπιτελῇ τὸ ἔργον.", "st": "7.14.1"}, {"sp": "N", "t": "Καλέσας δὲ τὸν παῖδα Σολόμωνα κατασκευάσαι τῷ θεῷ ναὸν αὐτὸν ἐκέλευε διαδεξάμενον τὴν βασιλείαν λέγων, ὡς αὐτὸν βουλόμενον κωλύσειεν ὁ θεὸς αἵματι καὶ πολέμοις πεφυραμένον, προείποι δ’ ὅτι Σολόμων οἰκοδομήσει αὐτῷ παῖς νεώτατος καὶ τοῦτο κληθησόμενος τοὔνομα, οὗ προνοήσειν μὲν αὐτὸς ὡς πατὴρ ἐπηγγέλλετο, τὴν δ’ Ἑβραίων χώραν εὐδαίμονα καταστήσειν ἐπ’ αὐτοῦ τοῖς τε ἄλλοις ἀγαθοῖς καὶ δὴ καὶ τῷ μεγίστῳ πάντων εἰρήνῃ καὶ πολέμων ἀπαλλαγῇ καὶ στάσεων ἐμφυλίων. σὺ τοίνυν ἐπεὶ καὶ πρὸ τῆς γενέσεως ἀπεδείχθης βασιλεὺς ὑπὸ τοῦ θεοῦ πειρῶ τά τε ἄλλα γίνεσθαι τῆς τούτου προνοίας ἄξιος εὐσεβὴς ὢν καὶ δίκαιος καὶ ἀνδρεῖος, καὶ τὰς ἐντολὰς αὐτοῦ καὶ τοὺς νόμους οὓς διὰ Μωυσέος ἔδωκεν ἡμῖν φύλαττε καὶ τοῖς ἄλλοις μὴ παραβαίνειν ἐπίτρεπε. τὸν δὲ ναόν, ὃν ὑπὸ σοῦ βασιλεύοντος εἵλετο αὑτῷ γενέσθαι, σπούδασον ἀποδοῦναι τῷ θεῷ μὴ καταπλαγεὶς τὸ μέγεθος τοῦ ἔργου μηδ’ ἀποδειλιάσας πρὸς αὐτό· πάντα γάρ σοι πρὸ τῆς ἐμαυτοῦ τελευτῆς ἕτοιμα ποιήσω. γίνωσκε χρυσοῦ μὲν ἤδη τάλαντα συνειλεγμένα μύρια, δέκα δ’ ἀργύρου μυριάδας ταλάντων, χαλκόν τε καὶ σίδηρον ἀριθμοῦ πλείονα συντέθεικα καὶ ξύλων δὲ καὶ λίθων ὕλην ἄφθονον, ἔχεις δὲ καὶ λατόμων πολλὰς μυριάδας καὶ τεκτόνων· ἂν δέ τι τούτοις προσδέῃ, σὺ προσθήσεις. γίνου τοίνυν ἄριστος τὸν θεὸν ἔχων προστάτην. προσπαρεκελεύσατο δὲ καὶ τοὺς ἄρχοντας τοῦ λαοῦ τῆς οἰκοδομίας συλλαβέσθαι τῷ παιδὶ καὶ πάντων ἀδεεῖς ὄντας τῶν κακῶν περὶ τὴν τοῦ θεοῦ θρησκείαν ἀσχολεῖν· καρπώσεσθαι γὰρ αὐτοὺς ἀντὶ τούτων εἰρήνην καὶ εὐνομίαν, οἷς ἀμείβεται τοὺς εὐσεβεῖς καὶ δικαίους ὁ θεὸς ἀνθρώπους. οἰκοδομηθέντος δὲ τοῦ ναοῦ τὴν κιβωτὸν αὐτὸν ἀποθέσθαι προσέταξε καὶ τὰ ἅγια σκεύη πρὸ πολλοῦ ναὸν ὀφείλοντα ἔχειν, εἰ τῶν ἐντολῶν τοῦ θεοῦ μὴ παρήκουσαν ἡμῶν οἱ πατέρες ἐντειλαμένου μετὰ τὸ τὴν γῆν ταύτην κατασχεῖν οἰκοδομῆσαι ναὸν αὐτῷ. ταῦτα μὲν πρὸς τοὺς ἡγεμόνας ὁ Δαυίδης καὶ τὸν υἱὸν αὐτοῦ διελέχθη.", "st": "7.14.2"}, {"sp": "N", "t": "Πρεσβύτερος δὲ ὢν ἤδη καὶ τοῦ σώματος αὐτῷ ψυχομένου διὰ τὸν χρόνον δύσριγος ὑπῆρχεν, ὡς μηδ’ ὑπὸ τῆς ἐπιβολῆς ἐκ πολλῶν ἱματίων γινομένης ἀναθερμαίνεσθαι. συνελθόντων δὲ τῶν ἰατρῶν καὶ συμβουλευσάντων, ὅπως ἐξ ἁπάσης τῆς χώρας εὐειδὴς ἐπιλεχθεῖσα παρθένος συγκαθεύδῃ τῷ βασιλεῖ, τοῦτο γὰρ αὐτῷ πρὸς τὸ ῥῖγος ἔσεσθαι βοήθημα θαλπούσης αὐτὸν τῆς κόρης, εὑρίσκετ’ ἐν πόλει γυνὴ μία πασῶν τὸ εἶδος ἀρίστη γυναικῶν Ἀβισάκη τοὔνομα, ἣ συγκοιμωμένη μόνον τῷ βασιλεῖ συνεθέρμαινεν αὐτόν· ὑπὸ γὰρ γήρως ἦν πρὸς τἀφροδίσια καὶ γυναικὸς ὁμιλίαν ἀσθενής. καὶ περὶ μὲν ταύτης τῆς παρθένου μετ’ ὀλίγον δηλώσομεν.", "st": "7.14.3"}, {"sp": "N", "t": "Ὁ δὲ τέταρτος υἱὸς Δαυίδου νεανίας εὐειδὴς καὶ μέγας, ἐκ γυναικὸς αὐτῷ Αἰγίσθης γεγονὼς Ἀδωνίας δὲ προσαγορευόμενος, ἐμφερὴς ὢν Ἀψαλώμῳ τήν τε διάνοιαν αὐτὸς ὡς βασιλεύσων ἐπῆρτο καὶ πρὸς τοὺς φίλους ἔλεγεν, ὡς τὴν ἀρχὴν αὐτὸν δεῖ παραλαβεῖν· κατεσκεύασε δὲ ἅρματα πολλὰ καὶ ἵππους καὶ πεντήκοντα ἄνδρας τοὺς προδρόμους. ταῦθ’ ὁρῶν ὁ πατὴρ οὐκ ἐπέπληττεν οὐδ’ ἐπεῖχεν αὐτὸν τῆς προαιρέσεως οὐδὲ μέχρι τοῦ πυθέσθαι διὰ τί ταῦτα πράττει προήχθη. συνεργοὺς δ’ εἶχεν Ἀδωνίας τὸν στρατηγὸν Ἰώαβον καὶ τὸν ἀρχιερέα Ἀβιάθαρον, μόνοι δ’ ἀντέπραττον ὁ ἀρχιερεὺς Σάδωκος καὶ ὁ προφήτης Νάθας καὶ Βαναίας ὁ ἐπὶ τῶν σωματοφυλάκων καὶ Σιμούεις ὁ Δαυίδου φίλος καὶ πάντες οἱ ἀνδρειότατοι. τοῦ δὲ Ἀδωνία παρασκευασαμένου δεῖπνον ἔξω τῆς πόλεως παρὰ τὴν πηγὴν τὴν ἐν τῷ βασιλικῷ παραδείσῳ καὶ πάντας καλέσαντος τοὺς ἀδελφοὺς χωρὶς Σολόμωνος, παραλαβόντος δὲ καὶ τὸν στρατηγὸν Ἰώαβον καὶ Ἀβιάθαρον καὶ τοὺς ἄρχοντας τῆς Ἰούδα φυλῆς, οὔτε δὲ Σάδωκον τὸν ἀρχιερέα καὶ Νάθαν τὸν προφήτην καὶ τὸν ἐπὶ τῶν σωματοφυλάκων Βαναίαν καὶ πάντας τοὺς ἐκ τῆς ἐναντίας αἱρέσεως καλέσαντος ἐπὶ τὴν ἑστίασιν, τοῦτο πρὸς τὴν Σολόμωνος κατεμήνυσε μητέρα Βερσάβην Νάθας ὁ προφήτης, ὡς Ἀδωνίας βασιλεῦσαι βούλεται, συνεβούλευέ τε σώζειν αὑτὴν καὶ τὸν παῖδα Σολόμωνα, εἴπερ Ἀδωνίας τὴν ἀρχὴν ἤδη παραλάβοι, καὶ περὶ τούτου πυθέσθαι τοῦ βασιλέως. ταῦτα δὲ τῷ βασιλεῖ διαλεγομένης ὁ προφήτης εἰσελεύσεσθαι καὶ αὐτὸς ἔφησε καὶ τοῖς λόγοις αὐτῆς ἐπιμαρτυρήσειν. ἡ δὲ Βερσάβη πεισθεῖσα τῷ Νάθᾳ πάρεισι πρὸς τὸν βασιλέα, καὶ προσκυνήσασα καὶ λόγον αἰτησαμένη πάντ’ αὐτῷ [καθὼς] ὁ προφήτης ὑπέθετο διεξέρχεται τό τε δεῖπνον τὸ Ἀδωνία καὶ τοὺς ὑπ’ αὐτοῦ κεκλημένους Ἀβιάθαρον τὸν ἀρχιερέα καὶ Ἰώαβον τὸν ἄρχοντα καὶ τοὺς υἱοὺς αὐτοῦ χωρὶς Σολόμωνος καὶ τῶν ἀναγκαίων αὐτοῦ φίλων μηνύσασα· ἔλεγέ τε πάντα τὸν λαὸν ἀφορᾶν, τίνα χειροτονήσει βασιλέα, παρεκάλει τε κατὰ νοῦν ἔχειν, ὡς μετὰ τὴν ἀπαλλαγὴν αὐτοῦ βασιλεύσας αὐτήν τε καὶ Σολόμωνα τὸν υἱὸν αὐτῆς ἀναιρήσει.", "st": "7.14.4"}, {"sp": "N", "t": "Διαλεγομένης δὲ ἔτι τῆς γυναικὸς ἤγγειλαν οἱ τοῦ δωματίου προεστῶτες, ὅτι βούλεται Νάθας ἰδεῖν αὐτόν. τοῦ δὲ βασιλέως ἐκδέξασθαι κελεύσαντος εἰσελθών, εἰ τήμερον ἀποδείξειε τὸν Ἀδωνίαν βασιλέα καὶ παραδοίη τὴν ἀρχὴν ἐπυνθάνετο· λαμπρὸν γὰρ αὐτὸν ποιήσαντα δεῖπνον κεκληκέναι τοὺς υἱοὺς αὐτοῦ πάντας χωρὶς Σολόμωνος καὶ τὸν στρατηγὸν Ἰώαβον, οἳ μετὰ κρότου καὶ παιδιᾶς εὐωχούμενοι πολλῆς αἰώνιον αὐτῷ συνεύχονται τὴν ἡγεμονίαν· ἐκάλεσε δὲ οὔτε ἐμὲ οὔτε τὸν ἀρχιερέα Σάδωκον οὔτε Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων· δίκαιον δ’ εἶναι ταῦτα γινώσκειν ἅπαντας, εἰ κατὰ τὴν σὴν γνώμην ἐγένετο. ταῦτα τοῦ Νάθα φήσαντος ὁ βασιλεὺς ἐκέλευσε καλέσαι τὴν Βερσάβην πρὸς αὑτόν· ἐκπεπηδήκει γὰρ ἐκ τοῦ δωματίου τοῦ προφήτου παραγενομένου. τῆς δὲ γυναικὸς ἐλθούσης, ὄμνυμί σοι, φησί, τὸν μέγιστον θεόν, ἦ μὴν τὸν υἱόν σου Σολόμωνα βασιλεύσειν, ὡς καὶ πρότερον ὤμοσα, καὶ τοῦτον ἐπὶ τοὐμοῦ καθιεῖσθαι θρόνου· καὶ τοῦτο ἔσται τήμερον. προσκυνησάσης δ’ αὐτὸν τῆς γυναικὸς καὶ μακρὸν εὐξαμένης αὐτῷ βίον Σάδωκον μεταπέμπεται τὸν ἀρχιερέα καὶ Βαναίαν τὸν ἐπὶ τῶν σωματοφυλάκων, καὶ παραγενομένοις κελεύει παραλαβεῖν Νάθαν τὸν προφήτην καὶ τοὺς περὶ τὴν αὐλὴν ὁπλίτας καὶ ἀναβιβάσαντας τὸν υἱὸν αὐτοῦ Σολόμωνα ἐπὶ τὴν βασιλικὴν ἡμίονον ἔξω τῆς πόλεως ἀγαγεῖν ἐπὶ πηγὴν τὴν λεγομένην Γειὼν καὶ περιχρίσαντας τὸ ἅγιον ἔλαιον ἀποδεῖξαι βασιλέα· τοῦτο δὲ ποιῆσαι προσέταξε Σάδωκον τὸν ἀρχιερέα καὶ Νάθαν τὸν προφήτην. ἀκολουθοῦντάς τε προσέταξε διὰ μέσης τῆς πόλεως τοῖς κέρασιν ἐπισαλπίζοντας βοᾶν εἰς αἰῶνα Σολόμωνα τὸν βασιλέα καθίσαι ἐπὶ τοῦ βασιλικοῦ θρόνου, ἵνα γνῷ πᾶς ὁ λαὸς ἀποδεδειγμένον αὐτὸν ὑπὸ τοῦ πατρὸς βασιλέα, Σολόμωνι δ’ ἐντετάλθαι περὶ τῆς ἀρχῆς, ἵνα εὐσεβῶς καὶ δικαίως προστῇ τοῦ τε Ἑβραίων ἔθνους παντὸς καὶ τῆς Ἰούδα φυλῆς. Βαναία δὲ εὐξαμένου τὸν θεὸν Σολόμωνι εὐμενῆ γενέσθαι μηδὲ μικρὸν διαλιπόντες ἀναβιβάζουσιν ἐπὶ τὴν ἡμίονον τὸν Σολόμωνα, καὶ προαγαγόντες ἔξω τῆς πόλεως ἐπὶ τὴν πηγὴν καὶ τῷ ἐλαίῳ χρίσαντες εἰσήγαγον εἰς τὴν πόλιν ἐπευφημοῦντες καὶ τὴν βασιλείαν αὐτῷ γενέσθαι πολυχρόνιον εὐχόμενοι, καὶ παραγαγόντες εἰς τὸν οἶκον τὸν βασιλικὸν καθίζουσιν αὐτὸν ἐπὶ τοῦ θρόνου, καὶ πᾶς ὁ λαὸς ἐπ’ εὐωχίαν εὐθὺς ἐτράπη καὶ ἑορτὴν χορεύων καὶ αὐλοῖς τερπόμενος, ὡς ὑπὸ τοῦ πλήθους τῶν ὀργάνων ἅπασαν περιηχεῖσθαι τὴν γῆν καὶ τὸν ἀέρα.", "st": "7.14.5"}, {"sp": "N", "t": "Ὡς δ’ ᾔσθοντο τῆς βοῆς Ἀδωνίας τε καὶ οἱ παρόντες ἐπὶ τὸ δεῖπνον ἐταράχθησαν, ὅ τε στρατηγὸς Ἰώαβος ἔλεγεν οὐκ ἀρέσκεσθαι τοῖς ἤχοις οὐδὲ τῇ σάλπιγγι. παρακειμένου δὲ τοῦ δείπνου καὶ μηδενὸς γευομένου πάντων δ’ ἐπ’ ἐννοίας ὑπαρχόντων, εἰστρέχει πρὸς αὐτοὺς ὁ τοῦ ἀρχιερέως Ἀβιαθάρου παῖς Ἰωνάθης. τοῦ δ’ Ἀδωνία θεασαμένου τὸν νεανίαν ἡδέως καὶ προσειπόντος ἀγαθῶν ἄγγελον, ἐδήλου πάντ’ αὐτοῖς τὰ περὶ τὸν Σολόμωνα καὶ τὴν Δαυίδου τοῦ βασιλέως γνώμην· ἀναπηδήσαντες δ’ ἐκ τοῦ συμποσίου ὅ τε Ἀδωνίας καὶ οἱ κεκλημένοι πάντες ἔφυγον πρὸς ἑαυτοὺς ἕκαστοι. φοβηθεὶς δ’ Ἀδωνίας τὸν βασιλέα περὶ τῶν γεγονότων ἱκέτης γίνεται τοῦ θεοῦ καὶ τῶν τοῦ θυσιαστηρίου κεράτων ἃ δὴ προεῖχεν ἐλλαβόμενος δηλοῦται τοῦτο Σολόμωνι πεποιηκὼς καὶ πίστεις ἀξιῶν παρ’ αὐτοῦ λαβεῖν, ὥστε μὴ μνησικακῆσαι μηδ’ ἐργάσασθαι δεινὸν αὐτὸν μηδέν. ὁ δὲ ἡμέρως πάνυ καὶ σωφρόνως τῆς μὲν τότε ἁμαρτίας αὐτὸν ἀφῆκεν ἀθῷον, εἰπὼν δέ, εἰ ληφθείη τι πάλιν καινοποιῶν, ἑαυτῷ αἴτιον τῆς τιμωρίας ἔσεσθαι, πέμψας ἀνίστησιν αὐτὸν ἀπὸ τῆς ἱκεσίας· ἐλθόντα δὲ καὶ προσκυνήσαντα εἰς τὴν ἰδίαν οἰκίαν ἀπελθεῖν ἐκέλευσε μηδὲν ὑφορώμενον καὶ τοῦ λοιποῦ παρέχειν αὑτὸν ἀγαθὸν ὡς αὐτῷ τοῦτο συμφέρον ἠξίου.", "st": "7.14.6"}, {"sp": "N", "t": "Βουλόμενος δὲ Δαυίδης ἐπὶ παντὸς τοῦ λαοῦ ἀποδεῖξαι τὸν υἱὸν βασιλέα συγκαλεῖ τοὺς ἄρχοντας εἰς Ἱεροσόλυμα καὶ τοὺς ἱερεῖς καὶ τοὺς Ληουίτας. ἐξαριθμήσας δὲ τούτους πρῶτον εὑρίσκει τῶν ἀπὸ τριάκοντα ἐτῶν ἕως πεντήκοντα τρισμυρίους ὀκτακισχιλίους. ἐξ ὧν ἀπέδειξεν ἐπιμελητὰς μὲν τῆς οἰκοδομίας τοῦ ναοῦ δισμυρίους τετρακισχιλίους, κριτὰς δὲ τοῦ λαοῦ καὶ γραμματεῖς τούτων ἑξακισχιλίους, πυλωροὺς δὲ τετρακισχιλίους καὶ τοσούτους ὑμνῳδοὺς τοῦ θεοῦ ᾄδοντας τοῖς ὀργάνοις οἷς Δαυίδης κατεσκεύασε, καθὼς προειρήκαμεν. διεμέρισε δ’ αὐτοὺς καὶ κατὰ πατριὰς καὶ χωρίσας ἐκ τῆς φυλῆς τοὺς ἱερεῖς εὗρε τούτων εἴκοσι τέσσαρας πατριάς, ἐκ μὲν τῆς Ἐλεαζάρου οἰκίας ἑκκαίδεκα, ἐκ δὲ τῆς Ἰθαμάρου ὀκτώ, διέταξέ τε μίαν πατριὰν διακονεῖσθαι τῷ θεῷ ἐπὶ ἡμέρας ὀκτὼ ἀπὸ σαββάτου ἐπὶ σάββατον. καὶ οὕτως αἱ πατριαὶ πᾶσαι διεκληρώσαντο Δαυίδου παρόντος καὶ Σαδώκου καὶ Ἀβιαθάρου τῶν ἀρχιερέων καὶ πάντων τῶν ἀρχόντων· καὶ ἡ πρώτη μὲν ἀναβᾶσα πατριὰ ἐγράφη πρώτη, ἡ δὲ δευτέρα ἀκολούθως ἄχρι τῶν εἴκοσι τεσσάρων· καὶ διέμεινεν οὗτος ὁ μερισμὸς ἄχρι τῆς σήμερον ἡμέρας. ἐποίησε δὲ καὶ τῆς Ληουίτιδος φυλῆς εἴκοσι μέρη καὶ τέσσαρα καὶ κληρωσαμένων κατὰ τὸν αὐτὸν ἀνέβησαν τρόπον ταῖς τῶν ἱερέων ἐφημερίσιν ἐπὶ ἡμέρας ὀκτώ. τοὺς δ’ ἀπογόνους τοὺς Μωυσέος ἐτίμησεν· ἐποίησε γὰρ αὐτοὺς φύλακας τῶν θησαυρῶν τοῦ θεοῦ καὶ τῶν ἀναθημάτων, ἃ συνέβη τοὺς βασιλεῖς ἀναθεῖναι· διέταξε δὲ πᾶσι τοῖς ἐκ τῆς Ληουίτιδος φυλῆς καὶ τοῖς ἱερεῦσι δουλεύειν κατὰ νύκτα καὶ ἡμέραν τῷ θεῷ, καθὼς αὐτοῖς ἐπέστειλε Μωυσῆς.", "st": "7.14.7"}, {"sp": "N", "t": "Μετὰ ταῦτα διεμέρισε τὴν στρατιὰν εἰς δώδεκα μοίρας σὺν ἡγεμόσι καὶ ἑκατοντάρχοις καὶ ταξιάρχαις. εἶχεν δ’ ἑκάστη τῶν μοιρῶν δισμυρίους καὶ τετρακισχιλίους, ὧν ἐκέλευσε προσεδρεύειν κατὰ τριάκονθ’ ἡμέρας ἀπὸ τῆς πρώτης ἕως τῆς ὑστάτης Σολόμωνι τῷ βασιλεῖ σὺν τοῖς χιλιάρχοις καὶ ἑκατοντάρχοις. κατέστησε δὲ καὶ ἄρχοντα ἑκάστης μοίρας ὃν ἀγαθὸν ᾔδει καὶ δίκαιον, ἐπιτρόπους τε τῶν θησαυρῶν καὶ κωμῶν καὶ ἀγρῶν ἄλλους καὶ κτηνῶν, ὧν οὐκ ἀναγκαῖον ἡγησάμην μνησθῆναι τῶν ὀνομάτων.", "st": "7.14.8"}, {"sp": "N", "t": "Ὡς δ’ ἕκαστα τούτων κατὰ τὸν προειρημένον διέταξε τρόπον, εἰς ἐκκλησίαν συγκαλέσας τοὺς ἄρχοντας τῶν Ἑβραίων καὶ τοὺς φυλάρχους καὶ τοὺς ἡγεμόνας τῶν διαιρέσεων καὶ τοὺς ἐπὶ πάσης πράξεως ἢ κτήσεως τοῦ βασιλέως τεταγμένους, στὰς ἐφ’ ὑψηλοτάτου βήματος ὁ βασιλεὺς ἔλεξε πρὸς τὸ πλῆθος· ἀδελφοὶ καὶ ὁμοεθνεῖς, γινώσκειν ὑμᾶς βούλομαι, ὅτι ναὸν οἰκοδομῆσαι τῷ θεῷ διανοηθεὶς χρυσόν τε πολὺν παρεσκευασάμην καὶ ἀργύρου ταλάντων μυριάδας δέκα, ὁ δὲ θεὸς ἐκώλυσέ με διὰ τοῦ προφήτου Νάθα διά τε τοὺς ὑπὲρ ὑμῶν πολέμους καὶ τῷ φόνῳ τῶν ἐχθρῶν μεμιάνθαι τὴν δεξιάν, τὸν δὲ υἱὸν ἐκέλευσε τὸν διαδεξόμενον τὴν βασιλείαν κατασκευάσαι τὸν ναὸν αὐτῷ. νῦν οὖν ἐπεὶ καὶ τῷ προγόνῳ ἡμῶν Ἰακώβῳ δυοκαίδεκα παίδων γενομένων ἴστε τὸν Ἰούδαν ἀποδειχθέντα βασιλέα, καὶ ἐμὲ τῶν ἀδελφῶν ἓξ ὄντων προκριθέντα καὶ τὴν ἡγεμονίαν λαβόντα παρὰ τοῦ θεοῦ καὶ μηδένα τούτων δυσχεράναντα, οὕτως ἀξιῶ κἀγὼ τοὺς ἐμαυτοῦ παῖδας μὴ στασιάζειν πρὸς ἀλλήλους Σολόμωνος τὴν βασιλείαν παρειληφότος, ἀλλ’ ἐπισταμένους ὡς ὁ θεὸς αὐτὸν ἐξελέξατο φέρειν ἡδέως αὐτὸν δεσπότην. οὐ δεινὸν γὰρ θεοῦ θέλοντος οὐδ’ ἀλλοτρίῳ κρατοῦντι δουλεύειν, χαίρειν δ’ ἐπ’ ἀδελφῷ ταύτης τυχόντι τῆς τιμῆς προσῆκεν ὡς κοινωνοῦντας αὐτῆς. εὔχομαι δὴ τὰς ὑποσχέσεις τοῦ θεοῦ παρελθεῖν εἰς τέλος καὶ τὴν εὐδαιμονίαν ταύτην ἀνὰ πᾶσαν τὴν χώραν σπαρῆναι καὶ τὸν ἅπαντα ταύτῃ παραμεῖναι χρόνον, ἣν αὐτὸς ἐπηγγείλατο παρέξειν ἐπὶ Σολόμωνος βασιλέως. ἔσται δὲ ταῦτα βέβαια καὶ καλὸν ἕξει πέρας, ἂν εὐσεβῆ καὶ δίκαιον αὑτὸν καὶ φύλακα τῶν πατρίων παρέχῃς νόμων, ὦ τέκνον· εἰ δὲ μή, τὰ χείρω προσδοκάτω ταῦτα παραβαίνων.", "st": "7.14.9"}, {"sp": "N", "t": "Ὁ μὲν οὖν βασιλεὺς τούτους ποιησάμενος τοὺς λόγους ἐπαύσατο, τήν τε διαγραφὴν καὶ διάταξιν τῆς οἰκοδομίας τοῦ ναοῦ πάντων ὁρώντων ἔδωκε Σολόμωνι θεμελίων καὶ οἴκων [καὶ] ὑπερῴων, ὅσοι τε τὸ πλῆθος καὶ πηλίκοι τὸ ὕψος καὶ εὖρος γένοιντο, ὅσα τε σκεύη χρυσᾶ καὶ ἀργυρᾶ τούτων τὸν σταθμὸν ὥρισε. προσπαρώρμησε δὲ καὶ λόγοις αὐτόν τε πάσῃ χρήσασθαι προθυμίᾳ περὶ τὸ ἔργον καὶ τοὺς ἄρχοντας καὶ τὴν Ληουιτῶν φυλὴν συναγωνίσασθαι διά τε τὴν ἡλικίαν καὶ διὰ τὸ τὸν θεὸν ἐκεῖνον ἑλέσθαι καὶ τῆς οἰκοδομίας τοῦ ναοῦ καὶ τῆς βασιλείας προστάτην. εὐμαρῆ δ’ αὐτοῖς καὶ οὐ σφόδρα ἐπίπονον τὴν οἰκοδομίαν ἀπέφαινεν αὐτοῦ μὲν πολλὰ τάλαντα χρυσοῦ πλείω δ’ ἀργύρου καὶ ξύλα καὶ τεκτόνων πλῆθος καὶ λατόμων ἤδη παρεσκευασμένου σμαράγδου τε καὶ πάσης ἰδέας λίθου πολυτελοῦς· καὶ νῦν δ’ ἔτι τῆς ἰδίας ἀπαρχὴν διακονίας ἄλλα τρισχίλια τάλαντα χρυσοῦ καθαροῦ παρέξειν ἔλεγεν εἰς τὸ ἄδυτον καὶ εἰς τὸ ἅρμα τοῦ θεοῦ τοὺς Χερουβεῖς, οὓς ἐφεστάναι δεήσει τὴν κιβωτὸν καλύπτοντας. σιωπήσαντος δὲ τοῦ Δαυίδου πολλὴ καὶ τῶν ἀρχόντων καὶ τῶν ἱερέων καὶ τῆς Ληουίτιδος φυλῆς προθυμία συμβαλλομένων καὶ ποιουμένων ἐπαγγελίας λαμπρὰς καὶ μεγαλοπρεπεῖς ἐγένετο· χρυσοῦ μὲν γὰρ ὑπέστησαν εἰσοίσειν τάλαντα πεντακισχίλια καὶ στατῆρας μυρίους, ἀργυρίου δὲ μύρια τάλαντα, καὶ σιδήρου μυριάδας ταλάντων πολλάς· καὶ εἴ τινι λίθος ἦν πολυτελὴς ἐκόμισε καὶ παρέδωκεν εἰς τοὺς θησαυρούς, ὧν ἐπετρόπευεν ὁ Μωυσέος ἔκγονος Ἴαλος.", "st": "7.14.10"}, {"sp": "N", "t": "Ἐπὶ τούτοις ἥσθη τε ὁ λαὸς ἅπας καὶ Δαυίδης τὴν σπουδὴν καὶ τὴν φιλοτιμίαν τῶν ἀρχόντων καὶ ἱερέων καὶ τῶν ἄλλων ἁπάντων ὁρῶν τὸν θεὸν εὐλογεῖν ἤρξατο μεγάλῃ βοῇ πατέρα τε καὶ γένεσιν τῶν ὅλων ἀποκαλῶν καὶ δημιουργὸν ἀνθρωπίνων καὶ θείων, οἷς αὑτὸν ἐκόσμησε, προστάτην τε καὶ κηδεμόνα γένους τῶν Ἑβραίων καὶ τῆς τούτων εὐδαιμονίας ἧς τε αὐτῷ βασιλείας ἔδωκεν. ἐπὶ τούτοις εὐξάμενος τῷ τε παντὶ λαῷ τὰ ἀγαθὰ καὶ τῷ παιδὶ Σολόμωνι διάνοιαν ὑγιῆ καὶ δικαίαν καὶ πᾶσι τοῖς τῆς ἀρετῆς μέρεσιν ἐρρωμένην ἐκέλευσε καὶ τὸ πλῆθος εὐλογεῖν τὸν θεόν. καὶ οἱ μὲν πεσόντες ἐπὶ τὴν γῆν προσεκύνησαν, εὐχαρίστησαν δὲ καὶ Δαυίδῃ περὶ πάντων ὧν αὐτοῦ τὴν βασιλείαν παραλαβόντος ἀπέλαυσαν. τῇ δ’ ἐπιούσῃ θυσίας τῷ θεῷ παρέστησαν μόσχους χιλίους καὶ κριοὺς τοσούτους καὶ χιλίους ἀμνούς, οὓς ὡλοκαύτωσαν· ἔθυσαν δὲ καὶ τὰς εἰρηνικὰς θυσίας πολλὰς μυριάδας ἱερείων κατασφάξαντες. καὶ δι’ ὅλης τῆς ἡμέρας ἑώρτασεν ὁ βασιλεὺς σὺν παντὶ τῷ λαῷ, καὶ Σολόμωνα δεύτερον ἔχρισαν τῷ ἐλαίῳ καὶ ἀπέδειξαν αὐτὸν βασιλέα καὶ Σάδωκον ἀρχιερέα τῆς πληθύος ἁπάσης. εἴς τε τὸ βασίλειον ἀγαγόντες Σολόμωνα καὶ καθίσαντες αὐτὸν ἐπὶ θρόνου τοῦ πατρῴου ἀπ’ ἐκείνης τῆς ἡμέρας ὑπήκουον αὐτῷ.", "st": "7.14.11"}, {"sp": "N", "t": "Μετ’ ὀλίγον δὲ χρόνον ὁ Δαυίδης καταπεσὼν εἰς νόσον ὑπὸ γήρως καὶ συνειδὼς ὅτι μέλλει τελευτᾶν καλέσας τὸν υἱὸν Σολόμωνα διελέχθη πρὸς αὐτὸν τοιάδε· ἐγὼ μέν, ὦ τέκνον, εἰς τὸ χρεὼν ἤδη καὶ πατέρας τοὺς ἐμοὺς ἀπαλλάσσομαι κοινὴν ὁδὸν ἁπάντων τῶν τε νῦν ὄντων καὶ τῶν ἐσομένων πορευόμενος, ἐξ ἧς οὐκέτι οἷόν τε ἐπανελθόντα γνῶναι, τί κατὰ τὸν βίον πράττεται. διὸ ζῶν ἔτι καὶ πρὸς αὐτῷ γεγονὼς τῷ τελευτᾶν παραινῶ σοι ταῦθ’ ἃ καὶ πρότερον ἔφθην συμβουλεύσας, δικαίῳ μὲν εἶναι πρὸς τοὺς ἀρχομένους, εὐσεβεῖ δὲ πρὸς τὸν τὴν βασιλείαν δεδωκότα θεόν, φυλάττειν δ’ αὐτοῦ τὰς ἐντολὰς καὶ τοὺς νόμους, οὓς αὐτὸς διὰ Μωυσέος κατέπεμψεν ἡμῖν, καὶ μήτε χάριτι μήτε θωπείᾳ μήτ’ ἐπιθυμίᾳ μήτε ἄλλῳ πάθει προστιθέμενον τούτων ἀμελῆσαι· τὴν γὰρ τοῦ θείου πρὸς σαυτὸν εὔνοιαν ἀπολεῖς παραβάς τι τῶν νομίμων καὶ πρὸς ἅπαντ’ αὐτοῦ τὴν ἀγαθὴν ἀποστρέψεις πρόνοιαν· τοιοῦτον δὲ σεαυτὸν παρέχων, ὁποῖον εἶναί τε δεῖ κἀγὼ δὲ παρακαλῶ, καθέξεις ἡμῶν τὴν βασιλείαν τῷ γένει καὶ οἶκος ἄλλος Ἑβραίων οὐκ ἂν δεσπόσειεν, ἀλλ’ ἡμεῖς αὐτοὶ διὰ τοῦ παντὸς αἰῶνος. μέμνησο δὲ καὶ τῆς Ἰωάβου τοῦ στρατηγοῦ παρανομίας ἀποκτείναντος διὰ ζηλοτυπίαν δύο στρατηγοὺς δικαίους καὶ ἀγαθούς, Ἀβεννῆρόν τε τὸν Νήρου παῖδα καὶ τὸν Ἀμασὰν υἱὸν Ἰέθρα· ὧν ὅπως ἄν σοι δόξῃ τὸν θάνατον ἐκδίκησον, ἐπεὶ καὶ κρείττων ἐμοῦ καὶ δυνατώτερος ὁ Ἰώαβος ὢν μέχρι νῦν τὴν δίκην διέφυγε. παρατίθεμαι δέ σοι καὶ τοὺς Βερζέλου τοῦ Γαλαδίτου παῖδας, οὓς ἐν τιμῇ πάσῃ καὶ προνοίᾳ τοῦτ’ ἐμοὶ χαριζόμενος ἕξεις· οὐ προκατάρχομεν γὰρ εὐποιίας, ἀλλ’ ἀμοιβὴν ὧν ὁ πατὴρ αὐτῶν παρὰ τὴν φυγὴν ὑπῆρξέ μοι χρεολυτοῦμεν. καὶ τὸν Γήρα δὲ υἱὸν Σουμούιν τὸν ἐκ τῆς Βενιαμίτιδος φυλῆς, ὃς πολλὰ βλασφημήσας με παρὰ τὴν φυγήν, ὅτ’ εἰς Παρεμβολὰς ἐπορευόμην, ἀπήντησεν ἐπὶ τὸν Ἰόρδανον καὶ πίστεις ἔλαβεν ὡς μηδὲν αὐτὸν παθεῖν τότε, νῦν ἐπιζητήσας αἰτίαν εὔλογον ἄμυνε.", "st": "7.15.1"}, {"sp": "N", "t": "Ταῦτα παραινέσας τῷ παιδὶ περί τε τῶν ὅλων πραγμάτων καὶ [περὶ] τῶν φίλων καὶ οὓς ᾔδει τιμωρίας ἀξίους γεγενημένους ἀπέθανεν, ἔτη μὲν βιώσας ἑβδομήκοντα, βασιλεύσας δὲ ἑπτὰ μὲν ἐν Χεβρῶνι τῆς Ἰούδα φυλῆς καὶ μῆνας ἕξ, ἐν Ἱεροσολύμοις δὲ ἁπάσης τῆς χώρας τρία καὶ τριάκοντα. οὕτως ἀρίστῳ ἀνδρὶ γεγενημένῳ καὶ πᾶσαν ἀρετὴν ἔχοντι καὶ τοσούτων ἐθνῶν σωτηρίαν ἐγκεχειρισμένῳ βασιλεῖ ἔδει προσεπαινέσαι καὶ τό τε τῆς δυνάμεως αὐτοῦ εὐσθενὲς καὶ τὸ τῆς σωφροσύνης συνετόν· ἀνδρεῖος γὰρ ἦν, ὡς οὐκ ἄλλος τις, ἐν δὲ τοῖς ὑπὲρ τῶν ὑπηκόων ἀγῶσι πρῶτος ἐπὶ τοὺς κινδύνους ὥρμα, τῷ πονεῖν καὶ μάχεσθαι παρακελευόμενος τοὺς στρατιώτας ἐπὶ τὰς παρατάξεις ἀλλ’ οὐχὶ τῷ προστάττειν ὡς δεσπότης, νοῆσαί τε καὶ συνιδεῖν καὶ περὶ τῶν μελλόντων καὶ τῆς τῶν ἐνεστηκότων οἰκονομίας ἱκανώτατος, σώφρων ἐπιεικὴς χρηστὸς πρὸς τοὺς ἐν συμφοραῖς ὑπάρχοντας δίκαιος φιλάνθρωπος, ἃ μόνοις δικαιότατα βασιλεῦσιν εἶναι προσῆκε, μηδὲν ὅλως παρὰ τοσοῦτο μέγεθος ἐξουσίας ἁμαρτὼν ἢ τὸ περὶ τὴν Οὐρία γυναῖκα. κατέλιπε δὲ καὶ πλοῦτον ὅσον οὐκ ἄλλος βασιλεὺς οὔθ’ Ἑβραίων οὔτ’ ἄλλων ἐθνῶν.", "st": "7.15.2"}, {"sp": "N", "t": "Ἔθαψε δὲ αὐτὸν ὁ παῖς Σολόμων ἐν Ἱεροσολύμοις διαπρεπῶς τοῖς τε ἄλλοις οἷς περὶ κηδείαν νομίζεται βασιλικὴν ἅπασι καὶ δὴ καὶ πλοῦτον αὐτῷ πολὺν καὶ ἄφθονον συνεκήδευσεν, ὧν τὴν ὑπερβολὴν τεκμήραιτ’ ἄν τις ῥᾳδίως ἐκ τοῦ λεχθησομένου· μετὰ γὰρ χρόνον ἐτῶν χιλίων καὶ τριακοσίων Ὑρκανὸς ὁ ἀρχιερεὺς πολιορκούμενος ὑπ’ Ἀντιόχου τοῦ Εὐσεβοῦς ἐπικληθέντος υἱοῦ δὲ Δημητρίου, βουλόμενος χρήματ’ αὐτῷ δοῦναι ὑπὲρ τοῦ λῦσαι τὴν πολιορκίαν καὶ τὴν στρατιὰν ἀπαγαγεῖν καὶ ἀλλαχόθεν οὐκ εὐπορῶν, ἀνοίξας ἕνα οἶκον τῶν ἐν τῷ Δαυίδου μνήματι καὶ βαστάσας τρισχίλια τάλαντα μέρος ἔδωκεν Ἀντιόχῳ καὶ διέλυσεν οὕτως τὴν πολιορκίαν, καθὼς καὶ ἐν ἄλλοις δεδηλώκαμεν. μετὰ δὲ τοῦτο ἐτῶν πολλῶν διαγενομένων πάλιν ὁ βασιλεὺς Ἡρώδης ἕτερον ἀνοίξας οἶκον ἀνείλετο χρήματα πολλά. ταῖς μέντοι γε θήκαις τῶν βασιλέων οὐδεὶς αὐτῶν ἐπέτυχεν· ἦσαν γὰρ ὑπὸ τὴν γῆν μηχανικῶς κεκηδευμέναι πρὸς τὸ μὴ φανεραὶ εἶναι τοῖς εἰς τὸ μνῆμα εἰσιοῦσιν. ἀλλὰ περὶ μὲν τούτων ἡμῖν τοσοῦτον ἀπόχρη δεδηλῶσθαι.", "st": "7.15.3"}], []);})();
